function requireCompatibleClient(data = {}) {
  if (safeString(data.clientReleaseId, 120) !== REALM_RELEASE_ID
    || safeString(data.clientResetGeneration, 120) !== RESET_GENERATION
    || safeString(data.clientWorldId, 120) !== ONLINE_WORLD_ID) {
    throw new HttpsError("failed-precondition", "Crownlands was updated. Refresh before continuing.");
  }
}

function requireAuth(request, { allowRealmMismatch = false } = {}) {
  const uid = request.auth?.uid || "";
  if (!uid) throw new HttpsError("unauthenticated", "Sign in before sending troops.");
  if (!allowRealmMismatch) requireCompatibleClient(request.data || {});
  return uid;
}

function requireRewardedAdAppCheck(request, consume = false) {
  if (!request.app) {
    throw new HttpsError("unauthenticated", "Rewarded ads require a verified Crownlands browser.");
  }
  if (consume && request.app.alreadyConsumed) {
    throw new HttpsError("permission-denied", "That rewarded-ad security token was already used.");
  }
  return request.app.appId || "";
}

function requireStatsAdmin(request) {
  const uid = requireAuth(request);
  const token = request.auth?.token || {};
  if (!token.admin && !token.developer && !token.statsAdmin) {
    throw new HttpsError("permission-denied", "Admin access is required to rebuild global stats.");
  }
  return uid;
}

function normalizeRegionId(value = "") {
  return String(value || "")
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9_-]+/g, "-")
    .replace(/^-+|-+$/g, "") || "west";
}

function getOnlineIslandId(regionId = "west") {
  return `${ONLINE_WORLD_ID}-${normalizeRegionId(regionId)}`;
}

function safeString(value, max = 80) {
  return String(value || "").trim().slice(0, max);
}

function operationResultMetrics(result = null) {
  const production = result?.production || {};
  const metrics = {
    status: safeString(result?.status || (result?.ok === false ? "failed" : "ok"), 32),
    cityCount: Math.max(0, Math.floor(Number(production.cityCount) || 0)),
    cityWrites: Math.max(0, Math.floor(Number(result?.cityWrites ?? result?.writes) || 0)),
    scanned: Math.max(0, Math.floor(Number(result?.scanned) || 0)),
    resolved: Math.max(0, Math.floor(Number(result?.resolved) || 0)),
    failed: Math.max(0, Math.floor(Number(result?.failed) || 0)),
  };
  const dailyStatus = result?.dailyLoginRewardStatus;
  const receipt = result?.receipt;
  if (dailyStatus && typeof dailyStatus === "object") {
    metrics.cycle = Math.max(1, Math.floor(Number(receipt?.cycle || dailyStatus.cycle) || 1));
    metrics.day = Math.max(1, Math.floor(Number(receipt?.day || dailyStatus.nextDay) || 1));
    metrics.eligible = Boolean(dailyStatus.eligible);
    metrics.pendingRewards = Math.max(0, Math.floor(Number(dailyStatus.pendingCount) || 0));
    metrics.attendanceDeferred = Boolean(dailyStatus.attendanceDeferred);
  }
  if (receipt && typeof receipt === "object") {
    metrics.rewardTypes = [
      Number(receipt.gold) > 0 ? "gold" : "",
      Number(receipt.troops) > 0 ? "troops" : "",
      Object.keys(receipt.items || {}).length ? "items" : "",
    ].filter(Boolean);
    metrics.itemKinds = Object.keys(receipt.items || {}).length;
  }
  return metrics;
}

function logOperation(operation, startedAtMs, request = null, outcome = "ok", details = {}) {
  console.log("crownlands_operation", {
    event: "crownlands_operation",
    operation: safeString(operation, 64),
    outcome: safeString(outcome, 24),
    durationMs: Math.max(0, Date.now() - startedAtMs),
    releaseId: REALM_RELEASE_ID,
    worldId: ONLINE_WORLD_ID,
    resetGeneration: RESET_GENERATION,
    appCheck: request?.app ? "valid" : "missing",
    ...details,
  });
}

function timedCallable(operation, options, handler) {
  return onCall(options, async request => {
    const startedAtMs = Date.now();
    try {
      const result = await handler(request);
      logOperation(operation, startedAtMs, request, "ok", operationResultMetrics(result));
      return result;
    } catch (error) {
      logOperation(operation, startedAtMs, request, "error", {
        code: safeString(error?.code || "internal", 48),
      });
      throw error;
    }
  });
}

function isRetryableTransactionInfrastructureError(error) {
  const code = String(error?.code || "").toLowerCase();
  const details = String(error?.details || error?.message || "").toLowerCase();
  return code === "10"
    || code === "aborted"
    || code.endsWith("/aborted")
    || details.includes("transaction lock timeout")
    || (code === "3" && details.includes("transaction is invalid or closed"));
}

async function runTransactionWithInfrastructureRetry(operation, label = "transaction", maxAttempts = 3) {
  let lastError = null;
  for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {
    try {
      return await db.runTransaction(operation);
    } catch (error) {
      lastError = error;
      if (!isRetryableTransactionInfrastructureError(error) || attempt >= maxAttempts) throw error;
      const delayMs = 75 * attempt + Math.floor(Math.random() * 75);
      console.warn("Retrying Crownlands Firestore transaction", {
        label: safeString(label, 64),
        attempt,
        code: safeString(error?.code || "internal", 48),
        delayMs,
      });
      await new Promise(resolve => setTimeout(resolve, delayMs));
    }
  }
  throw lastError;
}

function requireGameServerId(value = GAME_SERVER_ID) {
  const serverId = safeString(value || GAME_SERVER_ID, 64).toLowerCase();
  if (serverId !== GAME_SERVER_ID) {
    throw new HttpsError("not-found", "That Crownlands realm does not exist.");
  }
  return serverId;
}

function requireGameServerSessionId(value = "") {
  const sessionId = safeString(value, 128).replace(/[^a-zA-Z0-9_-]/g, "");
  if (!sessionId) throw new HttpsError("invalid-argument", "This browser session is missing its realm key.");
  return sessionId;
}

function cleanGameServerEntry(raw = {}, fallback = {}) {
  return {
    uid: safeString(raw.uid || fallback.uid, 128),
    sessionId: safeString(raw.sessionId || fallback.sessionId, 128),
    displayName: normalizePlayerName(raw.displayName || fallback.displayName || "Ruler"),
    joinedAtMs: Math.max(0, Math.floor(safeNumber(raw.joinedAtMs, fallback.joinedAtMs || 0))),
    queuedAtMs: Math.max(0, Math.floor(safeNumber(raw.queuedAtMs, fallback.queuedAtMs || 0))),
    admittedAtMs: Math.max(0, Math.floor(safeNumber(raw.admittedAtMs, fallback.admittedAtMs || 0))),
    lastSeenAtMs: Math.max(0, Math.floor(safeNumber(raw.lastSeenAtMs, fallback.lastSeenAtMs || 0))),
    ticket: Math.max(0, Math.floor(safeNumber(raw.ticket, fallback.ticket || 0))),
  };
}

function normalizeWelcomeBackSession(raw = null) {
  const source = raw?.welcomeBack && typeof raw.welcomeBack === "object"
    ? raw.welcomeBack
    : raw && typeof raw === "object" ? raw : {};
  const sessionId = safeString(source.sessionId, 128);
  const sessionStartedAtMs = Math.max(0, Math.floor(safeNumber(source.sessionStartedAtMs, 0)));
  const awayStartedAtMs = Math.max(0, Math.floor(safeNumber(source.awayStartedAtMs, 0)));
  const claimedAtMs = Math.max(0, Math.floor(safeNumber(source.claimedAtMs, 0)));
  const summary = source.summary && typeof source.summary === "object"
    ? source.summary
    : null;
  return {
    version: WELCOME_BACK_SUMMARY_VERSION,
    sessionId,
    sessionStartedAtMs,
    awayStartedAtMs,
    eligible: Boolean(source.eligible && sessionId && sessionStartedAtMs && awayStartedAtMs && !claimedAtMs),
    claimedAtMs,
    summary,
  };
}

function createWelcomeBackSession(priorMembership = {}, sessionId = "", nowMs = Date.now()) {
  const normalizedSessionId = safeString(sessionId, 128);
  const existing = normalizeWelcomeBackSession(priorMembership);
  if (existing.sessionId === normalizedSessionId && existing.sessionStartedAtMs) {
    return existing;
  }

  const priorSessionId = safeString(priorMembership.sessionId, 128);
  const priorLastSeenAtMs = Math.max(0, Math.floor(safeNumber(priorMembership.lastSeenAtMs, 0)));
  const awayElapsedMs = priorLastSeenAtMs > 0 ? Math.max(0, nowMs - priorLastSeenAtMs) : 0;
  const eligible = Boolean(
    normalizedSessionId
    && priorSessionId
    && priorSessionId !== normalizedSessionId
    && priorLastSeenAtMs
    && awayElapsedMs >= WELCOME_BACK_MIN_AWAY_MS
  );
  return {
    version: WELCOME_BACK_SUMMARY_VERSION,
    sessionId: normalizedSessionId,
    sessionStartedAtMs: nowMs,
    awayStartedAtMs: eligible ? priorLastSeenAtMs : 0,
    eligible,
    claimedAtMs: 0,
    summary: null,
  };
}

function normalizeGameServerEntries(raw = {}, nowMs = Date.now(), staleMs = 0) {
  const entries = {};
  Object.entries(raw && typeof raw === "object" ? raw : {}).forEach(([rawUid, value]) => {
    const uid = safeString(value?.uid || rawUid, 128);
    if (!uid || uid.includes("/")) return;
    const entry = cleanGameServerEntry(value, { uid });
    if (!entry.sessionId || !entry.lastSeenAtMs) return;
    if (staleMs > 0 && nowMs - entry.lastSeenAtMs > staleMs) return;
    entries[uid] = entry;
  });
  return entries;
}

function createGameServerState(raw = {}, nowMs = Date.now(), { pruneStale = true } = {}) {
  return {
    id: GAME_SERVER_ID,
    name: GAME_SERVER_NAME,
    capacity: GAME_SERVER_CAPACITY,
    nextTicket: Math.max(1, Math.floor(safeNumber(raw.nextTicket, 1))),
    activeSlots: normalizeGameServerEntries(
      raw.activeSlots,
      nowMs,
      pruneStale ? GAME_SERVER_ACTIVE_STALE_MS : 0
    ),
    waitingQueue: normalizeGameServerEntries(
      raw.waitingQueue,
      nowMs,
      pruneStale ? GAME_SERVER_WAITING_STALE_MS : 0
    ),
  };
}

function applyGameServerMemberHeartbeats(raw = {}, memberRows = []) {
  const activeSlots = { ...(raw.activeSlots && typeof raw.activeSlots === "object" ? raw.activeSlots : {}) };
  const waitingQueue = { ...(raw.waitingQueue && typeof raw.waitingQueue === "object" ? raw.waitingQueue : {}) };
  (Array.isArray(memberRows) ? memberRows : []).forEach(row => {
    const uid = safeString(row?.uid, 128);
    const sessionId = safeString(row?.sessionId, 128);
    const lastSeenAtMs = Math.max(0, Math.floor(safeNumber(row?.lastSeenAtMs, 0)));
    if (!uid || !sessionId || !lastSeenAtMs) return;
    const current = activeSlots[uid] || waitingQueue[uid];
    if (!current || safeString(current.sessionId, 128) !== sessionId) return;
    const next = {
      ...current,
      lastSeenAtMs: Math.max(
        Math.max(0, Math.floor(safeNumber(current.lastSeenAtMs, 0))),
        lastSeenAtMs
      ),
    };
    if (activeSlots[uid]) activeSlots[uid] = next;
    else waitingQueue[uid] = next;
  });
  return { ...raw, activeSlots, waitingQueue };
}

function getOrderedGameServerWaiters(state) {
  return Object.values(state.waitingQueue || {}).sort((a, b) => (
    (a.ticket - b.ticket)
    || (a.queuedAtMs - b.queuedAtMs)
    || a.uid.localeCompare(b.uid)
  ));
}

function promoteGameServerWaiters(state, nowMs = Date.now()) {
  const promoted = [];
  const waiters = getOrderedGameServerWaiters(state);
  while (Object.keys(state.activeSlots).length < GAME_SERVER_CAPACITY && waiters.length) {
    const waiter = waiters.shift();
    if (!waiter?.uid || !state.waitingQueue[waiter.uid]) continue;
    delete state.waitingQueue[waiter.uid];
    const activeEntry = cleanGameServerEntry(waiter, {
      uid: waiter.uid,
      admittedAtMs: nowMs,
      joinedAtMs: nowMs,
    });
    activeEntry.admittedAtMs = nowMs;
    activeEntry.joinedAtMs = activeEntry.joinedAtMs || nowMs;
    activeEntry.lastSeenAtMs = nowMs;
    activeEntry.ticket = 0;
    state.activeSlots[waiter.uid] = activeEntry;
    promoted.push(activeEntry);
  }
  return promoted;
}

function inactivityMaintenanceRef(uid = "") {
  const playerUid = safeString(uid, 128);
  return playerUid
    ? db.doc(`realmMaintenance/${RESET_GENERATION}/inactivePlayers/${playerUid}`)
    : null;
}

function getInactivityNotice(membership = {}) {
  const stage = safeString(membership.inactivityStage, 24);
  if (stage !== "surrendered" && stage !== "removed") return null;
  return {
    policyVersion: INACTIVITY_POLICY_VERSION,
    type: stage === "removed" ? "world-slot-reset" : "territory-surrendered",
    occurredAtMs: Math.max(0, Math.floor(safeNumber(
      stage === "removed" ? membership.removedAtMs : membership.surrenderedAtMs,
      0
    ))),
    releasedCities: Math.max(0, Math.floor(safeNumber(membership.releasedCities, 0))),
    releasedCamps: Math.max(0, Math.floor(safeNumber(membership.releasedCamps, 0))),
    consolidatedTroops: Math.max(0, Math.floor(safeNumber(membership.consolidatedTroops, 0))),
  };
}

function isInactivityJobLocked(receipt = {}, nowMs = Date.now()) {
  return receipt.status === "processing"
    && safeString(receipt.worldId, 120) === ONLINE_WORLD_ID
    && safeString(receipt.resetGeneration, 120) === RESET_GENERATION
    && Math.max(0, Math.floor(safeNumber(receipt.leaseUntilMs, 0))) > nowMs;
}

function isInactivityLifecycleBlockingPlayer(receipt = {}) {
  return ["processing", "failed"].includes(receipt.status)
    && safeString(receipt.worldId, 120) === ONLINE_WORLD_ID
    && safeString(receipt.resetGeneration, 120) === RESET_GENERATION;
}

function writeGameServerMembership(transaction, entry, status, nowMs = Date.now()) {
  if (!entry?.uid) return;
  transaction.set(db.doc(`players/${entry.uid}/serverMembership/current`), {
    serverId: GAME_SERVER_ID,
    serverName: GAME_SERVER_NAME,
    worldId: ONLINE_WORLD_ID,
    resetGeneration: RESET_GENERATION,
    releaseId: REALM_RELEASE_ID,
    status,
    sessionId: entry.sessionId || "",
    displayName: entry.displayName || "Ruler",
    queuedAtMs: status === "waiting" ? entry.queuedAtMs || nowMs : 0,
    admittedAtMs: status === "active" ? entry.admittedAtMs || nowMs : 0,
    lastSeenAtMs: nowMs,
    inactivityPolicyVersion: INACTIVITY_POLICY_VERSION,
    inactivityStage: status === "expired" ? "removed" : "active",
    basisLastSeenAtMs: 0,
    updatedAtMs: nowMs,
    updatedAt: FieldValue.serverTimestamp(),
  }, { merge: true });
}

function writeGameServerMember(transaction, entry, status, nowMs = Date.now()) {
  if (!entry?.uid) return;
  transaction.set(db.doc(`gameServers/${GAME_SERVER_DOCUMENT_ID}/members/${entry.uid}`), {
    uid: entry.uid,
    serverId: GAME_SERVER_ID,
    worldId: ONLINE_WORLD_ID,
    resetGeneration: RESET_GENERATION,
    releaseId: REALM_RELEASE_ID,
    heartbeatModelVersion: GAME_SERVER_HEARTBEAT_MODEL_VERSION,
    status,
    sessionId: entry.sessionId || "",
    displayName: entry.displayName || "Ruler",
    queuedAtMs: status === "waiting" ? entry.queuedAtMs || nowMs : 0,
    admittedAtMs: status === "active" ? entry.admittedAtMs || nowMs : 0,
    lastSeenAtMs: nowMs,
    updatedAtMs: nowMs,
    updatedAt: FieldValue.serverTimestamp(),
  }, { merge: true });
}

function writeGameServerState(transaction, serverRef, state, nowMs = Date.now()) {
  const serverState = {
    id: GAME_SERVER_ID,
    name: GAME_SERVER_NAME,
    worldId: ONLINE_WORLD_ID,
    resetGeneration: RESET_GENERATION,
    releaseId: REALM_RELEASE_ID,
    capacity: GAME_SERVER_CAPACITY,
    heartbeatModelVersion: GAME_SERVER_HEARTBEAT_MODEL_VERSION,
    activeCount: Object.keys(state.activeSlots).length,
    waitingCount: Object.keys(state.waitingQueue).length,
    activeSlots: state.activeSlots,
    waitingQueue: state.waitingQueue,
    nextTicket: state.nextTicket,
    updatedAtMs: nowMs,
    updatedAt: FieldValue.serverTimestamp(),
  };
  transaction.set(serverRef, serverState, { mergeFields: Object.keys(serverState) });
}

function serializeGameServerAdmission(operation) {
  const result = gameServerAdmissionQueue.then(operation, operation);
  gameServerAdmissionQueue = result.then(
    () => undefined,
    () => undefined
  );
  return result;
}

function isGameServerLeaseAlreadyHeld(error) {
  const code = String(error?.code || "").toLowerCase();
  const message = String(error?.message || error?.details || "").toLowerCase();
  return code === "6"
    || code === "already-exists"
    || code.endsWith("/already-exists")
    || message.includes("already exists");
}

function isGameServerLeaseRace(error) {
  const code = String(error?.code || "").toLowerCase();
  return isGameServerLeaseAlreadyHeld(error)
    || code === "5"
    || code === "9"
    || code === "not-found"
    || code === "failed-precondition"
    || code.endsWith("/not-found")
    || code.endsWith("/failed-precondition");
}

function waitForGameServerAdmission(attempt = 0) {
  const backoffMs = Math.min(300, 20 * (1.35 ** Math.min(12, attempt)));
  const jitterMs = Math.floor(Math.random() * 40);
  return new Promise(resolve => setTimeout(resolve, Math.ceil(backoffMs + jitterMs)));
}

async function withGameServerAdmissionLease(operation) {
  const leaseRef = db.doc(`gameServers/${GAME_SERVER_DOCUMENT_ID}/coordination/admission`);
  const ownerId = `${process.pid}-${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;
  const deadlineMs = Date.now() + GAME_SERVER_ADMISSION_WAIT_MS;
  let leaseWrite = null;
  let attempt = 0;

  while (!leaseWrite) {
    const nowMs = Date.now();
    try {
      leaseWrite = await leaseRef.create({
        ownerId,
        acquiredAtMs: nowMs,
        expiresAtMs: nowMs + GAME_SERVER_ADMISSION_LEASE_MS,
        resetGeneration: RESET_GENERATION,
        updatedAt: FieldValue.serverTimestamp(),
      });
    } catch (error) {
      if (!isGameServerLeaseAlreadyHeld(error)) throw error;
      const leaseSnap = await leaseRef.get();
      if (leaseSnap.exists && safeNumber(leaseSnap.data()?.expiresAtMs, 0) <= Date.now()) {
        try {
          await leaseRef.delete({ lastUpdateTime: leaseSnap.updateTime });
        } catch (deleteError) {
          if (!isGameServerLeaseRace(deleteError)) throw deleteError;
        }
      }
      if (Date.now() >= deadlineMs) {
        throw new HttpsError("resource-exhausted", "Realm admission is busy. Try entering again shortly.");
      }
      await waitForGameServerAdmission(attempt);
      attempt += 1;
    }
  }

  try {
    return await operation();
  } finally {
    try {
      await leaseRef.delete({ lastUpdateTime: leaseWrite.updateTime });
    } catch (error) {
      if (!isGameServerLeaseRace(error)) {
        console.error("Failed to release Crownlands realm admission lease", {
          code: safeString(error?.code || "internal", 48),
        });
      }
    }
  }
}

async function joinGameServerForPlayer({ uid, sessionId, displayName, nowMs = Date.now() }) {
  const serverRef = db.doc(`gameServers/${GAME_SERVER_DOCUMENT_ID}`);
  const membershipRef = db.doc(`players/${uid}/serverMembership/current`);
  const maintenanceRef = inactivityMaintenanceRef(uid);
  return serializeGameServerAdmission(() => withGameServerAdmissionLease(() => runTransactionWithInfrastructureRetry(async transaction => {
    const [serverSnap, membershipSnap, maintenanceSnap] = await Promise.all([
      transaction.get(serverRef),
      transaction.get(membershipRef),
      transaction.get(maintenanceRef),
    ]);
    const priorMembership = membershipSnap.exists ? membershipSnap.data() || {} : {};
    const maintenance = maintenanceSnap.exists ? maintenanceSnap.data() || {} : {};
    if (isInactivityLifecycleBlockingPlayer(maintenance)) {
      throw new HttpsError("unavailable", "Your kingdom is completing scheduled realm maintenance. Try again in a moment.");
    }
    const inactivityNotice = getInactivityNotice(priorMembership);
    const welcomeBack = createWelcomeBackSession(priorMembership, sessionId, nowMs);
    const state = createGameServerState(serverSnap.exists ? serverSnap.data() : {}, nowMs, { pruneStale: false });
    const promoted = promoteGameServerWaiters(state, nowMs);
    let activeEntry = state.activeSlots[uid] || null;
    let waitingEntry = state.waitingQueue[uid] || null;

    if (activeEntry) {
      activeEntry = cleanGameServerEntry(activeEntry, { uid });
      activeEntry.sessionId = sessionId;
      activeEntry.displayName = displayName;
      activeEntry.lastSeenAtMs = nowMs;
      activeEntry.joinedAtMs = activeEntry.joinedAtMs || nowMs;
      activeEntry.admittedAtMs = activeEntry.admittedAtMs || nowMs;
      state.activeSlots[uid] = activeEntry;
      delete state.waitingQueue[uid];
      waitingEntry = null;
    } else if (waitingEntry) {
      waitingEntry = cleanGameServerEntry(waitingEntry, { uid });
      waitingEntry.sessionId = sessionId;
      waitingEntry.displayName = displayName;
      waitingEntry.lastSeenAtMs = nowMs;
      waitingEntry.queuedAtMs = waitingEntry.queuedAtMs || nowMs;
      state.waitingQueue[uid] = waitingEntry;
    } else if (Object.keys(state.activeSlots).length < GAME_SERVER_CAPACITY && !getOrderedGameServerWaiters(state).length) {
      activeEntry = cleanGameServerEntry({
        uid,
        sessionId,
        displayName,
        joinedAtMs: nowMs,
        admittedAtMs: nowMs,
        lastSeenAtMs: nowMs,
      });
      state.activeSlots[uid] = activeEntry;
    } else {
      if (Object.keys(state.waitingQueue).length >= GAME_SERVER_MAX_WAITING) {
        throw new HttpsError("resource-exhausted", "The Crown Marches waiting list is full. Try again shortly.");
      }
      waitingEntry = cleanGameServerEntry({
        uid,
        sessionId,
        displayName,
        queuedAtMs: nowMs,
        lastSeenAtMs: nowMs,
        ticket: state.nextTicket,
      });
      state.nextTicket += 1;
      state.waitingQueue[uid] = waitingEntry;
    }

    const newlyPromoted = promoteGameServerWaiters(state, nowMs);
    promoted.push(...newlyPromoted);
    activeEntry = state.activeSlots[uid] || null;
    waitingEntry = state.waitingQueue[uid] || null;

    writeGameServerState(transaction, serverRef, state, nowMs);
    const membershipWrites = new Map(promoted.map(entry => [entry.uid, { entry, status: "active" }]));
    if (activeEntry) membershipWrites.set(uid, { entry: activeEntry, status: "active" });
    else if (waitingEntry) membershipWrites.set(uid, { entry: waitingEntry, status: "waiting" });
    membershipWrites.forEach(({ entry, status }) => {
      writeGameServerMember(transaction, entry, status, nowMs);
      writeGameServerMembership(transaction, entry, status, nowMs);
    });
    transaction.set(membershipRef, { welcomeBack }, { merge: true });

    return {
      serverId: GAME_SERVER_ID,
      serverName: GAME_SERVER_NAME,
      status: activeEntry ? "active" : "waiting",
      admittedAtMs: activeEntry?.admittedAtMs || 0,
      queuedAtMs: waitingEntry?.queuedAtMs || 0,
      inactivityNotice,
      welcomeBack,
    };
  })));
}

async function heartbeatGameServerForPlayer({ uid, sessionId, displayName, nowMs = Date.now() }) {
  const serverRef = db.doc(`gameServers/${GAME_SERVER_DOCUMENT_ID}`);
  const membershipRef = db.doc(`players/${uid}/serverMembership/current`);
  const profileRef = db.doc(`players/${uid}`);
  const maintenanceRef = inactivityMaintenanceRef(uid);
  const result = await runTransactionWithInfrastructureRetry(async transaction => {
    const [serverSnap, membershipSnap, maintenanceSnap] = await Promise.all([
      transaction.get(serverRef),
      transaction.get(membershipRef),
      transaction.get(maintenanceRef),
    ]);
    const maintenance = maintenanceSnap.exists ? maintenanceSnap.data() || {} : {};
    if (isInactivityLifecycleBlockingPlayer(maintenance)) {
      throw new HttpsError("unavailable", "Your kingdom is completing scheduled realm maintenance. Try again in a moment.");
    }
    const currentMembership = membershipSnap.exists ? membershipSnap.data() || {} : {};
    const inactivityNotice = getInactivityNotice(currentMembership);
    const welcomeBack = normalizeWelcomeBackSession(currentMembership);
    const state = createGameServerState(
      serverSnap.exists ? serverSnap.data() : {},
      nowMs,
      { pruneStale: false }
    );
    const activeEntry = state.activeSlots[uid] || null;
    const waitingEntry = state.waitingQueue[uid] || null;
    const currentEntry = activeEntry || waitingEntry;
    if (!currentEntry) return { status: "missing" };
    if (currentEntry.sessionId !== sessionId) {
      return { serverId: GAME_SERVER_ID, serverName: GAME_SERVER_NAME, status: "session-replaced" };
    }
    const status = activeEntry ? "active" : "waiting";
    const entry = cleanGameServerEntry(currentEntry, { uid, sessionId, displayName });
    entry.displayName = displayName;
    entry.lastSeenAtMs = nowMs;
    writeGameServerMember(transaction, entry, status, nowMs);
    writeGameServerMembership(transaction, entry, status, nowMs);
    if (status === "active" && !welcomeBack.eligible) {
      transaction.set(profileRef, {
        pendingAwayProduction: createEmptyPendingAwayProduction(nowMs),
      }, { merge: true });
    }
    return {
      serverId: GAME_SERVER_ID,
      serverName: GAME_SERVER_NAME,
      status,
      admittedAtMs: status === "active" ? entry.admittedAtMs || 0 : 0,
      queuedAtMs: status === "waiting" ? entry.queuedAtMs || 0 : 0,
      inactivityNotice,
      welcomeBack,
    };
  });
  if (result.status !== "missing") return result;
  return joinGameServerForPlayer({ uid, sessionId, displayName, nowMs });
}

async function leaveGameServerForPlayer({ uid, sessionId, nowMs = Date.now() }) {
  const serverRef = db.doc(`gameServers/${GAME_SERVER_DOCUMENT_ID}`);
  return serializeGameServerAdmission(() => withGameServerAdmissionLease(() => runTransactionWithInfrastructureRetry(async transaction => {
    const serverSnap = await transaction.get(serverRef);
    const state = createGameServerState(serverSnap.exists ? serverSnap.data() : {}, nowMs, { pruneStale: false });
    const activeEntry = state.activeSlots[uid] || null;
    const waitingEntry = state.waitingQueue[uid] || null;
    const currentEntry = activeEntry || waitingEntry;
    if (currentEntry && currentEntry.sessionId !== sessionId) {
      return { serverId: GAME_SERVER_ID, serverName: GAME_SERVER_NAME, status: "session-replaced" };
    }

    delete state.activeSlots[uid];
    delete state.waitingQueue[uid];
    const promoted = promoteGameServerWaiters(state, nowMs);
    writeGameServerState(transaction, serverRef, state, nowMs);
    promoted.forEach(entry => {
      writeGameServerMember(transaction, entry, "active", nowMs);
      writeGameServerMembership(transaction, entry, "active", nowMs);
    });
    transaction.delete(db.doc(`gameServers/${GAME_SERVER_DOCUMENT_ID}/members/${uid}`));
    writeGameServerMembership(transaction, {
      uid,
      sessionId,
      displayName: currentEntry?.displayName || "Ruler",
    }, "left", nowMs);
    return { serverId: GAME_SERVER_ID, serverName: GAME_SERVER_NAME, status: "left" };
  })));
}

async function maintainGameServer(nowMs = Date.now()) {
  const serverRef = db.doc(`gameServers/${GAME_SERVER_DOCUMENT_ID}`);
  return serializeGameServerAdmission(() => withGameServerAdmissionLease(() => runTransactionWithInfrastructureRetry(async transaction => {
    const staleBeforeMs = nowMs - GAME_SERVER_WAITING_STALE_MS;
    const memberQuery = serverRef.collection("members")
      .where("lastSeenAtMs", ">=", staleBeforeMs);
    const staleMemberQuery = serverRef.collection("members")
      .where("lastSeenAtMs", "<", staleBeforeMs)
      .limit(100);
    const [serverSnap, memberSnap, staleMemberSnap] = await Promise.all([
      transaction.get(serverRef),
      transaction.get(memberQuery),
      transaction.get(staleMemberQuery),
    ]);
    const rawState = applyGameServerMemberHeartbeats(
      serverSnap.exists ? serverSnap.data() : {},
      memberSnap.docs.map(doc => ({ uid: doc.id, ...doc.data() }))
    );
    const state = createGameServerState(rawState, nowMs);
    const promoted = promoteGameServerWaiters(state, nowMs);
    writeGameServerState(transaction, serverRef, state, nowMs);
    promoted.forEach(entry => {
      writeGameServerMember(transaction, entry, "active", nowMs);
      writeGameServerMembership(transaction, entry, "active", nowMs);
    });
    staleMemberSnap.docs.forEach(doc => transaction.delete(doc.ref));
    return {
      active: Object.keys(state.activeSlots).length,
      waiting: Object.keys(state.waitingQueue).length,
      promoted: promoted.length,
      staleMembersDeleted: staleMemberSnap.size,
    };
  })));
}

function getInactivePlayerUidFromMembershipDoc(membershipDoc = null) {
  const uid = safeString(membershipDoc?.ref?.parent?.parent?.id, 128);
  return uid && !uid.includes("/") ? uid : "";
}

function getInactivityTargetStage(lastSeenAtMs = 0, nowMs = Date.now()) {
  const elapsedMs = Math.max(0, nowMs - Math.max(0, Math.floor(safeNumber(lastSeenAtMs, 0))));
  if (elapsedMs >= INACTIVITY_REMOVAL_MS) return "removing";
  if (elapsedMs >= INACTIVITY_SURRENDER_MS) return "surrendering";
  return "";
}

function isCurrentInactivityMembership(membership = {}) {
  return safeString(membership.worldId, 120) === ONLINE_WORLD_ID
    && safeString(membership.resetGeneration, 120) === RESET_GENERATION;
}

async function loadInactiveMembershipCandidates(nowMs = Date.now()) {
  const baseQuery = db.collectionGroup("serverMembership")
    .where("resetGeneration", "==", RESET_GENERATION)
    .where("worldId", "==", ONLINE_WORLD_ID);
  const [newlyInactiveSnap, surrenderedSnap] = await Promise.all([
    baseQuery
      .where("status", "in", ["active", "left", "waiting"])
      .where("lastSeenAtMs", "<=", nowMs - INACTIVITY_SURRENDER_MS)
      .orderBy("lastSeenAtMs", "asc")
      .limit(INACTIVITY_CANDIDATE_LIMIT)
      .get(),
    baseQuery
      .where("status", "==", "inactive")
      .where("lastSeenAtMs", "<=", nowMs - INACTIVITY_REMOVAL_MS)
      .orderBy("lastSeenAtMs", "asc")
      .limit(INACTIVITY_CANDIDATE_LIMIT)
      .get(),
  ]);
  return [...new Map(
    [...newlyInactiveSnap.docs, ...surrenderedSnap.docs].map(doc => [doc.ref.path, doc])
  ).values()]
    .filter(doc => doc.id === "current")
    .map(doc => ({
      uid: getInactivePlayerUidFromMembershipDoc(doc),
      ref: doc.ref,
      membership: doc.data() || {},
    }))
    .filter(entry => entry.uid && isCurrentInactivityMembership(entry.membership))
    .sort((a, b) => safeNumber(a.membership.lastSeenAtMs, 0) - safeNumber(b.membership.lastSeenAtMs, 0))
    .slice(0, INACTIVITY_CANDIDATE_LIMIT);
}

async function beginInactivePlayerMaintenance(uid = "", targetStage = "", nowMs = Date.now()) {
  const playerUid = safeString(uid, 128);
  const membershipRef = db.doc(`players/${playerUid}/serverMembership/current`);
  const receiptRef = inactivityMaintenanceRef(playerUid);
  if (!playerUid || !receiptRef || !["surrendering", "removing"].includes(targetStage)) {
    return { acquired: false, reason: "invalid" };
  }
  return runTransactionWithInfrastructureRetry(async transaction => {
    const [membershipSnap, receiptSnap] = await Promise.all([
      transaction.get(membershipRef),
      transaction.get(receiptRef),
    ]);
    const membership = membershipSnap.exists ? membershipSnap.data() || {} : {};
    const receipt = receiptSnap.exists ? receiptSnap.data() || {} : {};
    if (!isCurrentInactivityMembership(membership)) {
      return { acquired: false, reason: "realm-changed" };
    }
    const basisLastSeenAtMs = Math.max(0, Math.floor(safeNumber(membership.lastSeenAtMs, 0)));
    const currentTargetStage = getInactivityTargetStage(basisLastSeenAtMs, nowMs);
    if (!currentTargetStage || (targetStage === "removing" && currentTargetStage !== "removing")) {
      return { acquired: false, reason: "activity-renewed" };
    }
    const completedStage = targetStage === "removing" ? "removed" : "surrendered";
    if (
      receipt.status === "completed"
      && receipt.stage === completedStage
      && Math.floor(safeNumber(receipt.basisLastSeenAtMs, 0)) === basisLastSeenAtMs
    ) {
      return { acquired: false, reason: "already-completed" };
    }
    if (isInactivityJobLocked(receipt, nowMs)) {
      return { acquired: false, reason: "locked" };
    }
    const continuing = ["processing", "failed"].includes(receipt.status)
      && receipt.stage === targetStage
      && Math.floor(safeNumber(receipt.basisLastSeenAtMs, 0)) === basisLastSeenAtMs;
    const resetCounters = continuing ? {} : {
      releasedCities: 0,
      releasedCamps: 0,
      consolidatedTroops: 0,
      canceledArmies: 0,
      returnedReinforcements: 0,
    };
    transaction.set(receiptRef, {
      uid: playerUid,
      worldId: ONLINE_WORLD_ID,
      resetGeneration: RESET_GENERATION,
      policyVersion: INACTIVITY_POLICY_VERSION,
      status: "processing",
      stage: targetStage,
      basisLastSeenAtMs,
      startedAtMs: continuing ? Math.max(0, Math.floor(safeNumber(receipt.startedAtMs, nowMs))) : nowMs,
      leaseUntilMs: nowMs + INACTIVITY_JOB_LEASE_MS,
      attempts: FieldValue.increment(1),
      lastError: FieldValue.delete(),
      ...resetCounters,
      updatedAtMs: nowMs,
      updatedAt: FieldValue.serverTimestamp(),
      ...(receiptSnap.exists ? {} : {
        createdAtMs: nowMs,
        createdAt: FieldValue.serverTimestamp(),
      }),
    }, { merge: true });
    transaction.set(membershipRef, {
      inactivityPolicyVersion: INACTIVITY_POLICY_VERSION,
      inactivityStage: targetStage,
      basisLastSeenAtMs,
      updatedAtMs: nowMs,
      updatedAt: FieldValue.serverTimestamp(),
    }, { merge: true });
    return { acquired: true, basisLastSeenAtMs, receiptRef, membershipRef };
  });
}

async function assertInactiveMaintenanceRun(transaction, receiptRef, {
  uid = "",
  stage = "",
  basisLastSeenAtMs = 0,
} = {}) {
  const receiptSnap = await transaction.get(receiptRef);
  const receipt = receiptSnap.exists ? receiptSnap.data() || {} : {};
  if (
    receipt.status !== "processing"
    || receipt.stage !== stage
    || safeString(receipt.uid, 128) !== safeString(uid, 128)
    || Math.floor(safeNumber(receipt.basisLastSeenAtMs, 0)) !== Math.floor(safeNumber(basisLastSeenAtMs, 0))
  ) {
    throw new HttpsError("aborted", "Inactive-player maintenance was superseded by newer activity.");
  }
  return receipt;
}

async function settleInactivePlayerProduction(uid = "", run = {}, nowMs = Date.now()) {
  return runTransactionWithInfrastructureRetry(async transaction => {
    await assertInactiveMaintenanceRun(transaction, run.receiptRef, {
      uid,
      stage: "surrendering",
      basisLastSeenAtMs: run.basisLastSeenAtMs,
    });
    const economy = await prepareEconomyCollection(transaction, uid, nowMs, {
      allowInactivityMaintenance: true,
    });
    writePreparedEconomy(transaction, economy, {}, [], { nowMs });
    return true;
  });
}

async function loadInactivePlayerHoldings(uid = "") {
  const playerUid = safeString(uid, 128);
  const [profileSnap, citySnap, campSnap, armySnap, reinforcementSnap] = await Promise.all([
    db.doc(`players/${playerUid}`).get(),
    db.collectionGroup("cities")
      .where("ownerUid", "==", playerUid)
      .where("resetGeneration", "==", RESET_GENERATION)
      .where("worldId", "==", ONLINE_WORLD_ID)
      .get(),
    heldRewardCampsQueryForPlayer(playerUid).get(),
    activeArmiesQueryForPlayer(playerUid).get(),
    db.collection("reinforcements")
      .where("ownerUid", "==", playerUid)
      .where("resetGeneration", "==", RESET_GENERATION)
      .where("worldId", "==", ONLINE_WORLD_ID)
      .where("status", "==", REINFORCEMENT_STATUS_STATIONED)
      .get(),
  ]);
  const profile = profileSnap.exists ? profileSnap.data() || {} : {};
  const cityEntries = createOwnedCityEntriesFromSnapshot(playerUid, citySnap);
  const mainEntry = getCanonicalMainCityEntry(profile, cityEntries);
  return {
    profileSnap,
    profile,
    cityEntries,
    mainEntry,
    campDocs: campSnap.docs,
    armyDocs: armySnap.docs.filter(doc => doc.ref.parent?.parent === null),
    reinforcementDocs: reinforcementSnap.docs,
  };
}

function getInactiveCityNeutralPatch(city = {}, nowMs = Date.now()) {
  return {
    ownerKind: "neutral",
    ownerUid: null,
    ownerName: "",
    ownerFlag: null,
    ownerKingPower: 0,
    ownerShieldExpiresAtMs: 0,
    level: isStronghold(city) ? getStrongholdDefenseLevel(city) : clampCityLevel(city.level),
    troops: 0,
    troopFloat: 0,
    investedGold: 0,
    isMainCity: false,
    productionUpdatedAtMs: nowMs,
    relinquishedAtMs: nowMs,
    relocatedAtMs: 0,
    ...getNeutralClaimClearedPatch(nowMs),
  };
}

function isCurrentInactivityAsset(asset = {}) {
  return safeString(asset.worldId, 120) === ONLINE_WORLD_ID
    && safeString(asset.resetGeneration, 120) === RESET_GENERATION;
}

function getInactiveCampNeutralPatch(camp = {}, nowMs = Date.now()) {
  const config = getRewardCampConfig(camp);
  const combatMetadata = getRewardCampCombatMetadata(config);
  const activeArmyIds = normalizeActiveArmyIds(camp.activeArmyIds);
  return {
    ...combatMetadata,
    holderUid: "",
    holderName: "",
    holderFlag: null,
    heldSinceMs: 0,
    payoutAtMs: 0,
    payoutPending: false,
    currentGarrison: combatMetadata.baseDefenders,
    returnSourceCityId: "",
    returnSourceRegionId: "",
    returnSourceCityName: "",
    returnPathSegments: [],
    returnRouteRegionIds: [],
    returnPathLength: 0,
    state: getRewardCampState(activeArmyIds, ""),
    lastInactiveReleaseAtMs: nowMs,
    updatedAt: FieldValue.serverTimestamp(),
  };
}

function getInactiveHomeTroopPatch(home = {}, addedTroops = 0, nowMs = Date.now()) {
  const currentTroops = Math.max(0, safeNumber(home.troopFloat, home.troops || 0));
  const nextTroops = Math.min(Number.MAX_SAFE_INTEGER, currentTroops + Math.max(0, Math.floor(safeNumber(addedTroops, 0))));
  return {
    troops: Math.floor(nextTroops),
    troopFloat: nextTroops,
    productionUpdatedAtMs: nowMs,
  };
}

async function releaseInactiveCity(uid = "", cityDoc = null, homeRef = null, run = {}, nowMs = Date.now()) {
  if (!cityDoc?.ref) return { released: false, troops: 0 };
  return runTransactionWithInfrastructureRetry(async transaction => {
    const refs = [run.receiptRef, cityDoc.ref];
    if (homeRef) refs.push(homeRef);
    const snapshots = await Promise.all(refs.map(ref => transaction.get(ref)));
    const receiptSnap = snapshots[0];
    const citySnap = snapshots[1];
    const homeSnap = homeRef ? snapshots[2] : null;
    const receipt = receiptSnap.exists ? receiptSnap.data() || {} : {};
    if (
      receipt.status !== "processing"
      || receipt.stage !== run.stage
      || Math.floor(safeNumber(receipt.basisLastSeenAtMs, 0)) !== run.basisLastSeenAtMs
    ) {
      throw new HttpsError("aborted", "Inactive-player city cleanup was superseded.");
    }
    if (!citySnap.exists) return { released: false, troops: 0 };
    const city = { id: citySnap.id, ...citySnap.data() };
    if (
      getOwnerUid(city) !== uid
      || !isCurrentInactivityAsset(city)
      || (homeRef && cityDoc.ref.path === homeRef.path)
    ) {
      return { released: false, troops: 0 };
    }
    const citadelReignSnapshots = await prefetchCrownCitadelReignSnapshots(transaction, {
      citadel: city,
      previousOwnerUid: uid,
      nextOwnerUid: "",
    });
    const strongholdLegacySnapshots = await prefetchStrongholdLegacySnapshots(transaction, {
      stronghold: city,
      previousOwnerUid: uid,
      nextOwnerUid: "",
    });
    const troops = homeRef ? getTargetOwnerTroops(city, "city") : 0;
    if (homeRef) {
      if (!homeSnap?.exists || getOwnerUid(homeSnap.data() || {}) !== uid) {
        throw new HttpsError("failed-precondition", "The inactive player's home base is no longer available.");
      }
      transaction.set(homeRef, cleanCityUpdate(homeSnap.data() || {}, getInactiveHomeTroopPatch(
        homeSnap.data() || {},
        troops,
        nowMs
      )), { merge: true });
    }
    const regionId = getRegionIdFromCityDoc(citySnap, city);
    if (isCrownCitadel(city)) {
      recordCrownCitadelControlChange(transaction, {
        citadel: city,
        previousOwnerUid: uid,
        previousOwnerName: normalizePlayerName(city.ownerName, "Ruler"),
        nextOwnerUid: "",
        nowMs,
        reignSnapshots: citadelReignSnapshots,
      });
    } else if (isStrongholdLegacyTarget(city)) {
      recordStrongholdLegacyControlChange(transaction, {
        stronghold: city,
        previousOwnerUid: uid,
        previousOwnerName: normalizePlayerName(city.ownerName, "Ruler"),
        nextOwnerUid: "",
        nowMs,
        legacySnapshots: strongholdLegacySnapshots,
      });
    }
    transaction.set(cityDoc.ref, cleanCityUpdate(city, getInactiveCityNeutralPatch(city, nowMs)), { merge: true });
    writeOwnershipChangeEvent(transaction, {
      eventId: `inactive_${run.stage}_${uid}_${city.id}_${run.basisLastSeenAtMs}`,
      targetType: "city",
      targetId: city.id,
      regionId,
      beforeOwnerUid: uid,
      afterOwnerUid: "",
      reason: run.stage === "removing" ? "inactive_player_removed" : "inactive_city_surrendered",
      nowMs,
    });
    transaction.set(run.receiptRef, {
      releasedCities: FieldValue.increment(1),
      consolidatedTroops: FieldValue.increment(troops),
      updatedAtMs: nowMs,
      updatedAt: FieldValue.serverTimestamp(),
    }, { merge: true });
    return { released: true, troops };
  });
}

async function releaseInactiveCamp(uid = "", campDoc = null, homeRef = null, run = {}, nowMs = Date.now()) {
  if (!campDoc?.ref) return { released: false, troops: 0 };
  return runTransactionWithInfrastructureRetry(async transaction => {
    const refs = [run.receiptRef, campDoc.ref];
    if (homeRef) refs.push(homeRef);
    const snapshots = await Promise.all(refs.map(ref => transaction.get(ref)));
    const receipt = snapshots[0].exists ? snapshots[0].data() || {} : {};
    const campSnap = snapshots[1];
    const homeSnap = homeRef ? snapshots[2] : null;
    if (
      receipt.status !== "processing"
      || receipt.stage !== run.stage
      || Math.floor(safeNumber(receipt.basisLastSeenAtMs, 0)) !== run.basisLastSeenAtMs
    ) {
      throw new HttpsError("aborted", "Inactive-player camp cleanup was superseded.");
    }
    if (!campSnap.exists) return { released: false, troops: 0 };
    const rawCamp = { id: campSnap.id, ...campSnap.data() };
    const camp = getRewardCampCombatTarget(rawCamp);
    if (!camp || getOwnerUid(camp) !== uid || !isCurrentInactivityAsset(rawCamp)) {
      return { released: false, troops: 0 };
    }
    const troops = homeRef ? getTargetOwnerTroops(camp, "camp") : 0;
    if (homeRef) {
      if (!homeSnap?.exists || getOwnerUid(homeSnap.data() || {}) !== uid) {
        throw new HttpsError("failed-precondition", "The inactive player's home base is no longer available.");
      }
      transaction.set(homeRef, cleanCityUpdate(homeSnap.data() || {}, getInactiveHomeTroopPatch(
        homeSnap.data() || {},
        troops,
        nowMs
      )), { merge: true });
    }
    const regionId = normalizeRegionId(rawCamp.regionId || getRegionIdFromOnlineIslandId(campDoc.ref.parent?.parent?.id));
    transaction.set(campDoc.ref, getInactiveCampNeutralPatch(rawCamp, nowMs), { merge: true });
    writeOwnershipChangeEvent(transaction, {
      eventId: `inactive_${run.stage}_${uid}_${camp.id}_${run.basisLastSeenAtMs}`,
      targetType: "camp",
      targetId: camp.id,
      regionId,
      beforeOwnerUid: uid,
      afterOwnerUid: "",
      reason: run.stage === "removing" ? "inactive_player_removed" : "inactive_camp_surrendered",
      nowMs,
    });
    transaction.set(run.receiptRef, {
      releasedCamps: FieldValue.increment(1),
      consolidatedTroops: FieldValue.increment(troops),
      updatedAtMs: nowMs,
      updatedAt: FieldValue.serverTimestamp(),
    }, { merge: true });
    return { released: true, troops };
  });
}

async function cancelInactiveArmy(uid = "", armyDoc = null, homeRef = null, run = {}, nowMs = Date.now()) {
  if (!armyDoc?.ref) return { canceled: false, troops: 0 };
  const queuedArmy = { id: armyDoc.id, ...armyDoc.data() };
  const targetCampRef = queuedArmy.targetType === "camp"
    ? campRefForRegion(queuedArmy.targetRegionId, queuedArmy.toId)
    : null;
  return runTransactionWithInfrastructureRetry(async transaction => {
    const refs = [run.receiptRef, armyDoc.ref];
    if (homeRef) refs.push(homeRef);
    if (targetCampRef) refs.push(targetCampRef);
    const snapshots = await Promise.all(refs.map(ref => transaction.get(ref)));
    const receipt = snapshots[0].exists ? snapshots[0].data() || {} : {};
    const armySnap = snapshots[1];
    let snapshotIndex = 2;
    const homeSnap = homeRef ? snapshots[snapshotIndex++] : null;
    const campSnap = targetCampRef ? snapshots[snapshotIndex] : null;
    if (
      receipt.status !== "processing"
      || receipt.stage !== run.stage
      || Math.floor(safeNumber(receipt.basisLastSeenAtMs, 0)) !== run.basisLastSeenAtMs
    ) {
      throw new HttpsError("aborted", "Inactive-player army cleanup was superseded.");
    }
    if (!armySnap.exists) return { canceled: false, troops: 0 };
    const army = { id: armySnap.id, ...armySnap.data() };
    if (army.status !== "active" || getOwnerUid(army) !== uid || !isCurrentWorldArmy(army)) {
      return { canceled: false, troops: 0 };
    }
    const troops = homeRef ? Math.max(0, Math.floor(safeNumber(army.troops, 0))) : 0;
    if (homeRef) {
      if (!homeSnap?.exists || getOwnerUid(homeSnap.data() || {}) !== uid) {
        throw new HttpsError("failed-precondition", "The inactive player's home base is no longer available.");
      }
      transaction.set(homeRef, cleanCityUpdate(homeSnap.data() || {}, getInactiveHomeTroopPatch(
        homeSnap.data() || {},
        troops,
        nowMs
      )), { merge: true });
    }
    const armyPatch = {
      status: "canceled",
      troops: 0,
      canceledAtMs: nowMs,
      canceledReason: run.stage === "removing" ? "inactive_player_removed" : "inactive_troops_consolidated",
      inactivityPolicyVersion: INACTIVITY_POLICY_VERSION,
      updatedAt: FieldValue.serverTimestamp(),
    };
    armyRefsForRegions(army.viewRegionIds || army.routeRegionIds || [], army.id)
      .forEach(ref => transaction.set(ref, armyPatch, { merge: true }));
    if (targetCampRef && campSnap?.exists) {
      const camp = campSnap.data() || {};
      const activeArmyIds = removeActiveCampArmyId(camp, army.id);
      transaction.set(targetCampRef, {
        activeArmyIds,
        state: getRewardCampState(activeArmyIds, safeString(camp.holderUid, 128)),
        updatedAt: FieldValue.serverTimestamp(),
      }, { merge: true });
    }
    transaction.set(run.receiptRef, {
      canceledArmies: FieldValue.increment(1),
      consolidatedTroops: FieldValue.increment(troops),
      updatedAtMs: nowMs,
      updatedAt: FieldValue.serverTimestamp(),
    }, { merge: true });
    return { canceled: true, troops };
  });
}

async function returnInactiveReinforcement(uid = "", reinforcementDoc = null, homeRef = null, run = {}, nowMs = Date.now()) {
  if (!reinforcementDoc?.ref) return { returned: false, troops: 0 };
  const queued = reinforcementDoc.data() || {};
  const targetRef = getReinforcementTargetRef(queued);
  return runTransactionWithInfrastructureRetry(async transaction => {
    const refs = [run.receiptRef, reinforcementDoc.ref];
    if (homeRef) refs.push(homeRef);
    if (targetRef) refs.push(targetRef);
    const snapshots = await Promise.all(refs.map(ref => transaction.get(ref)));
    const receipt = snapshots[0].exists ? snapshots[0].data() || {} : {};
    const reinforcementSnap = snapshots[1];
    let snapshotIndex = 2;
    const homeSnap = homeRef ? snapshots[snapshotIndex++] : null;
    const targetSnap = targetRef ? snapshots[snapshotIndex] : null;
    if (
      receipt.status !== "processing"
      || receipt.stage !== run.stage
      || Math.floor(safeNumber(receipt.basisLastSeenAtMs, 0)) !== run.basisLastSeenAtMs
    ) {
      throw new HttpsError("aborted", "Inactive-player reinforcement cleanup was superseded.");
    }
    if (!reinforcementSnap.exists) return { returned: false, troops: 0 };
    const reinforcement = reinforcementSnap.data() || {};
    if (
      reinforcement.status !== REINFORCEMENT_STATUS_STATIONED
      || safeString(reinforcement.ownerUid, 128) !== uid
      || safeString(reinforcement.worldId, 120) !== ONLINE_WORLD_ID
      || safeString(reinforcement.resetGeneration, 120) !== RESET_GENERATION
    ) {
      return { returned: false, troops: 0 };
    }
    const troops = homeRef ? Math.max(0, Math.floor(safeNumber(reinforcement.troops, 0))) : 0;
    if (homeRef) {
      if (!homeSnap?.exists || getOwnerUid(homeSnap.data() || {}) !== uid) {
        throw new HttpsError("failed-precondition", "The inactive player's home base is no longer available.");
      }
      transaction.set(homeRef, cleanCityUpdate(homeSnap.data() || {}, getInactiveHomeTroopPatch(
        homeSnap.data() || {},
        troops,
        nowMs
      )), { merge: true });
    }
    if (targetRef && targetSnap?.exists) {
      const target = targetSnap.data() || {};
      transaction.set(targetRef, {
        alliedReinforcementTroops: Math.max(
          0,
          getAlliedReinforcementTroops(target) - Math.max(0, Math.floor(safeNumber(reinforcement.troops, 0)))
        ),
        updatedAt: FieldValue.serverTimestamp(),
      }, { merge: true });
    }
    transaction.set(reinforcementDoc.ref, {
      troops: 0,
      status: REINFORCEMENT_STATUS_RETURNED,
      returnReason: run.stage === "removing" ? "inactive_player_removed" : "inactive_troops_consolidated",
      returnedAtMs: nowMs,
      updatedAt: FieldValue.serverTimestamp(),
    }, { merge: true });
    transaction.set(run.receiptRef, {
      returnedReinforcements: FieldValue.increment(1),
      consolidatedTroops: FieldValue.increment(troops),
      updatedAtMs: nowMs,
      updatedAt: FieldValue.serverTimestamp(),
    }, { merge: true });
    return { returned: true, troops };
  });
}

async function processInactivePlayerAssets(uid = "", run = {}, {
  consolidate = false,
  nowMs = Date.now(),
} = {}) {
  if (consolidate) await settleInactivePlayerProduction(uid, run, nowMs);
  const holdings = await loadInactivePlayerHoldings(uid);
  const homeRef = consolidate ? holdings.mainEntry?.ref || null : null;
  if (consolidate && !homeRef) {
    throw new HttpsError("failed-precondition", "The inactive player has no home base for troop consolidation.");
  }
  for (const reinforcementDoc of holdings.reinforcementDocs) {
    await returnInactiveReinforcement(uid, reinforcementDoc, homeRef, run, nowMs);
  }
  for (const armyDoc of holdings.armyDocs) {
    await cancelInactiveArmy(uid, armyDoc, homeRef, run, nowMs);
  }
  for (const campDoc of holdings.campDocs) {
    await releaseInactiveCamp(uid, campDoc, homeRef, run, nowMs);
  }
  for (const entry of holdings.cityEntries) {
    await releaseInactiveCity(uid, { ref: entry.ref, id: entry.city.id, data: () => entry.city }, homeRef, run, nowMs);
  }
  return { homeRef, holdings };
}

async function completeInactivePlayerSurrender(uid = "", run = {}, homeRef = null, nowMs = Date.now()) {
  const playerUid = safeString(uid, 128);
  await db.doc(`players/${playerUid}`).set({
    stationedReinforcementTroops: 0,
    activeClanReinforcementTargets: [],
    clanReinforcementLimitResetGeneration: RESET_GENERATION,
    updatedAt: FieldValue.serverTimestamp(),
  }, { merge: true });
  await rebuildGlobalStatsForPlayer(playerUid);
  return runTransactionWithInfrastructureRetry(async transaction => {
    const membershipRef = db.doc(`players/${playerUid}/serverMembership/current`);
    const profileRef = db.doc(`players/${playerUid}`);
    const refs = [run.receiptRef, membershipRef, profileRef];
    if (homeRef) refs.push(homeRef);
    const snapshots = await Promise.all(refs.map(ref => transaction.get(ref)));
    const receipt = snapshots[0].exists ? snapshots[0].data() || {} : {};
    const membership = snapshots[1].exists ? snapshots[1].data() || {} : {};
    const profileSnap = snapshots[2];
    const homeSnap = homeRef ? snapshots[3] : null;
    if (
      receipt.status !== "processing"
      || receipt.stage !== "surrendering"
      || Math.floor(safeNumber(receipt.basisLastSeenAtMs, 0)) !== run.basisLastSeenAtMs
    ) {
      throw new HttpsError("aborted", "Inactive-player surrender was superseded.");
    }
    if (
      !isCurrentInactivityMembership(membership)
      || Math.floor(safeNumber(membership.lastSeenAtMs, 0)) !== run.basisLastSeenAtMs
    ) {
      throw new HttpsError("aborted", "The player returned before inactive-player surrender completed.");
    }
    const releasedCities = Math.max(0, Math.floor(safeNumber(receipt.releasedCities, 0)));
    const releasedCamps = Math.max(0, Math.floor(safeNumber(receipt.releasedCamps, 0)));
    const consolidatedTroops = Math.max(0, Math.floor(safeNumber(receipt.consolidatedTroops, 0)));
    const home = homeSnap?.exists ? { id: homeSnap.id, ...homeSnap.data() } : {
      id: safeString(profileSnap.data()?.mainCityId, 96),
      name: "Main City",
      level: 1,
    };
    const report = makeReport({
      id: `inactive_surrender_${run.basisLastSeenAtMs}_${playerUid}`,
      uid: playerUid,
      type: "defense",
      outcome: "held",
      city: home,
      opponentName: "Realm inactivity policy",
      troopCount: consolidatedTroops,
      result: { survivors: consolidatedTroops, defendersLeft: consolidatedTroops },
      summary: `${releasedCities} cities and ${releasedCamps} camps were surrendered after 15 inactive days. ${consolidatedTroops.toLocaleString()} troops were secured at the main city.`,
      nowMs,
    });
    writeReport(transaction, playerUid, report, profileSnap, {
      inactivityNotice: {
        policyVersion: INACTIVITY_POLICY_VERSION,
        type: "territory-surrendered",
        occurredAtMs: nowMs,
        releasedCities,
        releasedCamps,
        consolidatedTroops,
      },
    });
    transaction.set(membershipRef, {
      status: "inactive",
      inactivityPolicyVersion: INACTIVITY_POLICY_VERSION,
      inactivityStage: "surrendered",
      basisLastSeenAtMs: run.basisLastSeenAtMs,
      surrenderedAtMs: nowMs,
      releasedCities,
      releasedCamps,
      consolidatedTroops,
      updatedAtMs: nowMs,
      updatedAt: FieldValue.serverTimestamp(),
    }, { merge: true });
    transaction.set(run.receiptRef, {
      status: "completed",
      stage: "surrendered",
      leaseUntilMs: 0,
      completedAtMs: nowMs,
      updatedAtMs: nowMs,
      updatedAt: FieldValue.serverTimestamp(),
    }, { merge: true });
    return { releasedCities, releasedCamps, consolidatedTroops };
  });
}

function compareInactiveClanSuccessors(a = {}, b = {}) {
  const aOfficer = a.role === "officer" ? 0 : 1;
  const bOfficer = b.role === "officer" ? 0 : 1;
  return aOfficer - bOfficer
    || Math.max(0, timestampToMs(a.joinedAtMs || a.joinedAt)) - Math.max(0, timestampToMs(b.joinedAtMs || b.joinedAt))
    || safeString(a.uid, 128).localeCompare(safeString(b.uid, 128));
}

async function getInactiveClanSuccessor(clanId = "", departingUid = "", nowMs = Date.now()) {
  const membersSnap = await db.collection(`clans/${safeString(clanId, 128)}/members`)
    .orderBy("joinedAtMs", "asc")
    .get();
  const candidates = membersSnap.docs
    .map(doc => ({ uid: doc.id, ...doc.data() }))
    .filter(member => member.uid !== departingUid);
  if (!candidates.length) return { successor: null, members: [] };
  const membershipSnaps = await db.getAll(...candidates.map(member => (
    db.doc(`players/${member.uid}/serverMembership/current`)
  )));
  const activeCandidates = candidates.filter((member, index) => {
    const membership = membershipSnaps[index]?.data() || {};
    const lastSeenAtMs = Math.max(0, Math.floor(safeNumber(membership.lastSeenAtMs, 0)));
    return isCurrentInactivityMembership(membership)
      && nowMs - lastSeenAtMs < INACTIVITY_SURRENDER_MS;
  }).sort(compareInactiveClanSuccessors);
  return { successor: activeCandidates[0] || null, members: candidates };
}

async function transferInactiveClanLeadership(clanId = "", departingUid = "", successorUid = "", nowMs = Date.now()) {
  const safeClanId = safeString(clanId, 128);
  const nextLeaderUid = safeString(successorUid, 128);
  if (!safeClanId || !nextLeaderUid) return false;
  return runTransactionWithInfrastructureRetry(async transaction => {
    const clanRef = db.doc(`clans/${safeClanId}`);
    const departingRef = db.doc(`clans/${safeClanId}/members/${departingUid}`);
    const successorRef = db.doc(`clans/${safeClanId}/members/${nextLeaderUid}`);
    const [clanSnap, departingSnap, successorSnap] = await Promise.all([
      transaction.get(clanRef),
      transaction.get(departingRef),
      transaction.get(successorRef),
    ]);
    if (
      !clanSnap.exists
      || !departingSnap.exists
      || !successorSnap.exists
      || safeString(clanSnap.data()?.leaderUid, 128) !== departingUid
    ) {
      return false;
    }
    transaction.set(clanRef, {
      leaderUid: nextLeaderUid,
      updatedAtMs: nowMs,
      updatedAt: FieldValue.serverTimestamp(),
    }, { merge: true });
    transaction.set(departingRef, {
      role: "officer",
      roleChangedAtMs: nowMs,
      updatedAt: FieldValue.serverTimestamp(),
    }, { merge: true });
    transaction.set(successorRef, {
      role: "leader",
      roleChangedAtMs: nowMs,
      updatedAt: FieldValue.serverTimestamp(),
    }, { merge: true });
    transaction.set(db.doc(`players/${departingUid}`), { clanRole: "officer" }, { merge: true });
    transaction.set(db.doc(`players/${nextLeaderUid}`), { clanRole: "leader" }, { merge: true });
    transaction.set(leaderboardEntryRef(departingUid), { clanRole: "officer" }, { merge: true });
    transaction.set(leaderboardEntryRef(nextLeaderUid), { clanRole: "leader" }, { merge: true });
    writeClanAudit(transaction, safeClanId, departingUid, "inactive_leadership_transferred", {
      targetUid: nextLeaderUid,
    }, nowMs);
    return true;
  });
}

async function removeInactivePlayerFromClan(uid = "", nowMs = Date.now()) {
  const playerUid = safeString(uid, 128);
  const profileSnap = await db.doc(`players/${playerUid}`).get();
  const profile = profileSnap.exists ? profileSnap.data() || {} : {};
  const clanId = safeString(profile.clanId, 128);
  if (!clanId) return { removed: false, disbanded: false, successorUid: "" };
  const [clanSnap, targetMemberSnap] = await Promise.all([
    db.doc(`clans/${clanId}`).get(),
    db.doc(`clans/${clanId}/members/${playerUid}`).get(),
  ]);
  if (!clanSnap.exists || !targetMemberSnap.exists) {
    await db.doc(`players/${playerUid}`).set({
      ...clanIdentityPatch(),
      pendingClanApplicationId: FieldValue.delete(),
      updatedAt: FieldValue.serverTimestamp(),
    }, { merge: true });
    return { removed: false, disbanded: false, successorUid: "" };
  }
  const clan = clanSnap.data() || {};
  const target = targetMemberSnap.data() || {};
  let successorUid = "";
  if (target.role === "leader" || safeString(clan.leaderUid, 128) === playerUid) {
    const { successor, members } = await getInactiveClanSuccessor(clanId, playerUid, nowMs);
    if (successor) {
      const transferred = await transferInactiveClanLeadership(clanId, playerUid, successor.uid, nowMs);
      if (transferred) successorUid = successor.uid;
    } else {
      for (const member of members) {
        await removeClanMember({
          actorUid: playerUid,
          targetUid: member.uid,
          clanId,
          reason: "inactive_clan_disbanded",
        });
      }
    }
  }
  const result = await removeClanMember({
    actorUid: playerUid,
    targetUid: playerUid,
    clanId,
    reason: "inactive_member_removed",
  });
  return {
    removed: true,
    disbanded: Boolean(result?.disbanded),
    successorUid,
  };
}

async function deleteDocumentsInBatches(docRefs = []) {
  const uniqueRefs = [...new Map(
    docRefs.filter(Boolean).map(ref => [ref.path, ref])
  ).values()];
  for (let index = 0; index < uniqueRefs.length; index += 400) {
    const batch = db.batch();
    uniqueRefs.slice(index, index + 400).forEach(ref => batch.delete(ref));
    await batch.commit();
  }
  return uniqueRefs.length;
}

async function purgeInactivePlayerArmyRecords(uid = "") {
  const playerUid = safeString(uid, 128);
  const [armySnap, reinforcementSnap] = await Promise.all([
    db.collection("armies").where("ownerUid", "==", playerUid).get(),
    db.collection("reinforcements").where("ownerUid", "==", playerUid).get(),
  ]);
  const deletions = [];
  armySnap.docs.forEach(doc => {
    const army = { id: doc.id, ...doc.data() };
    if (!isCurrentInactivityAsset(army)) return;
    armyRefsForRegions(army.viewRegionIds || army.routeRegionIds || [], doc.id)
      .forEach(ref => deletions.push(ref));
  });
  reinforcementSnap.docs.forEach(doc => {
    if (isCurrentInactivityAsset(doc.data() || {})) deletions.push(doc.ref);
  });
  return deleteDocumentsInBatches(deletions);
}

async function clearInactivePlayerWorldDocuments(uid = "") {
  const playerUid = safeString(uid, 128);
  const profileRef = db.doc(`players/${playerUid}`);
  const collections = await profileRef.listCollections();
  const deletions = [];
  for (const collectionRef of collections) {
    if (collectionRef.id === "serverMembership") continue;
    const snapshot = await collectionRef.get();
    snapshot.docs.forEach(doc => {
      const data = doc.data() || {};
      const currentWorldDocument = isCurrentInactivityAsset(data)
        || collectionRef.id === "notificationTokens"
        || (collectionRef.id === "saves" && doc.id === `default-${RESET_GENERATION}`)
        || ["stats", "objectiveStats", "rewardedAds", "rewardedAdIntents", "protectedDefenseXpClaims", "serverReports"]
          .includes(collectionRef.id);
      if (currentWorldDocument) deletions.push(doc.ref);
    });
  }
  const presenceSnap = await db.collectionGroup("presence")
    .where("uid", "==", playerUid)
    .get();
  presenceSnap.docs.forEach(doc => {
    if (isCurrentInactivityAsset(doc.data() || {})) deletions.push(doc.ref);
  });
  deletions.push(leaderboardEntryRef(playerUid));
  return deleteDocumentsInBatches(deletions);
}

async function replaceInactivePlayerProfile(uid = "", nowMs = Date.now()) {
  const playerUid = safeString(uid, 128);
  const profileRef = db.doc(`players/${playerUid}`);
  const profileSnap = await profileRef.get();
  const profile = profileSnap.exists ? profileSnap.data() || {} : {};
  const identity = {
    uid: playerUid,
    displayName: safeString(profile.displayName, 120),
    email: safeString(profile.email, 240),
    photoURL: safeString(profile.photoURL, 500),
    playerName: normalizePlayerName(profile.playerName || profile.displayName || "Ruler"),
    flag: normalizeServerFlag(profile.flag, playerUid) || PLAYER_FLAG_CONFIG.createDeterministicFlag(playerUid),
    inactivityNotice: {
      policyVersion: INACTIVITY_POLICY_VERSION,
      type: "world-slot-reset",
      occurredAtMs: nowMs,
    },
    worldSlotResetAtMs: nowMs,
    updatedAt: FieldValue.serverTimestamp(),
    ...(profile.createdAt ? { createdAt: profile.createdAt } : {}),
  };
  await profileRef.set(identity, { merge: false });
  return identity;
}

async function completeInactivePlayerRemoval(uid = "", run = {}, nowMs = Date.now()) {
  const playerUid = safeString(uid, 128);
  await removeInactivePlayerFromClan(playerUid, nowMs);
  await purgeInactivePlayerArmyRecords(playerUid);
  await clearInactivePlayerWorldDocuments(playerUid);
  await replaceInactivePlayerProfile(playerUid, nowMs);
  const serverRef = db.doc(`gameServers/${GAME_SERVER_DOCUMENT_ID}`);
  const membershipRef = db.doc(`players/${playerUid}/serverMembership/current`);
  return runTransactionWithInfrastructureRetry(async transaction => {
    const [receiptSnap, membershipSnap, serverSnap] = await Promise.all([
      transaction.get(run.receiptRef),
      transaction.get(membershipRef),
      transaction.get(serverRef),
    ]);
    const receipt = receiptSnap.exists ? receiptSnap.data() || {} : {};
    const membership = membershipSnap.exists ? membershipSnap.data() || {} : {};
    if (
      receipt.status !== "processing"
      || receipt.stage !== "removing"
      || Math.floor(safeNumber(receipt.basisLastSeenAtMs, 0)) !== run.basisLastSeenAtMs
    ) {
      throw new HttpsError("aborted", "Inactive-player removal was superseded.");
    }
    if (
      !isCurrentInactivityMembership(membership)
      || Math.floor(safeNumber(membership.lastSeenAtMs, 0)) !== run.basisLastSeenAtMs
    ) {
      throw new HttpsError("aborted", "The player returned before inactive-player removal completed.");
    }
    const state = createGameServerState(serverSnap.exists ? serverSnap.data() : {}, nowMs);
    delete state.activeSlots[playerUid];
    delete state.waitingQueue[playerUid];
    const promoted = promoteGameServerWaiters(state, nowMs);
    writeGameServerState(transaction, serverRef, state, nowMs);
    promoted.forEach(entry => writeGameServerMembership(transaction, entry, "active", nowMs));
    const releasedCities = Math.max(0, Math.floor(safeNumber(receipt.releasedCities, 0)));
    const releasedCamps = Math.max(0, Math.floor(safeNumber(receipt.releasedCamps, 0)));
    transaction.set(membershipRef, {
      serverId: GAME_SERVER_ID,
      serverName: GAME_SERVER_NAME,
      worldId: ONLINE_WORLD_ID,
      resetGeneration: RESET_GENERATION,
      releaseId: REALM_RELEASE_ID,
      status: "expired",
      sessionId: "",
      inactivityPolicyVersion: INACTIVITY_POLICY_VERSION,
      inactivityStage: "removed",
      basisLastSeenAtMs: run.basisLastSeenAtMs,
      removedAtMs: nowMs,
      releasedCities,
      releasedCamps,
      consolidatedTroops: 0,
      lastSeenAtMs: run.basisLastSeenAtMs,
      updatedAtMs: nowMs,
      updatedAt: FieldValue.serverTimestamp(),
    }, { merge: false });
    transaction.set(run.receiptRef, {
      status: "completed",
      stage: "removed",
      leaseUntilMs: 0,
      completedAtMs: nowMs,
      updatedAtMs: nowMs,
      updatedAt: FieldValue.serverTimestamp(),
    }, { merge: true });
    return { releasedCities, releasedCamps, promoted: promoted.length };
  });
}

async function failInactivePlayerMaintenance(uid = "", run = {}, error = null, nowMs = Date.now()) {
  if (!run?.receiptRef) return;
  await Promise.all([
    run.receiptRef.set({
      status: "failed",
      leaseUntilMs: 0,
      lastError: safeString(error?.message || error || "Unknown inactivity maintenance failure", 300),
      failedAtMs: nowMs,
      updatedAtMs: nowMs,
      updatedAt: FieldValue.serverTimestamp(),
    }, { merge: true }),
    db.doc(`players/${safeString(uid, 128)}/serverMembership/current`).set({
      inactivityStage: run.stage === "removing" ? "removal-failed" : "surrender-failed",
      updatedAtMs: nowMs,
      updatedAt: FieldValue.serverTimestamp(),
    }, { merge: true }),
  ]);
}

async function processInactivePlayerCandidate(candidate = {}, nowMs = Date.now()) {
  const uid = safeString(candidate.uid, 128);
  const lastSeenAtMs = Math.max(0, Math.floor(safeNumber(candidate.membership?.lastSeenAtMs, 0)));
  const targetStage = getInactivityTargetStage(lastSeenAtMs, nowMs);
  if (!uid || !targetStage) return { uid, status: "skipped", reason: "recent" };
  if (INACTIVITY_POLICY_MODE === "audit") {
    return {
      uid,
      status: "audit",
      targetStage,
      lastSeenAtMs,
      inactiveMs: Math.max(0, nowMs - lastSeenAtMs),
    };
  }
  const acquired = await beginInactivePlayerMaintenance(uid, targetStage, nowMs);
  if (!acquired.acquired) return { uid, status: "skipped", reason: acquired.reason };
  const run = {
    ...acquired,
    uid,
    stage: targetStage,
  };
  try {
    const assets = await processInactivePlayerAssets(uid, run, {
      consolidate: targetStage === "surrendering",
      nowMs,
    });
    const result = targetStage === "surrendering"
      ? await completeInactivePlayerSurrender(uid, run, assets.homeRef, nowMs)
      : await completeInactivePlayerRemoval(uid, run, nowMs);
    return { uid, status: "completed", stage: targetStage, ...result };
  } catch (error) {
    await failInactivePlayerMaintenance(uid, run, error, Date.now());
    throw error;
  }
}

async function maintainInactivePlayers(nowMs = Date.now()) {
  const candidates = await loadInactiveMembershipCandidates(nowMs);
  const results = [];
  await processWithConcurrency(candidates, INACTIVITY_PROCESS_CONCURRENCY, async candidate => {
    try {
      results.push(await processInactivePlayerCandidate(candidate, nowMs));
    } catch (error) {
      console.error("Inactive-player maintenance failed", {
        uid: candidate.uid,
        error: error?.message || String(error),
      });
      results.push({ uid: candidate.uid, status: "failed", error: error?.message || String(error) });
    }
  });
  return {
    policyVersion: INACTIVITY_POLICY_VERSION,
    mode: INACTIVITY_POLICY_MODE,
    scanned: candidates.length,
    completed: results.filter(result => result.status === "completed").length,
    audited: results.filter(result => result.status === "audit").length,
    skipped: results.filter(result => result.status === "skipped").length,
    failed: results.filter(result => result.status === "failed").length,
    results,
  };
}

function normalizePlayerName(value, fallback = "Ruler") {
  const cleaned = String(value || "")
    .replace(/[^a-z0-9 _.-]/gi, "")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, PLAYER_NAME_MAX_LENGTH);
  return cleaned || fallback;
}

const SERVER_WORLD_MAPS = Array.isArray(SERVER_WORLD_LAYOUT?.maps) ? SERVER_WORLD_LAYOUT.maps : [];
const SERVER_WORLD_MAP_BY_ID = new Map(SERVER_WORLD_MAPS.map(map => [safeString(map?.id, 80), map]));
const SERVER_WORLD_REGION_IDS = new Set(SERVER_WORLD_MAP_BY_ID.keys());
const SERVER_WORLD_OBJECTIVE_TARGETS = SERVER_WORLD_MAPS.flatMap(map => (
  Array.isArray(map?.objectives) ? map.objectives : []
).map(objective => ({
  id: safeString(objective?.id, 96),
  regionId: safeString(map?.id, 80),
  strongholdType: safeString(objective?.strongholdType || objective?.type, 32),
}))).filter(objective => objective.id && objective.regionId);
const SERVER_WORLD_OBJECTIVE_TARGET_KEYS = new Set(
  SERVER_WORLD_OBJECTIVE_TARGETS.map(objective => (
    `${normalizeRegionId(objective.regionId)}:${objective.id}`
  ))
);
const STARTER_REGION_IDS = Object.freeze(
  SERVER_WORLD_MAPS
    .filter(map => safeString(map?.type, 32).toLowerCase() === "starter")
    .map(map => normalizeRegionId(map.id))
);

function requireKnownWorldRegionId(regionId = "") {
  const normalized = normalizeRegionId(regionId);
  if (!SERVER_WORLD_REGION_IDS.has(normalized)) {
    throw new HttpsError("invalid-argument", "That Crownlands map does not exist.");
  }
  return normalized;
}

function getServerWorldMap(regionId = "") {
  return SERVER_WORLD_MAP_BY_ID.get(normalizeRegionId(regionId)) || null;
}

function getServerWorldTargetIds(regionId = "") {
  const map = getServerWorldMap(regionId);
  return new Set([
    ...(Array.isArray(map?.cities) ? map.cities : []),
    ...(Array.isArray(map?.objectives) ? map.objectives : []),
  ].map(target => safeString(target?.id, 96)).filter(Boolean));
}

function getServerWorldRegularCityIds(regionId = "") {
  const map = getServerWorldMap(regionId);
  return new Set((Array.isArray(map?.cities) ? map.cities : [])
    .map(city => safeString(city?.id, 96))
    .filter(Boolean));
}

const SERVER_MEDIEVAL_CITY_PREFIXES = [
  "Alder", "Ash", "Barrow", "Bell", "Black", "Briar", "Brindle", "Brook", "Cedar", "Crow",
  "Dun", "Elder", "Ember", "Fair", "Fen", "Flint", "Green", "Grey", "Hart", "High",
  "Iron", "Kings", "Low", "Oak", "Raven", "Red", "Silver", "Stone", "Thorn", "Vale",
  "White", "Wolf", "Wyvern",
];
const SERVER_MEDIEVAL_REGION_PREFIXES = {
  center: ["Crown", "Lion", "Regal", "Scepter", "Royal", "Queen", "King", "High", "Gold", "Star"],
  north: ["Frost", "Snow", "Pine", "Winter", "Storm", "Moon", "Peak", "Cold", "Cloud", "Hawk"],
  south: ["Sun", "Salt", "Reed", "Willow", "Rose", "Marsh", "Tide", "Warm", "Bloom", "Pearl"],
  west: ["Oak", "Thorn", "Fox", "Ash", "Briar", "Crow", "Wild", "Wood", "Moss", "Fern"],
  east: ["Dawn", "Gold", "Bright", "Falcon", "Rose", "Wind", "Star", "Pearl", "Blue", "Ivory"],
};
const SERVER_MEDIEVAL_CITY_SUFFIXES = [
  "bury", "ford", "wick", "stead", "mere", "brook", "hollow", "watch", "gate", "fall",
  "bridge", "market", "vale", "den", "field", "worth", "cross", "moor", "reach", "cliffe",
  "hurst", "wall", "ham", "port",
];
const SERVER_MEDIEVAL_CITY_TITLES = [
  "Abbey", "Cross", "Gate", "March", "Market", "Mead", "Moor", "Rest", "Rise", "Watch",
];

function hashServerCityName(value = "") {
  let hash = 2166136261;
  const text = String(value || "");
  for (let index = 0; index < text.length; index += 1) {
    hash ^= text.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return hash >>> 0;
}

function getServerCityNameIndex(cityId = "", fallbackIndex = 0) {
  const match = String(cityId || "").match(/_(\d+)$/);
  if (match) return Math.max(0, Math.floor(Number(match[1]) || 1) - 1);
  return Math.max(0, Math.floor(safeNumber(fallbackIndex, 0)));
}

function isServerGenericCityName(value = "", cityId = "") {
  const name = safeString(value, 80);
  if (!name) return true;
  if (/\d/.test(name)) return true;
  if (/^city(?:\s+|[-_])\d+$/i.test(name)) return true;
  return Boolean(cityId) && name.toLowerCase() === safeString(cityId, 96).toLowerCase();
}

function getServerCanonicalCityName(city = {}, regionId = "") {
  const cityId = safeString(city.id, 96);
  const normalizedRegionId = normalizeRegionId(regionId || city.regionId || city.startPool);
  const map = getServerWorldMap(normalizedRegionId);
  const mapCities = Array.isArray(map?.cities) ? map.cities : [];
  const mapIndex = mapCities.findIndex(entry => safeString(entry?.id, 96) === cityId);
  const mapCity = mapIndex >= 0 ? mapCities[mapIndex] : null;
  const configuredName = safeString(mapCity?.name || city.name, 80);
  if (!isServerGenericCityName(configuredName, cityId)) return configuredName;
  const cityIndex = getServerCityNameIndex(cityId, mapIndex >= 0 ? mapIndex : city.index);
  const prefixes = [...new Set([
    ...SERVER_MEDIEVAL_CITY_PREFIXES,
    ...(SERVER_MEDIEVAL_REGION_PREFIXES[normalizedRegionId] || []),
  ])];
  const comboCount = prefixes.length * SERVER_MEDIEVAL_CITY_SUFFIXES.length;
  const offset = hashServerCityName(`medieval-city:${normalizedRegionId}`) % comboCount;
  const comboIndex = (cityIndex * 487 + offset) % comboCount;
  const prefix = prefixes[comboIndex % prefixes.length];
  const suffix = SERVER_MEDIEVAL_CITY_SUFFIXES[
    Math.floor(comboIndex / prefixes.length) % SERVER_MEDIEVAL_CITY_SUFFIXES.length
  ];
  const title = SERVER_MEDIEVAL_CITY_TITLES[(cityIndex * 191 + offset) % SERVER_MEDIEVAL_CITY_TITLES.length];
  return cityIndex % 5 === 0 ? `${prefix}${suffix} ${title}` : `${prefix}${suffix}`;
}

function getServerWorldCampIds(regionId = "") {
  const map = getServerWorldMap(regionId);
  return new Set((Array.isArray(map?.camps) ? map.camps : [])
    .map(camp => safeString(camp?.id, 96))
    .filter(Boolean));
}

function getServerWorldDimensions() {
  const settings = SERVER_WORLD_LAYOUT?.globalSettings || {};
  return {
    width: Math.max(1000, Math.floor(safeNumber(settings.worldWidth, 13000))),
    height: Math.max(1000, Math.floor(safeNumber(settings.worldHeight, 17000))),
  };
}

function getServerMapImageDimensions(map = {}) {
  return {
    width: Math.max(1, Math.floor(safeNumber(map.imageWidth, 2048))),
    height: Math.max(1, Math.floor(safeNumber(map.imageHeight, 1536))),
  };
}

function getServerMapBounds(regionId = "") {
  const map = getServerWorldMap(regionId);
  if (!map) return null;
  const region = map.region || {};
  const dimensions = getServerMapImageDimensions(map);
  const world = getServerWorldDimensions();
  const aspect = Math.max(0.1, dimensions.width / Math.max(1, dimensions.height));
  const padding = Math.max(
    SERVER_ISLAND_MAP_PADDING,
    Math.round(Math.max(safeNumber(region.rx, 0), safeNumber(region.ry, 0)) * 0.22)
  );
  let width;
  let height;
  if (aspect >= 1) {
    width = Math.round((safeNumber(region.rx, 1000) + padding) * 2);
    height = Math.round(width / aspect);
  } else {
    height = Math.round((safeNumber(region.ry, 800) + padding) * 2);
    width = Math.round(height * aspect);
  }
  width = clamp(width, 1, world.width);
  height = clamp(height, 1, world.height);
  const left = clamp(Math.round(safeNumber(region.x, world.width / 2) - width / 2), 0, Math.max(0, world.width - width));
  const top = clamp(Math.round(safeNumber(region.y, world.height / 2) - height / 2), 0, Math.max(0, world.height - height));
  return { left, top, width, height, right: left + width, bottom: top + height };
}

function serverImagePointToWorld(regionId = "", point = {}) {
  const map = getServerWorldMap(regionId);
  const bounds = getServerMapBounds(regionId);
  if (!map || !bounds) return null;
  const dimensions = getServerMapImageDimensions(map);
  return {
    x: bounds.left + safeNumber(point.x, 0) / dimensions.width * bounds.width,
    y: bounds.top + safeNumber(point.y, 0) / dimensions.height * bounds.height,
  };
}

function getAuthoritativeIslandSeed(regionId = "") {
  const targetRegionId = requireKnownWorldRegionId(regionId);
  const map = getServerWorldMap(targetRegionId);
  const cities = (Array.isArray(map.cities) ? map.cities : []).map((city, index) => {
    const point = serverImagePointToWorld(targetRegionId, city);
    const id = city.id || `${targetRegionId}_${String(index + 1).padStart(3, "0")}`;
    return cleanServerCityLayoutSeed({
      ...city,
      id,
      name: getServerCanonicalCityName({ ...city, id, index }, targetRegionId),
      regionId: targetRegionId,
      startPool: targetRegionId,
      x: Math.round(point.x),
      y: Math.round(point.y),
      level: city.level || 1,
    });
  });
  (Array.isArray(map.objectives) ? map.objectives : []).forEach((objective, index) => {
    const point = serverImagePointToWorld(targetRegionId, objective);
    cities.push(cleanServerCityLayoutSeed({
      id: objective.id || `${targetRegionId}_stronghold_${index + 1}`,
      name: objective.name || objective.id,
      regionId: targetRegionId,
      startPool: targetRegionId,
      x: Math.round(point.x),
      y: Math.round(point.y),
      kind: "stronghold",
      strongholdType: objective.strongholdType || objective.type,
      bonus: objective.bonus,
      bonusPercent: objective.bonusPercent,
      size: getServerStrongholdVisualSize({
        id: objective.id || `${targetRegionId}_stronghold_${index + 1}`,
        strongholdType: objective.strongholdType || objective.type,
        kind: "stronghold",
      }),
      artSrc: objective.artSrc,
      startTroops: objective.startTroops || objective.troops,
      level: objective.level,
    }));
  });
  const camps = (Array.isArray(map.camps) ? map.camps : []).map((camp, index) => {
    const point = serverImagePointToWorld(targetRegionId, camp);
    return cleanServerCampLayoutSeed({
      id: camp.id || `${targetRegionId}_camp_${index + 1}`,
      name: camp.name || camp.id,
      regionId: targetRegionId,
      mapId: targetRegionId,
      x: Math.round(point.x),
      y: Math.round(point.y),
      size: DEFAULT_CAMP_VISUAL_SIZE,
      artSrc: camp.artSrc,
      campType: camp.campType || camp.type,
      rewardSchedule: camp.rewardSchedule,
      maxDailyRewards: camp.maxDailyRewards,
    });
  }).filter(camp => camp.id && isRewardCamp(camp));
  const world = getServerWorldDimensions();
  return {
    regionId: targetRegionId,
    islandId: getOnlineIslandId(targetRegionId),
    cities,
    camps,
    meta: {
      worldId: ONLINE_WORLD_ID,
      resetGeneration: RESET_GENERATION,
      releaseId: REALM_RELEASE_ID,
      regionId: targetRegionId,
      regionName: safeString(map.label || map.name || targetRegionId, 80),
      version: Math.max(1, Math.floor(safeNumber(SERVER_WORLD_LAYOUT.version, 1))),
      name: safeString(`${map.label || map.name || targetRegionId} - Crownlands`, 120),
      cityCount: cities.length,
      regionCount: SERVER_WORLD_MAPS.length,
      cityCountPerRegion: Math.max(0, Math.floor(safeNumber(map.cityCapacity, 0))),
      worldWidth: world.width,
      worldHeight: world.height,
    },
  };
}

function sanitizeJsonValue(value, depth = 0) {
  if (value === undefined || typeof value === "function" || typeof value === "symbol") return null;
  if (value === null || typeof value !== "object") return value;
  if (depth >= 6) return null;
  if (Array.isArray(value)) {
    return value.slice(0, 40).map(item => sanitizeJsonValue(item, depth + 1));
  }
  const output = {};
  Object.entries(value).slice(0, 80).forEach(([key, entry]) => {
    const cleanKey = safeString(key, 80);
    if (!cleanKey) return;
    const cleanValue = sanitizeJsonValue(entry, depth + 1);
    if (cleanValue !== undefined) output[cleanKey] = cleanValue;
  });
  return output;
}

function safeNumber(value, fallback = 0) {
  const number = Number(value);
  return Number.isFinite(number) ? number : fallback;
}

function clamp(value, min, max) {
  return Math.min(max, Math.max(min, value));
}

function clampInt(value, min, max) {
  return clamp(Math.floor(safeNumber(value, min)), min, max);
}

function clampCityLevel(level) {
  return clampInt(level, 1, Number.MAX_SAFE_INTEGER);
}

function isStronghold(city = {}) {
  return Boolean(city && (city.kind === "stronghold" || city.strongholdType || STRONGHOLD_IDS.has(city.id)));
}

function isGoldStronghold(city = {}) {
  const type = String(city.strongholdType || "").toLowerCase();
  return isStronghold(city) && (type === "gold" || type === "gold_stronghold" || city.id === GOLD_STRONGHOLD_ID);
}

function isTrainingStronghold(city = {}) {
  const type = String(city.strongholdType || "").toLowerCase();
  return isStronghold(city) && (type === "training" || type === "troop" || type === "troop_stronghold" || city.id === TRAINING_STRONGHOLD_ID);
}

function isSpeedStronghold(city = {}) {
  const type = String(city.strongholdType || "").toLowerCase();
  return isStronghold(city) && (type === "speed" || type === "march_speed" || type === "march_speed_stronghold" || city.id === SPEED_STRONGHOLD_ID);
}

function isDefenseStronghold(city = {}) {
  const type = String(city.strongholdType || "").toLowerCase();
  return isStronghold(city) && (type === "defense" || type === "defense_stronghold" || city.id === DEFENSE_STRONGHOLD_ID);
}

function isCrownCitadel(city = {}) {
  const type = String(city.strongholdType || "").toLowerCase();
  return isStronghold(city) && (type === "crown" || type === "crown_citadel" || city.id === CROWN_CITADEL_ID);
}

function getServerStrongholdVisualSize(city = {}) {
  return isCrownCitadel(city) ? CROWN_CITADEL_VISUAL_SIZE : DEFAULT_STRONGHOLD_VISUAL_SIZE;
}

function getPublicStrongholdSnapshot(city = {}) {
  if (!isStronghold(city)) return null;
  const id = safeString(city.id, 96);
  const fallbackNames = {
    [GOLD_STRONGHOLD_ID]: "Aurum Keep",
    [TRAINING_STRONGHOLD_ID]: "Greybanner Hold",
    [SPEED_STRONGHOLD_ID]: "Swiftgate",
    [DEFENSE_STRONGHOLD_ID]: "Ironwatch",
    [CROWN_CITADEL_ID]: "Crown Citadel",
  };
  return {
    id,
    name: safeString(city.name || fallbackNames[id] || "Stronghold", 80),
    strongholdType: safeString(city.strongholdType, 32),
    regionId: normalizeRegionId(city.regionId || ""),
  };
}

function crownCitadelReignRef(uid = "") {
  const safeUid = safeString(uid, 128).replace(/[^a-zA-Z0-9_-]/g, "_");
  return safeUid ? db.doc(`crownCitadelReigns/${RESET_GENERATION}/entries/${safeUid}`) : null;
}

function getCrownCitadelReignChangeRefs({
  citadel = {},
  previousOwnerUid = "",
  nextOwnerUid = "",
} = {}) {
  if (!isCrownCitadel(citadel)) return [];
  const oldUid = safeString(previousOwnerUid, 128);
  const newUid = safeString(nextOwnerUid, 128);
  if (oldUid === newUid) return [];
  return [...new Map([
    crownCitadelReignRef(oldUid),
    crownCitadelReignRef(newUid),
  ].filter(Boolean).map(ref => [ref.path, ref])).values()];
}

async function prefetchCrownCitadelReignSnapshots(transaction, change = {}) {
  const refs = getCrownCitadelReignChangeRefs(change);
  const snapshots = refs.length
    ? await Promise.all(refs.map(ref => transaction.get(ref)))
    : [];
  return new Map(snapshots.map(snapshot => [snapshot.ref.path, snapshot]));
}

function recordCrownCitadelControlChange(transaction, {
  citadel = {},
  previousOwnerUid = "",
  previousOwnerName = "",
  nextOwnerUid = "",
  nextOwnerName = "",
  nextOwnerFlag = null,
  nowMs = Date.now(),
  reignSnapshots = new Map(),
} = {}) {
  if (!transaction || !isCrownCitadel(citadel)) return;
  const oldUid = safeString(previousOwnerUid, 128);
  const newUid = safeString(nextOwnerUid, 128);
  if (oldUid === newUid) return;

  const oldRef = crownCitadelReignRef(oldUid);
  const newRef = crownCitadelReignRef(newUid);
  const refs = [...new Set([oldRef, newRef].filter(Boolean))];
  refs.forEach(ref => {
    if (!reignSnapshots.has(ref.path)) {
      throw new Error(`Crown Citadel reign snapshot was not prefetched: ${ref.path}`);
    }
  });

  if (oldRef) {
    const oldData = reignSnapshots.get(oldRef.path)?.data() || {};
    const isCurrentWorldRecord = safeString(oldData.worldId, 120) === ONLINE_WORLD_ID
      && safeString(oldData.resetGeneration, 120) === RESET_GENERATION;
    const recordedHeldSinceMs = isCurrentWorldRecord
      ? Math.max(0, Math.floor(safeNumber(oldData.currentHeldSinceMs, 0)))
      : 0;
    const heldSinceMs = recordedHeldSinceMs || Math.max(0, Math.floor(safeNumber(
      citadel.lastCapturedAtMs,
      timestampToMs(citadel.lastCapturedAt)
    )));
    const completedReignMs = heldSinceMs > 0 ? Math.max(0, nowMs - heldSinceMs) : 0;
    transaction.set(oldRef, {
      playerId: oldUid,
      playerName: normalizePlayerName(previousOwnerName || oldData.playerName, "Ruler"),
      playerFlag: oldData.playerFlag || citadel.ownerFlag || null,
      worldId: ONLINE_WORLD_ID,
      resetGeneration: RESET_GENERATION,
      totalHeldMs: (isCurrentWorldRecord ? Math.max(0, Math.floor(safeNumber(oldData.totalHeldMs, 0))) : 0) + completedReignMs,
      currentHeldSinceMs: 0,
      isCurrentHolder: false,
      lastLostAtMs: nowMs,
      updatedAtMs: nowMs,
      updatedAt: FieldValue.serverTimestamp(),
    }, { merge: true });
  }

  if (newRef) {
    const newData = reignSnapshots.get(newRef.path)?.data() || {};
    const isCurrentWorldRecord = safeString(newData.worldId, 120) === ONLINE_WORLD_ID
      && safeString(newData.resetGeneration, 120) === RESET_GENERATION;
    transaction.set(newRef, {
      playerId: newUid,
      playerName: normalizePlayerName(nextOwnerName || newData.playerName, "Ruler"),
      playerFlag: nextOwnerFlag || newData.playerFlag || null,
      worldId: ONLINE_WORLD_ID,
      resetGeneration: RESET_GENERATION,
      totalHeldMs: isCurrentWorldRecord ? Math.max(0, Math.floor(safeNumber(newData.totalHeldMs, 0))) : 0,
      currentHeldSinceMs: nowMs,
      isCurrentHolder: true,
      lastCapturedAtMs: nowMs,
      updatedAtMs: nowMs,
      updatedAt: FieldValue.serverTimestamp(),
    }, { merge: true });
  }
}

function isStrongholdLegacyTarget(stronghold = {}) {
  return isStronghold(stronghold) && !isCrownCitadel(stronghold);
}

function strongholdLegacyRef(stronghold = {}, uid = "") {
  if (!isStrongholdLegacyTarget(stronghold)) return null;
  const strongholdId = safeString(stronghold.id, 96).replace(/[^a-zA-Z0-9_-]/g, "_");
  const safeUid = safeString(uid, 128).replace(/[^a-zA-Z0-9_-]/g, "_");
  return strongholdId && safeUid
    ? db.doc(`strongholdLegacies/${RESET_GENERATION}/entries/${strongholdId}__${safeUid}`)
    : null;
}

function getStrongholdLegacyRefsForPlayer(uid = "") {
  return [...STRONGHOLD_IDS]
    .filter(strongholdId => strongholdId !== CROWN_CITADEL_ID)
    .map(strongholdId => strongholdLegacyRef({ id: strongholdId }, uid))
    .filter(Boolean);
}

function getStrongholdLegacyChangeRefs({
  stronghold = {},
  previousOwnerUid = "",
  nextOwnerUid = "",
} = {}) {
  if (!isStrongholdLegacyTarget(stronghold)) return [];
  const oldUid = safeString(previousOwnerUid, 128);
  const newUid = safeString(nextOwnerUid, 128);
  if (oldUid === newUid) return [];
  return [...new Map([
    strongholdLegacyRef(stronghold, oldUid),
    strongholdLegacyRef(stronghold, newUid),
  ].filter(Boolean).map(ref => [ref.path, ref])).values()];
}

async function prefetchStrongholdLegacySnapshots(transaction, change = {}) {
  const refs = getStrongholdLegacyChangeRefs(change);
  const snapshots = refs.length
    ? await Promise.all(refs.map(ref => transaction.get(ref)))
    : [];
  return new Map(snapshots.map(snapshot => [snapshot.ref.path, snapshot]));
}

function recordStrongholdLegacyControlChange(transaction, {
  stronghold = {},
  previousOwnerUid = "",
  previousOwnerName = "",
  nextOwnerUid = "",
  nextOwnerName = "",
  nextOwnerFlag = null,
  nowMs = Date.now(),
  legacySnapshots = new Map(),
} = {}) {
  if (!transaction || !isStrongholdLegacyTarget(stronghold)) return;
  const oldUid = safeString(previousOwnerUid, 128);
  const newUid = safeString(nextOwnerUid, 128);
  if (oldUid === newUid) return;

  const oldRef = strongholdLegacyRef(stronghold, oldUid);
  const newRef = strongholdLegacyRef(stronghold, newUid);
  const refs = [...new Set([oldRef, newRef].filter(Boolean))];
  refs.forEach(ref => {
    if (!legacySnapshots.has(ref.path)) {
      throw new Error(`Stronghold legacy snapshot was not prefetched: ${ref.path}`);
    }
  });
  const publicStronghold = getPublicStrongholdSnapshot(stronghold) || {};
  const commonFields = {
    strongholdId: safeString(publicStronghold.id || stronghold.id, 96),
    strongholdName: safeString(publicStronghold.name || stronghold.name || "Stronghold", 80),
    strongholdType: safeString(publicStronghold.strongholdType || stronghold.strongholdType, 32),
    regionId: normalizeRegionId(publicStronghold.regionId || stronghold.regionId),
    worldId: ONLINE_WORLD_ID,
    resetGeneration: RESET_GENERATION,
  };

  if (oldRef) {
    const oldData = legacySnapshots.get(oldRef.path)?.data() || {};
    const isCurrentWorldRecord = safeString(oldData.worldId, 120) === ONLINE_WORLD_ID
      && safeString(oldData.resetGeneration, 120) === RESET_GENERATION
      && safeString(oldData.strongholdId, 96) === commonFields.strongholdId;
    const recordedHeldSinceMs = isCurrentWorldRecord
      ? Math.max(0, Math.floor(safeNumber(oldData.currentHeldSinceMs, 0)))
      : 0;
    const heldSinceMs = recordedHeldSinceMs || Math.max(0, Math.floor(safeNumber(
      stronghold.lastCapturedAtMs,
      timestampToMs(stronghold.lastCapturedAt)
    )));
    const completedTenureMs = heldSinceMs > 0 ? Math.max(0, nowMs - heldSinceMs) : 0;
    transaction.set(oldRef, {
      ...commonFields,
      playerId: oldUid,
      playerName: normalizePlayerName(previousOwnerName || oldData.playerName, "Ruler"),
      playerFlag: oldData.playerFlag || stronghold.ownerFlag || null,
      totalHeldMs: (isCurrentWorldRecord ? Math.max(0, Math.floor(safeNumber(oldData.totalHeldMs, 0))) : 0)
        + completedTenureMs,
      currentHeldSinceMs: 0,
      isCurrentHolder: false,
      lastLostAtMs: nowMs,
      updatedAtMs: nowMs,
      updatedAt: FieldValue.serverTimestamp(),
    }, { merge: true });
  }

  if (newRef) {
    const newData = legacySnapshots.get(newRef.path)?.data() || {};
    const isCurrentWorldRecord = safeString(newData.worldId, 120) === ONLINE_WORLD_ID
      && safeString(newData.resetGeneration, 120) === RESET_GENERATION
      && safeString(newData.strongholdId, 96) === commonFields.strongholdId;
    transaction.set(newRef, {
      ...commonFields,
      playerId: newUid,
      playerName: normalizePlayerName(nextOwnerName || newData.playerName, "Ruler"),
      playerFlag: nextOwnerFlag || newData.playerFlag || null,
      totalHeldMs: isCurrentWorldRecord ? Math.max(0, Math.floor(safeNumber(newData.totalHeldMs, 0))) : 0,
      currentHeldSinceMs: nowMs,
      isCurrentHolder: true,
      lastCapturedAtMs: nowMs,
      updatedAtMs: nowMs,
      updatedAt: FieldValue.serverTimestamp(),
    }, { merge: true });
  }
}

function realmActivityEventRef(eventId = "") {
  const safeEventId = safeString(eventId, 180).replace(/[^a-zA-Z0-9_-]/g, "_");
  return safeEventId
    ? db.doc(`realmEvents/${RESET_GENERATION}/activity/${safeEventId}`)
    : null;
}

function getRealmActivityClanSnapshot(profile = {}, fallback = {}) {
  const clanId = safeString(profile.clanId || fallback.ownerClanId, 128);
  const clanName = safeString(profile.clanName || fallback.ownerClanName, 24);
  if (!clanId || !clanName) return null;
  return {
    clanId,
    clanName,
    clanTag: safeString(profile.clanTag || fallback.ownerClanTag, 5),
  };
}

function writeRealmActivityCaptureEvent(transaction, {
  eventId = "",
  sourceResolutionId = "",
  target = {},
  targetRegionId = "",
  previousOwnerUid = "",
  previousOwnerName = "",
  previousOwnerProfile = {},
  nextOwnerUid = "",
  nextOwnerName = "",
  nextOwnerProfile = {},
  nowMs = Date.now(),
} = {}) {
  if (!transaction || !isStronghold(target)) return null;
  const attackerPlayerId = safeString(nextOwnerUid, 128);
  const defenderPlayerId = safeString(previousOwnerUid, 128);
  if (!attackerPlayerId || attackerPlayerId === defenderPlayerId) return null;
  const ref = realmActivityEventRef(eventId);
  if (!ref) return null;

  const citadel = isCrownCitadel(target);
  const previousReignStartedAtMs = citadel
    ? Math.max(0, timestampToMs(target.lastCapturedAtMs || target.lastCapturedAt))
    : 0;
  const objective = getPublicStrongholdSnapshot(target) || {};
  const regionId = requireKnownWorldRegionId(targetRegionId || target.regionId);
  const attackerClan = getRealmActivityClanSnapshot(nextOwnerProfile);
  const defenderClan = defenderPlayerId
    ? getRealmActivityClanSnapshot(previousOwnerProfile, target)
    : null;
  const normalizedAttackerName = normalizePlayerName(
    nextOwnerName || nextOwnerProfile.playerName || nextOwnerProfile.displayName,
    "Ruler"
  );
  const normalizedDefenderName = defenderPlayerId
    ? normalizePlayerName(
      previousOwnerName || previousOwnerProfile.playerName || previousOwnerProfile.displayName || target.ownerName,
      "Ruler"
    )
    : "";

  transaction.set(ref, {
    schemaVersion: REALM_ACTIVITY_SCHEMA_VERSION,
    eventId: ref.id,
    eventType: citadel ? "CITADEL_CAPTURED" : "STRONGHOLD_CAPTURED",
    sourceResolutionId: safeString(sourceResolutionId, 160),
    worldId: ONLINE_WORLD_ID,
    resetGeneration: RESET_GENERATION,
    releaseId: REALM_RELEASE_ID,
    occurredAtMs: nowMs,
    createdAtMs: nowMs,
    createdAt: FieldValue.serverTimestamp(),
    objectiveId: safeString(target.id || objective.id, 96),
    objectiveType: citadel ? "crown_citadel" : "stronghold",
    objectiveName: safeString(objective.name || target.name || (citadel ? "Crown Citadel" : "Stronghold"), 80),
    strongholdType: safeString(target.strongholdType || objective.strongholdType, 32),
    regionId,
    x: safeNumber(target.x, 0),
    y: safeNumber(target.y, 0),
    attackerPlayerId,
    attackerPlayerName: normalizedAttackerName,
    attackerClanId: attackerClan?.clanId || "",
    attackerClanName: attackerClan?.clanName || "",
    attackerClanTag: attackerClan?.clanTag || "",
    defenderPlayerId,
    defenderPlayerName: normalizedDefenderName,
    defenderClanId: defenderClan?.clanId || "",
    defenderClanName: defenderClan?.clanName || "",
    defenderClanTag: defenderClan?.clanTag || "",
    newKingPlayerId: citadel ? attackerPlayerId : "",
    previousKingPlayerId: citadel ? defenderPlayerId : "",
    previousReignStartedAtMs,
  }, { merge: false });
  return ref;
}

function getStrongholdBonusPercent(city = {}) {
  if (isCrownCitadel(city)) return CROWN_CITADEL_GOLD_BONUS_PERCENT;
  if (isDefenseStronghold(city)) return DEFENSE_STRONGHOLD_BONUS_PERCENT;
  if (isSpeedStronghold(city)) return SPEED_STRONGHOLD_BONUS_PERCENT;
  if (isTrainingStronghold(city)) return TRAINING_STRONGHOLD_BONUS_PERCENT;
  if (isGoldStronghold(city)) return GOLD_STRONGHOLD_BONUS_PERCENT;
  return Number.isFinite(Number(city.bonusPercent)) ? Math.max(0, Math.floor(Number(city.bonusPercent) || 0)) : 0;
}

function getStrongholdDefenseLevel(city = {}) {
  if (!isStronghold(city)) return 0;
  return clampCityLevel(city.level || STRONGHOLD_LEVELS[city.id] || 50);
}

function normalizeSkillLevel(value) {
  return Math.max(0, Math.floor(safeNumber(value, 0)));
}

function getSkillMaxLevel(skill = "") {
  const config = SKILL_CONFIG[skill];
  if (!config || !Number.isFinite(config.maxPercent)) return Number.MAX_SAFE_INTEGER;
  return Math.max(0, Math.ceil(config.maxPercent / Math.max(1, config.percentPerLevel)));
}

function normalizeSkillLevelForSkill(skill = "", value = 0) {
  return Math.min(normalizeSkillLevel(value), getSkillMaxLevel(skill));
}

function normalizeSkillUpgrades(upgrades = {}) {
  const source = upgrades && typeof upgrades === "object" ? upgrades : {};
  const normalized = SKILL_ORDER.reduce((skills, key) => {
    skills[key] = normalizeSkillLevel(source[key]);
    return skills;
  }, {});

  const legacyAttack = Math.max(normalizeSkillLevel(source.striker), normalizeSkillLevel(source.attack));
  const legacyIncome = Math.max(normalizeSkillLevel(source.prosperous), normalizeSkillLevel(source.income));
  const legacyTroops = Math.max(normalizeSkillLevel(source.recruiter), normalizeSkillLevel(source.income));
  const legacyDefense = Math.max(normalizeSkillLevel(source.guardian), normalizeSkillLevel(source.defense));
  const legacySpeed = Math.max(normalizeSkillLevel(source.rusher), normalizeSkillLevel(source.speed));
  const legacyRecovery = Math.max(normalizeSkillLevel(source.fearless), normalizeSkillLevel(source.brave));

  normalized.swordmastery = Math.max(normalized.swordmastery, legacyAttack);
  normalized.taxStewardship = Math.max(normalized.taxStewardship, legacyIncome);
  normalized.royalGranaries = Math.max(normalized.royalGranaries, legacyTroops);
  normalized.stoneworks = Math.max(normalized.stoneworks, legacyDefense);
  normalized.marchOrders = Math.max(normalized.marchOrders, legacySpeed);
  normalized.fieldMedics = Math.max(normalized.fieldMedics, legacyRecovery);
  SKILL_ORDER.forEach(key => {
    normalized[key] = normalizeSkillLevelForSkill(key, normalized[key]);
  });
  return normalized;
}

function getSpentSkillPoints(upgrades = {}) {
  const normalized = normalizeSkillUpgrades(upgrades);
  return SKILL_ORDER.reduce((total, key) => total + normalizeSkillLevel(normalized[key]), 0);
}

function getEarnedSkillPoints(character = {}) {
  return Math.max(0, Math.floor(safeNumber(character?.level, CHARACTER_START_LEVEL)) - 1);
}

function getAvailableSkillPoints(character = {}, upgrades = {}) {
  return Math.max(0, getEarnedSkillPoints(character) - getSpentSkillPoints(upgrades));
}

function normalizeFreeSkillResetState(profile = {}) {
  const storedVersion = Math.max(0, Math.floor(safeNumber(profile.freeSkillResetGrantVersion, 0)));
  const storedCredits = Math.max(0, Math.floor(safeNumber(profile.freeSkillResetCredits, 0)));
  if (storedVersion >= DEFENSE_SKILL_FREE_RESET_GRANT_VERSION) {
    return { version: storedVersion, credits: storedCredits };
  }
  const createdAtMs = timestampToMs(profile.createdAtMs || profile.createdAt);
  const eligible = !createdAtMs || createdAtMs < DEFENSE_SKILL_FREE_RESET_ROLLOUT_AT_MS;
  return {
    version: DEFENSE_SKILL_FREE_RESET_GRANT_VERSION,
    credits: storedCredits + (eligible ? 1 : 0),
  };
}

function reconcileSkillPoints(character = {}, upgrades = {}) {
  const next = normalizeCharacterProgress(character);
  next.skillPoints = getAvailableSkillPoints(next, upgrades);
  return next;
}

function getSkillPresetSlotDefinition(slot = 0) {
  const normalizedSlot = Math.floor(safeNumber(slot, 0));
  return SKILL_PRESET_SLOTS.find(entry => entry.slot === normalizedSlot) || null;
}

function normalizeSkillPresetName(value = "", slot = 1) {
  const fallback = `Preset ${Math.max(1, Math.floor(safeNumber(slot, 1)))}`;
  const cleaned = String(value || "")
    .replace(/[\u0000-\u001f\u007f]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
  return safeString(cleaned || fallback, SKILL_PRESET_NAME_MAX_LENGTH) || fallback;
}

function requireSkillPresetName(value = "", slot = 1) {
  const raw = String(value || "")
    .replace(/[\u0000-\u001f\u007f]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
  if (!raw) throw new HttpsError("invalid-argument", "Enter a preset name.");
  if ([...raw].length > SKILL_PRESET_NAME_MAX_LENGTH) {
    throw new HttpsError(
      "invalid-argument",
      `Preset names can contain at most ${SKILL_PRESET_NAME_MAX_LENGTH} characters.`
    );
  }
  return normalizeSkillPresetName(raw, slot);
}

function normalizeSkillPresetAllocation(upgrades = {}) {
  const source = upgrades && typeof upgrades === "object" ? upgrades : {};
  return SKILL_ORDER.reduce((allocation, skill) => {
    allocation[skill] = normalizeSkillLevel(source[skill]);
    return allocation;
  }, {});
}

function normalizeSkillPresets(value = {}) {
  const source = value && typeof value === "object" ? value : {};
  const rawSlots = Array.isArray(source.slots) ? source.slots : [];
  const slots = SKILL_PRESET_SLOTS.map(definition => {
    const raw = rawSlots.find(entry => Math.floor(safeNumber(entry?.slot, 0)) === definition.slot) || {};
    const saved = raw.saved === true && raw.upgrades && typeof raw.upgrades === "object";
    const upgrades = saved ? normalizeSkillPresetAllocation(raw.upgrades) : null;
    return {
      slot: definition.slot,
      unlockLevel: definition.unlockLevel,
      name: normalizeSkillPresetName(raw.name, definition.slot),
      saved,
      upgrades,
      spentPoints: saved ? getSpentSkillPoints(upgrades) : 0,
      savedAtMs: saved ? Math.max(0, timestampToMs(raw.savedAtMs)) : 0,
    };
  });
  const requestedActiveSlot = Math.floor(safeNumber(source.activeSlot, 0));
  return {
    modelVersion: SKILL_PRESET_MODEL_VERSION,
    activeSlot: slots.some(slot => slot.slot === requestedActiveSlot && slot.saved) ? requestedActiveSlot : 0,
    slots,
  };
}

function replaceSkillPresetSlot(presets = {}, nextSlot = {}) {
  const normalized = normalizeSkillPresets(presets);
  return normalizeSkillPresets({
    modelVersion: SKILL_PRESET_MODEL_VERSION,
    activeSlot: normalized.activeSlot,
    slots: normalized.slots.map(slot => slot.slot === nextSlot.slot ? { ...slot, ...nextSlot } : slot),
  });
}

function setActiveSkillPresetSlot(presets = {}, slotNumber = 0) {
  const normalized = normalizeSkillPresets(presets);
  return normalizeSkillPresets({
    ...normalized,
    activeSlot: Math.floor(safeNumber(slotNumber, 0)),
  });
}

function skillPresetAllocationsMatch(left = {}, right = {}) {
  const first = normalizeSkillPresetAllocation(left);
  const second = normalizeSkillPresetAllocation(right);
  return SKILL_ORDER.every(skill => first[skill] === second[skill]);
}

function isValidSkillPresetAllocation(upgrades = null, character = {}) {
  if (!upgrades || typeof upgrades !== "object") return false;
  const allocation = normalizeSkillPresetAllocation(upgrades);
  const hasInvalidLevel = SKILL_ORDER.some(skill => {
    const rawLevel = Number(upgrades[skill]);
    return !Number.isFinite(rawLevel)
      || rawLevel < 0
      || Math.floor(rawLevel) !== rawLevel
      || allocation[skill] > getSkillMaxLevel(skill);
  });
  return !hasInvalidLevel && getSpentSkillPoints(allocation) <= getEarnedSkillPoints(character);
}

function requireUnlockedSkillPresetSlot(slot = 0, character = {}) {
  const definition = getSkillPresetSlotDefinition(slot);
  if (!definition) throw new HttpsError("invalid-argument", "Choose a valid skill preset tab.");
  const level = Math.max(1, Math.floor(safeNumber(character?.level, CHARACTER_START_LEVEL)));
  if (level < definition.unlockLevel) {
    throw new HttpsError(
      "failed-precondition",
      `Preset ${definition.slot} unlocks at Hero Level ${definition.unlockLevel}.`
    );
  }
  return definition;
}

function getSkillLevel(profile = {}, skill = "") {
  return normalizeSkillUpgrades(profile?.upgrades)[skill] || 0;
}

function getSkillPercent(profile = {}, skill = "") {
  const config = SKILL_CONFIG[skill];
  if (!config) return 0;
  const raw = getSkillLevel(profile, skill) * config.percentPerLevel;
  return Number.isFinite(config.maxPercent) ? Math.min(raw, config.maxPercent) : raw;
}

function skillMultiplier(profile = {}, skill = "") {
  return Number((1 + getSkillPercent(profile, skill) / 100).toFixed(3));
}

function getMillionLordsCityProductionVp(level) {
  const normalizedLevel = clampCityLevel(level);
  const rawValue = MILLION_LORDS_CITY_PRODUCTION_VP_BASE
    * Math.pow(MILLION_LORDS_CITY_PRODUCTION_VP_GROWTH, normalizedLevel - 1);
  if (!Number.isFinite(rawValue)) return Number.MAX_SAFE_INTEGER;
  return Math.min(Number.MAX_SAFE_INTEGER, Math.max(0, Math.floor(rawValue + 0.000001)));
}

function getMillionLordsPassiveGoldPerHour(level) {
  const normalizedLevel = clampCityLevel(level);
  const curveLevel = Math.min(normalizedLevel, CITY_GOLD_ENDGAME_START_LEVEL);
  const level100Base = getMillionLordsCityProductionVp(curveLevel)
    * MILLION_LORDS_PASSIVE_GOLD_PER_CITY_VP;
  const endgameMultiplier = normalizedLevel > CITY_GOLD_ENDGAME_START_LEVEL
    ? Math.pow(CITY_GOLD_ENDGAME_GROWTH, normalizedLevel - CITY_GOLD_ENDGAME_START_LEVEL)
    : 1;
  const rawGold = level100Base * endgameMultiplier;
  if (!Number.isFinite(rawGold)) return Number.MAX_SAFE_INTEGER;
  return Math.min(Number.MAX_SAFE_INTEGER, Math.max(0, Math.floor(rawGold)));
}

function calculateGoldProductionRates(
  baseGoldProductionPerHour = 0,
  taxStewardshipPercent = 0,
  strongholdGoldBonusPercent = 0,
  royalTaxDecreeGoldBonusPercent = 0
) {
  const base = Number.isFinite(Number(baseGoldProductionPerHour))
    ? Math.max(0, Number(baseGoldProductionPerHour))
    : 0;
  const taxPercent = Number.isFinite(Number(taxStewardshipPercent))
    ? Math.max(0, Number(taxStewardshipPercent))
    : 0;
  const strongholdPercent = Number.isFinite(Number(strongholdGoldBonusPercent))
    ? Math.max(0, Number(strongholdGoldBonusPercent))
    : 0;
  const royalTaxPercent = Number.isFinite(Number(royalTaxDecreeGoldBonusPercent))
    ? Math.max(0, Number(royalTaxDecreeGoldBonusPercent))
    : 0;
  const untimedGoldProductionPerHour = base * (1 + (taxPercent + strongholdPercent) / 100);
  const goldProductionPerHour = untimedGoldProductionPerHour + base * royalTaxPercent / 100;
  return {
    baseGoldProductionPerHour: base,
    untimedGoldProductionPerHour,
    goldProductionPerHour,
    goldProductionBonusPerHour: Math.max(0, goldProductionPerHour - base),
  };
}

function calculateTroopProductionRates(
  baseTroopProductionPerHour = 0,
  royalGranariesPercent = 0,
  strongholdTroopBonusPercent = 0,
  warDrumsTroopBonusPercent = 0
) {
  const base = Number.isFinite(Number(baseTroopProductionPerHour))
    ? Math.max(0, Number(baseTroopProductionPerHour))
    : 0;
  const granariesPercent = Number.isFinite(Number(royalGranariesPercent))
    ? Math.max(0, Number(royalGranariesPercent))
    : 0;
  const strongholdPercent = Number.isFinite(Number(strongholdTroopBonusPercent))
    ? Math.max(0, Number(strongholdTroopBonusPercent))
    : 0;
  const warDrumsPercent = Number.isFinite(Number(warDrumsTroopBonusPercent))
    ? Math.max(0, Number(warDrumsTroopBonusPercent))
    : 0;
  const untimedTroopProductionPerHour = base * (1 + (granariesPercent + strongholdPercent) / 100);
  const troopProductionPerHour = untimedTroopProductionPerHour + base * warDrumsPercent / 100;
  return {
    baseTroopProductionPerHour: base,
    untimedTroopProductionPerHour,
    troopProductionPerHour,
    troopProductionBonusPerHour: Math.max(0, troopProductionPerHour - base),
  };
}

function getCityProductionStats(city = {}, profile = {}, bonuses = {}, options = {}) {
  const stronghold = isStronghold(city);
  const level = stronghold ? getStrongholdDefenseLevel(city) : clampCityLevel(city.level);
  const victoryPoints = Math.floor(
    CITY_LEVEL_STATS.victoryPointsBase
      + level * CITY_LEVEL_STATS.victoryPointsPerLevel
      + Math.pow(level, CITY_LEVEL_STATS.victoryPointsExponent) * CITY_LEVEL_STATS.victoryPointsExponentScale
  );
  const includeSkillBoosts = options.includeSkillBoosts !== false;
  const includeStrongholdBoosts = options.includeStrongholdBoosts !== false;
  const gearBonuses = getCommonGearBonuses(profile);
  const royalGranariesPercent = includeSkillBoosts ? getSkillPercent(profile, "royalGranaries") : 0;
  const taxStewardshipPercent = includeSkillBoosts ? getSkillPercent(profile, "taxStewardship") : 0;
  const strongholdTroopBonusPercent = includeStrongholdBoosts
    ? Math.max(0, safeNumber(bonuses.troopBonusPercent, 0))
    : 0;
  const strongholdGoldBonusPercent = includeStrongholdBoosts
    ? Math.max(0, safeNumber(bonuses.goldBonusPercent, 0))
    : 0;
  const nowMs = Math.max(0, safeNumber(options.nowMs, Date.now()));
  const warDrumsExpiresAtMs = Math.max(0, Math.floor(safeNumber(profile?.itemEffects?.warDrumsExpiresAtMs, 0)));
  const warDrumsTroopBonusPercent = options.includeWarDrums !== false && !stronghold && warDrumsExpiresAtMs > nowMs
    ? WAR_DRUMS_TROOP_PRODUCTION_BONUS_PERCENT
    : 0;
  const royalTaxDecreeExpiresAtMs = Math.max(0, Math.floor(safeNumber(profile?.itemEffects?.royalTaxDecreeExpiresAtMs, 0)));
  const royalTaxDecreeGoldBonusPercent = options.includeRoyalTaxDecree !== false && !stronghold && royalTaxDecreeExpiresAtMs > nowMs
    ? ROYAL_TAX_DECREE_GOLD_PRODUCTION_BONUS_PERCENT
    : 0;
  const rawTroopProductionPerHour = stronghold ? 0 : victoryPoints * CITY_LEVEL_STATS.troopProductionPerVictoryPoint;
  const {
    baseTroopProductionPerHour,
    untimedTroopProductionPerHour,
    troopProductionPerHour,
    troopProductionBonusPerHour,
  } = calculateTroopProductionRates(
    rawTroopProductionPerHour,
    royalGranariesPercent + gearBonuses.troopProductionAllCities,
    strongholdTroopBonusPercent,
    warDrumsTroopBonusPercent
  );
  const rawGoldProductionPerHour = stronghold ? 0 : getMillionLordsPassiveGoldPerHour(level);
  const isMainCity = !stronghold && safeString(city.id, 96) === safeString(profile?.mainCityId, 96);
  const gearGoldProductionPercent = gearBonuses.goldProductionAllCities
    + (isMainCity ? gearBonuses.goldProductionMainCity : 0);
  const {
    baseGoldProductionPerHour,
    untimedGoldProductionPerHour,
    goldProductionPerHour,
    goldProductionBonusPerHour,
  } = calculateGoldProductionRates(
    rawGoldProductionPerHour,
    taxStewardshipPercent + gearGoldProductionPercent,
    strongholdGoldBonusPercent,
    royalTaxDecreeGoldBonusPercent
  );

  return {
    level,
    victoryPoints,
    baseTroopProductionPerHour,
    untimedTroopProductionPerHour,
    troopProductionPerHour,
    troopProductionBonusPerHour,
    baseGoldProductionPerHour,
    untimedGoldProductionPerHour,
    goldProductionPerHour,
    goldProductionBonusPerHour,
    royalGranariesPercent,
    taxStewardshipPercent,
    strongholdTroopBonusPercent,
    strongholdGoldBonusPercent,
    warDrumsTroopBonusPercent,
    royalTaxDecreeGoldBonusPercent,
    gearTroopProductionPercent: gearBonuses.troopProductionAllCities,
    gearGoldProductionPercent,
    troopProductionPerSecond: troopProductionPerHour / 3600,
    goldProductionPerSecond: goldProductionPerHour / 3600,
  };
}

function getBaseCityWalls(level) {
  const normalizedLevel = clampCityLevel(level);
  const levelOffset = normalizedLevel - 1;
  const walls = CITY_LEVEL_STATS.cityWallsBase
    + CITY_LEVEL_STATS.cityWallsPerLevel * levelOffset;
  if (!Number.isFinite(walls)) return Number.MAX_SAFE_INTEGER;
  return Math.min(Number.MAX_SAFE_INTEGER, Math.max(0, Math.floor(walls)));
}

function getSiegeRepairWindowMinutes(level) {
  const normalizedLevel = clampCityLevel(level);
  const minutes = Math.round(
    SIEGE_REPAIR_BASE_MINUTES + normalizedLevel * SIEGE_REPAIR_MINUTES_PER_LEVEL
  );
  if (!Number.isFinite(minutes)) return Number.MAX_SAFE_INTEGER;
  return Math.min(Number.MAX_SAFE_INTEGER, Math.max(1, minutes));
}

function getSiegeRepairTiming(
  level,
  wallDamagePower,
  fullWallPower,
  currentRepairAtMs = 0,
  nowMs = Date.now(),
  reductionPercent = 0
) {
  const repairWindowMinutes = getSiegeRepairWindowMinutes(level);
  const damagePower = Math.max(0, safeNumber(wallDamagePower, 0));
  const maximumPower = Math.max(0, safeNumber(fullWallPower, 0));
  const damageShare = maximumPower > 0 ? clamp(damagePower / maximumPower, 0, 1) : 0;
  const reduction = clamp(safeNumber(reductionPercent, 0), 0, 100);
  const fullRepairWindowMs = Math.min(
    Number.MAX_SAFE_INTEGER,
    repairWindowMinutes * 60_000
  );
  const repairAddedMs = Math.max(
    0,
    Math.round(fullRepairWindowMs * damageShare * (1 - reduction / 100))
  );
  const startedAtMs = Math.max(0, Math.floor(safeNumber(nowMs, Date.now())));
  const existingDeadlineMs = Math.max(0, timestampToMs(currentRepairAtMs));
  const extensionBaseMs = existingDeadlineMs > startedAtMs ? existingDeadlineMs : startedAtMs;
  return {
    repairWindowMinutes,
    repairReductionPercent: reduction,
    repairAddedMs,
    repairAtMs: Math.min(Number.MAX_SAFE_INTEGER, extensionBaseMs + repairAddedMs),
  };
}

function getSiegeRepairLevel(target = {}) {
  return isStronghold(target) ? getStrongholdDefenseLevel(target) : clampCityLevel(target.level);
}

function usesSoldierDefenseModel(version = DEFENSE_COMBAT_VERSION, city = {}) {
  return !isRewardCamp(city) && Math.floor(safeNumber(version, 0)) >= DEFENSE_COMBAT_VERSION;
}

function getObjectiveTroopDefenseBonusPercent(value = {}) {
  if (!value || typeof value !== "object") return 0;
  return Math.max(0, safeNumber(
    value.objectiveTroopDefenseBonusPercent,
    safeNumber(
      value.troopDefenseBonusPercent,
      safeNumber(value.strongholdDefenseBonusPercent, value.cityDefenseBonusPercent)
    )
  ));
}

function getCityStats(city = {}, defenderProfile = null, bonuses = {}, options = {}) {
  const stronghold = isStronghold(city);
  const rewardCamp = isRewardCamp(city);
  const level = rewardCamp ? 0 : stronghold ? getStrongholdDefenseLevel(city) : clampCityLevel(city.level);
  const victoryPoints = rewardCamp ? 0 : Math.floor(
    CITY_LEVEL_STATS.victoryPointsBase
      + level * CITY_LEVEL_STATS.victoryPointsPerLevel
      + Math.pow(level, CITY_LEVEL_STATS.victoryPointsExponent) * CITY_LEVEL_STATS.victoryPointsExponentScale
  );
  const defenseCombatVersion = Math.max(0, Math.floor(safeNumber(
    options.defenseCombatVersion,
    DEFENSE_COMBAT_VERSION
  )));
  const soldierDefenseEnabled = usesSoldierDefenseModel(defenseCombatVersion, city);
  const defensePercent = soldierDefenseEnabled || rewardCamp ? 0 : level * 2;
  const baseCityWalls = rewardCamp ? 0 : getBaseCityWalls(level);
  const gearBonuses = defenderProfile ? getCommonGearBonuses(defenderProfile) : {};
  const stoneworksPercent = !rewardCamp && defenderProfile ? getSkillPercent(defenderProfile, "stoneworks") : 0;
  const gearWallStrengthPercent = rewardCamp ? 0 : Math.max(0, safeNumber(gearBonuses.wallStrength, 0));
  const cityWalls = Math.floor(
    baseCityWalls + baseCityWalls * (stoneworksPercent + gearWallStrengthPercent) / 100
  );
  const troopCount = Math.max(0, Math.floor(safeNumber(city.troops, 0)));
  const shieldwallDisciplinePercent = soldierDefenseEnabled && defenderProfile
    ? getSkillPercent(defenderProfile, "shieldwallDiscipline")
    : 0;
  const objectiveTroopDefenseBonusPercent = rewardCamp ? 0 : getObjectiveTroopDefenseBonusPercent(bonuses);
  const gearDefenderStrengthPercent = rewardCamp ? 0 : Math.max(0, safeNumber(gearBonuses.defenderStrength, 0));
  const baseTroopDefense = rewardCamp
    ? Math.floor(troopCount * REWARD_CAMP_TROOP_POWER)
    : soldierDefenseEnabled
      ? Math.floor(troopCount * BASE_TROOP_DEFENSE_POWER)
      : troopCount;
  const troopDefenseBeforeObjective = rewardCamp
    ? baseTroopDefense
    : soldierDefenseEnabled
      ? Math.floor(troopCount * BASE_TROOP_DEFENSE_POWER * (1 + shieldwallDisciplinePercent / 100))
      : Math.floor(troopCount * (1 + defensePercent / 100));
  const troopDefenseBeforeGear = rewardCamp
    ? baseTroopDefense
    : soldierDefenseEnabled
      ? Math.floor(troopCount * BASE_TROOP_DEFENSE_POWER * (
        1 + (shieldwallDisciplinePercent + objectiveTroopDefenseBonusPercent) / 100
      ))
      : troopDefenseBeforeObjective;
  const gearDefenderStrengthBonusPower = soldierDefenseEnabled
    ? Math.floor(troopCount * BASE_TROOP_DEFENSE_POWER * gearDefenderStrengthPercent / 100)
    : 0;
  const troopDefense = troopDefenseBeforeGear + gearDefenderStrengthBonusPower;
  const cityWallsBonus = Math.max(0, cityWalls - baseCityWalls);
  const baseTotalDefense = Math.floor(baseCityWalls + baseTroopDefense);
  const preStrongholdTotalDefense = Math.floor(cityWalls + troopDefenseBeforeObjective);
  const strongholdDefenseBonus = soldierDefenseEnabled
    ? Math.max(0, troopDefense - troopDefenseBeforeObjective)
    : Math.floor(preStrongholdTotalDefense * objectiveTroopDefenseBonusPercent / 100);
  const totalDefense = soldierDefenseEnabled
    ? Math.floor(cityWalls + troopDefense)
    : preStrongholdTotalDefense + strongholdDefenseBonus;

  return {
    level,
    victoryPoints,
    defenseCombatVersion: soldierDefenseEnabled ? DEFENSE_COMBAT_VERSION : 0,
    baseDefensePowerPerTroop: soldierDefenseEnabled ? BASE_TROOP_DEFENSE_POWER : 1,
    defensePercent,
    baseCityWalls,
    cityWalls,
    cityWallsBonus,
    stoneworksPercent,
    gearWallStrengthPercent,
    shieldwallDisciplineLevel: soldierDefenseEnabled && defenderProfile
      ? getSkillLevel(defenderProfile, "shieldwallDiscipline")
      : 0,
    shieldwallDisciplinePercent,
    baseTroopDefense,
    troopDefenseBeforeObjective,
    troopDefenseBeforeGear,
    gearDefenderStrengthBonusPower,
    troopDefense,
    baseTotalDefense,
    objectiveTroopDefenseBonusPercent,
    gearDefenderStrengthPercent,
    strongholdDefenseBonusPercent: objectiveTroopDefenseBonusPercent,
    strongholdDefenseBonus,
    totalDefenseBonus: Math.max(0, totalDefense - baseTotalDefense),
    totalDefense,
  };
}

function usesSiegeCombat(version = 0, targetType = "city") {
  return targetType !== "camp" && Math.floor(safeNumber(version, 0)) >= SIEGE_COMBAT_VERSION;
}

function normalizeFortificationState(city = {}, nowMs = Date.now()) {
  const raw = city?.fortificationState && typeof city.fortificationState === "object"
    ? city.fortificationState
    : {};
  const repairAtMs = Math.max(0, timestampToMs(raw.repairAtMs));
  const current = Math.floor(safeNumber(raw.integrityBps, 10_000));
  const lastDamagedAtMs = Math.max(0, timestampToMs(raw.lastDamagedAtMs));
  const inferredRepairWindowMinutes = repairAtMs > lastDamagedAtMs
    ? Math.max(1, Math.round((repairAtMs - lastDamagedAtMs) / 60_000))
    : 0;
  const repairWindowMinutes = Math.max(
    0,
    Math.floor(safeNumber(raw.repairWindowMinutes, inferredRepairWindowMinutes))
  );
  const active = Math.floor(safeNumber(raw.version, 0)) === FORTIFICATION_STATE_VERSION
    && repairAtMs > nowMs
    && current < 10_000;
  return {
    version: FORTIFICATION_STATE_VERSION,
    integrityBps: active ? clampInt(current, 0, 10_000) : 10_000,
    lastDamagedAtMs: active ? lastDamagedAtMs : 0,
    repairAtMs: active ? repairAtMs : 0,
    repairWindowMinutes: active ? repairWindowMinutes : 0,
    repairReductionPercent: active
      ? clamp(safeNumber(raw.repairReductionPercent, 0), 0, 100)
      : 0,
    lastArmyId: active ? safeString(raw.lastArmyId, 96) : "",
  };
}

function getFortificationIntegrityBpsAt(state = {}, nowMs = Date.now()) {
  const integrityBps = clampInt(state.integrityBps, 0, 10_000);
  if (integrityBps >= 10_000) return 10_000;
  const repairAtMs = Math.max(0, timestampToMs(state.repairAtMs));
  if (!repairAtMs) return integrityBps;
  const sampledAtMs = Math.max(0, Math.floor(safeNumber(nowMs, Date.now())));
  if (sampledAtMs >= repairAtMs) return 10_000;
  const lastDamagedAtMs = Math.max(0, timestampToMs(state.lastDamagedAtMs));
  if (!lastDamagedAtMs || repairAtMs <= lastDamagedAtMs || sampledAtMs <= lastDamagedAtMs) {
    return integrityBps;
  }
  const repairProgress = clamp(
    (sampledAtMs - lastDamagedAtMs) / (repairAtMs - lastDamagedAtMs),
    0,
    1
  );
  return clampInt(
    integrityBps + Math.floor((10_000 - integrityBps) * repairProgress),
    integrityBps,
    10_000
  );
}

function getFortificationSnapshot(city = {}, ownerStats = {}, nowMs = Date.now()) {
  const state = normalizeFortificationState(city, nowMs);
  const currentIntegrityBps = getFortificationIntegrityBpsAt(state, nowMs);
  const troopObjectiveDefenseBonusPercent = getObjectiveTroopDefenseBonusPercent(ownerStats);
  const objectiveDefenseBonusPercent = Math.floor(safeNumber(ownerStats.defenseCombatVersion, 0)) >= DEFENSE_COMBAT_VERSION
    ? 0
    : troopObjectiveDefenseBonusPercent;
  const fullWallPower = Math.max(0, Math.floor(
    Math.max(0, safeNumber(ownerStats.cityWalls, 0))
      * (1 + objectiveDefenseBonusPercent / 100)
  ));
  const currentWallPower = Math.max(0, Math.floor(fullWallPower * currentIntegrityBps / 10_000));
  return {
    modelVersion: SIEGE_COMBAT_VERSION,
    stateVersion: FORTIFICATION_STATE_VERSION,
    baseCityWalls: Math.max(0, Math.floor(safeNumber(ownerStats.baseCityWalls, 0))),
    reinforcedCityWalls: Math.max(0, Math.floor(safeNumber(ownerStats.cityWalls, 0))),
    stoneworksPercent: Math.max(0, safeNumber(ownerStats.stoneworksPercent, 0)),
    gearWallStrengthPercent: Math.max(0, safeNumber(ownerStats.gearWallStrengthPercent, 0)),
    defenseCombatVersion: Math.max(0, Math.floor(safeNumber(ownerStats.defenseCombatVersion, 0))),
    baseDefensePowerPerTroop: Math.max(1, safeNumber(ownerStats.baseDefensePowerPerTroop, 1)),
    shieldwallDisciplinePercent: Math.max(0, safeNumber(ownerStats.shieldwallDisciplinePercent, 0)),
    gearDefenderStrengthPercent: Math.max(0, safeNumber(ownerStats.gearDefenderStrengthPercent, 0)),
    objectiveDefenseBonusPercent,
    troopObjectiveDefenseBonusPercent,
    fullWallPower,
    integrityBps: currentIntegrityBps,
    currentWallPower,
    repairAtMs: state.repairAtMs,
    repairWindowMinutes: state.repairWindowMinutes,
    repairReductionPercent: state.repairReductionPercent,
    lastDamagedAtMs: state.lastDamagedAtMs,
    lastArmyId: state.lastArmyId,
  };
}

function getFortificationStatePatch(fortification = null, armyId = "", nowMs = Date.now()) {
  if (!fortification?.persistentDamageApplied) return null;
  return {
    version: FORTIFICATION_STATE_VERSION,
    integrityBps: clampInt(fortification.endingIntegrityBps, 0, 10_000),
    lastDamagedAtMs: nowMs,
    repairAtMs: Math.max(nowMs, timestampToMs(fortification.repairAtMs)),
    repairWindowMinutes: Math.max(1, Math.floor(safeNumber(fortification.repairWindowMinutes, 1))),
    repairReductionPercent: clamp(safeNumber(fortification.repairReductionPercent, 0), 0, 100),
    lastArmyId: safeString(armyId, 96),
  };
}

function writeFortificationSettlement(writer, targetRef, result = {}, armyId = "", nowMs = Date.now()) {
  const state = getFortificationStatePatch(result.fortification, armyId, nowMs);
  if (!writer || !targetRef || !state) return null;
  writer.set(targetRef, {
    fortificationState: state,
    updatedAt: FieldValue.serverTimestamp(),
  }, { merge: true });
  return state;
}

function getAlliedReinforcementTroops(target = {}) {
  return Math.max(0, Math.floor(safeNumber(target.alliedReinforcementTroops, 0)));
}

function getTargetOwnerTroops(target = {}, targetType = "city") {
  return Math.max(0, Math.floor(safeNumber(
    targetType === "camp" ? target.currentGarrison : target.troops,
    target.troops
  )));
}

function createReinforcedCombatTarget(target = {}, targetType = "city") {
  const ownerTroops = getTargetOwnerTroops(target, targetType);
  const alliedTroops = getAlliedReinforcementTroops(target);
  const totalTroops = Math.min(Number.MAX_SAFE_INTEGER, ownerTroops + alliedTroops);
  return {
    ...target,
    troops: totalTroops,
    troopFloat: totalTroops,
    ownerGarrisonTroops: ownerTroops,
    alliedReinforcementTroops: alliedTroops,
  };
}

function getTroopKingPower(troops = 0) {
  const troopCount = Math.max(0, Math.floor(safeNumber(troops, 0)));
  if (!troopCount) return 0;
  const power = troopCount * KING_POWER_ARMY_TROOP_VALUE;
  return Number.isFinite(power) ? Math.min(Number.MAX_SAFE_INTEGER, Math.floor(power)) : Number.MAX_SAFE_INTEGER;
}

function getCityInfrastructurePowerComponents(city = {}, bonuses = {}) {
  if (!city) {
    return { replacementPower: 0, defensivePower: 0, sustainableTroopPerHour: 0 };
  }
  const troopCount = Math.max(0, Math.floor(safeNumber(city.troops, 0)));
  const production = getCityProductionStats(city, {}, bonuses, {
    includeWarDrums: false,
    includeRoyalTaxDecree: false,
  });
  const defense = getCityStats(city, null, bonuses);
  const sustainableTroopPerHour = Math.max(0, safeNumber(production.troopProductionPerHour, 0));
  const defensiveAdvantage = Math.max(0, safeNumber(defense.totalDefense, 0) - troopCount);
  return {
    replacementPower: Math.min(
      Number.MAX_SAFE_INTEGER,
      Math.floor(sustainableTroopPerHour * KING_POWER_REPLACEMENT_HOURS)
    ),
    defensivePower: Math.min(
      Number.MAX_SAFE_INTEGER,
      Math.floor(defensiveAdvantage * KING_POWER_DEFENSIVE_ADVANTAGE_WEIGHT)
    ),
    sustainableTroopPerHour,
  };
}

function getCityInfrastructurePower(city = {}, bonuses = {}) {
  const components = getCityInfrastructurePowerComponents(city, bonuses);
  return Math.min(
    Number.MAX_SAFE_INTEGER,
    Math.max(0, Math.floor(safeNumber(components.replacementPower, 0)))
      + Math.max(0, Math.floor(safeNumber(components.defensivePower, 0)))
  );
}

function getCityPowerFloor(city = {}) {
  if (!city) return 0;
  return getCityInfrastructurePower(city) + getTroopKingPower(city.troops);
}

function playerGlobalStatsRef(uid = "") {
  return db.doc(`players/${safeString(uid, 128)}/stats/global`);
}

function rewardedAdStateRef(uid = "") {
  return db.doc(`players/${safeString(uid, 128)}/rewardedAds/state`);
}

function rewardedAdIntentRef(uid = "", intentId = "") {
  return db.doc(`players/${safeString(uid, 128)}/rewardedAdIntents/${safeString(intentId, 96)}`);
}

function rewardedAdServerConfigRef() {
  return db.doc("serverConfig/rewardedAds");
}

function leaderboardEntryRef(uid = "") {
  return db.doc(`leaderboards/${RESET_GENERATION}/entries/${safeString(uid, 128)}`);
}

function getArmyStatsKey(army = {}) {
  return safeString(army.id || army.armyId || "", 96);
}

function createActiveArmiesFromSnapshot(uid = "", activeArmiesSnap = null) {
  const playerUid = safeString(uid, 128);
  if (!playerUid || !activeArmiesSnap?.docs) return [];
  const armiesById = new Map();
  activeArmiesSnap.docs.forEach(doc => {
    const army = {
      id: safeString(doc.data()?.id || doc.id, 96),
      islandId: safeString(doc.ref.parent?.parent?.id, 160),
      ...doc.data(),
    };
    if (getOwnerUid(army) !== playerUid || army.status !== "active" || !isCurrentWorldArmy(army)) return;
    if (!armiesById.has(army.id)) armiesById.set(army.id, army);
  });
  return [...armiesById.values()];
}

function activeArmiesQueryForPlayer(uid = "") {
  return db.collection("armies")
    .where("ownerUid", "==", safeString(uid, 128))
    .where("resetGeneration", "==", RESET_GENERATION)
    .where("worldId", "==", ONLINE_WORLD_ID)
    .where("status", "==", "active");
}

function activeArmiesTargetingPlayerQuery(uid = "") {
  return db.collection("armies")
    .where("targetOwnerUid", "==", safeString(uid, 128))
    .where("resetGeneration", "==", RESET_GENERATION)
    .where("worldId", "==", ONLINE_WORLD_ID)
    .where("status", "==", "active");
}

function heldRewardCampsQueryForPlayer(uid = "") {
  return db.collectionGroup("camps")
    .where("holderUid", "==", safeString(uid, 128))
    .where("resetGeneration", "==", RESET_GENERATION)
    .where("worldId", "==", ONLINE_WORLD_ID);
}

function createHeldCampEntriesFromSnapshot(uid = "", heldCampsSnap = null) {
  const playerUid = safeString(uid, 128);
  if (!playerUid || !heldCampsSnap?.docs) return [];
  return heldCampsSnap.docs.map(doc => {
    const islandId = safeString(doc.ref.parent?.parent?.id, 160);
    if (!isCurrentWorldIslandId(islandId)) return null;
    const data = doc.data() || {};
    if (safeString(data.holderUid || data.ownerUid, 128) !== playerUid) return null;
    const regionId = normalizeRegionId(data.regionId || getRegionIdFromOnlineIslandId(islandId));
    if (!getServerWorldCampIds(regionId).has(doc.id)) return null;
    const camp = getRewardCampCombatTarget({
      id: doc.id,
      ...data,
      islandId,
      regionId,
    });
    return camp ? { ref: doc.ref, camp } : null;
  }).filter(Boolean);
}

function isCurrentWorldArmy(army = {}) {
  if (army.worldId && safeString(army.worldId, 120) !== ONLINE_WORLD_ID) return false;
  if (army.resetGeneration && safeString(army.resetGeneration, 120) !== RESET_GENERATION) return false;
  const routeRegionIds = normalizeRegionIds(army.routeRegionIds || []);
  if (routeRegionIds.some(regionId => isCurrentWorldIslandId(getOnlineIslandId(regionId)))) return true;
  const sourceRegionId = normalizeRegionId(army.sourceRegionId || "");
  const targetRegionId = normalizeRegionId(army.targetRegionId || "");
  return isCurrentWorldIslandId(army.islandId)
    || isCurrentWorldIslandId(getOnlineIslandId(sourceRegionId))
    || isCurrentWorldIslandId(getOnlineIslandId(targetRegionId));
}

function createGlobalStatsSnapshot({
  uid = "",
  profile = {},
  cityEntries = [],
  heldCamps = [],
  activeArmies = [],
  bonuses = null,
  nowMs = Date.now(),
} = {}) {
  const playerUid = safeString(uid, 128);
  const ownedEntries = (Array.isArray(cityEntries) ? cityEntries : [])
    .filter(entry => entry?.city && getOwnerUid(entry.city) === playerUid)
    .filter(entry => isCurrentWorldIslandId(getCityEntryIslandId(entry) || getOnlineIslandId(entry.city.regionId)));
  const resolvedBonuses = bonuses || getOwnedStrongholdBonuses(ownedEntries);
  const profileForStats = {
    ...profile,
    itemEffects: normalizeItemEffects(profile.itemEffects),
  };
  const stationedReinforcementTroops = safeString(profileForStats.reinforcementResetGeneration, 120) === RESET_GENERATION
    ? Math.max(0, Math.floor(safeNumber(profileForStats.stationedReinforcementTroops, 0)))
    : 0;
  const committedRallyTroops = safeString(profileForStats.rallyResetGeneration, 120) === RESET_GENERATION
    ? Math.max(0, Math.floor(safeNumber(profileForStats.committedRallyTroops, 0)))
    : 0;

  let totalCities = 0;
  let strongholdCount = 0;
  let totalCityTroops = 0;
  let totalCampTroops = 0;
  let totalCityLevels = 0;
  let totalVictoryPoints = 0;
  let replacementPower = 0;
  let defensivePower = 0;
  let baseReplacementPower = 0;
  let baseDefensivePower = 0;
  let sustainableTroopPerHour = 0;
  let goldPerHour = 0;
  let troopPerHour = 0;
  let baseGoldPerHour = 0;
  let baseTroopPerHour = 0;
  let untimedGoldPerHour = 0;
  let untimedTroopPerHour = 0;
  // Include zeroes so Firestore merge writes clear regions where the player lost their final city.
  const cityCountsByRegion = Object.fromEntries(
    [...SERVER_WORLD_REGION_IDS].map(regionId => [regionId, 0])
  );

  ownedEntries.forEach(entry => {
    const city = entry.city || {};
    const troopCount = Math.max(0, Math.floor(safeNumber(city.troops, 0)));
    const stats = getCityProductionStats(city, profileForStats, resolvedBonuses, { nowMs });
    const powerComponents = getCityInfrastructurePowerComponents(city, resolvedBonuses);
    const basePowerComponents = getCityInfrastructurePowerComponents(city, {});
    totalCityTroops += troopCount;
    totalVictoryPoints += Math.max(0, Math.floor(safeNumber(stats.victoryPoints, 0)));
    replacementPower += powerComponents.replacementPower;
    defensivePower += powerComponents.defensivePower;
    baseReplacementPower += basePowerComponents.replacementPower;
    baseDefensivePower += basePowerComponents.defensivePower;
    sustainableTroopPerHour += powerComponents.sustainableTroopPerHour;
    goldPerHour += Math.max(0, safeNumber(stats.goldProductionPerHour, 0));
    troopPerHour += Math.max(0, safeNumber(stats.troopProductionPerHour, 0));
    baseGoldPerHour += Math.max(0, safeNumber(stats.baseGoldProductionPerHour, 0));
    baseTroopPerHour += Math.max(0, safeNumber(stats.baseTroopProductionPerHour, 0));
    untimedGoldPerHour += Math.max(0, safeNumber(stats.untimedGoldProductionPerHour, 0));
    untimedTroopPerHour += Math.max(0, safeNumber(stats.untimedTroopProductionPerHour, 0));
    if (isStronghold(city)) {
      strongholdCount += 1;
    } else {
      totalCities += 1;
      totalCityLevels += clampCityLevel(city.level);
      const regionId = normalizeRegionId(city.regionId || getRegionIdFromOnlineIslandId(getCityEntryIslandId(entry)));
      cityCountsByRegion[regionId] = (cityCountsByRegion[regionId] || 0) + 1;
    }
  });

  (Array.isArray(heldCamps) ? heldCamps : []).forEach(entry => {
    const camp = entry?.camp;
    if (!camp || getOwnerUid(camp) !== playerUid) return;
    const islandId = safeString(camp.islandId || entry.ref?.parent?.parent?.id, 160);
    if (!isCurrentWorldIslandId(islandId)) return;
    const troopCount = Math.max(0, Math.floor(safeNumber(camp.troops, 0)));
    const powerComponents = getCityInfrastructurePowerComponents(camp, resolvedBonuses);
    const basePowerComponents = getCityInfrastructurePowerComponents(camp, {});
    totalCampTroops += troopCount;
    defensivePower += powerComponents.defensivePower;
    baseDefensivePower += basePowerComponents.defensivePower;
  });

  const marchingById = new Map();
  (Array.isArray(activeArmies) ? activeArmies : []).forEach(army => {
    if (!army || getOwnerUid(army) !== playerUid || army.status !== "active" || !isCurrentWorldArmy(army)) return;
    if (army.rallyAttack === true) return;
    const key = getArmyStatsKey(army);
    if (!key || marchingById.has(key)) return;
    marchingById.set(key, army);
  });
  const totalMarchingTroops = [...marchingById.values()]
    .reduce((total, army) => total + Math.max(0, Math.floor(safeNumber(army.troops, 0))), 0);
  const totalTroops = totalCityTroops + totalCampTroops;
  const totalMilitaryTroops = getTotalMilitaryTroopsFromGlobalStats({
    totalTroops,
    totalMarchingTroops,
    totalReinforcementTroops: stationedReinforcementTroops,
    totalRallyTroops: committedRallyTroops,
  });
  const armyPower = getTroopKingPower(totalMilitaryTroops);
  const cityTroopPower = getTroopKingPower(totalCityTroops);
  const campTroopPower = getTroopKingPower(totalCampTroops);
  const reinforcementTroopPower = getTroopKingPower(stationedReinforcementTroops);
  const rallyTroopPower = getTroopKingPower(committedRallyTroops);
  const stationedTroopPower = Math.min(
    Number.MAX_SAFE_INTEGER,
    cityTroopPower + campTroopPower + reinforcementTroopPower + rallyTroopPower
  );
  const marchingPower = getTroopKingPower(totalMarchingTroops);
  replacementPower = Math.min(Number.MAX_SAFE_INTEGER, Math.max(0, Math.floor(replacementPower)));
  defensivePower = Math.min(Number.MAX_SAFE_INTEGER, Math.max(0, Math.floor(defensivePower)));
  baseReplacementPower = Math.min(Number.MAX_SAFE_INTEGER, Math.max(0, Math.floor(baseReplacementPower)));
  baseDefensivePower = Math.min(Number.MAX_SAFE_INTEGER, Math.max(0, Math.floor(baseDefensivePower)));
  sustainableTroopPerHour = Math.min(Number.MAX_SAFE_INTEGER, Math.max(0, Math.floor(sustainableTroopPerHour)));
  const cityPower = Math.min(Number.MAX_SAFE_INTEGER, replacementPower + defensivePower);
  const kingPower = Math.min(Number.MAX_SAFE_INTEGER, Math.max(0, Math.floor(armyPower + cityPower)));
  const baseKingPower = Math.min(
    Number.MAX_SAFE_INTEGER,
    Math.max(0, Math.floor(armyPower + baseReplacementPower + baseDefensivePower))
  );
  const character = normalizeCharacterProgress(profileForStats.character);

  return {
    playerId: playerUid,
    uid: playerUid,
    worldId: ONLINE_WORLD_ID,
    resetGeneration: RESET_GENERATION,
    version: GLOBAL_PLAYER_STATS_VERSION,
    totalCities,
    totalTroops,
    totalCityTroops,
    totalCampTroops,
    totalMarchingTroops,
    totalReinforcementTroops: stationedReinforcementTroops,
    totalRallyTroops: committedRallyTroops,
    totalCityLevels,
    totalVictoryPoints,
    strongholdCount,
    cityCountsByRegion,
    goldPerHour: Math.max(0, Math.floor(goldPerHour)),
    troopPerHour: Math.max(0, Math.floor(troopPerHour)),
    baseGoldPerHour: Math.max(0, Math.floor(baseGoldPerHour)),
    baseTroopPerHour: Math.max(0, Math.floor(baseTroopPerHour)),
    untimedGoldPerHour: Math.max(0, Math.floor(untimedGoldPerHour)),
    untimedTroopPerHour: Math.max(0, Math.floor(untimedTroopPerHour)),
    sustainableTroopPerHour,
    armyPower,
    replacementPower,
    defensivePower,
    baseReplacementPower,
    baseDefensivePower,
    strongholdBonusesAuthoritative: true,
    strongholdBonusSource: safeString(resolvedBonuses.source, 32),
    crownCitadelControlled: Boolean(resolvedBonuses.crownCitadelControlled),
    strongholdGoldBonusPercent: Math.max(0, Math.floor(safeNumber(resolvedBonuses.goldBonusPercent, 0))),
    strongholdTroopBonusPercent: Math.max(0, Math.floor(safeNumber(resolvedBonuses.troopBonusPercent, 0))),
    strongholdMarchSpeedBonusPercent: Math.max(0, Math.floor(safeNumber(resolvedBonuses.marchSpeedBonusPercent, 0))),
    objectiveTroopDefenseBonusPercent: getObjectiveTroopDefenseBonusPercent(resolvedBonuses),
    strongholdDefenseBonusPercent: Math.max(0, Math.floor(safeNumber(resolvedBonuses.cityDefenseBonusPercent, 0))),
    strongholdUpgradeCostReductionPercent: Math.max(0, Math.floor(safeNumber(resolvedBonuses.upgradeCostReductionPercent, 0))),
    personalStrongholdGoldBonusPercent: Math.max(0, safeNumber(resolvedBonuses.personalGoldBonusPercent, resolvedBonuses.goldBonusPercent)),
    personalStrongholdTroopBonusPercent: Math.max(0, safeNumber(resolvedBonuses.personalTroopBonusPercent, resolvedBonuses.troopBonusPercent)),
    personalStrongholdMarchSpeedBonusPercent: Math.max(0, safeNumber(resolvedBonuses.personalMarchSpeedBonusPercent, resolvedBonuses.marchSpeedBonusPercent)),
    personalObjectiveTroopDefenseBonusPercent: Math.max(0, safeNumber(resolvedBonuses.personalDefenseBonusPercent, resolvedBonuses.cityDefenseBonusPercent)),
    personalStrongholdDefenseBonusPercent: Math.max(0, safeNumber(resolvedBonuses.personalDefenseBonusPercent, resolvedBonuses.cityDefenseBonusPercent)),
    personalStrongholdUpgradeCostReductionPercent: Math.max(0, safeNumber(resolvedBonuses.personalUpgradeCostReductionPercent, resolvedBonuses.upgradeCostReductionPercent)),
    sharedClanGoldBonusPercent: Math.max(0, safeNumber(resolvedBonuses.sharedGoldBonusPercent, 0)),
    sharedClanTroopBonusPercent: Math.max(0, safeNumber(resolvedBonuses.sharedTroopBonusPercent, 0)),
    sharedClanMarchSpeedBonusPercent: Math.max(0, safeNumber(resolvedBonuses.sharedMarchSpeedBonusPercent, 0)),
    sharedClanObjectiveTroopDefenseBonusPercent: Math.max(0, safeNumber(resolvedBonuses.sharedDefenseBonusPercent, 0)),
    sharedClanDefenseBonusPercent: Math.max(0, safeNumber(resolvedBonuses.sharedDefenseBonusPercent, 0)),
    sharedClanUpgradeCostReductionPercent: Math.max(0, safeNumber(resolvedBonuses.sharedUpgradeCostReductionPercent, 0)),
    clanCitadelBonusPercent: Math.max(0, safeNumber(resolvedBonuses.clanCitadelBonusPercent, 0)),
    clanObjectiveBenefitRevision: Math.max(0, Math.floor(safeNumber(resolvedBonuses.clanObjectiveBenefitRevision, 0))),
    stationedTroopPower: Math.max(0, Math.floor(stationedTroopPower)),
    campTroopPower: Math.max(0, Math.floor(campTroopPower)),
    reinforcementTroopPower: Math.max(0, Math.floor(reinforcementTroopPower)),
    rallyTroopPower: Math.max(0, Math.floor(rallyTroopPower)),
    cityPower: Math.max(0, Math.floor(cityPower)),
    marchingPower: Math.max(0, Math.floor(marchingPower)),
    troopPower: Math.max(0, Math.floor(armyPower)),
    territoryPower: 0,
    cityLevelPower: 0,
    economicPower: 0,
    troopProductionPower: replacementPower,
    fortificationPower: defensivePower,
    strongholdPower: 0,
    kingPower,
    baseKingPower,
    kingPowerBonus: Math.max(0, kingPower - baseKingPower),
    characterLevel: character.level,
    mainCityId: safeString(profileForStats.mainCityId, 96),
    mainIslandId: safeString(profileForStats.mainIslandId, 160),
    mainRegionId: normalizeRegionId(profileForStats.mainRegionId || getRegionIdFromOnlineIslandId(profileForStats.mainIslandId)),
    updatedAtMs: nowMs,
    updatedAt: FieldValue.serverTimestamp(),
  };
}

function getTotalMilitaryTroopsFromGlobalStats(stats = {}) {
  return [
    stats.totalTroops,
    stats.totalMarchingTroops,
    stats.totalReinforcementTroops,
    stats.totalRallyTroops,
  ].reduce((total, value) => Math.min(
    Number.MAX_SAFE_INTEGER,
    total + Math.max(0, Math.floor(safeNumber(value, 0)))
  ), 0);
}

function getTimedProductionBoostOverlapSeconds(intervalStartMs, intervalEndMs, startedAtMs, expiresAtMs) {
  const endMs = Math.max(0, safeNumber(intervalEndMs, 0));
  const startMs = clamp(safeNumber(intervalStartMs, endMs), 0, endMs);
  const effectStartMs = clamp(timestampToMs(startedAtMs), 0, endMs);
  const effectEndMs = Math.max(0, timestampToMs(expiresAtMs));
  if (!effectStartMs || !effectEndMs || effectEndMs <= effectStartMs || effectEndMs <= startMs || effectStartMs >= endMs) return 0;
  return Math.max(0, (Math.min(endMs, effectEndMs) - Math.max(startMs, effectStartMs)) / 1000);
}

function resolveTimedProductionBoostStartedAtMs(startedAtMs, expiresAtMs, checkpointAtMs, nowMs = Date.now()) {
  const effectEndMs = Math.max(0, timestampToMs(expiresAtMs));
  if (!effectEndMs) return 0;
  const recordedStartMs = Math.max(0, timestampToMs(startedAtMs));
  if (recordedStartMs > 0 && recordedStartMs < effectEndMs) return recordedStartMs;
  // Timed-item activation checkpoints the economy before extending the timer.
  // Old profiles did not store a start, so migrate them from the latest safe
  // checkpoint instead of inferring a single-item window or granting time
  // before an activation that cannot be proven.
  return Math.min(
    effectEndMs,
    Math.max(0, timestampToMs(checkpointAtMs) || Math.floor(safeNumber(nowMs, Date.now())))
  );
}

function globalStatsForClient(stats = null) {
  if (!stats || typeof stats !== "object") return null;
  const { updatedAt, ...clientStats } = stats;
  return clientStats;
}

function getPowerValue(...values) {
  return Math.max(0, ...values.map(value => Math.floor(safeNumber(value, 0))));
}

function getLegacyGlobalStatsKingPower(stats = {}) {
  if (!stats || typeof stats !== "object") return 0;
  const totalCities = Math.max(0, Math.floor(safeNumber(stats.totalCities, stats.cityCount)));
  const totalLevels = Math.max(totalCities, Math.floor(safeNumber(stats.totalCityLevels, totalCities)));
  const stationedTroops = Math.max(0, Math.floor(safeNumber(stats.totalTroops, 0)))
    + Math.max(0, Math.floor(safeNumber(stats.totalReinforcementTroops, 0)));
  const totalTroops = stationedTroops + Math.max(0, Math.floor(safeNumber(stats.totalMarchingTroops, 0)));
  const averageLevel = totalCities > 0 ? totalLevels / totalCities : 0;
  const baseWalls = totalCities > 0 ? getBaseCityWalls(averageLevel) * totalCities : 0;
  const sustainableTroopPerHour = Math.max(0, Math.floor(
    safeNumber(stats.totalVictoryPoints, 0) * CITY_LEVEL_STATS.troopProductionPerVictoryPoint
  ));
  const replacementPower = Math.floor(sustainableTroopPerHour * KING_POWER_REPLACEMENT_HOURS);
  const objectiveDefensePercent = getObjectiveTroopDefenseBonusPercent(stats);
  const baseTroopDefense = stationedTroops * BASE_TROOP_DEFENSE_POWER;
  const defensiveAdvantage = baseWalls
    + Math.max(0, baseTroopDefense - stationedTroops)
    + baseTroopDefense * objectiveDefensePercent / 100;
  const defensivePower = Math.floor(
    Math.max(0, defensiveAdvantage) * KING_POWER_DEFENSIVE_ADVANTAGE_WEIGHT
  );
  return Math.max(0, Math.floor(
    getTroopKingPower(totalTroops) + replacementPower + defensivePower
  ));
}

function getPlayerPowerSnapshot({ profile = {}, leaderboard = {}, globalStats = {}, city = {}, fallback = 0 } = {}) {
  const authoritativeCandidates = [
    {
      version: Math.max(0, Math.floor(safeNumber(globalStats.version, 0))),
      power: Math.max(0, Math.floor(safeNumber(globalStats.kingPower, 0))),
      updatedAtMs: Math.max(0, timestampToMs(globalStats.updatedAtMs || globalStats.updatedAt)),
    },
    {
      version: Math.max(0, Math.floor(safeNumber(leaderboard.kingPowerVersion, 0))),
      power: Math.max(0, Math.floor(safeNumber(leaderboard.kingPower, 0))),
      updatedAtMs: Math.max(0, timestampToMs(leaderboard.kingPowerUpdatedAtMs || leaderboard.updatedAtMs)),
    },
    {
      version: Math.max(0, Math.floor(safeNumber(profile.kingPowerVersion, 0))),
      power: Math.max(0, Math.floor(safeNumber(profile.kingPower, 0))),
      updatedAtMs: Math.max(0, timestampToMs(profile.kingPowerUpdatedAtMs)),
    },
  ]
    .filter(candidate => candidate.version >= GLOBAL_PLAYER_STATS_VERSION && candidate.power > 0);
  if (authoritativeCandidates.length) return authoritativeCandidates[0].power;

  const legacyGlobalPower = getLegacyGlobalStatsKingPower(globalStats);
  if (legacyGlobalPower > 0) return legacyGlobalPower;

  const serverPower = getPowerValue(
    safeNumber(profile.kingPowerVersion, 0) > 0 ? 0 : profile.kingPower,
    safeNumber(leaderboard.kingPowerVersion, 0) > 0 ? 0 : leaderboard.kingPower,
    safeNumber(city.kingPowerVersion, 0) > 0 ? 0 : city.ownerKingPower,
    getCityPowerFloor(city)
  );
  return serverPower > 0 ? serverPower : getPowerValue(fallback);
}

function getDemoAttackTier(powerRatio) {
  const ratio = safeNumber(powerRatio, 0);
  return DEMO_ATTACK_TIERS.find(tier => ratio >= tier.minRatio) || null;
}

function roundDownToTwoSignificantDigits(value) {
  const integer = Math.max(0, Math.floor(safeNumber(value, 0)));
  if (integer < 10) return integer;
  const magnitude = 10 ** Math.max(0, Math.floor(Math.log10(integer)) - 1);
  return Math.floor(integer / magnitude) * magnitude;
}

function roundUpToTwoSignificantDigits(value) {
  const integer = Math.max(0, Math.ceil(safeNumber(value, 0)));
  if (integer < 10) return integer;
  const magnitude = 10 ** Math.max(0, Math.floor(Math.log10(integer)) - 1);
  return Math.ceil(integer / magnitude) * magnitude;
}

function getAttackProtectionMode(powerRatio) {
  const ratio = Math.max(0, safeNumber(powerRatio, 0));
  if (ratio >= ATTACK_PROTECTION_RAID_MIN_RATIO) return "raid";
  if (ratio >= ATTACK_PROTECTION_ASSAULT_MIN_RATIO) return "assault";
  return "normal";
}

function getAttackProtectionBreakEvenScale(mode, powerRatio) {
  const ratio = Math.max(0, safeNumber(powerRatio, 0));
  if (mode === "assault") {
    const progress = clamp(
      (ratio - ATTACK_PROTECTION_ASSAULT_MIN_RATIO)
        / (ATTACK_PROTECTION_RAID_MIN_RATIO - ATTACK_PROTECTION_ASSAULT_MIN_RATIO),
      0,
      1
    );
    return 1.25 - progress * 0.2;
  }
  if (mode === "raid") {
    const progress = clamp(
      (ratio - ATTACK_PROTECTION_RAID_MIN_RATIO)
        / (ATTACK_PROTECTION_RAID_MAX_SCALE_RATIO - ATTACK_PROTECTION_RAID_MIN_RATIO),
      0,
      1
    );
    return 0.5 - progress * 0.25;
  }
  return 1;
}

function normalizeAttackProtectionSnapshot(raw = null, legacyDemoAttack = null) {
  if (raw && typeof raw === "object" && safeNumber(raw.version, 0) === ATTACK_PROTECTION_VERSION) {
    const mode = raw.mode === "raid" ? "raid" : raw.mode === "assault" ? "assault" : "normal";
    if (mode === "normal") return null;
    const assaultStage = mode === "assault" && raw.assaultStage === "capture" ? "capture" : mode === "assault" ? "breach" : "";
    const maxTroops = Math.max(1, Math.floor(safeNumber(raw.maxTroops, 1)));
    const requestedTroops = Math.max(1, Math.floor(safeNumber(raw.requestedTroops, maxTroops)));
    return {
      version: ATTACK_PROTECTION_VERSION,
      mode,
      assaultStage,
      label: mode === "raid"
        ? "Protected Raid"
        : assaultStage === "capture"
          ? "Protected Capture Assault"
          : "Protected Breach Assault",
      powerRatio: Math.max(ATTACK_PROTECTION_ASSAULT_MIN_RATIO, safeNumber(raw.powerRatio, ATTACK_PROTECTION_ASSAULT_MIN_RATIO)),
      maxTroops,
      requestedTroops,
      effectiveTroops: Math.max(1, Math.min(maxTroops, Math.floor(safeNumber(raw.effectiveTroops, requestedTroops)))),
      captureAllowed: mode === "assault" && assaultStage === "capture",
      breachRequired: mode === "assault" && assaultStage === "breach",
      maxDefenderLossPercent: mode === "raid" ? 10 : 100,
      attackerXpMultiplier: 0,
      defenderXpPolicy: ATTACK_PROTECTION_DEFENDER_XP_POLICY,
      legacyDemoAttack: raw.legacyDemoAttack === true,
    };
  }
  const legacy = normalizeDemoAttackSnapshot(legacyDemoAttack);
  if (!legacy) return null;
  return {
    version: ATTACK_PROTECTION_VERSION,
    mode: "raid",
    assaultStage: "",
    label: "Protected Raid",
    powerRatio: Math.max(ATTACK_PROTECTION_RAID_MIN_RATIO, legacy.powerRatio),
    maxTroops: legacy.maxTroops,
    requestedTroops: legacy.requestedTroops,
    effectiveTroops: legacy.effectiveTroops,
    captureAllowed: false,
    breachRequired: false,
    maxDefenderLossPercent: 10,
    attackerXpMultiplier: 0,
    defenderXpPolicy: ATTACK_PROTECTION_DEFENDER_XP_POLICY,
    legacyDemoAttack: true,
  };
}

function createServerAttackProtectionSnapshot({
  sourceTroops = 1,
  target = null,
  targetType = "city",
  requestedTroops = 1,
  attackerKingPower = 0,
  defenderKingPower = 1,
  attackerUid = "",
  attackerProfile = null,
  defenderProfile = null,
  defenderBonuses = {},
  defensePower = null,
  assaultStage = "breach",
} = {}) {
  if (!target || targetType === "camp" || isStronghold(target)) return null;
  const targetOwnerUid = getOwnerUid(target);
  if (!targetOwnerUid || targetOwnerUid === attackerUid) return null;
  const attackerPower = Math.max(0, Math.floor(safeNumber(attackerKingPower, 0)));
  const defenderPower = Math.max(1, Math.floor(safeNumber(defenderKingPower, 1)));
  const powerRatio = attackerPower / defenderPower;
  const mode = getAttackProtectionMode(powerRatio);
  if (mode === "normal") return null;

  const availableTroops = Math.max(1, Math.floor(safeNumber(sourceTroops, 1)));
  const requested = clampInt(requestedTroops, 1, availableTroops);
  const attackPerTroop = Math.max(1, getAttackPower(1, attackerProfile));
  const totalDefense = Math.max(
    1,
    defensePower !== null && defensePower !== undefined && Number.isFinite(Number(defensePower))
      ? Math.floor(Number(defensePower))
      : getCityStats(target, defenderProfile, defenderBonuses).totalDefense
  );
  const breakEvenTroops = Math.max(1, Math.floor(totalDefense / attackPerTroop) + 1);
  const normalizedAssaultStage = mode === "assault" && assaultStage === "capture" ? "capture" : "breach";
  const captureSafeCap = Math.max(1, roundUpToTwoSignificantDigits(breakEvenTroops));
  const scaledCap = Math.max(1, Math.floor(
    breakEvenTroops * getAttackProtectionBreakEvenScale(mode, powerRatio)
  ));
  const exposedCap = mode === "assault"
    ? normalizedAssaultStage === "breach"
      ? captureSafeCap
      : Math.max(captureSafeCap, roundDownToTwoSignificantDigits(scaledCap))
    : Math.max(1, roundDownToTwoSignificantDigits(scaledCap));
  const maxTroops = Math.min(availableTroops, exposedCap);
  return normalizeAttackProtectionSnapshot({
    version: ATTACK_PROTECTION_VERSION,
    mode,
    assaultStage: normalizedAssaultStage,
    powerRatio: Number(powerRatio.toFixed(4)),
    maxTroops,
    requestedTroops: requested,
    effectiveTroops: Math.min(requested, maxTroops),
  });
}

function createAttackProtectionPreview(snapshot = null, sourceTroops = 1, requestedTroops = 1) {
  const availableTroops = Math.max(1, Math.floor(safeNumber(sourceTroops, 1)));
  const requested = clampInt(requestedTroops, 1, availableTroops);
  const protectedSnapshot = normalizeAttackProtectionSnapshot(snapshot);
  if (protectedSnapshot) return protectedSnapshot;
  return {
    version: ATTACK_PROTECTION_VERSION,
    mode: "normal",
    assaultStage: "",
    label: "Normal Attack",
    powerRatio: 0,
    maxTroops: availableTroops,
    requestedTroops: requested,
    effectiveTroops: requested,
    captureAllowed: true,
    breachRequired: false,
    maxDefenderLossPercent: 100,
    attackerXpMultiplier: 1,
    defenderXpPolicy: "normal",
  };
}

function getAttackProtectionQuoteSignature(snapshot = null, sourceTroops = 1, requestedTroops = 1) {
  const preview = createAttackProtectionPreview(snapshot, sourceTroops, requestedTroops);
  return [
    preview.version,
    preview.mode,
    preview.assaultStage || "",
    preview.maxTroops,
    preview.captureAllowed ? 1 : 0,
    preview.maxDefenderLossPercent,
  ].join("|");
}

function isCurrentProtectedDefenseXpClaim(claim = null) {
  return Boolean(
    claim
    && typeof claim === "object"
    && safeString(claim.worldId, 128) === ONLINE_WORLD_ID
    && safeString(claim.resetGeneration, 128) === RESET_GENERATION
    && safeString(claim.firstResolvedArmyId, 96)
  );
}

function normalizeDemoAttackSnapshot(demo = null) {
  if (!demo || typeof demo !== "object" || !demo.active) return null;
  const attackerKingPower = Math.max(0, Math.floor(safeNumber(demo.attackerKingPower, 0)));
  const defenderKingPower = Math.max(1, Math.floor(safeNumber(demo.defenderKingPower, 1)));
  const powerRatio = Number.isFinite(Number(demo.powerRatio))
    ? Number(demo.powerRatio)
    : attackerKingPower / Math.max(1, defenderKingPower);
  const tier = getDemoAttackTier(powerRatio);
  if (!tier) return null;
  const maxTroops = Math.max(1, Math.floor(safeNumber(demo.maxTroops, 1)));
  const requestedTroops = Math.max(1, Math.floor(safeNumber(demo.requestedTroops, maxTroops)));
  const effectiveTroops = Math.max(1, Math.min(maxTroops, Math.floor(safeNumber(demo.effectiveTroops, maxTroops))));
  const attackPowerPercent = clampInt(demo.attackPowerPercent || tier.attackPowerPercent, 1, 100);
  const troopCapPercent = clampInt(demo.troopCapPercent || tier.troopCapPercent, 1, 100);
  const travelMultiplier = Math.max(1, safeNumber(demo.travelMultiplier, tier.travelMultiplier));
  return {
    active: true,
    label: safeString(demo.label || tier.label || "Demo Attack", 32),
    attackerKingPower,
    defenderKingPower,
    powerRatio: Number(powerRatio.toFixed(2)),
    requestedTroops,
    effectiveTroops,
    maxTroops,
    troopCapPercent,
    attackPowerPercent,
    attackPowerMultiplier: attackPowerPercent / 100,
    travelMultiplier,
    attackerXpMultiplier: 0,
    defenderXpMultiplier: DEMO_ATTACK_DEFENDER_XP_MULTIPLIER,
  };
}

function getAttackPower(troops, attackerProfile = null) {
  const boost = attackerProfile
    ? skillMultiplier(attackerProfile, "swordmastery") + getCommonGearBonuses(attackerProfile).attackStrength / 100
    : 1;
  return troops * BASE_TROOP_ATTACK_POWER * boost;
}

function calculateCombatResult(attackTroops, target, attackerProfile = null, defenderProfile = null, options = {}) {
  const troops = Math.max(0, Math.floor(safeNumber(attackTroops, 0)));
  const defendersAtStart = Math.max(0, Math.floor(safeNumber(target?.troops, 0)));
  const attackProtection = normalizeAttackProtectionSnapshot(options.attackProtection, options.demoAttack);
  const attackPower = Number.isFinite(Number(options.attackPower))
    ? Math.max(0, Math.floor(Number(options.attackPower)))
    : getAttackPower(troops, attackerProfile);
  const siegeEnabled = usesSiegeCombat(
    options.siegeCombatVersion,
    options.targetType === "camp" ? "camp" : "city"
  ) && options.fortification && typeof options.fortification === "object";
  const wallDefenseIgnored = siegeEnabled && options.ignoreWallDefense === true;
  const fullWallPower = siegeEnabled
    ? Math.max(0, Math.floor(safeNumber(options.fortification.fullWallPower, 0)))
    : 0;
  const startingIntegrityBps = siegeEnabled
    ? clampInt(options.fortification.integrityBps, 0, 10_000)
    : 10_000;
  const startingWallPower = siegeEnabled
    ? Math.max(0, Math.floor(safeNumber(options.fortification.currentWallPower, 0)))
    : 0;
  const effectiveWallPower = wallDefenseIgnored ? 0 : startingWallPower;
  const garrisonDefensePower = siegeEnabled
    ? Math.max(0, Math.floor(safeNumber(
      options.garrisonDefensePower,
      Math.max(0, safeNumber(options.defensePower, 0) - startingWallPower)
    )))
    : 0;
  const defensePower = wallDefenseIgnored
    ? garrisonDefensePower
    : Number.isFinite(Number(options.defensePower))
      ? Math.max(0, Math.floor(Number(options.defensePower)))
      : siegeEnabled
        ? startingWallPower + garrisonDefensePower
        : getCityStats(target, defenderProfile, options.defenderBonuses).totalDefense;
  const ratio = attackPower / Math.max(1, defensePower);
  const protectedRaid = attackProtection?.mode === "raid";
  const convertedReinforcement = options.convertedReinforcement === true;
  const convertedReinforcementCaptureAllowed = convertedReinforcement
    && options.convertedReinforcementCaptureAllowed !== false;
  const convertedReinforcementCanCapture = protectedRaid && convertedReinforcementCaptureAllowed;
  const breachOnly = attackProtection?.mode === "assault"
    && attackProtection.captureAllowed !== true
    && !convertedReinforcementCaptureAllowed;
  const wallDamagePower = siegeEnabled && !wallDefenseIgnored
    ? Math.min(attackPower, startingWallPower)
    : 0;
  const penetratingAttackPower = siegeEnabled ? Math.max(0, attackPower - effectiveWallPower) : attackPower;
  const wallBreached = siegeEnabled && !wallDefenseIgnored && startingWallPower <= attackPower;
  const garrisonExposed = wallDefenseIgnored || wallBreached;
  const rawEndingIntegrityBps = siegeEnabled && fullWallPower > 0
    ? Math.max(
      0,
      startingIntegrityBps - Math.ceil(wallDamagePower * 10_000 / fullWallPower)
    )
    : startingIntegrityBps;
  const meaningfulWallDamage = siegeEnabled && startingWallPower > 0 && (
    wallDamagePower * 100 >= fullWallPower * SIEGE_MEANINGFUL_WALL_DAMAGE_PERCENT
    || rawEndingIntegrityBps <= 0
  );
  const siegePowerWon = siegeEnabled
    ? penetratingAttackPower > garrisonDefensePower
    : attackPower > defensePower;
  const battleWon = (!protectedRaid || convertedReinforcementCanCapture) && siegePowerWon;
  const success = battleWon && !breachOnly;
  const raid = protectedRaid && !success;
  const persistentDamageApplied = meaningfulWallDamage && !raid;
  const endingIntegrityBps = persistentDamageApplied ? rawEndingIntegrityBps : startingIntegrityBps;
  const repairTiming = persistentDamageApplied
    ? getSiegeRepairTiming(
      getSiegeRepairLevel(target),
      wallDamagePower,
      fullWallPower,
      options.fortification?.repairAtMs,
      Math.max(0, Math.floor(safeNumber(options.nowMs, Date.now()))),
      Math.min(
        95,
        Math.max(0, safeNumber(options.repairReductionPercent, 0))
          + getCommonGearBonuses(defenderProfile || {}).wallRepairSpeed
      )
    )
    : null;
  const repairAtMs = repairTiming?.repairAtMs
    || Math.max(0, timestampToMs(options.fortification?.repairAtMs));
  const repairWindowMinutes = repairTiming?.repairWindowMinutes
    || Math.max(0, Math.floor(safeNumber(options.fortification?.repairWindowMinutes, 0)));
  const repairReductionPercent = repairTiming?.repairReductionPercent
    ?? clamp(safeNumber(options.fortification?.repairReductionPercent, 0), 0, 100);
  const repairAddedMs = repairTiming?.repairAddedMs || 0;
  const attackerBoost = attackerProfile
    ? skillMultiplier(attackerProfile, "swordmastery") + getCommonGearBonuses(attackerProfile).attackStrength / 100
    : 1;
  let survivors = 0;
  let defendersLeft = defendersAtStart;
  let attackerLosses = troops;
  let defenderLosses = 0;

  if (raid) {
    const pressure = clamp(ratio, 0, 1);
    const damageRate = Math.min(0.1, pressure * 0.2);
    const damageCeiling = Math.floor(defendersAtStart * 0.1);
    defenderLosses = Math.min(damageCeiling, Math.floor(defendersAtStart * damageRate));
    if (defendersAtStart > 0) {
      defenderLosses = Math.min(defenderLosses, defendersAtStart - 1);
      defendersLeft = Math.max(1, defendersAtStart - defenderLosses);
    }
  } else if (battleWon) {
    const leftoverPower = Math.max(0, attackPower - defensePower * (siegeEnabled ? 1 : 0.68));
    survivors = Number.isFinite(Number(options.attackPower))
      ? clamp(Math.floor(troops * leftoverPower / Math.max(attackPower, 1)), 1, troops)
      : clamp(Math.floor(leftoverPower / Math.max(BASE_TROOP_ATTACK_POWER * attackerBoost, 1)), 1, troops);
    attackerLosses = troops - survivors;
    defenderLosses = breachOnly ? Math.max(0, defendersAtStart - 1) : defendersAtStart;
    defendersLeft = breachOnly && defendersAtStart > 0 ? 1 : 0;
  } else if (siegeEnabled && !garrisonExposed) {
    const pressure = clamp(attackPower / Math.max(1, startingWallPower), 0, 1);
    const maximumRate = SIEGE_INTACT_WALL_DEFENDER_LOSS_CAP_PERCENT / 100;
    defenderLosses = Math.min(
      defendersAtStart,
      Math.floor(defendersAtStart * Math.min(maximumRate, pressure * maximumRate))
    );
    defendersLeft = Math.max(defendersAtStart > 0 ? 1 : 0, defendersAtStart - defenderLosses);
  } else if (siegeEnabled) {
    const pressure = clamp(penetratingAttackPower / Math.max(1, garrisonDefensePower), 0, 1);
    defenderLosses = Math.min(
      defendersAtStart,
      Math.floor(defendersAtStart * Math.min(0.82, pressure * 0.82))
    );
    defendersLeft = Math.max(defendersAtStart > 0 ? 1 : 0, defendersAtStart - defenderLosses);
  } else {
    const pressure = clamp(ratio, 0, 1);
    defenderLosses = Math.min(defendersAtStart, Math.floor(defendersAtStart * Math.min(0.82, pressure * 0.82)));
    defendersLeft = Math.max(defendersAtStart > 0 ? 1 : 0, defendersAtStart - defenderLosses);
  }

  return {
    attackPower,
    defensePower,
    ratio,
    battleWon,
    success,
    survivors,
    defendersLeft,
    attackerLosses,
    defenderLosses,
    killedAttackers: attackerLosses,
    killedDefenders: defenderLosses,
    attackProtection,
    demoAttack: attackProtection?.legacyDemoAttack ? normalizeDemoAttackSnapshot(options.demoAttack) : null,
    raidCompleted: raid,
    breachCompleted: breachOnly && battleWon,
    fortificationBreached: wallBreached,
    fortification: siegeEnabled ? {
      modelVersion: SIEGE_COMBAT_VERSION,
      baseCityWalls: Math.max(0, Math.floor(safeNumber(options.fortification.baseCityWalls, 0))),
      reinforcedCityWalls: Math.max(0, Math.floor(safeNumber(options.fortification.reinforcedCityWalls, 0))),
      stoneworksPercent: Math.max(0, safeNumber(options.fortification.stoneworksPercent, 0)),
      gearWallStrengthPercent: Math.max(0, safeNumber(options.fortification.gearWallStrengthPercent, 0)),
      cityLevelDefensePercent: Math.max(0, safeNumber(options.fortification.cityLevelDefensePercent, 0)),
      defenseCombatVersion: Math.max(0, Math.floor(safeNumber(options.fortification.defenseCombatVersion, 0))),
      baseDefensePowerPerTroop: Math.max(1, safeNumber(options.fortification.baseDefensePowerPerTroop, 1)),
      shieldwallDisciplinePercent: Math.max(0, safeNumber(options.fortification.shieldwallDisciplinePercent, 0)),
      gearDefenderStrengthPercent: Math.max(0, safeNumber(options.fortification.gearDefenderStrengthPercent, 0)),
      troopObjectiveDefenseBonusPercent: Math.max(0, safeNumber(
        options.fortification.troopObjectiveDefenseBonusPercent,
        0
      )),
      objectiveDefenseBonusPercent: Math.max(0, safeNumber(options.fortification.objectiveDefenseBonusPercent, 0)),
      fullWallPower,
      wallDefenseIgnored,
      startingIntegrityBps,
      startingWallPower,
      wallDamagePower,
      penetratingAttackPower,
      garrisonDefensePower,
      ownerGarrisonDefensePower: Math.max(0, Math.floor(safeNumber(
        options.fortification.ownerGarrisonDefensePower,
        garrisonDefensePower
      ))),
      reinforcementGarrisonDefensePower: Math.max(0, Math.floor(safeNumber(
        options.fortification.reinforcementGarrisonDefensePower,
        0
      ))),
      rawEndingIntegrityBps,
      endingIntegrityBps,
      meaningfulWallDamage,
      persistentDamageApplied,
      repairAtMs,
      repairWindowMinutes,
      repairReductionPercent,
      repairAddedMs,
      breached: wallBreached,
    } : null,
    convertedReinforcement,
    convertedReinforcementCapture: convertedReinforcementCanCapture && success,
  };
}

function getXpRequiredForLevel(level) {
  const current = Math.max(1, Math.floor(safeNumber(level, 1)));
  const legacyRequirement = value => Math.floor(
    150 + value * 65 + Math.pow(value, 2.05) * 35
  );
  if (current <= HERO_XP_EXPONENTIAL_START_LEVEL) return legacyRequirement(current);
  const anchor = legacyRequirement(HERO_XP_EXPONENTIAL_START_LEVEL);
  const requirement = anchor * Math.pow(
    HERO_XP_EXPONENTIAL_GROWTH_RATE,
    current - HERO_XP_EXPONENTIAL_START_LEVEL
  );
  if (!Number.isFinite(requirement)) return Number.MAX_SAFE_INTEGER;
  return Math.min(
    Number.MAX_SAFE_INTEGER,
    Math.floor(requirement)
  );
}

function getLevelUpGoldUpgradeShare(level) {
  const current = Math.max(1, Math.floor(safeNumber(level, 1)));
  if (current <= HERO_XP_SOFT_CAP_LEVEL) return LEVEL_UP_GOLD_EARLY_UPGRADE_SHARE;
  if (current <= HERO_XP_HARD_CAP_LEVEL) {
    const progress = (current - HERO_XP_SOFT_CAP_LEVEL)
      / (HERO_XP_HARD_CAP_LEVEL - HERO_XP_SOFT_CAP_LEVEL);
    return LEVEL_UP_GOLD_EARLY_UPGRADE_SHARE
      + (LEVEL_UP_GOLD_MID_END_UPGRADE_SHARE - LEVEL_UP_GOLD_EARLY_UPGRADE_SHARE) * progress;
  }
  return LEVEL_UP_GOLD_END_UPGRADE_SHARE;
}

function getLevelUpGoldProductionHours(level) {
  const current = Math.max(1, Math.floor(safeNumber(level, 1)));
  if (current <= HERO_XP_SOFT_CAP_LEVEL) return LEVEL_UP_GOLD_EARLY_PRODUCTION_HOURS;
  if (current <= HERO_XP_HARD_CAP_LEVEL) {
    const progress = (current - HERO_XP_SOFT_CAP_LEVEL)
      / (HERO_XP_HARD_CAP_LEVEL - HERO_XP_SOFT_CAP_LEVEL);
    return LEVEL_UP_GOLD_EARLY_PRODUCTION_HOURS
      + (LEVEL_UP_GOLD_MID_END_PRODUCTION_HOURS - LEVEL_UP_GOLD_EARLY_PRODUCTION_HOURS) * progress;
  }
  return LEVEL_UP_GOLD_END_PRODUCTION_HOURS;
}

function getLevelUpGoldFloor(level) {
  const current = Math.max(1, Math.floor(safeNumber(level, 1)));
  return LEVEL_UP_GOLD_FLOOR_BASE
    + current * LEVEL_UP_GOLD_FLOOR_PER_LEVEL
    + Math.pow(current, LEVEL_UP_GOLD_FLOOR_EXPONENT) * LEVEL_UP_GOLD_FLOOR_EXPONENT_SCALE;
}

function getLevelUpGoldReward(level) {
  const current = Math.max(1, Math.floor(safeNumber(level, 1)));
  const goldFloor = getLevelUpGoldFloor(current);
  const referenceCityLevel = Math.max(1, current - 1);
  const referenceUpgradeCost = getCityUpgradeCost({ level: referenceCityLevel });
  const upgradeRelief = Number.isFinite(referenceUpgradeCost)
    ? referenceUpgradeCost * getLevelUpGoldUpgradeShare(current)
    : 0;
  const productionRelief = getMillionLordsPassiveGoldPerHour(current)
    * getLevelUpGoldProductionHours(current);
  return Math.floor(Math.max(goldFloor, Math.min(upgradeRelief, productionRelief)));
}

function getLevelUpTroopRewardHours(level) {
  const current = Math.max(1, Math.floor(safeNumber(level, 1)));
  if (current <= HERO_XP_SOFT_CAP_LEVEL) {
    return LEVEL_UP_TROOP_REWARD_EARLY_BASE_HOURS
      + current * LEVEL_UP_TROOP_REWARD_EARLY_HOURS_PER_LEVEL;
  }
  if (current <= HERO_XP_HARD_CAP_LEVEL) {
    return LEVEL_UP_TROOP_REWARD_MID_BASE_HOURS
      + (current - HERO_XP_SOFT_CAP_LEVEL) * LEVEL_UP_TROOP_REWARD_MID_HOURS_PER_LEVEL;
  }
  return Math.min(
    LEVEL_UP_TROOP_REWARD_MAX_HOURS,
    LEVEL_UP_TROOP_REWARD_END_BASE_HOURS
      + (current - HERO_XP_HARD_CAP_LEVEL) * LEVEL_UP_TROOP_REWARD_END_HOURS_PER_LEVEL
  );
}

function getLevelUpTroopReward(level) {
  const current = Math.max(1, Math.floor(safeNumber(level, 1)));
  const production = getCityProductionStats({ level: current }, {}, {}, {
    includeWarDrums: false,
    includeRoyalTaxDecree: false,
  });
  return Math.floor(Math.max(
    50,
    production.troopProductionPerHour * getLevelUpTroopRewardHours(current)
  ));
}

function normalizeCharacterProgress(character = {}) {
  const normalized = {
    level: Math.max(1, Math.floor(safeNumber(character.level, CHARACTER_START_LEVEL))),
    xp: Math.max(0, Math.floor(safeNumber(character.xp, CHARACTER_START_XP))),
    skillPoints: Math.max(0, Math.floor(safeNumber(character.skillPoints, 0))),
  };
  while (normalized.xp >= getXpRequiredForLevel(normalized.level)) {
    normalized.xp -= getXpRequiredForLevel(normalized.level);
    normalized.level += 1;
  }
  return normalized;
}

function applyXpToCharacter(character = {}, amount = 0) {
  const next = normalizeCharacterProgress(character);
  const fromLevel = next.level;
  let xp = Math.max(0, Math.floor(safeNumber(amount, 0)));
  let goldReward = 0;
  let troopReward = 0;
  let levelsGained = 0;
  next.xp += xp;
  while (next.xp >= getXpRequiredForLevel(next.level)) {
    next.xp -= getXpRequiredForLevel(next.level);
    next.level += 1;
    next.skillPoints += 1;
    levelsGained += 1;
    goldReward += getLevelUpGoldReward(next.level);
    troopReward += getLevelUpTroopReward(next.level);
  }
  return {
    character: next,
    xp,
    levelsGained,
    goldReward,
    troopReward,
    levelUpReward: levelsGained > 0
      ? {
        fromLevel,
        toLevel: next.level,
        levelsGained,
        skillPointsAwarded: levelsGained,
        goldAwarded: goldReward,
        troopsAwarded: troopReward,
        cityId: "",
        cityName: "",
        regionId: "",
      }
      : null,
  };
}

function getBattleXpTroopCredit(target = {}, troops = 0, defenderProfile = null) {
  const stats = getCityStats(target, defenderProfile);
  const cap = Math.max(
    25,
    Math.floor(
      stats.cityWalls * BATTLE_XP_TROOP_CREDIT_CITY_WALL_MULTIPLIER
        + stats.victoryPoints * BATTLE_XP_TROOP_CREDIT_VP_MULTIPLIER
    )
  );
  const hardCap = Math.min(
    Number.MAX_SAFE_INTEGER,
    getXpRequiredForLevel(stats.level) * BATTLE_XP_TROOP_CREDIT_LEVEL_CAP_MULTIPLIER
  );
  return Math.min(Math.max(0, Math.floor(safeNumber(troops, 0))), Math.max(cap, hardCap));
}

function getOpponentPowerXpMultiplier(opponentRatio) {
  const ratio = safeNumber(opponentRatio, 0);
  if (ratio >= 2) return 2;
  if (ratio >= 1.5) return 1.5;
  if (ratio >= 0.5) return 1;
  return 0;
}

function getCityXpScore(target = {}, oldOwnerUid = "", defenderProfile = null) {
  const stats = getCityStats(target, defenderProfile);
  const ownerBonus = oldOwnerUid ? 45 : 10;
  return stats.victoryPoints
    + getBattleXpTroopCredit(target, target.troops, defenderProfile) * 0.25
    + ownerBonus;
}

function getCaptureXpEfficiency(target = {}, oldOwnerUid = "", {
  attackerProfile = null,
  defenderProfile = null,
  attackerKingPower = 0,
  defenderKingPower = 0,
  attackerCityCount = 0,
} = {}) {
  if (oldOwnerUid) {
    const attackerPower = Math.max(1, Math.floor(safeNumber(attackerKingPower, 1)));
    const defenderPower = Math.max(1, Math.floor(safeNumber(defenderKingPower, 1)));
    return getOpponentPowerXpMultiplier(defenderPower / attackerPower);
  }

  const heroLevel = normalizeCharacterProgress(attackerProfile?.character || {}).level;
  const empirePressure = 48 + heroLevel * 20 + Math.max(0, Math.floor(safeNumber(attackerCityCount, 0))) * 2;
  const targetScore = getCityXpScore(target, oldOwnerUid, defenderProfile);
  return Number(clamp(0.35 + targetScore / Math.max(1, empirePressure), 0.25, 2).toFixed(2));
}

function getCaptureXpAward(
  target = {},
  oldOwnerUid = "",
  defenderLosses = 0,
  defenderProfile = null,
  options = {}
) {
  if (isGivenUpNeutralCity(target)) return 0;
  const level = clampCityLevel(target.level);
  const troopXp = Math.floor(
    getBattleXpTroopCredit(target, defenderLosses, defenderProfile) * CAPTURE_XP_PER_DEFENDER
  );
  const cityXp = CAPTURE_XP_BASE
    + level * CAPTURE_XP_PER_CITY_LEVEL
    + (oldOwnerUid ? ENEMY_CAPTURE_XP_BONUS : 0);
  const efficiency = getCaptureXpEfficiency(target, oldOwnerUid, {
    ...options,
    defenderProfile,
  });
  return Math.floor((cityXp + troopXp) * efficiency);
}

function getDefenseHeldXpAward(attackingTroops, target = {}, defenderProfile = null) {
  return Math.floor(DEFENSE_HELD_XP_BASE + getBattleXpTroopCredit(target, attackingTroops, defenderProfile) * DEFENSE_HELD_XP_PER_ATTACKER);
}

function getPartialBattleXpAward(fullWinXp) {
  return Math.floor(Math.max(0, safeNumber(fullWinXp, 0)) * FAILED_BATTLE_XP_RATE);
}

function getBattleXpLevelCapRate(level) {
  const current = Math.max(1, Math.floor(safeNumber(level, 1)));
  if (current <= HERO_XP_SOFT_CAP_LEVEL) return BATTLE_XP_EARLY_LEVEL_CAP_RATE;
  if (current <= HERO_XP_HARD_CAP_LEVEL) {
    const progress = (current - HERO_XP_SOFT_CAP_LEVEL)
      / (HERO_XP_HARD_CAP_LEVEL - HERO_XP_SOFT_CAP_LEVEL);
    return BATTLE_XP_MID_START_LEVEL_CAP_RATE
      + (BATTLE_XP_MID_END_LEVEL_CAP_RATE - BATTLE_XP_MID_START_LEVEL_CAP_RATE) * progress;
  }
  const progress = Math.min(1, (current - HERO_XP_HARD_CAP_LEVEL) / BATTLE_XP_END_CAP_RAMP_LEVELS);
  return Math.max(
    BATTLE_XP_END_FLOOR_LEVEL_CAP_RATE,
    BATTLE_XP_END_START_LEVEL_CAP_RATE
      + (BATTLE_XP_END_FLOOR_LEVEL_CAP_RATE - BATTLE_XP_END_START_LEVEL_CAP_RATE) * progress
  );
}

function capBattleXpForHeroLevel(xp, profile = {}) {
  const base = Math.max(0, Math.floor(safeNumber(xp, 0)));
  const character = normalizeCharacterProgress(profile?.character || {});
  const heroLevel = Math.max(1, Math.floor(safeNumber(character.level, CHARACTER_START_LEVEL)));
  const cap = Math.max(
    250,
    Math.floor(getXpRequiredForLevel(heroLevel) * getBattleXpLevelCapRate(heroLevel))
  );
  return Math.min(base, cap);
}

function getTroopTravelBandIndex(troops) {
  const count = Math.max(1, Math.floor(safeNumber(troops, 1)));
  const index = ARMY_TRAVEL_TROOP_BAND_LIMITS.findIndex(limit => count <= limit);
  return index >= 0 ? index : ARMY_TRAVEL_TROOP_BAND_MULTIPLIERS.length - 1;
}

function getTroopTravelMultiplier(troops) {
  return ARMY_TRAVEL_TROOP_BAND_MULTIPLIERS[getTroopTravelBandIndex(troops)] || 1;
}

function calculateTravelTime({ pathLength = 0, troopCount = 1, kind = "attack", requestedTotal = 0, demoAttack = null, speedMultiplier = 1 }) {
  const distance = Math.max(1, safeNumber(pathLength, 1));
  const kindMultiplier = ARMY_TRAVEL_KIND_MULTIPLIERS[kind] || ARMY_TRAVEL_KIND_MULTIPLIERS.attack;
  const troopMultiplier = getTroopTravelMultiplier(troopCount);
  const demoMultiplier = normalizeDemoAttackSnapshot(demoAttack)?.travelMultiplier || 1;
  const minSeconds = kind === "scout" ? ARMY_TRAVEL_SCOUT_MIN_SECONDS : ARMY_TRAVEL_MIN_SECONDS;
  const speed = Math.max(0.1, safeNumber(speedMultiplier, 1));
  const computed = clamp(distance * ARMY_TRAVEL_SECONDS_PER_MAP_UNIT * kindMultiplier * troopMultiplier * demoMultiplier / speed, minSeconds, ARMY_TRAVEL_MAX_SECONDS);
  const requested = safeNumber(requestedTotal, computed);
  return clamp(Math.max(computed, requested), minSeconds, ARMY_TRAVEL_MAX_SECONDS);
}

function normalizePoint(point = {}) {
  const x = safeNumber(point.x, NaN);
  const y = safeNumber(point.y, NaN);
  return Number.isFinite(x) && Number.isFinite(y) ? { x, y } : null;
}

function normalizePath(points = []) {
  return Array.isArray(points)
    ? points.map(normalizePoint).filter(Boolean).slice(0, MAX_ROUTE_POINTS_PER_SEGMENT)
    : [];
}

function routeLength(points = []) {
  let total = 0;
  for (let index = 1; index < points.length; index += 1) {
    total += Math.hypot(points[index].x - points[index - 1].x, points[index].y - points[index - 1].y);
  }
  return total;
}

function normalizePathSegments(segments = []) {
  return Array.isArray(segments)
    ? segments.map(segment => {
      const points = normalizePath(segment?.points);
      if (points.length < 2) return null;
      return {
        regionId: normalizeRegionId(segment.regionId),
        points,
        length: Math.max(0, safeNumber(segment.length, routeLength(points))),
      };
    }).filter(Boolean).slice(0, MAX_ROUTE_SEGMENT_COUNT)
    : [];
}

function normalizeRegionIds(value = []) {
  return [...new Set((Array.isArray(value) ? value : [])
    .map(normalizeRegionId)
    .filter(Boolean))]
    .slice(0, MAX_ROUTE_REGION_COUNT);
}

function normalizeArmyPayload(data = {}, uid = "") {
  const raw = data.army && typeof data.army === "object" ? data.army : data.movement || {};
  const fromId = safeString(raw.fromId || data.fromId, 96);
  const toId = safeString(raw.toId || data.toId, 96);
  const kind = ARMY_ORDER_KINDS.includes(raw.kind) ? raw.kind : "attack";
  const sourceRegionId = normalizeRegionId(data.sourceRegionId || raw.sourceRegionId || data.fromRegionId);
  const targetRegionId = normalizeRegionId(data.targetRegionId || raw.targetRegionId || data.toRegionId);
  const pathSegments = normalizePathSegments(raw.pathSegments || data.pathSegments);
  const routeRegionIds = normalizeRegionIds([
    ...normalizeRegionIds(raw.routeRegionIds || data.routeRegionIds),
    ...pathSegments.map(segment => segment.regionId),
    sourceRegionId,
    targetRegionId,
  ]);
  const path = normalizePath(raw.path || data.path);
  const pathLength = Math.max(
    0,
    safeNumber(raw.pathLength || data.pathLength, 0),
    pathSegments.reduce((total, segment) => total + segment.length, 0),
    routeLength(path)
  );

  return {
    id: safeString(raw.id || data.armyId || `${uid}_${kind}_${Date.now().toString(36)}`, 96).replace(/[^a-zA-Z0-9_-]/g, "_"),
    ownerUid: uid,
    ownerName: normalizePlayerName(raw.ownerName || data.ownerName),
    ownerFlag: raw.ownerFlag || data.ownerFlag || null,
    ownerKingPower: Math.max(0, Math.floor(safeNumber(raw.ownerKingPower, 0))),
    kind,
    launchKind: ARMY_ORDER_KINDS.includes(raw.launchKind) ? raw.launchKind : kind,
    targetType: raw.targetType === "camp" || data.targetType === "camp" ? "camp" : "city",
    fromId,
    toId,
    fromName: safeString(raw.fromName, 40),
    toName: safeString(raw.toName, 40),
    troops: Math.max(0, Math.floor(safeNumber(raw.troops ?? data.troops, 0))),
    requestedTroops: Math.max(0, Math.floor(safeNumber(raw.requestedTroops ?? data.requestedTroops, raw.troops ?? data.troops ?? 0))),
    total: Math.max(0.1, safeNumber(raw.total, 0.1)),
    path,
    pathSegments,
    routeRegionIds,
    pathLength,
    sourceRegionId,
    targetRegionId,
    targetOwnerAtLaunch: safeString(raw.targetOwnerAtLaunch || "neutral", 32),
    originalTargetOwnerUid: safeString(raw.originalTargetOwnerUid || raw.targetOwnerUid, 128),
    attackerKingPower: Math.max(0, Math.floor(safeNumber(raw.attackerKingPower || raw.ownerKingPower, 0))),
    defenderKingPower: Math.max(0, Math.floor(safeNumber(raw.defenderKingPower, 0))),
    acceptedAttackProtection: raw.acceptedAttackProtection && typeof raw.acceptedAttackProtection === "object"
      ? raw.acceptedAttackProtection
      : data.acceptedAttackProtection && typeof data.acceptedAttackProtection === "object"
        ? data.acceptedAttackProtection
        : null,
    attackProtection: raw.attackProtection && typeof raw.attackProtection === "object" ? raw.attackProtection : null,
    demoAttack: raw.demoAttack && typeof raw.demoAttack === "object" ? raw.demoAttack : null,
    protectionHandling: raw.protectionHandling === "auto_cap" || data.protectionHandling === "auto_cap"
      ? "auto_cap"
      : "reconfirm",
    useSwiftMarchOrder: raw.useSwiftMarchOrder === true || data.useSwiftMarchOrder === true,
  };
}

function allocateDefenderLosses(ownerTroops = 0, contributions = [], totalLosses = 0) {
  const ownerStart = Math.max(0, Math.floor(safeNumber(ownerTroops, 0)));
  const rows = (Array.isArray(contributions) ? contributions : [])
    .map(entry => ({
      ...entry,
      troops: Math.max(0, Math.floor(safeNumber(entry?.troops, 0))),
    }))
    .filter(entry => entry.ownerUid && entry.troops > 0);
  const alliedStart = rows.reduce((total, entry) => total + entry.troops, 0);
  const defendersAtStart = ownerStart + alliedStart;
  const losses = Math.min(defendersAtStart, Math.max(0, Math.floor(safeNumber(totalLosses, 0))));
  if (!defendersAtStart || !losses) {
    return {
      ownerStart,
      ownerLosses: 0,
      ownerRemaining: ownerStart,
      alliedStart,
      alliedLosses: 0,
      alliedRemaining: alliedStart,
      contributions: rows.map(entry => ({ ...entry, losses: 0, remaining: entry.troops })),
    };
  }

  const ownerExact = losses * ownerStart / defendersAtStart;
  let ownerLosses = Math.min(ownerStart, Math.floor(ownerExact));
  const allocated = rows.map(entry => {
    const exact = losses * entry.troops / defendersAtStart;
    const entryLosses = Math.min(entry.troops, Math.floor(exact));
    return {
      ...entry,
      exact,
      losses: entryLosses,
      remaining: entry.troops - entryLosses,
    };
  });
  let assigned = ownerLosses + allocated.reduce((total, entry) => total + entry.losses, 0);
  let remainder = Math.max(0, losses - assigned);

  const ownerCapacity = Math.max(0, ownerStart - ownerLosses);
  const ownerRemainder = Math.min(ownerCapacity, remainder);
  ownerLosses += ownerRemainder;
  remainder -= ownerRemainder;
  if (remainder > 0) {
    allocated
      .sort((a, b) => (b.exact - Math.floor(b.exact)) - (a.exact - Math.floor(a.exact))
        || a.ownerUid.localeCompare(b.ownerUid))
      .forEach(entry => {
        if (remainder <= 0 || entry.losses >= entry.troops) return;
        entry.losses += 1;
        entry.remaining -= 1;
        remainder -= 1;
      });
  }
  assigned = ownerLosses + allocated.reduce((total, entry) => total + entry.losses, 0);
  if (assigned < losses) {
    for (const entry of allocated) {
      const capacity = entry.troops - entry.losses;
      const extra = Math.min(capacity, losses - assigned);
      entry.losses += extra;
      entry.remaining -= extra;
      assigned += extra;
      if (assigned >= losses) break;
    }
  }
  allocated.sort((a, b) => a.ownerUid.localeCompare(b.ownerUid));
  const alliedLosses = allocated.reduce((total, entry) => total + entry.losses, 0);
  return {
    ownerStart,
    ownerLosses,
    ownerRemaining: Math.max(0, ownerStart - ownerLosses),
    alliedStart,
    alliedLosses,
    alliedRemaining: Math.max(0, alliedStart - alliedLosses),
    contributions: allocated,
  };
}

function allocateDefenseXp(totalXp = 0, ownerTroops = 0, contributions = []) {
  const pool = Math.max(0, Math.floor(safeNumber(totalXp, 0)));
  const ownerStart = Math.max(0, Math.floor(safeNumber(ownerTroops, 0)));
  const rows = (Array.isArray(contributions) ? contributions : []).filter(entry => entry?.ownerUid && entry.troops > 0);
  const totalTroops = ownerStart + rows.reduce((total, entry) => total + entry.troops, 0);
  if (!pool || !totalTroops) {
    return { ownerXp: pool, contributorXp: new Map(rows.map(entry => [entry.ownerUid, 0])) };
  }
  const contributorXp = new Map();
  let assigned = 0;
  rows.forEach(entry => {
    const value = Math.max(0, Math.floor(pool * entry.troops / totalTroops));
    contributorXp.set(entry.ownerUid, value);
    assigned += value;
  });
  return {
    ownerXp: Math.max(0, pool - assigned),
    contributorXp,
  };
}

function cityRefForRegion(regionId, cityId) {
  return db.doc(`islands/${getOnlineIslandId(regionId)}/cities/${cityId}`);
}

function getReinforcementTargetKey(targetType = "city", regionId = "", targetId = "") {
  return `${targetType === "camp" ? "camp" : "city"}:${normalizeRegionId(regionId)}:${safeString(targetId, 96)}`;
}

function getReinforcementId(ownerUid = "", targetKey = "") {
  const digest = crypto.createHash("sha256")
    .update(`${RESET_GENERATION}|${safeString(ownerUid, 128)}|${safeString(targetKey, 220)}`)
    .digest("hex")
    .slice(0, 40);
  return `reinforce_${digest}`;
}

function reinforcementRef(ownerUid = "", targetKey = "") {
  return db.doc(`reinforcements/${getReinforcementId(ownerUid, targetKey)}`);
}

function stationedReinforcementsForTargetQuery(targetKey = "") {
  return db.collection("reinforcements")
    .where("targetKey", "==", safeString(targetKey, 220))
    .where("resetGeneration", "==", RESET_GENERATION)
    .where("worldId", "==", ONLINE_WORLD_ID)
    .where("status", "==", REINFORCEMENT_STATUS_STATIONED);
}

function normalizeReinforcementContribution(doc = null) {
  if (!doc?.exists) return null;
  const data = doc.data() || {};
  if (
    safeString(data.resetGeneration, 120) !== RESET_GENERATION
    || safeString(data.worldId, 120) !== ONLINE_WORLD_ID
    || data.status !== REINFORCEMENT_STATUS_STATIONED
  ) return null;
  const troops = Math.max(0, Math.floor(safeNumber(data.troops, 0)));
  if (!troops) return null;
  return {
    id: doc.id,
    ref: doc.ref,
    ...data,
    ownerUid: safeString(data.ownerUid, 128),
    targetOwnerUid: safeString(data.targetOwnerUid, 128),
    troops,
  };
}

function getProfileStationedReinforcementTroops(profile = {}) {
  if (safeString(profile.reinforcementResetGeneration, 120) !== RESET_GENERATION) return 0;
  return Math.max(0, Math.floor(safeNumber(profile.stationedReinforcementTroops, 0)));
}

function getClanReinforcementAssignmentToken(recipientUid = "", targetKey = "") {
  const recipient = safeString(recipientUid, 128);
  const target = safeString(targetKey, 220);
  return recipient && target ? `${recipient}|${target}` : "";
}

function parseClanReinforcementAssignmentToken(value = "") {
  const token = safeString(value, 360);
  const separator = token.indexOf("|");
  if (separator <= 0) return null;
  const recipientUid = safeString(token.slice(0, separator), 128);
  const targetKey = safeString(token.slice(separator + 1), 220);
  return recipientUid && targetKey ? { token, recipientUid, targetKey } : null;
}

function normalizeActiveClanReinforcementAssignments(profile = {}) {
  if (
    safeString(profile.clanReinforcementLimitResetGeneration, 120) !== RESET_GENERATION
    || clampInt(profile.clanReinforcementLimitVersion, 0, 99) < REINFORCEMENT_MODEL_VERSION
  ) return [];
  const assignments = (Array.isArray(profile.activeClanReinforcementAssignments)
    ? profile.activeClanReinforcementAssignments
    : [])
    .map(parseClanReinforcementAssignmentToken)
    .filter(Boolean);
  return [...new Map(assignments.map(entry => [entry.token, entry])).values()];
}

async function getActiveClanReinforcementAssignmentsForLaunch(transaction, uid = "", profile = {}) {
  const storedAssignments = normalizeActiveClanReinforcementAssignments(profile);
  if (
    safeString(profile.clanReinforcementLimitResetGeneration, 120) === RESET_GENERATION
    && clampInt(profile.clanReinforcementLimitVersion, 0, 99) >= REINFORCEMENT_MODEL_VERSION
  ) {
    return storedAssignments;
  }

  const playerUid = safeString(uid, 128);
  if (!playerUid) return [];
  const contributionQuery = status => db.collection("reinforcements")
    .where("ownerUid", "==", playerUid)
    .where("resetGeneration", "==", RESET_GENERATION)
    .where("worldId", "==", ONLINE_WORLD_ID)
    .where("status", "==", status);
  const [activeArmiesSnap, stationedSnap] = await Promise.all([
    transaction.get(activeArmiesQueryForPlayer(playerUid)),
    transaction.get(contributionQuery(REINFORCEMENT_STATUS_STATIONED)),
  ]);
  const assignments = new Map(storedAssignments.map(entry => [entry.token, entry]));
  activeArmiesSnap.docs.forEach(doc => {
    const army = doc.data() || {};
    const launchedAsReinforcement = !army.reinforcementReturn
      && (
        army.kind === "reinforce"
        || army.launchKind === "reinforce"
        || army.retargetedFromKind === "reinforce"
      );
    if (!launchedAsReinforcement) return;
    const targetKey = safeString(
      army.reinforcementTargetKey
        || getReinforcementTargetKey(army.targetType, army.targetRegionId, army.toId),
      220
    );
    const recipientUid = safeString(
      army.reinforcementRecipientUid || army.originalTargetOwnerUid || army.targetOwnerUid,
      128
    );
    const token = getClanReinforcementAssignmentToken(recipientUid, targetKey);
    if (token) assignments.set(token, { token, recipientUid, targetKey });
  });
  stationedSnap.docs.forEach(doc => {
    const contribution = doc.data() || {};
    const targetKey = safeString(contribution.targetKey, 220);
    const recipientUid = safeString(
      contribution.reinforcementRecipientUid || contribution.originalTargetOwnerUid || contribution.targetOwnerUid,
      128
    );
    const token = getClanReinforcementAssignmentToken(recipientUid, targetKey);
    if (token) assignments.set(token, { token, recipientUid, targetKey });
  });
  return [...assignments.values()];
}

function releaseClanReinforcementAssignment(
  transaction,
  ownerUid = "",
  recipientUid = "",
  targetKey = ""
) {
  const playerUid = safeString(ownerUid, 128);
  const normalizedRecipientUid = safeString(recipientUid, 128);
  const normalizedTargetKey = safeString(targetKey, 220);
  if (!playerUid || !normalizedTargetKey) return;
  const token = getClanReinforcementAssignmentToken(normalizedRecipientUid, normalizedTargetKey);
  transaction.set(db.doc(`players/${playerUid}`), {
    ...(token ? { activeClanReinforcementAssignments: FieldValue.arrayRemove(token) } : {}),
    activeClanReinforcementTargets: FieldValue.arrayRemove(normalizedTargetKey),
    updatedAt: FieldValue.serverTimestamp(),
  }, { merge: true });
}

function getReinforcementCapacityId(targetKey = "") {
  return crypto.createHash("sha256")
    .update(`${RESET_GENERATION}|${safeString(targetKey, 220)}`)
    .digest("hex")
    .slice(0, 40);
}

function reinforcementCapacityRef(targetKey = "") {
  return db.doc(
    `reinforcementCapacity/${RESET_GENERATION}/cities/${getReinforcementCapacityId(targetKey)}`
  );
}

function isOrdinaryReinforcementCity(target = {}, targetType = "city") {
  return targetType === "city" && !isStronghold(target);
}

function normalizeReinforcementCapacityReservations(data = {}) {
  const rows = Array.isArray(data.reservations) ? data.reservations : [];
  return [...new Map(rows.map(row => {
    const ownerUid = safeString(row?.ownerUid, 128);
    if (!ownerUid) return null;
    return [ownerUid, {
      ownerUid,
      armyId: safeString(row?.armyId, 96),
      recipientUid: safeString(row?.recipientUid, 128),
      reservedAtMs: Math.max(0, Math.floor(safeNumber(row?.reservedAtMs, 0))),
    }];
  }).filter(Boolean)).values()]
    .sort((a, b) => a.reservedAtMs - b.reservedAtMs || a.ownerUid.localeCompare(b.ownerUid));
}

function writeReinforcementCapacityState(transaction, {
  capacityRef = null,
  targetRef = null,
  target = {},
  targetKey = "",
  reservations = [],
  nowMs = Date.now(),
} = {}) {
  if (!capacityRef || !targetRef || !isOrdinaryReinforcementCity(target, "city")) return reservations;
  const normalized = normalizeReinforcementCapacityReservations({ reservations })
    .slice(0, ORDINARY_CITY_REINFORCEMENT_CAPACITY);
  transaction.set(capacityRef, {
    id: capacityRef.id,
    worldId: ONLINE_WORLD_ID,
    resetGeneration: RESET_GENERATION,
    targetKey: safeString(targetKey, 220),
    targetId: safeString(target.id, 96),
    targetRegionId: normalizeRegionId(target.regionId),
    reservations: normalized,
    reservedSlotCount: normalized.length,
    modelVersion: REINFORCEMENT_MODEL_VERSION,
    updatedAtMs: nowMs,
    updatedAt: FieldValue.serverTimestamp(),
  }, { merge: true });
  transaction.set(targetRef, {
    clanReinforcementSlotCount: normalized.length,
    updatedAt: FieldValue.serverTimestamp(),
  }, { merge: true });
  return normalized;
}

function reserveOrdinaryCityReinforcementSlot(transaction, {
  capacitySnap = null,
  targetRef = null,
  target = {},
  targetKey = "",
  ownerUid = "",
  recipientUid = "",
  armyId = "",
  nowMs = Date.now(),
} = {}) {
  if (!isOrdinaryReinforcementCity(target, "city")) return [];
  const capacityRef = capacitySnap?.ref || reinforcementCapacityRef(targetKey);
  const reservations = normalizeReinforcementCapacityReservations(capacitySnap?.data() || {});
  if (reservations.some(entry => entry.ownerUid === ownerUid)) {
    throw new HttpsError(
      "failed-precondition",
      "You already have one active reinforcement assigned to this holding."
    );
  }
  if (reservations.length >= ORDINARY_CITY_REINFORCEMENT_CAPACITY) {
    throw new HttpsError(
      "resource-exhausted",
      `This city already has all ${ORDINARY_CITY_REINFORCEMENT_CAPACITY} reinforcement slots reserved.`,
      {
        reason: "reinforcement-city-capacity",
        reinforcementCapacity: {
          used: reservations.length,
          limit: ORDINARY_CITY_REINFORCEMENT_CAPACITY,
        },
      }
    );
  }
  return writeReinforcementCapacityState(transaction, {
    capacityRef,
    targetRef,
    target,
    targetKey,
    reservations: [...reservations, {
      ownerUid: safeString(ownerUid, 128),
      recipientUid: safeString(recipientUid, 128),
      armyId: safeString(armyId, 96),
      reservedAtMs: nowMs,
    }],
    nowMs,
  });
}

function releaseOrdinaryCityReinforcementSlot(transaction, {
  capacitySnap = null,
  targetRef = null,
  target = {},
  targetKey = "",
  ownerUid = "",
  nowMs = Date.now(),
} = {}) {
  if (!isOrdinaryReinforcementCity(target, "city") || !capacitySnap?.ref) return [];
  const reservations = normalizeReinforcementCapacityReservations(capacitySnap.data() || {})
    .filter(entry => entry.ownerUid !== safeString(ownerUid, 128));
  return writeReinforcementCapacityState(transaction, {
    capacityRef: capacitySnap.ref,
    targetRef,
    target,
    targetKey,
    reservations,
    nowMs,
  });
}

function normalizeRallyId(value = "") {
  return safeString(value, 96).replace(/[^a-zA-Z0-9_-]/g, "_");
}

function clanRallyRef(clanId = "", rallyId = "") {
  return db.doc(`clans/${safeString(clanId, 128)}/rallies/${normalizeRallyId(rallyId)}`);
}

function clanRallyStateRef(clanId = "") {
  return db.doc(`clans/${safeString(clanId, 128)}/rallyState/${RESET_GENERATION}`);
}

function rallyBattleReceiptRef(armyId = "", contributorUid = "") {
  const receiptId = safeString(`${armyId}_${contributorUid}`, 190).replace(/[^a-zA-Z0-9_-]/g, "_");
  return db.doc(`rallyBattleReceipts/${RESET_GENERATION}/entries/${receiptId}`);
}

function getProfileCommittedRallyTroops(profile = {}) {
  if (safeString(profile.rallyResetGeneration, 120) !== RESET_GENERATION) return 0;
  return Math.max(0, Math.floor(safeNumber(profile.committedRallyTroops, 0)));
}

function normalizeRallyParticipant(raw = {}) {
  const uid = safeString(raw.uid || raw.ownerUid, 128);
  const troops = Math.max(0, Math.floor(safeNumber(raw.troops, 0)));
  if (!uid || !troops) return null;
  const status = [
    RALLY_PARTICIPANT_ASSEMBLED,
    RALLY_PARTICIPANT_INBOUND,
    RALLY_PARTICIPANT_RETURNING,
    RALLY_PARTICIPANT_RETURNED,
  ].includes(raw.status)
    ? raw.status
    : RALLY_PARTICIPANT_INBOUND;
  return {
    uid,
    ownerUid: uid,
    ownerName: normalizePlayerName(raw.ownerName, "Ruler"),
    ownerFlag: raw.ownerFlag || null,
    role: raw.role === "leader" ? "leader" : "ally",
    sourceId: safeString(raw.sourceId, 96),
    sourceName: safeString(raw.sourceName, 40),
    sourceRegionId: normalizeRegionId(raw.sourceRegionId),
    troops,
    status,
    joinArmyId: normalizeRallyId(raw.joinArmyId),
    joinedAtMs: Math.max(0, Math.floor(safeNumber(raw.joinedAtMs, 0))),
    assembledAtMs: Math.max(0, Math.floor(safeNumber(raw.assembledAtMs, 0))),
    arrivesAtMs: Math.max(0, Math.floor(safeNumber(raw.arrivesAtMs, 0))),
    returnArmyId: normalizeRallyId(raw.returnArmyId),
    attackSkillLevel: Math.max(0, Math.floor(safeNumber(raw.attackSkillLevel, 0))),
    attackBonusPercent: Math.max(0, safeNumber(raw.attackBonusPercent, 0)),
    attackGearPercent: Math.max(0, safeNumber(raw.attackGearPercent, 0)),
    attackPowerPerTroop: Math.max(0, safeNumber(raw.attackPowerPerTroop, 0)),
    fieldMedicsPercent: Math.max(0, safeNumber(raw.fieldMedicsPercent, 0)),
    ownerKingPower: Math.max(0, Math.floor(safeNumber(raw.ownerKingPower, 0))),
    losses: Math.max(0, Math.floor(safeNumber(raw.losses, 0))),
    survivors: Math.max(0, Math.floor(safeNumber(raw.survivors, troops))),
    xpAwarded: Math.max(0, Math.floor(safeNumber(raw.xpAwarded, 0))),
    settledAtMs: Math.max(0, Math.floor(safeNumber(raw.settledAtMs, 0))),
  };
}

function normalizeRallyParticipants(value = []) {
  const byUid = new Map();
  (Array.isArray(value) ? value : []).forEach(raw => {
    const participant = normalizeRallyParticipant(raw);
    if (participant && !byUid.has(participant.uid)) byUid.set(participant.uid, participant);
  });
  return [...byUid.values()].slice(0, RALLY_MAX_PARTICIPANTS);
}

function activeRallyParticipants(rally = {}) {
  return normalizeRallyParticipants(rally.participants)
    .filter(participant => [
      RALLY_PARTICIPANT_ASSEMBLED,
      RALLY_PARTICIPANT_INBOUND,
    ].includes(participant.status));
}

function assembledRallyParticipants(rally = {}) {
  return activeRallyParticipants(rally)
    .filter(participant => participant.status === RALLY_PARTICIPANT_ASSEMBLED);
}

function getRallyParticipant(rally = {}, uid = "") {
  const playerUid = safeString(uid, 128);
  return activeRallyParticipants(rally).find(participant => participant.uid === playerUid) || null;
}

function normalizeClanRally(snapshotOrData = null) {
  const exists = snapshotOrData?.exists;
  const data = exists ? snapshotOrData.data() || {} : snapshotOrData || {};
  const id = normalizeRallyId(exists ? snapshotOrData.id : data.id);
  if (
    !id
    || safeString(data.worldId, 120) !== ONLINE_WORLD_ID
    || safeString(data.resetGeneration, 120) !== RESET_GENERATION
  ) return null;
  return {
    ...data,
    id,
    clanId: safeString(data.clanId, 128),
    leaderUid: safeString(data.leaderUid, 128),
    status: safeString(data.status, 24),
    targetType: data.targetType === "camp" ? "camp" : "city",
    targetId: safeString(data.targetId, 96),
    targetRegionId: normalizeRegionId(data.targetRegionId),
    assemblyCityId: safeString(data.assemblyCityId, 96),
    assemblyRegionId: normalizeRegionId(data.assemblyRegionId),
    participants: normalizeRallyParticipants(data.participants),
    routeRegionIds: normalizeRegionIds(data.routeRegionIds),
    pathSegments: normalizePathSegments(data.pathSegments),
    path: normalizePath(data.path),
    pathLength: Math.max(0, safeNumber(data.pathLength, 0)),
    armyId: normalizeRallyId(data.armyId),
  };
}

function isRallyObjectiveTarget(target = {}, targetType = "city") {
  return targetType === "camp" ? Boolean(getRewardCampConfig(target)) : isStronghold(target);
}

function rallyTargetRef(rally = {}) {
  if (!rally.targetRegionId || !rally.targetId) return null;
  return rally.targetType === "camp"
    ? campRefForRegion(rally.targetRegionId, rally.targetId)
    : cityRefForRegion(rally.targetRegionId, rally.targetId);
}

function rallyAssemblyRef(rally = {}) {
  if (!rally.assemblyRegionId || !rally.assemblyCityId) return null;
  return cityRefForRegion(rally.assemblyRegionId, rally.assemblyCityId);
}

function normalizeRallyState(raw = {}) {
  if (
    safeString(raw.worldId, 120) !== ONLINE_WORLD_ID
    || safeString(raw.resetGeneration, 120) !== RESET_GENERATION
  ) {
    return { leaderUids: [] };
  }
  return {
    leaderUids: [...new Set((Array.isArray(raw.leaderUids) ? raw.leaderUids : [])
      .map(uid => safeString(uid, 128))
      .filter(Boolean))]
      .slice(0, CLAN_FORMING_RALLY_LIMIT),
  };
}

function releaseFormingRallySlot(transaction, stateRef, state = {}, leaderUid = "", nowMs = Date.now()) {
  const playerUid = safeString(leaderUid, 128);
  const leaderUids = normalizeRallyState(state).leaderUids.filter(uid => uid !== playerUid);
  transaction.set(stateRef, {
    worldId: ONLINE_WORLD_ID,
    resetGeneration: RESET_GENERATION,
    activeCount: leaderUids.length,
    leaderUids,
    updatedAtMs: nowMs,
    updatedAt: FieldValue.serverTimestamp(),
  }, { merge: true });
}

function getRallyParticipantAttackPower(participant = {}) {
  const troops = Math.max(0, Math.floor(safeNumber(participant.troops, 0)));
  const bonusPercent = Math.max(0, safeNumber(participant.attackBonusPercent, 0));
  const snapshottedPowerPerTroop = Math.max(0, safeNumber(participant.attackPowerPerTroop, 0));
  const attackPowerPerTroop = snapshottedPowerPerTroop
    || BASE_TROOP_ATTACK_POWER * (1 + bonusPercent / 100);
  return Math.max(0, Math.floor(troops * attackPowerPerTroop));
}

function getRallyAttackPackages(rally = {}) {
  const packages = assembledRallyParticipants(rally).map(participant => ({
    ...participant,
    effectivePower: getRallyParticipantAttackPower(participant),
  }));
  const storedAttackPower = Math.max(0, Math.floor(safeNumber(rally.attackPower, 0)));
  const calculatedAttackPower = packages.reduce((total, participant) => total + participant.effectivePower, 0);
  if (!storedAttackPower || !calculatedAttackPower || storedAttackPower === calculatedAttackPower) return packages;
  let assignedPower = 0;
  return packages.map((participant, index) => {
    const effectivePower = index === packages.length - 1
      ? Math.max(0, storedAttackPower - assignedPower)
      : Math.max(0, Math.floor(storedAttackPower * participant.effectivePower / calculatedAttackPower));
    assignedPower += effectivePower;
    return { ...participant, effectivePower };
  });
}

function allocateRallyAttackerLosses(packages = [], totalLosses = 0) {
  const rows = (Array.isArray(packages) ? packages : [])
    .map(entry => ({
      ...entry,
      troops: Math.max(0, Math.floor(safeNumber(entry?.troops, 0))),
    }))
    .filter(entry => entry.uid && entry.troops > 0);
  const totalTroops = rows.reduce((total, entry) => total + entry.troops, 0);
  const losses = Math.min(totalTroops, Math.max(0, Math.floor(safeNumber(totalLosses, 0))));
  let survivorsToAssign = Math.max(0, totalTroops - losses);
  const allocated = rows.map(entry => {
    const exact = totalTroops ? survivorsToAssign * entry.troops / totalTroops : 0;
    const survivors = Math.min(entry.troops, Math.floor(exact));
    return {
      ...entry,
      exact,
      survivors,
      losses: entry.troops - survivors,
    };
  });
  let assigned = allocated.reduce((total, entry) => total + entry.survivors, 0);
  allocated
    .sort((left, right) => (
      (right.exact - Math.floor(right.exact)) - (left.exact - Math.floor(left.exact))
      || Number(right.role === "leader") - Number(left.role === "leader")
      || left.uid.localeCompare(right.uid)
    ))
    .forEach(entry => {
      if (assigned >= survivorsToAssign || entry.survivors >= entry.troops) return;
      entry.survivors += 1;
      entry.losses -= 1;
      assigned += 1;
    });
  const leader = allocated.find(entry => entry.role === "leader");
  if (survivorsToAssign > 0 && leader && leader.survivors <= 0) {
    const donor = allocated.find(entry => entry.role !== "leader" && entry.survivors > 0);
    if (donor) {
      donor.survivors -= 1;
      donor.losses += 1;
      leader.survivors = 1;
      leader.losses = Math.max(0, leader.troops - 1);
    }
  }
  return allocated.sort((left, right) => (
    Number(right.role === "leader") - Number(left.role === "leader")
    || left.uid.localeCompare(right.uid)
  ));
}

function allocateRallyAttackXp(totalXp = 0, packages = []) {
  const pool = Math.max(0, Math.floor(safeNumber(totalXp, 0)));
  const rows = (Array.isArray(packages) ? packages : []).filter(entry => entry?.uid && entry.effectivePower > 0);
  const totalPower = rows.reduce((total, entry) => total + entry.effectivePower, 0);
  const result = new Map(rows.map(entry => [entry.uid, 0]));
  if (!pool || !totalPower) return result;
  let assigned = 0;
  rows
    .slice()
    .sort((left, right) => (
      Number(right.role === "leader") - Number(left.role === "leader")
      || left.uid.localeCompare(right.uid)
    ))
    .forEach((entry, index, ordered) => {
      const value = index === ordered.length - 1
        ? Math.max(0, pool - assigned)
        : Math.max(0, Math.floor(pool * entry.effectivePower / totalPower));
      result.set(entry.uid, value);
      assigned += value;
    });
  return result;
}

function createRallyParticipantSnapshot({
  uid = "",
  profile = {},
  source = {},
  sourceRegionId = "",
  troops = 0,
  role = "ally",
  status = RALLY_PARTICIPANT_INBOUND,
  joinArmyId = "",
  joinedAtMs = Date.now(),
  assembledAtMs = 0,
  ownerKingPower = 0,
} = {}) {
  return normalizeRallyParticipant({
    uid,
    ownerName: normalizePlayerName(profile.playerName || profile.displayName || source.ownerName, "Ruler"),
    ownerFlag: profile.flag || source.ownerFlag || null,
    role,
    sourceId: source.id,
    sourceName: source.name || source.id,
    sourceRegionId: normalizeRegionId(sourceRegionId || source.regionId),
    troops,
    status,
    joinArmyId,
    joinedAtMs,
    assembledAtMs,
    attackSkillLevel: getSkillLevel(profile, "swordmastery"),
    attackBonusPercent: getSkillPercent(profile, "swordmastery"),
    attackGearPercent: getCommonGearBonuses(profile).attackStrength,
    attackPowerPerTroop: BASE_TROOP_ATTACK_POWER * (
      skillMultiplier(profile, "swordmastery") + getCommonGearBonuses(profile).attackStrength / 100
    ),
    fieldMedicsPercent: getCasualtyRecoveryPercent(profile),
    ownerKingPower,
  });
}

function rallyForClient(rally = {}) {
  const participants = normalizeRallyParticipants(rally.participants);
  return {
    id: normalizeRallyId(rally.id),
    clanId: safeString(rally.clanId, 128),
    status: safeString(rally.status, 24),
    leaderUid: safeString(rally.leaderUid, 128),
    leaderName: normalizePlayerName(rally.leaderName, "Ruler"),
    targetType: rally.targetType === "camp" ? "camp" : "city",
    targetId: safeString(rally.targetId, 96),
    targetName: safeString(rally.targetName || rally.targetId, 80),
    targetRegionId: normalizeRegionId(rally.targetRegionId),
    assemblyCityId: safeString(rally.assemblyCityId, 96),
    assemblyCityName: safeString(rally.assemblyCityName || rally.assemblyCityId, 80),
    assemblyRegionId: normalizeRegionId(rally.assemblyRegionId),
    participantUids: participants.map(participant => participant.uid),
    participants,
    participantCount: activeRallyParticipants({ participants }).length,
    assembledTroops: participants
      .filter(participant => participant.status === RALLY_PARTICIPANT_ASSEMBLED)
      .reduce((total, participant) => total + participant.troops, 0),
    inboundTroops: participants
      .filter(participant => participant.status === RALLY_PARTICIPANT_INBOUND)
      .reduce((total, participant) => total + participant.troops, 0),
    armyId: normalizeRallyId(rally.armyId),
    createdAtMs: Math.max(0, timestampToMs(rally.createdAtMs)),
    launchedAtMs: Math.max(0, timestampToMs(rally.launchedAtMs)),
    updatedAtMs: Math.max(0, timestampToMs(rally.updatedAtMs)),
  };
}

function rallyParticipantTotals(participants = []) {
  const normalized = normalizeRallyParticipants(participants);
  return {
    participantUids: normalized.map(participant => participant.uid),
    participantCount: activeRallyParticipants({ participants: normalized }).length,
    assembledTroops: normalized
      .filter(participant => participant.status === RALLY_PARTICIPANT_ASSEMBLED)
      .reduce((total, participant) => total + participant.troops, 0),
    inboundTroops: normalized
      .filter(participant => participant.status === RALLY_PARTICIPANT_INBOUND)
      .reduce((total, participant) => total + participant.troops, 0),
  };
}

function createRallyAssemblyMovement({
  order = {},
  rally = {},
  participant = {},
  source = {},
  assembly = {},
  profile = {},
  economy = null,
  validatedRoute = {},
  nowMs = Date.now(),
} = {}) {
  const troops = Math.max(1, Math.floor(safeNumber(participant.troops, 1)));
  const stats = createPreparedEconomyStatsSnapshot(economy, {}, { nowMs });
  const speedMultiplier = addCommonGearMarchSpeed(profile, "rally_join", skillMultiplier(profile, "marchOrders")
    * (1 + Math.max(0, safeNumber(economy?.bonuses?.marchSpeedBonusPercent, 0)) / 100));
  const duration = calculateTravelTime({
    pathLength: validatedRoute.pathLength,
    troopCount: troops,
    kind: "rally_join",
    speedMultiplier,
  });
  return {
    id: normalizeRallyId(order.id),
    worldId: ONLINE_WORLD_ID,
    resetGeneration: RESET_GENERATION,
    ownerKind: "player",
    ownerUid: participant.uid,
    ownerName: participant.ownerName,
    ownerFlag: participant.ownerFlag || null,
    ownerKingPower: Math.max(0, Math.floor(safeNumber(stats?.kingPower, participant.ownerKingPower))),
    kingPowerVersion: GLOBAL_PLAYER_STATS_VERSION,
    kind: "rally_join",
    launchKind: "rally_join",
    rallyJoin: true,
    rallyId: normalizeRallyId(rally.id),
    rallyClanId: safeString(rally.clanId, 128),
    targetType: "city",
    fromId: safeString(source.id, 96),
    toId: safeString(assembly.id, 96),
    sourceRegionId: normalizeRegionId(order.sourceRegionId),
    targetRegionId: normalizeRegionId(rally.assemblyRegionId),
    fromName: safeString(source.name || source.id, 40),
    toName: safeString(assembly.name || assembly.id, 40),
    troops,
    requestedTroops: troops,
    total: duration,
    path: validatedRoute.path,
    pathSegments: validatedRoute.pathSegments,
    routeRegionIds: validatedRoute.routeRegionIds,
    viewRegionIds: validatedRoute.routeRegionIds,
    pathLength: validatedRoute.pathLength,
    targetKey: `${rally.assemblyRegionId}:${rally.assemblyCityId}`,
    targetOwnerAtLaunch: "player",
    originalTargetOwnerUid: rally.leaderUid,
    targetOwnerUid: rally.leaderUid,
    lastIncomingNotificationOwnerUid: "",
    attackerKingPower: Math.max(0, Math.floor(safeNumber(stats?.kingPower, participant.ownerKingPower))),
    defenderKingPower: Math.max(0, Math.floor(safeNumber(rally.leaderKingPower, 0))),
    launchedAtMs: nowMs,
    arrivesAtMs: nowMs + Math.ceil(duration * 1000),
    status: "active",
    createdByServer: true,
    rallyModelVersion: RALLY_MODEL_VERSION,
    serverAuthorityVersion: 3,
  };
}

function isRallyTargetFriendly(targetOwnerUid = "", targetOwnerProfile = {}, rally = {}) {
  const ownerUid = safeString(targetOwnerUid, 128);
  if (!ownerUid) return false;
  if (ownerUid === safeString(rally.leaderUid, 128)) return true;
  return safeString(targetOwnerProfile.clanId, 128) === safeString(rally.clanId, 128);
}

function protectedAssaultBreachRef(cityRef, attackerUid = "") {
  const safeAttackerUid = safeString(attackerUid, 128).replace(/[^a-zA-Z0-9_-]/g, "_");
  return cityRef.collection("protectedAssaultBreaches").doc(safeAttackerUid || "unknown");
}

function getCityOwnershipStartedAtMs(city = {}) {
  return Math.max(0, timestampToMs(city.lastCapturedAtMs || city.lastCapturedAt));
}

function isCurrentProtectedAssaultBreach(
  breach = null,
  { attackerUid = "", defenderUid = "", city = null } = {}
) {
  return Boolean(
    breach
    && typeof breach === "object"
    && Math.max(0, Math.floor(safeNumber(breach.version, 0))) === PROTECTED_ASSAULT_BREACH_VERSION
    && breach.status === "active"
    && safeString(breach.worldId, 128) === ONLINE_WORLD_ID
    && safeString(breach.resetGeneration, 128) === RESET_GENERATION
    && safeString(breach.attackerUid, 128) === safeString(attackerUid, 128)
    && safeString(breach.defenderUid, 128) === safeString(defenderUid, 128)
    && safeString(breach.cityId, 96) === safeString(city?.id, 96)
    && Math.max(0, timestampToMs(breach.defenderOwnershipStartedAtMs))
      === getCityOwnershipStartedAtMs(city)
    && safeString(breach.firstResolvedArmyId, 96)
  );
}

function campRefForRegion(regionId, campId) {
  return db.doc(`islands/${getOnlineIslandId(regionId)}/camps/${campId}`);
}

function getAuthoritativeRewardCampSeed(regionId = "", campId = "") {
  const safeCampId = safeString(campId, 96).replace(/[^a-zA-Z0-9_-]/g, "_");
  if (!safeCampId) return null;
  return getAuthoritativeIslandSeed(regionId).camps.find(camp => camp.id === safeCampId) || null;
}

function createNeutralRewardCampState(camp = {}) {
  const seed = cleanServerCampLayoutSeed(camp);
  if (!seed.id) return null;
  return {
    ...seed,
    holderUid: "",
    holderName: "",
    holderFlag: null,
    heldSinceMs: 0,
    payoutAtMs: 0,
    payoutPending: false,
    currentGarrison: seed.baseDefenders,
    returnSourceCityId: "",
    returnSourceRegionId: "",
    returnSourceCityName: "",
    returnPathSegments: [],
    returnRouteRegionIds: [],
    returnPathLength: 0,
    activeArmyIds: [],
    dailyRewardClaims: {},
    lastResetDate: "",
    state: "neutral",
  };
}

function getRewardCampConfig(campOrType = {}) {
  const camp = typeof campOrType === "object" && campOrType ? campOrType : null;
  const rawType = typeof campOrType === "string"
    ? campOrType
    : campOrType?.campType
      || (campOrType?.kind === "warbandCamp" ? "troops" : "")
      || (campOrType?.kind === "relicCamp" ? "items" : "")
      || (campOrType?.kind === "goldCamp" || campOrType?.targetType === "camp" ? "gold" : "");
  const normalizedType = safeString(rawType, 24).toLowerCase();
  const campType = normalizedType === "relic" || normalizedType === "item"
    ? "items"
    : normalizedType === "troop"
      ? "troops"
      : normalizedType;
  const base = REWARD_CAMP_CONFIG[campType] || null;
  if (!base || !camp) return base;
  const rewardSchedule = Array.isArray(camp.rewardSchedule) && camp.rewardSchedule.length
    ? camp.rewardSchedule.map(entry => ({
        minimumReward: Math.max(0, Math.floor(safeNumber(entry?.minimumReward, 0))),
        productionHours: Math.max(0, safeNumber(entry?.productionHours, 0)),
      }))
    : base.dailyRewards?.map((minimumReward, index) => ({
        minimumReward,
        productionHours: base.rewardHours?.[index] || 0,
      })) || [];
  return {
    ...base,
    baseReward: rewardSchedule[0]?.minimumReward ?? base.baseReward,
    dailyRewards: rewardSchedule.map(entry => entry.minimumReward),
    rewardHours: rewardSchedule.map(entry => entry.productionHours),
    rewardSchedule,
    maxDailyRewards: Math.max(0, Math.floor(safeNumber(camp.maxDailyRewards, base.maxDailyRewards || 0))),
  };
}

function getRewardCampCombatMetadata(campOrType = {}) {
  const config = getRewardCampConfig(campOrType);
  return {
    combatVersion: REWARD_CAMP_COMBAT_VERSION,
    baseDefenders: Math.max(1, Math.floor(safeNumber(config?.baseDefenders, 20_000))),
    troopPower: REWARD_CAMP_TROOP_POWER,
  };
}

function isRewardCamp(target = {}) {
  return Boolean(getRewardCampConfig(target));
}

function cleanServerCampLayoutSeed(camp = {}) {
  if (!camp || typeof camp !== "object") return {};
  const campId = safeString(camp.id, 96).replace(/[^a-zA-Z0-9_-]/g, "_");
  const config = getRewardCampConfig(camp);
  if (!config) return {};
  const combatMetadata = getRewardCampCombatMetadata(config);
  return {
    id: campId,
    campId,
    worldId: ONLINE_WORLD_ID,
    resetGeneration: RESET_GENERATION,
    name: safeString(camp.name || config.name, 80),
    mapId: safeString(camp.mapId || camp.regionId, 80),
    regionId: normalizeRegionId(camp.regionId || camp.mapId),
    x: safeNumber(camp.x, 0),
    y: safeNumber(camp.y, 0),
    size: DEFAULT_CAMP_VISUAL_SIZE,
    artSrc: safeString(camp.artSrc || config.artSrc, 180),
    kind: config.kind,
    targetType: "camp",
    ...combatMetadata,
    campType: config.campType,
    rewardType: config.rewardType,
    holdDurationMs: config.holdDurationMs,
    baseReward: config.baseReward,
    rewardSchedule: config.rewardSchedule,
    maxDailyRewards: config.maxDailyRewards,
  };
}

function normalizeActiveArmyIds(value = []) {
  return [...new Set((Array.isArray(value) ? value : [])
    .map(id => safeString(id, 96).replace(/[^a-zA-Z0-9_-]/g, "_"))
    .filter(Boolean))]
    .slice(0, 200);
}

function getRewardCampCombatTarget(camp = {}) {
  const authoritativeSeed = camp?.id
    ? getAuthoritativeRewardCampSeed(camp.regionId || camp.mapId, camp.id)
    : null;
  const resolvedCamp = authoritativeSeed ? { ...camp, ...authoritativeSeed } : camp;
  const config = getRewardCampConfig(resolvedCamp);
  if (!config) return null;
  const combatMetadata = getRewardCampCombatMetadata(config);
  const storedHolderUid = safeString(camp.holderUid || camp.ownerUid, 128);
  const legacyNeutralCamp = !storedHolderUid
    && Math.floor(safeNumber(camp.combatVersion, 0)) < REWARD_CAMP_COMBAT_VERSION;
  const currentGarrison = legacyNeutralCamp
    ? combatMetadata.baseDefenders
    : Math.max(0, Math.floor(safeNumber(resolvedCamp.currentGarrison, combatMetadata.baseDefenders)));
  const cleanResolvedCamp = { ...resolvedCamp };
  delete cleanResolvedCamp.level;
  delete cleanResolvedCamp.defenseLevel;
  return {
    ...cleanResolvedCamp,
    kind: config.kind,
    targetType: "camp",
    ...combatMetadata,
    campType: config.campType,
    rewardType: config.rewardType,
    holdDurationMs: config.holdDurationMs,
    baseReward: config.baseReward,
    level: 0,
    troops: currentGarrison,
    troopFloat: currentGarrison,
    rewardSchedule: config.rewardSchedule,
    maxDailyRewards: config.maxDailyRewards,
    ownerKind: resolvedCamp.holderUid ? "player" : "neutral",
    ownerUid: safeString(resolvedCamp.holderUid || resolvedCamp.ownerUid, 128),
    ownerName: normalizePlayerName(resolvedCamp.holderName || resolvedCamp.ownerName, ""),
    ownerFlag: resolvedCamp.holderFlag || resolvedCamp.ownerFlag || null,
    defense: 1,
    isMainCity: false,
    ownerShieldExpiresAtMs: 0,
  };
}

function getRewardCampState(activeArmyIds = [], holderUid = "") {
  if (normalizeActiveArmyIds(activeArmyIds).length) return "contested";
  return holderUid ? "held" : "neutral";
}

function removeActiveCampArmyId(camp = {}, armyId = "") {
  return normalizeActiveArmyIds(camp.activeArmyIds).filter(id => id !== armyId);
}

function campUpdateForClient(campId, regionId, patch = {}) {
  const { updatedAt, createdAt, ...safePatch } = patch;
  return { id: campId, regionId: normalizeRegionId(regionId), ...safePatch };
}

function cleanServerCityLayoutSeed(city = {}) {
  const cityId = safeString(city.id, 96).replace(/[^a-zA-Z0-9_-]/g, "_");
  const isStrongholdCity = city.kind === "stronghold" || Boolean(city.strongholdType);
  return {
    id: cityId,
    worldId: ONLINE_WORLD_ID,
    resetGeneration: RESET_GENERATION,
    name: safeString(city.name || cityId, 80),
    x: safeNumber(city.x, 0),
    y: safeNumber(city.y, 0),
    startPool: safeString(city.startPool, 80),
    regionId: safeString(city.regionId || city.startPool, 80),
    kind: isStrongholdCity ? "stronghold" : "",
    strongholdType: isStrongholdCity ? safeString(city.strongholdType, 32) : "",
    bonus: isStrongholdCity ? safeString(city.bonus, 32) : "",
    bonusPercent: isStrongholdCity ? Math.max(0, Math.floor(safeNumber(city.bonusPercent, 0))) : 0,
    size: isStrongholdCity ? getServerStrongholdVisualSize(city) : 0,
    artSrc: isStrongholdCity ? safeString(city.artSrc, 180) : "",
    startTroops: isStrongholdCity ? Math.max(0, Math.floor(safeNumber(city.startTroops, safeNumber(city.troops, 0)))) : 0,
    level: clampCityLevel(city.level || (isStrongholdCity ? 50 : 1)),
    defense: 1,
  };
}

function canonicalArmyRef(armyId = "") {
  return db.doc(`armies/${safeString(armyId, 96).replace(/[^a-zA-Z0-9_-]/g, "_")}`);
}

function incomingArmyViewRef(uid = "", armyId = "") {
  const safeUid = safeString(uid, 128).replace(/[^a-zA-Z0-9_-]/g, "_");
  const safeArmyId = safeString(armyId, 96).replace(/[^a-zA-Z0-9_-]/g, "_");
  return safeUid && safeArmyId
    ? db.doc(`players/${safeUid}/incomingArmies/${safeArmyId}`)
    : null;
}

function armyViewRefsForRegions(regionIds, armyId) {
  return normalizeRegionIds(regionIds).map(regionId => db.doc(`islands/${getOnlineIslandId(regionId)}/armies/${armyId}`));
}

function armyRefsForRegions(regionIds, armyId) {
  return [canonicalArmyRef(armyId), ...armyViewRefsForRegions(regionIds, armyId)];
}

function formatTroopEstimateBound(value = 0) {
  const count = Math.max(0, Math.floor(safeNumber(value, 0)));
  const units = [
    { value: 1_000_000_000_000, suffix: "T" },
    { value: 1_000_000_000, suffix: "B" },
    { value: 1_000_000, suffix: "M" },
    { value: 1_000, suffix: "K" },
  ];
  const unit = units.find(entry => count >= entry.value);
  if (!unit) return count.toLocaleString("en-US");
  const scaled = count / unit.value;
  const digits = Number.isInteger(scaled) ? 0 : 1;
  return `${scaled.toFixed(digits)}${unit.suffix}`;
}

function getIncomingTroopEstimate(troops = 0) {
  const count = Math.max(1, Math.floor(safeNumber(troops, 1)));
  let min = 1;
  let max = 10;
  if (count > 10 && count <= ARMY_TROOP_ESTIMATE_DECADE_MAX) {
    max = 10 ** Math.ceil(Math.log10(count));
    min = max / 10;
  } else if (count > ARMY_TROOP_ESTIMATE_DECADE_MAX) {
    min = ARMY_TROOP_ESTIMATE_DECADE_MAX;
    max = 5_000_000;
    if (count > max) {
      min = max;
      max = 10_000_000;
    }
    if (count > max) {
      let base = 10_000_000;
      min = base;
      let matched = false;
      while (!matched && Number.isFinite(base) && base <= Number.MAX_SAFE_INTEGER / 10) {
        for (const multiplier of [2, 5, 10]) {
          const candidate = base * multiplier;
          if (count <= candidate) {
            max = candidate;
            matched = true;
            break;
          }
          min = candidate;
        }
        base *= 10;
      }
      if (!matched) max = Number.MAX_SAFE_INTEGER;
    }
  }
  return {
    min: Math.max(1, Math.floor(min)),
    max: Math.max(1, Math.floor(max)),
    label: `${formatTroopEstimateBound(min)}\u2013${formatTroopEstimateBound(max)}`,
  };
}

function isEstimatedAttackMovement(movement = {}) {
  return Boolean(
    movement
    && (
      movement.kind === "attack"
      || movement.launchKind === "attack"
      || movement.rallyAttack
    )
  );
}

function isEstimatedClanReinforcementMovement(movement = {}) {
  return Boolean(
    movement
    && movement.kind === "reinforce"
    && !movement.returning
    && !movement.reinforcementReturn
  );
}

function isPrivateTransferMovement(movement = {}) {
  return Boolean(
    movement
    && (
      movement.kind === "transfer"
      || (movement.kind !== "attack" && movement.launchKind === "transfer")
      || movement.retargetedFromKind === "transfer"
      || movement.relinquishTransfer
      || movement.reinforcementReturn
      || movement.campReturn
      || movement.rallyReturn
    )
  );
}

function createArmyPublicProjection(movement = {}) {
  const projection = {
    ...movement,
    armyTroopVisibilityVersion: ARMY_TROOP_VISIBILITY_VERSION,
  };
  delete projection.id;
  if (isEstimatedAttackMovement(movement) || isEstimatedClanReinforcementMovement(movement)) {
    const estimate = getIncomingTroopEstimate(movement.troops);
    projection.troopVisibility = "estimate";
    projection.troopEstimateMin = estimate.min;
    projection.troopEstimateMax = estimate.max;
    projection.troopEstimateLabel = estimate.label;
    projection.troops = FieldValue.delete();
    projection.requestedTroops = FieldValue.delete();
    projection.attackProtection = FieldValue.delete();
    projection.demoAttack = FieldValue.delete();
  } else if (isPrivateTransferMovement(movement)) {
    projection.troopVisibility = "hidden";
    projection.troopEstimateMin = FieldValue.delete();
    projection.troopEstimateMax = FieldValue.delete();
    projection.troopEstimateLabel = FieldValue.delete();
    projection.troops = FieldValue.delete();
    projection.requestedTroops = FieldValue.delete();
    projection.attackProtection = FieldValue.delete();
    projection.demoAttack = FieldValue.delete();
  } else {
    projection.troopVisibility = "exact";
    projection.troopEstimateMin = FieldValue.delete();
    projection.troopEstimateMax = FieldValue.delete();
    projection.troopEstimateLabel = FieldValue.delete();
  }
  // Forecasts and launch combat snapshots contain attacker-only troop power and
  // scout-derived defense intelligence. Never expose them through incoming views.
  projection.attackCombatSnapshot = FieldValue.delete();
  projection.launchCombatForecast = FieldValue.delete();
  projection.combatForecastVersion = FieldValue.delete();
  return projection;
}

function shouldWriteIncomingArmyView(movement = {}) {
  const ownerUid = safeString(movement.ownerUid, 128);
  const targetOwnerUid = safeString(movement.targetOwnerUid, 128);
  return Boolean(
    targetOwnerUid
    && targetOwnerUid !== ownerUid
    && movement.status === "active"
    && !movement.returning
  );
}

function writeArmyMovementCopies(writer, movement = {}, {
  includeCreatedAt = false,
  previousTargetOwnerUid = "",
} = {}) {
  const armyId = safeString(movement.id, 96).replace(/[^a-zA-Z0-9_-]/g, "_");
  if (!armyId) throw new HttpsError("invalid-argument", "Army movement id is missing.");
  const timestampPatch = {
    ...(includeCreatedAt ? { createdAt: FieldValue.serverTimestamp() } : {}),
    updatedAt: FieldValue.serverTimestamp(),
  };
  const canonicalMovement = {
    ...movement,
    armyTroopVisibilityVersion: ARMY_TROOP_VISIBILITY_VERSION,
    ...timestampPatch,
  };
  delete canonicalMovement.id;
  writer.set(canonicalArmyRef(armyId), canonicalMovement, { merge: true });

  const publicMovement = {
    ...createArmyPublicProjection(movement),
    ...timestampPatch,
  };
  armyViewRefsForRegions(movement.viewRegionIds || movement.routeRegionIds || [], armyId)
    .forEach(ref => writer.set(ref, publicMovement, { merge: true }));

  const priorTargetUid = safeString(previousTargetOwnerUid || movement.targetOwnerUid, 128);
  const nextTargetUid = shouldWriteIncomingArmyView(movement)
    ? safeString(movement.targetOwnerUid, 128)
    : "";
  if (priorTargetUid && priorTargetUid !== nextTargetUid) {
    const oldViewRef = incomingArmyViewRef(priorTargetUid, armyId);
    if (oldViewRef) writer.delete(oldViewRef);
  }
  if (nextTargetUid) {
    const incomingView = {
      ...createArmyPublicProjection(movement),
      id: armyId,
      viewerAccess: "target",
      ...timestampPatch,
    };
    const nextViewRef = incomingArmyViewRef(nextTargetUid, armyId);
    if (nextViewRef) writer.set(nextViewRef, incomingView, { merge: true });
  }
}

function rallyJoinPublicMovement(movement = {}) {
  return {
    worldId: safeString(movement.worldId, 120),
    resetGeneration: safeString(movement.resetGeneration, 120),
    ownerKind: "player",
    ownerUid: safeString(movement.ownerUid, 128),
    ownerName: normalizePlayerName(movement.ownerName, "Ruler"),
    kind: "rally_join",
    launchKind: "rally_join",
    rallyJoin: true,
    targetType: "city",
    fromId: safeString(movement.fromId, 96),
    toId: safeString(movement.toId, 96),
    fromName: safeString(movement.fromName, 40),
    toName: safeString(movement.toName, 40),
    sourceRegionId: normalizeRegionId(movement.sourceRegionId),
    targetRegionId: normalizeRegionId(movement.targetRegionId),
    troops: Math.max(0, Math.floor(safeNumber(movement.troops, 0))),
    total: Math.max(0.1, safeNumber(movement.total, 0.1)),
    path: normalizePath(movement.path),
    pathSegments: normalizePathSegments(movement.pathSegments),
    routeRegionIds: normalizeRegionIds(movement.routeRegionIds),
    viewRegionIds: normalizeRegionIds(movement.viewRegionIds || movement.routeRegionIds),
    pathLength: Math.max(0, safeNumber(movement.pathLength, 0)),
    launchedAtMs: Math.max(0, Math.floor(safeNumber(movement.launchedAtMs, 0))),
    arrivesAtMs: Math.max(0, Math.floor(safeNumber(movement.arrivesAtMs, 0))),
    returning: Boolean(movement.returning),
    returnStartProgress: clamp(safeNumber(movement.returnStartProgress, 0), 0, 1),
    returnDestinationId: safeString(movement.returnDestinationId, 96),
    returnDestinationRegionId: normalizeRegionId(movement.returnDestinationRegionId),
    status: movement.status === "resolved" ? "resolved" : "active",
    createdByServer: true,
    serverAuthorityVersion: Math.max(3, Math.floor(safeNumber(movement.serverAuthorityVersion, 3))),
  };
}

function writeRallyJoinMovementCopies(transaction, movement = {}, { includeCreatedAt = false } = {}) {
  const canonicalPatch = {
    ...movement,
    ...(includeCreatedAt ? { createdAt: FieldValue.serverTimestamp() } : {}),
    updatedAt: FieldValue.serverTimestamp(),
  };
  delete canonicalPatch.id;
  transaction.set(canonicalArmyRef(movement.id), canonicalPatch, { merge: true });
  const publicPatch = {
    ...rallyJoinPublicMovement(movement),
    ...(includeCreatedAt ? { createdAt: FieldValue.serverTimestamp() } : {}),
    updatedAt: FieldValue.serverTimestamp(),
  };
  armyViewRefsForRegions(movement.routeRegionIds, movement.id).forEach(ref => {
    transaction.set(ref, publicPatch, { merge: true });
  });
}

function getArmyRouteProgressAtMs(army = {}, nowMs = Date.now()) {
  const launchedAtMs = Math.max(0, Math.floor(safeNumber(army.launchedAtMs, 0)));
  const arrivesAtMs = Math.max(0, Math.floor(safeNumber(army.arrivesAtMs, 0)));
  const swiftUsedAtMs = Math.max(0, Math.floor(safeNumber(army.swiftMarchUsedAtMs, 0)));
  if (swiftUsedAtMs > 0 && arrivesAtMs > swiftUsedAtMs && nowMs >= swiftUsedAtMs) {
    const progressAtUse = clamp(safeNumber(army.swiftMarchProgressAtUse, 0), 0, 1);
    const acceleratedProgress = clamp((nowMs - swiftUsedAtMs) / (arrivesAtMs - swiftUsedAtMs), 0, 1);
    return clamp(progressAtUse + (1 - progressAtUse) * acceleratedProgress, 0, 1);
  }
  if (launchedAtMs > 0 && arrivesAtMs > launchedAtMs) {
    return clamp((nowMs - launchedAtMs) / (arrivesAtMs - launchedAtMs), 0, 1);
  }
  const totalMs = Math.max(100, safeNumber(army.total, 0.1) * 1000);
  return clamp(1 - Math.max(0, arrivesAtMs - nowMs) / totalMs, 0, 1);
}

function createMidRouteReturnMovement(army = {}, nowMs = Date.now(), returnReason = "") {
  const sourceRegionId = normalizeRegionId(army.sourceRegionId);
  const targetRegionId = normalizeRegionId(army.targetRegionId);
  if (!sourceRegionId || !targetRegionId || !army.fromId || !army.toId) {
    throw new HttpsError("failed-precondition", "That troop march is missing its return route.");
  }
  const oldArrivesAtMs = Math.max(0, Math.floor(safeNumber(army.arrivesAtMs, 0)));
  const fallbackTotalMs = Math.max(100, safeNumber(army.total, 0.1) * 1000);
  const launchedAtMs = Math.max(0, Math.floor(safeNumber(
    army.launchedAtMs,
    oldArrivesAtMs - fallbackTotalMs
  )));
  const originalArrivesAtMs = Math.max(
    oldArrivesAtMs,
    Math.floor(safeNumber(army.swiftMarchOriginalArrivesAtMs, oldArrivesAtMs))
  );
  const originalTotalMs = Math.max(100, originalArrivesAtMs - launchedAtMs);
  const returnStartProgress = clamp(getArmyRouteProgressAtMs(army, nowMs), 0.000001, 0.999999);
  const returnDurationMs = Math.max(
    RECALL_HORN_MINIMUM_RETURN_MS,
    Math.ceil(originalTotalMs * returnStartProgress)
  );
  return {
    ...army,
    returning: true,
    returnReason: safeString(returnReason, 40),
    recalledAtMs: nowMs,
    recallOriginalArrivesAtMs: oldArrivesAtMs,
    returnStartProgress,
    returnDestinationId: army.fromId,
    returnDestinationRegionId: sourceRegionId,
    arrivesAtMs: nowMs + returnDurationMs,
    total: Math.max(0.1, returnDurationMs / 1000),
    targetOwnerUid: "",
    routeRegionIds: normalizeRegionIds([
      ...(army.routeRegionIds || []),
      sourceRegionId,
      targetRegionId,
    ]),
    status: "active",
  };
}

function getPeaceShieldReturnDirection(army = {}, shieldOwnerUid = "", nowMs = Date.now()) {
  const uid = safeString(shieldOwnerUid, 128);
  const ownerUid = safeString(army.ownerUid, 128);
  const targetOwnerUid = safeString(army.targetOwnerUid, 128);
  const arrivesAtMs = Math.max(0, Math.floor(safeNumber(army.arrivesAtMs, 0)));
  if (
    !uid
    || !ownerUid
    || !targetOwnerUid
    || ownerUid === targetOwnerUid
    || army.ownerKind !== "player"
    || army.status !== "active"
    || !isCurrentWorldArmy(army)
    || army.kind !== "attack"
    || army.targetType !== "city"
    || army.returning
    || timestampToMs(army.recalledAtMs) > 0
    || arrivesAtMs <= nowMs
    || army.rallyAttack
    || army.rallyJoin
    || army.rallyReturn
    || army.campReturn
    || army.reinforcementReturn
    || army.relinquishTransfer
    || army.eventKind === CITADEL_ASSAULT_EVENT_KIND
    || isStronghold({ id: army.fromId })
    || isStronghold({ id: army.toId })
  ) return "";
  if (ownerUid === uid) return "outgoing";
  if (targetOwnerUid === uid) return "incoming";
  return "";
}

function createAlliedTargetReturnMovement(army = {}, nowMs = Date.now()) {
  const sourceRegionId = normalizeRegionId(army.sourceRegionId);
  const targetRegionId = normalizeRegionId(army.targetRegionId);
  if (!sourceRegionId || !targetRegionId || !army.fromId || !army.toId) {
    throw new HttpsError("failed-precondition", "That troop march is missing its return route.");
  }
  const oldArrivesAtMs = Math.max(0, Math.floor(safeNumber(army.arrivesAtMs, 0)));
  const fallbackTotalMs = Math.max(100, safeNumber(army.total, 0.1) * 1000);
  const launchedAtMs = Math.max(0, Math.floor(safeNumber(
    army.launchedAtMs,
    oldArrivesAtMs - fallbackTotalMs
  )));
  const originalArrivesAtMs = Math.max(
    oldArrivesAtMs,
    Math.floor(safeNumber(army.swiftMarchOriginalArrivesAtMs, oldArrivesAtMs))
  );
  const returnDurationMs = Math.max(
    RECALL_HORN_MINIMUM_RETURN_MS,
    originalArrivesAtMs - launchedAtMs
  );
  const originalKind = ARMY_ORDER_KINDS.includes(army.kind) ? army.kind : "attack";
  return {
    ...army,
    kind: "transfer",
    launchKind: ARMY_ORDER_KINDS.includes(army.launchKind) ? army.launchKind : originalKind,
    retargetedFromKind: originalKind,
    returning: true,
    returnReason: ALLIED_TARGET_RETURN_REASON,
    recalledAtMs: nowMs,
    recallOriginalArrivesAtMs: oldArrivesAtMs,
    returnStartProgress: 1,
    returnDestinationId: army.fromId,
    returnDestinationRegionId: sourceRegionId,
    arrivesAtMs: nowMs + returnDurationMs,
    total: Math.max(0.1, returnDurationMs / 1000),
    targetOwnerUid: "",
    routeRegionIds: normalizeRegionIds([
      ...(army.routeRegionIds || []),
      sourceRegionId,
      targetRegionId,
    ]),
    status: "active",
  };
}

function reverseArmyRoute(pathSegments = []) {
  const segments = normalizePathSegments(pathSegments)
    .reverse()
    .map(segment => {
      const points = [...segment.points].reverse();
      return { regionId: segment.regionId, points, length: routeLength(points) };
    });
  if (!segments.length) return null;
  return {
    routeRegionIds: segments.map(segment => segment.regionId),
    pathSegments: segments,
    path: segments.flatMap((segment, index) => index ? segment.points.slice(1) : segment.points).slice(0, MAX_ROUTE_POINTS_PER_SEGMENT),
    pathLength: segments.reduce((total, segment) => total + segment.length, 0),
  };
}

function buildServerGeneratedArmyRoute(source = {}, target = {}) {
  const sourceRegionId = requireKnownWorldRegionId(source.regionId || source.startPool);
  const targetRegionId = requireKnownWorldRegionId(target.regionId || target.startPool);
  const route = AUTHORITATIVE_ROUTE_PLANNER.calculate(
    { ...source, regionId: sourceRegionId },
    { ...target, regionId: targetRegionId }
  );
  if (!route?.pathSegments?.length || !(route.pathLength > 0)) {
    throw new HttpsError("failed-precondition", "No safe route through the Crownlands terrain could be found.");
  }
  if (
    route.routeRegionIds.length > MAX_ROUTE_REGION_COUNT
    || route.pathSegments.length > MAX_ROUTE_SEGMENT_COUNT
    || route.pathSegments.some(segment => segment.points.length > MAX_ROUTE_POINTS_PER_SEGMENT)
  ) {
    throw new HttpsError("failed-precondition", "The authoritative march route is too complex.");
  }
  return route;
}

function getCampReturnRoute(camp = {}, destination = {}) {
  const destinationRegionId = normalizeRegionId(destination.regionId || destination.startPool);
  const storedSourceId = safeString(camp.returnSourceCityId, 96);
  const storedSourceRegionId = normalizeRegionId(camp.returnSourceRegionId);
  if (storedSourceId === safeString(destination.id, 96) && storedSourceRegionId === destinationRegionId) {
    const reversed = reverseArmyRoute(camp.returnPathSegments);
    if (reversed?.pathLength > 0) return reversed;
  }
  return buildServerGeneratedArmyRoute(camp, destination);
}

function reportRef(uid, reportId) {
  return db.doc(`players/${uid}/serverReports/${reportId}`);
}

function battleSnapshotRef(battleId = "") {
  const safeBattleId = safeString(battleId, 160).replace(/[^a-zA-Z0-9_-]/g, "_");
  return safeBattleId
    ? db.doc(`battleSnapshots/${RESET_GENERATION}/entries/${safeBattleId}`)
    : null;
}

function islandReportRef(regionId, reportId) {
  return db.doc(`islands/${getOnlineIslandId(regionId)}/reports/${reportId}`);
}

function getOwnerUid(city = {}) {
  return safeString(city.ownerUid, 128);
}

function canUseSwiftMarchOrderOnTransfer(army = {}, source = {}, target = {}, uid = "") {
  if (
    !uid
    || army.kind !== "transfer"
    || army.targetType === "camp"
    || army.relinquishTransfer
    || getOwnerUid(army) !== uid
    || getOwnerUid(source) !== uid
    || getOwnerUid(target) !== uid
  ) {
    return false;
  }
  if (isStronghold(target)) return true;
  return !isStronghold(source);
}

function getMainCityInfo(profile = {}) {
  const id = safeString(profile?.mainCityId, 96).replace(/[^a-zA-Z0-9_-]/g, "_");
  if (!id) return null;
  const islandRegionId = profile?.mainIslandId ? getRegionIdFromOnlineIslandId(profile.mainIslandId) : "";
  const regionId = normalizeRegionId(profile?.mainRegionId || profile?.mainRegion || islandRegionId || profile?.regionId || "west");
  return {
    id,
    regionId,
    ref: cityRefForRegion(regionId, id),
  };
}

function isGivenUpNeutralCity(city = {}) {
  return Boolean(
    city
    && !getOwnerUid(city)
    && !isStronghold(city)
    && (timestampToMs(city.relinquishedAtMs) > 0 || timestampToMs(city.relocatedAtMs) > 0)
  );
}

function getOwnerName(city = {}, fallback = "Unknown") {
  return normalizePlayerName(city.ownerName, "") || safeString(city.name || fallback, 40);
}

function normalizeServerFlag(flag = null, stableKey = "") {
  if (!flag || typeof flag !== "object") return null;
  return PLAYER_FLAG_CONFIG.toStoredFlag(flag, stableKey);
}

function isCurrentWorldIslandId(islandId = "") {
  return String(islandId || "").startsWith(`${ONLINE_WORLD_ID}-`);
}

function getCanonicalPlayerIdentity(uid = "", profile = {}, data = {}, authToken = {}) {
  const ownerName = normalizePlayerName(
    data.ownerName || data.playerName || profile.playerName || profile.displayName || authToken.name
  );
  const hasFlagPayload = Object.prototype.hasOwnProperty.call(data, "ownerFlag")
    || Object.prototype.hasOwnProperty.call(data, "flag");
  const rawFlag = hasFlagPayload
    ? (data.ownerFlag !== undefined ? data.ownerFlag : data.flag)
    : profile.flag;
  const ownerFlag = normalizeServerFlag(rawFlag, uid) || PLAYER_FLAG_CONFIG.createDeterministicFlag(uid);
  const ownerKingPower = Math.max(
    0,
    Math.floor(safeNumber(profile.kingPower, 0))
  );
  return {
    uid,
    ownerName,
    ownerFlag,
    ownerKingPower,
    clanId: safeString(profile.clanId, 128),
    clanName: safeString(profile.clanName, 24),
    clanTag: safeString(profile.clanTag, 5),
  };
}

function isProtectedMainCity(city = {}, attackerUid = "", ownerProfile = null) {
  const ownerUid = getOwnerUid(city);
  if (!ownerUid || ownerUid === attackerUid) return false;
  const cityId = safeString(city.id, 96);
  const profileMainCityId = safeString(ownerProfile?.mainCityId, 96);
  if (!profileMainCityId) return Boolean(city.isMainCity);
  if (!cityId || cityId !== profileMainCityId) return false;

  const cityRegionId = safeString(city.regionId || city.startPool, 160);
  const profileRegionId = safeString(
    ownerProfile?.mainRegionId || getRegionIdFromOnlineIslandId(ownerProfile?.mainIslandId),
    160
  );
  return !cityRegionId
    || !profileRegionId
    || normalizeRegionId(cityRegionId) === normalizeRegionId(profileRegionId);
}

function getMainCityProtectionProfile(...sources) {
  const candidates = sources.filter(source => source && typeof source === "object");
  const pointerSource = candidates.find(source => safeString(source.mainCityId, 96));
  if (!pointerSource) return null;
  const mainCityId = safeString(pointerSource.mainCityId, 96);
  const locationSource = candidates.find(source => (
    safeString(source.mainCityId, 96) === mainCityId
    && (safeString(source.mainRegionId, 160) || safeString(source.mainIslandId, 160))
  )) || pointerSource;
  return {
    mainCityId,
    mainRegionId: safeString(locationSource.mainRegionId, 160),
    mainIslandId: safeString(locationSource.mainIslandId, 160),
  };
}

function getShieldExpiresAtMs(city = {}) {
  if (isStronghold(city)) return 0;
  const value = city.ownerShieldExpiresAtMs;
  if (typeof value?.toMillis === "function") return value.toMillis();
  return Math.max(0, Math.floor(safeNumber(value, 0)));
}

function isCityShielded(city = {}, attackerUid = "", nowMs = Date.now()) {
  const ownerUid = getOwnerUid(city);
  if (!ownerUid || ownerUid === attackerUid || isStronghold(city)) return false;
  return getShieldExpiresAtMs(city) > nowMs;
}

function shouldDeactivatePeaceShieldForAttack(target = {}, targetType = "city", attackerUid = "", resolvedKind = "attack") {
  if (resolvedKind !== "attack") return false;
  if (targetType === "camp" || isStronghold(target)) return true;
  const targetOwnerUid = getOwnerUid(target);
  return Boolean(targetOwnerUid && targetOwnerUid !== attackerUid);
}

function getCurrentDateKey(now = new Date()) {
  const year = now.getUTCFullYear();
  const month = String(now.getUTCMonth() + 1).padStart(2, "0");
  const day = String(now.getUTCDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function normalizeRewardedAdState(raw = {}, nowMs = Date.now()) {
  const dayKey = getCurrentDateKey(new Date(nowMs));
  const sameDay = safeString(raw?.dayKey, 10) === dayKey;
  return {
    schemaVersion: 1,
    dayKey,
    claimedToday: sameDay ? clampInt(raw?.claimedToday, 0, REWARDED_AD_DAILY_LIMIT) : 0,
    lastClaimedAtMs: Math.max(0, timestampToMs(raw?.lastClaimedAtMs)),
    activeIntentId: safeString(raw?.activeIntentId, 96),
  };
}

function createRewardedAdStatus(rawState = {}, enabled = true, nowMs = Date.now(), previewRewards = {}) {
  const state = normalizeRewardedAdState(rawState, nowMs);
  const cooldownEndsAtMs = state.lastClaimedAtMs
    ? state.lastClaimedAtMs + REWARDED_AD_COOLDOWN_MS
    : 0;
  const cooldownRemainingMs = Math.max(0, cooldownEndsAtMs - nowMs);
  const remainingToday = Math.max(0, REWARDED_AD_DAILY_LIMIT - state.claimedToday);
  const eligible = Boolean(enabled && remainingToday > 0 && cooldownRemainingMs <= 0);
  const reason = !enabled
    ? "disabled"
    : remainingToday <= 0
      ? "daily-limit"
      : cooldownRemainingMs > 0
        ? "cooldown"
        : "";
  return {
    enabled: Boolean(enabled),
    eligible,
    reason,
    dayKey: state.dayKey,
    claimedToday: state.claimedToday,
    dailyLimit: REWARDED_AD_DAILY_LIMIT,
    remainingToday,
    rewardMinutes: REWARDED_AD_REWARD_MINUTES,
    cooldownMinutes: Math.floor(REWARDED_AD_COOLDOWN_MS / 60000),
    cooldownEndsAtMs,
    cooldownRemainingMs,
    previewRewards: {
      gold: Math.max(0, Math.floor(safeNumber(previewRewards?.gold, 0))),
      troops: Math.max(0, Math.floor(safeNumber(previewRewards?.troops, 0))),
    },
  };
}

function getRewardedAdServerConfigFromSnapshot(snapshot = null) {
  const config = snapshot?.exists ? snapshot.data() || {} : {};
  return {
    enabled: config.enabled === true,
  };
}

function normalizeDaily(daily = {}, now = new Date()) {
  const today = getCurrentDateKey(now);
  if (!daily || typeof daily !== "object" || daily.date !== today) {
    return { date: today, neutralCaptures: 0, harvestedBonuses: 0, harvestedGoldBonuses: 0, harvestedTroopBonuses: 0 };
  }
  return {
    date: today,
    neutralCaptures: clampInt(daily.neutralCaptures, 0, DAILY_NEUTRAL_CAPTURE_LIMIT),
    harvestedBonuses: clampInt(daily.harvestedBonuses, 0, HARVEST_BONUS_DAILY_LIMIT),
    harvestedGoldBonuses: clampInt(daily.harvestedGoldBonuses, 0, HARVEST_BONUS_DAILY_GOLD_LIMIT),
    harvestedTroopBonuses: clampInt(daily.harvestedTroopBonuses, 0, HARVEST_BONUS_DAILY_TROOP_LIMIT),
  };
}

function mergeHarvestDailyTrackers(serverDaily = {}, clientDaily = {}, now = new Date()) {
  const server = normalizeDaily(serverDaily, now);
  const client = normalizeDaily(clientDaily, now);
  const harvestedGoldBonuses = clampInt(
    Math.max(server.harvestedGoldBonuses, client.harvestedGoldBonuses),
    0,
    HARVEST_BONUS_DAILY_GOLD_LIMIT
  );
  const harvestedTroopBonuses = clampInt(
    Math.max(server.harvestedTroopBonuses, client.harvestedTroopBonuses),
    0,
    HARVEST_BONUS_DAILY_TROOP_LIMIT
  );
  return {
    date: server.date,
    neutralCaptures: clampInt(Math.max(server.neutralCaptures, client.neutralCaptures), 0, DAILY_NEUTRAL_CAPTURE_LIMIT),
    harvestedGoldBonuses,
    harvestedTroopBonuses,
    harvestedBonuses: clampInt(harvestedGoldBonuses + harvestedTroopBonuses, 0, HARVEST_BONUS_DAILY_LIMIT),
  };
}

function getHarvestBonusRemaining(type = "gold", daily = {}) {
  const normalizedType = type === "troops" ? "troops" : "gold";
  const typeLimit = normalizedType === "troops" ? HARVEST_BONUS_DAILY_TROOP_LIMIT : HARVEST_BONUS_DAILY_GOLD_LIMIT;
  const typeCount = normalizedType === "troops" ? daily.harvestedTroopBonuses : daily.harvestedGoldBonuses;
  const typeRemaining = typeLimit - clampInt(typeCount, 0, typeLimit);
  const totalRemaining = HARVEST_BONUS_DAILY_LIMIT - clampInt(daily.harvestedBonuses, 0, HARVEST_BONUS_DAILY_LIMIT);
  return Math.max(0, Math.min(typeRemaining, totalRemaining));
}

function incrementHarvestDailyTracker(type = "gold", daily = {}) {
  const next = normalizeDaily(daily);
  if (type === "troops") {
    next.harvestedTroopBonuses = clampInt(next.harvestedTroopBonuses + 1, 0, HARVEST_BONUS_DAILY_TROOP_LIMIT);
  } else {
    next.harvestedGoldBonuses = clampInt(next.harvestedGoldBonuses + 1, 0, HARVEST_BONUS_DAILY_GOLD_LIMIT);
  }
  next.harvestedBonuses = clampInt(next.harvestedGoldBonuses + next.harvestedTroopBonuses, 0, HARVEST_BONUS_DAILY_LIMIT);
  return next;
}

function getServerNeutralCaptureBlockReason(economy = null, profile = {}, target = {}) {
  if (!economy || getOwnerUid(target) || isStronghold(target)) return "";
  const ownedCityCount = Math.max(0, Math.floor(safeNumber(
    economy.globalStats?.totalCities,
    economy.cityEntries?.filter(entry => entry?.city && !isStronghold(entry.city) && getOwnerUid(entry.city) === economy.uid).length || 0
  )));
  if (ownedCityCount >= NEUTRAL_CITY_COUNT_LIMIT) {
    return `Neutral expansion is capped while you own ${NEUTRAL_CITY_COUNT_LIMIT} or more cities.`;
  }
  const daily = normalizeDaily(profile.daily);
  if (daily.neutralCaptures >= DAILY_NEUTRAL_CAPTURE_LIMIT) {
    return `Daily neutral capture limit reached: ${DAILY_NEUTRAL_CAPTURE_LIMIT}/${DAILY_NEUTRAL_CAPTURE_LIMIT}.`;
  }
  return "";
}

function antiFarmHash(value = "") {
  return crypto.createHash("sha256").update(String(value || ""), "utf8").digest("hex");
}

function getAntiFarmPairUids(leftUid = "", rightUid = "") {
  return [safeString(leftUid, 128), safeString(rightUid, 128)].filter(Boolean).sort();
}

function getAntiFarmPairId(leftUid = "", rightUid = "") {
  const uids = getAntiFarmPairUids(leftUid, rightUid);
  return uids.length === 2 && uids[0] !== uids[1]
    ? antiFarmHash(`${uids[0]}\n${uids[1]}`)
    : "";
}

function antiFarmPairRef(leftUid = "", rightUid = "") {
  const pairId = getAntiFarmPairId(leftUid, rightUid);
  return pairId
    ? db.doc(`realmSecurity/${RESET_GENERATION}/accountPairs/${pairId}`)
    : null;
}

function antiFarmInstallationRef(installationHash = "") {
  const normalizedHash = safeString(installationHash, 64);
  return normalizedHash
    ? db.doc(`realmSecurity/${RESET_GENERATION}/installations/${normalizedHash}`)
    : null;
}

function antiFarmAccountRef(uid = "") {
  const accountHash = antiFarmHash(safeString(uid, 128));
  return db.doc(`realmSecurity/${RESET_GENERATION}/accounts/${accountHash}`);
}

function normalizeAntiFarmInstallationEntries(entries = [], nowMs = Date.now()) {
  return (Array.isArray(entries) ? entries : [])
    .map(entry => ({
      installationHash: safeString(entry?.installationHash, 64),
      lastSeenAtMs: Math.max(0, timestampToMs(entry?.lastSeenAtMs)),
    }))
    .filter(entry => (
      entry.installationHash
      && entry.lastSeenAtMs > nowMs - ANTI_FARM_INSTALLATION_RETENTION_MS
    ))
    .sort((left, right) => right.lastSeenAtMs - left.lastSeenAtMs)
    .filter((entry, index, all) => (
      all.findIndex(candidate => candidate.installationHash === entry.installationHash) === index
    ))
    .slice(0, ANTI_FARM_MAX_ACCOUNT_INSTALLATIONS);
}

function normalizeAntiFarmInstallationAccounts(accounts = [], nowMs = Date.now()) {
  return (Array.isArray(accounts) ? accounts : [])
    .map(entry => ({
      uid: safeString(entry?.uid, 128),
      lastSeenAtMs: Math.max(0, timestampToMs(entry?.lastSeenAtMs)),
    }))
    .filter(entry => (
      entry.uid
      && entry.lastSeenAtMs > nowMs - ANTI_FARM_INSTALLATION_RETENTION_MS
    ))
    .sort((left, right) => right.lastSeenAtMs - left.lastSeenAtMs)
    .filter((entry, index, all) => all.findIndex(candidate => candidate.uid === entry.uid) === index)
    .slice(0, ANTI_FARM_MAX_INSTALLATION_ACCOUNTS);
}

function normalizeFreshHandoffHistory(entries = [], nowMs = Date.now()) {
  return (Array.isArray(entries) ? entries : [])
    .map(entry => ({
      eventId: safeString(entry?.eventId, 160),
      atMs: Math.max(0, timestampToMs(entry?.atMs)),
      attackerUid: safeString(entry?.attackerUid, 128),
      defenderUid: safeString(entry?.defenderUid, 128),
      targetKey: safeString(entry?.targetKey, 220),
      neutralClaimedAtMs: Math.max(0, timestampToMs(entry?.neutralClaimedAtMs)),
    }))
    .filter(entry => (
      entry.eventId
      && entry.atMs > nowMs - ANTI_FARM_HANDOFF_WINDOW_MS
      && entry.attackerUid
      && entry.defenderUid
      && entry.attackerUid !== entry.defenderUid
    ))
    .sort((left, right) => left.atMs - right.atMs)
    .filter((entry, index, all) => all.findIndex(candidate => candidate.eventId === entry.eventId) === index)
    .slice(-ANTI_FARM_MAX_HANDOFF_HISTORY);
}

function isFreshNeutralClaimTarget(target = {}, defenderUid = "", nowMs = Date.now()) {
  const ownerUid = getOwnerUid(target);
  const claimedByUid = safeString(target.neutralClaimedByUid, 128);
  const claimedAtMs = Math.max(0, timestampToMs(target.neutralClaimedAtMs));
  return Boolean(
    defenderUid
    && ownerUid === defenderUid
    && target.neutralClaimOpen === true
    && claimedByUid === defenderUid
    && claimedAtMs > nowMs - ANTI_FARM_FRESH_NEUTRAL_WINDOW_MS
    && claimedAtMs <= nowMs
    && !isStronghold(target)
    && !target.isMainCity
    && !target.targetType
    && !target.campType
  );
}

function getNeutralClaimCapturePatch(target = {}, attackerUid = "", nowMs = Date.now(), source = "attack") {
  if (isStronghold(target) || target.isMainCity || target.targetType || target.campType) return {};
  if (!getOwnerUid(target)) {
    return {
      neutralClaimOpen: true,
      neutralClaimedByUid: safeString(attackerUid, 128),
      neutralClaimedAtMs: nowMs,
      neutralClaimSource: safeString(source, 32) || "attack",
      neutralClaimClosedAtMs: 0,
    };
  }
  return {
    neutralClaimOpen: false,
    neutralClaimedByUid: "",
    neutralClaimedAtMs: 0,
    neutralClaimSource: "",
    neutralClaimClosedAtMs: nowMs,
  };
}

function getNeutralClaimClearedPatch(nowMs = Date.now()) {
  return {
    neutralClaimOpen: false,
    neutralClaimedByUid: "",
    neutralClaimedAtMs: 0,
    neutralClaimSource: "",
    neutralClaimClosedAtMs: nowMs,
  };
}

function normalizeAntiFarmPairState(data = {}, nowMs = Date.now()) {
  return {
    sharedInstallationLastSeenAtMs: Math.max(0, timestampToMs(data.sharedInstallationLastSeenAtMs)),
    blockedUntilMs: Math.max(0, timestampToMs(data.blockedUntilMs)),
    blockReason: safeString(data.blockReason, 48),
    freshHandoffs: normalizeFreshHandoffHistory(data.freshHandoffs, nowMs),
  };
}

function createAntiFarmPolicy(blocked = false, reason = "", blockedUntilMs = 0) {
  return {
    blocked: Boolean(blocked),
    reason: safeString(reason, 48),
    blockedUntilMs: Math.max(0, Math.floor(safeNumber(blockedUntilMs, 0))),
  };
}

function evaluateAntiFarmPairData({
  pairData = {},
  target = {},
  attackerUid = "",
  defenderUid = "",
  nowMs = Date.now(),
  checkFreshHandoff = true,
} = {}) {
  const pairState = normalizeAntiFarmPairState(pairData, nowMs);
  const freshNeutralHandoff = Boolean(
    checkFreshHandoff && isFreshNeutralClaimTarget(target, defenderUid, nowMs)
  );
  if (!attackerUid || !defenderUid || attackerUid === defenderUid) {
    return {
      policy: createAntiFarmPolicy(),
      internalReason: "",
      activatesPairBlock: false,
      freshNeutralHandoff: false,
      pairState,
    };
  }
  if (pairState.blockedUntilMs > nowMs) {
    return {
      policy: createAntiFarmPolicy(true, "linked-account-activity", pairState.blockedUntilMs),
      internalReason: pairState.blockReason || "repeated-fresh-neutral-handoffs",
      activatesPairBlock: false,
      freshNeutralHandoff,
      pairState,
    };
  }
  const sharedInstallationUntilMs = pairState.sharedInstallationLastSeenAtMs
    ? pairState.sharedInstallationLastSeenAtMs + ANTI_FARM_INSTALLATION_RETENTION_MS
    : 0;
  if (sharedInstallationUntilMs > nowMs) {
    return {
      policy: createAntiFarmPolicy(true, "linked-account-activity", sharedInstallationUntilMs),
      internalReason: "shared-installation",
      activatesPairBlock: false,
      freshNeutralHandoff,
      pairState,
    };
  }
  if (freshNeutralHandoff && pairState.freshHandoffs.length >= ANTI_FARM_ALLOWED_FRESH_HANDOFFS) {
    return {
      policy: createAntiFarmPolicy(true, "linked-account-activity", nowMs + ANTI_FARM_PAIR_BLOCK_MS),
      internalReason: "repeated-fresh-neutral-handoffs",
      activatesPairBlock: true,
      freshNeutralHandoff,
      pairState,
    };
  }
  return {
    policy: createAntiFarmPolicy(),
    internalReason: "",
    activatesPairBlock: false,
    freshNeutralHandoff,
    pairState,
  };
}

function formatAntiFarmDuration(remainingMs = 0) {
  const seconds = Math.max(0, Math.ceil(safeNumber(remainingMs, 0) / 1000));
  const days = Math.floor(seconds / 86400);
  const hours = Math.floor((seconds % 86400) / 3600);
  const minutes = Math.floor((seconds % 3600) / 60);
  if (days > 0) return `${days}d ${hours}h`;
  if (hours > 0) return `${hours}h ${minutes}m`;
  return `${Math.max(1, minutes)}m`;
}

function getAntiFarmBlockedMessage(policy = {}, nowMs = Date.now()) {
  const blockedUntilMs = Math.max(0, Math.floor(safeNumber(policy.blockedUntilMs, 0)));
  const suffix = blockedUntilMs > nowMs
    ? ` Available again in ${formatAntiFarmDuration(blockedUntilMs - nowMs)}.`
    : "";
  return `These kingdoms cannot attack each other because repeated linked-account activity was detected.${suffix}`;
}

function getAntiFarmTargetKey(target = {}, targetType = "city", targetRegionId = "") {
  return safeString(
    `${targetType === "camp" ? "camp" : "city"}:${normalizeRegionId(targetRegionId || target.regionId)}:${target.id || ""}`,
    220
  );
}

function writeAntiFarmAudit(transaction, pairRef, {
  eventId = "",
  attackerUid = "",
  defenderUid = "",
  target = {},
  targetType = "city",
  targetRegionId = "",
  internalReason = "",
  policy = {},
  phase = "launch",
  nowMs = Date.now(),
  neutralClaimedAtMs = 0,
} = {}) {
  if (!pairRef) return;
  const normalizedEventId = safeString(
    eventId || `${phase}_${attackerUid}_${defenderUid}_${target.id || "target"}_${nowMs}`,
    220
  ).replace(/[^a-zA-Z0-9_-]/g, "_");
  transaction.set(pairRef.collection("audit").doc(normalizedEventId), {
    version: ANTI_FARM_POLICY_VERSION,
    worldId: ONLINE_WORLD_ID,
    resetGeneration: RESET_GENERATION,
    pairId: pairRef.id,
    pairUids: getAntiFarmPairUids(attackerUid, defenderUid),
    attackerUid: safeString(attackerUid, 128),
    defenderUid: safeString(defenderUid, 128),
    targetType: targetType === "camp" ? "camp" : "city",
    targetId: safeString(target.id, 96),
    targetKey: getAntiFarmTargetKey(target, targetType, targetRegionId),
    targetRegionId: normalizeRegionId(targetRegionId || target.regionId),
    neutralClaimedByUid: safeString(target.neutralClaimedByUid, 128),
    neutralClaimedAtMs: Math.max(
      0,
      Math.floor(safeNumber(neutralClaimedAtMs, timestampToMs(target.neutralClaimedAtMs)))
    ),
    phase: safeString(phase, 32),
    reason: safeString(internalReason, 64),
    blockedUntilMs: Math.max(0, Math.floor(safeNumber(policy.blockedUntilMs, 0))),
    occurredAtMs: nowMs,
    createdAt: FieldValue.serverTimestamp(),
  }, { merge: false });
}

async function evaluateHostileAntiFarmPolicy(transaction, {
  attackerUid = "",
  defenderUid = "",
  target = {},
  targetType = "city",
  targetRegionId = "",
  checkFreshHandoff = true,
  attemptId = "",
  phase = "launch",
  nowMs = Date.now(),
} = {}) {
  const pairRef = antiFarmPairRef(attackerUid, defenderUid);
  if (!pairRef) {
    return {
      pairRef: null,
      pairData: {},
      ...evaluateAntiFarmPairData({
        attackerUid,
        defenderUid,
        target,
        nowMs,
        checkFreshHandoff,
      }),
    };
  }
  const pairSnap = await transaction.get(pairRef);
  const pairData = pairSnap.exists ? pairSnap.data() || {} : {};
  const decision = evaluateAntiFarmPairData({
    pairData,
    target,
    attackerUid,
    defenderUid,
    nowMs,
    checkFreshHandoff,
  });
  if (decision.policy.blocked) {
    if (decision.activatesPairBlock) {
      transaction.set(pairRef, {
        version: ANTI_FARM_POLICY_VERSION,
        worldId: ONLINE_WORLD_ID,
        resetGeneration: RESET_GENERATION,
        pairUids: getAntiFarmPairUids(attackerUid, defenderUid),
        freshHandoffs: decision.pairState.freshHandoffs,
        blockedUntilMs: decision.policy.blockedUntilMs,
        blockReason: decision.internalReason,
        blockedAtMs: nowMs,
        blockedAt: FieldValue.serverTimestamp(),
        updatedAt: FieldValue.serverTimestamp(),
      }, { merge: true });
    }
    writeAntiFarmAudit(transaction, pairRef, {
      eventId: `blocked_${phase}_${attemptId || target.id}_${nowMs}`,
      attackerUid,
      defenderUid,
      target,
      targetType,
      targetRegionId,
      internalReason: decision.internalReason,
      policy: decision.policy,
      phase,
      nowMs,
    });
  }
  return { pairRef, pairData, ...decision };
}

function recordSuccessfulFreshNeutralHandoff(transaction, context = {}, {
  eventId = "",
  attackerUid = "",
  defenderUid = "",
  target = {},
  targetType = "city",
  targetRegionId = "",
  nowMs = Date.now(),
} = {}) {
  if (!context.pairRef || !context.freshNeutralHandoff || targetType === "camp") return false;
  const normalizedEventId = safeString(eventId, 160);
  if (!normalizedEventId) return false;
  const prior = normalizeFreshHandoffHistory(context.pairState?.freshHandoffs, nowMs);
  if (prior.some(entry => entry.eventId === normalizedEventId)) return false;
  const handoff = {
    eventId: normalizedEventId,
    atMs: nowMs,
    attackerUid: safeString(attackerUid, 128),
    defenderUid: safeString(defenderUid, 128),
    targetKey: getAntiFarmTargetKey(target, targetType, targetRegionId),
    neutralClaimedAtMs: Math.max(0, timestampToMs(target.neutralClaimedAtMs)),
  };
  const freshHandoffs = [...prior, handoff].slice(-ANTI_FARM_MAX_HANDOFF_HISTORY);
  transaction.set(context.pairRef, {
    version: ANTI_FARM_POLICY_VERSION,
    worldId: ONLINE_WORLD_ID,
    resetGeneration: RESET_GENERATION,
    pairUids: getAntiFarmPairUids(attackerUid, defenderUid),
    freshHandoffs,
    lastFreshHandoffAtMs: nowMs,
    updatedAt: FieldValue.serverTimestamp(),
  }, { merge: true });
  writeAntiFarmAudit(transaction, context.pairRef, {
    eventId: `handoff_${normalizedEventId}`,
    attackerUid,
    defenderUid,
    target,
    targetType,
    targetRegionId,
    internalReason: "fresh-neutral-handoff-recorded",
    policy: createAntiFarmPolicy(),
    phase: "capture",
    nowMs,
    neutralClaimedAtMs: handoff.neutralClaimedAtMs,
  });
  return true;
}

function normalizeHarvestBonusType(type = "gold") {
  return safeString(type, 16) === "troops" ? "troops" : "gold";
}

function normalizeHarvestBonuses(bonuses = [], nowMs = Date.now()) {
  return (Array.isArray(bonuses) ? bonuses : [])
    .map(bonus => {
      const id = safeString(bonus?.id, 96).replace(/[^a-zA-Z0-9_-]/g, "_");
      const regionId = normalizeRegionId(bonus?.regionId);
      const x = safeNumber(bonus?.x, NaN);
      const y = safeNumber(bonus?.y, NaN);
      const createdAt = Math.max(0, safeNumber(bonus?.createdAt, 0));
      const createdAtMs = timestampToMs(bonus?.createdAtMs) || 0;
      if (!id || !Number.isFinite(x) || !Number.isFinite(y)) return null;
      return {
        id,
        type: normalizeHarvestBonusType(bonus?.type),
        regionId,
        x: Math.round(x),
        y: Math.round(y),
        createdAt,
        createdAtMs,
      };
    })
    .filter(Boolean)
    .filter(bonus => !bonus.createdAtMs || nowMs - bonus.createdAtMs <= HARVEST_BONUS_EXPIRE_SECONDS * 1000);
}

function enforceHarvestBonusActiveLimit(bonuses = [], nowMs = Date.now()) {
  return normalizeHarvestBonuses(bonuses, nowMs)
    .sort((a, b) => (b.createdAtMs || b.createdAt) - (a.createdAtMs || a.createdAt))
    .slice(0, HARVEST_BONUS_MAX_ACTIVE_PER_PLAYER)
    .sort((a, b) => (a.createdAtMs || a.createdAt) - (b.createdAtMs || b.createdAt));
}

function getHarvestNextSpawnAtMs(profile = {}, nowMs = Date.now()) {
  const explicit = timestampToMs(profile.harvestNextSpawnAtMs);
  if (explicit) return explicit;
  if (Number.isFinite(Number(profile.harvestSpawnTimer))) {
    return nowMs + clampInt(profile.harvestSpawnTimer, 0, HARVEST_BONUS_SPAWN_INTERVAL_SECONDS) * 1000;
  }
  return nowMs + HARVEST_BONUS_SPAWN_INTERVAL_SECONDS * 1000;
}

function getHarvestSpawnTimerFromNextAt(nextSpawnAtMs = 0, nowMs = Date.now()) {
  return clampInt(Math.ceil(Math.max(0, nextSpawnAtMs - nowMs) / 1000), 0, HARVEST_BONUS_SPAWN_INTERVAL_SECONDS);
}

function createHarvestBonusFromPayload(data = {}, uid = "", nowMs = Date.now()) {
  const bonus = data.bonus && typeof data.bonus === "object" ? data.bonus : data;
  const id = safeString(bonus.id || `harvest-${uid}-${nowMs}`, 96).replace(/[^a-zA-Z0-9_-]/g, "_");
  const regionId = normalizeRegionId(bonus.regionId || data.regionId);
  const x = safeNumber(bonus.x, NaN);
  const y = safeNumber(bonus.y, NaN);
  if (!id || !Number.isFinite(x) || !Number.isFinite(y)) return null;
  return {
    id,
    type: normalizeHarvestBonusType(bonus.type || data.type),
    regionId,
    x: Math.round(x),
    y: Math.round(y),
    createdAt: Math.max(0, safeNumber(bonus.createdAt, 0)),
    createdAtMs: nowMs,
  };
}

function getPlayerIdentitySyncSignature(identity = {}) {
  return JSON.stringify([
    normalizePlayerName(identity.ownerName),
    normalizeServerFlag(identity.ownerFlag),
    safeString(identity.clanId, 128),
    safeString(identity.clanName, 24),
    safeString(identity.clanTag, 5),
  ]);
}

function createScoutReportSnapshot(target = {}, defenderProfile = null, nowMs = Date.now(), bonuses = {}, statsOverride = null, defensePackages = null) {
  const stats = statsOverride || getCityStats(target, defenderProfile, bonuses);
  const targetType = isRewardCamp(target) ? "camp" : "city";
  const troopCount = Math.max(0, Math.floor(safeNumber(target.troops, 0)));
  const troopDefense = Math.max(0, Math.floor(safeNumber(stats.troopDefense, troopCount)));
  const reinforcements = (Array.isArray(defensePackages?.reinforcements) ? defensePackages.reinforcements : [])
    .map(row => ({
      ownerUid: safeString(row?.ownerUid, 128),
      ownerName: normalizePlayerName(row?.ownerName, "Ruler"),
      ownerFlag: normalizeServerFlag(row?.ownerFlag, row?.ownerUid) || PLAYER_FLAG_CONFIG.createDeterministicFlag(row?.ownerUid),
      troops: Math.max(0, Math.floor(safeNumber(row?.troops, 0))),
      defenseCombatVersion: Math.max(0, Math.floor(safeNumber(row?.defenseCombatVersion, 0))),
      baseDefensePowerPerTroop: Math.max(1, safeNumber(row?.baseDefensePowerPerTroop, 1)),
      basePower: Math.max(0, Math.floor(safeNumber(row?.basePower, row?.troops))),
      shieldwallDisciplineLevel: Math.max(0, Math.floor(safeNumber(row?.shieldwallDisciplineLevel, 0))),
      shieldwallDisciplinePercent: Math.max(0, safeNumber(row?.shieldwallDisciplinePercent, 0)),
      gearDefenderStrengthPercent: Math.max(0, safeNumber(row?.gearDefenderStrengthPercent, 0)),
      personalDefenseBonusPercent: Math.max(0, safeNumber(row?.personalBonusPercent, 0)),
      sharedDefenseBonusPercent: Math.max(0, safeNumber(row?.sharedBonusPercent, 0)),
      effectivePower: Math.max(0, Math.floor(safeNumber(row?.effectivePower, row?.basePower))),
    }))
    .filter(row => row.ownerUid && row.troops > 0)
    .slice(0, 50);
  const reinforcementTroops = reinforcements.reduce((total, row) => total + row.troops, 0);
  const fortification = defensePackages?.fortification && typeof defensePackages.fortification === "object"
    ? {
      modelVersion: SIEGE_COMBAT_VERSION,
      baseCityWalls: Math.max(0, Math.floor(safeNumber(stats.baseCityWalls, 0))),
      reinforcedCityWalls: Math.max(0, Math.floor(safeNumber(stats.cityWalls, 0))),
      stoneworksPercent: Math.max(0, safeNumber(stats.stoneworksPercent, 0)),
      gearWallStrengthPercent: Math.max(0, safeNumber(stats.gearWallStrengthPercent, 0)),
      cityLevelDefensePercent: Math.max(0, safeNumber(stats.defensePercent, 0)),
      objectiveDefenseBonusPercent: Math.max(0, safeNumber(defensePackages.fortification.objectiveDefenseBonusPercent, 0)),
      troopObjectiveDefenseBonusPercent: getObjectiveTroopDefenseBonusPercent(stats),
      defenseCombatVersion: Math.max(0, Math.floor(safeNumber(defensePackages.defenseCombatVersion, 0))),
      baseDefensePowerPerTroop: Math.max(1, safeNumber(stats.baseDefensePowerPerTroop, 1)),
      shieldwallDisciplinePercent: Math.max(0, safeNumber(stats.shieldwallDisciplinePercent, 0)),
      gearDefenderStrengthPercent: Math.max(0, safeNumber(stats.gearDefenderStrengthPercent, 0)),
      fullWallPower: Math.max(0, Math.floor(safeNumber(defensePackages.fortification.fullWallPower, 0))),
      currentWallPower: Math.max(0, Math.floor(safeNumber(defensePackages.fortification.currentWallPower, 0))),
      integrityBps: clampInt(defensePackages.fortification.integrityBps, 0, 10_000),
      repairAtMs: Math.max(0, timestampToMs(defensePackages.fortification.repairAtMs)),
      repairWindowMinutes: Math.max(0, Math.floor(safeNumber(defensePackages.fortification.repairWindowMinutes, 0))),
      repairReductionPercent: clamp(safeNumber(defensePackages.fortification.repairReductionPercent, 0), 0, 100),
      garrisonDefensePower: Math.max(0, Math.floor(safeNumber(defensePackages.totalGarrisonDefense, 0))),
      ownerGarrisonDefensePower: Math.max(0, Math.floor(safeNumber(defensePackages.owner?.effectivePower, 0))),
      reinforcementGarrisonDefensePower: Math.max(
        0,
        Math.floor(safeNumber(defensePackages.totalGarrisonDefense, 0))
          - Math.floor(safeNumber(defensePackages.owner?.effectivePower, 0))
      ),
    }
    : null;
  const ownerTroops = Math.max(0, Math.floor(safeNumber(
    defensePackages?.owner?.troops,
    Math.max(0, troopCount - reinforcementTroops)
  )));
  const skillSnapshot = {};
  for (const skill of SKILL_ORDER) {
    skillSnapshot[`${skill}Level`] = defenderProfile ? getSkillLevel(defenderProfile, skill) : 0;
    skillSnapshot[`${skill}Percent`] = defenderProfile ? getSkillPercent(defenderProfile, skill) : 0;
  }
  return {
    targetType,
    troops: troopCount,
    ownerTroops,
    reinforcementTroops,
    reinforcements,
    totalDefense: Math.floor(stats.totalDefense),
    baseTotalDefense: Math.floor(stats.baseTotalDefense),
    totalDefenseBonus: Math.floor(stats.totalDefenseBonus),
    siegeCombatVersion: fortification ? SIEGE_COMBAT_VERSION : 0,
    defenseCombatVersion: Math.max(0, Math.floor(safeNumber(stats.defenseCombatVersion, 0))),
    baseDefensePowerPerTroop: Math.max(1, safeNumber(stats.baseDefensePowerPerTroop, 1)),
    gearWallStrengthPercent: Math.max(0, safeNumber(stats.gearWallStrengthPercent, 0)),
    gearDefenderStrengthPercent: Math.max(0, safeNumber(stats.gearDefenderStrengthPercent, 0)),
    fortification,
    owner: getOwnerUid(target) ? "enemy" : "neutral",
    ownerUid: safeString(getOwnerUid(target), 128),
    ownerName: getOwnerName(target),
    ownerFlag: normalizeServerFlag(defenderProfile?.flag || target.ownerFlag, getOwnerUid(target))
      || (getOwnerUid(target) ? PLAYER_FLAG_CONFIG.createDeterministicFlag(getOwnerUid(target)) : null),
    cityLevel: targetType === "camp" ? 0 : stats.level,
    defensePercent: stats.defensePercent,
    baseCityWalls: stats.baseCityWalls,
    cityWalls: stats.cityWalls,
    troopDefense,
    cityDefenseBonus: Math.max(0, troopDefense - troopCount),
    objectiveTroopDefenseBonusPercent: getObjectiveTroopDefenseBonusPercent(stats),
    strongholdDefenseBonusPercent: getObjectiveTroopDefenseBonusPercent(stats),
    strongholdDefenseBonus: stats.strongholdDefenseBonus,
    stoneworksBonus: Math.max(0, stats.cityWalls - stats.baseCityWalls),
    ...skillSnapshot,
    scoutedAtMs: nowMs,
    expiresAtMs: nowMs + SCOUT_REPORT_SECONDS * 1000,
  };
}

function createDefenderScoutDisclosure(scoutReport = null) {
  if (!scoutReport || typeof scoutReport !== "object") return null;
  const skills = {};
  for (const skill of SKILL_ORDER) {
    skills[skill] = {
      level: Math.max(0, Math.floor(safeNumber(scoutReport[`${skill}Level`], 0))),
      percent: Math.max(0, safeNumber(scoutReport[`${skill}Percent`], 0)),
    };
  }
  return {
    version: 1,
    targetType: scoutReport.targetType === "camp" ? "camp" : "city",
    troops: Math.max(0, Math.floor(safeNumber(scoutReport.troops, 0))),
    ownerTroops: Math.max(0, Math.floor(safeNumber(scoutReport.ownerTroops, scoutReport.troops))),
    reinforcementTroops: Math.max(0, Math.floor(safeNumber(scoutReport.reinforcementTroops, 0))),
    reinforcements: (Array.isArray(scoutReport.reinforcements) ? scoutReport.reinforcements : [])
      .map(row => ({
        ownerUid: safeString(row?.ownerUid, 128),
        ownerName: normalizePlayerName(row?.ownerName, "Ruler"),
        ownerFlag: normalizeServerFlag(row?.ownerFlag, row?.ownerUid) || PLAYER_FLAG_CONFIG.createDeterministicFlag(row?.ownerUid),
        troops: Math.max(0, Math.floor(safeNumber(row?.troops, 0))),
      }))
      .filter(row => row.ownerUid && row.troops > 0)
      .slice(0, 50),
    totalDefense: Math.max(0, Math.floor(safeNumber(scoutReport.totalDefense, 0))),
    cityLevel: scoutReport.targetType === "camp"
      ? 0
      : clampCityLevel(scoutReport.cityLevel || 1),
    wallIntegrityBps: scoutReport.fortification
      ? clampInt(scoutReport.fortification.integrityBps, 0, 10_000)
      : 0,
    skills,
  };
}

function createDefenderScoutActivityReport({
  army = {},
  source = null,
  target = null,
  attackerUid = "",
  attackerName = "Rival ruler",
  attackerFlag = null,
  defenderUid = "",
  scoutReport = null,
  nowMs = Date.now(),
} = {}) {
  const normalizedAttackerUid = safeString(attackerUid, 128);
  const normalizedDefenderUid = safeString(defenderUid, 128);
  if (!normalizedAttackerUid || !normalizedDefenderUid || normalizedAttackerUid === normalizedDefenderUid) return null;
  const sourceCityId = safeString(source?.id || army.fromId, 96);
  const sourceCityName = safeString(source?.name || army.fromName || sourceCityId || "Unknown city", 80);
  const sourceRegionId = safeString(normalizeRegionId(source?.regionId || source?.startPool || army.sourceRegionId), 80);
  const normalizedAttackerName = normalizePlayerName(attackerName, "Rival ruler");
  const targetName = safeString(target?.name || target?.id || "your holding", 80);
  const reportIdKey = `${safeString(army.id, 160)}:${normalizedDefenderUid}`;
  const reportId = `scouted_${crypto.createHash("sha256").update(reportIdKey, "utf8").digest("hex").slice(0, 32)}`;
  const report = makeReport({
      id: reportId,
      uid: normalizedDefenderUid,
      type: "scout",
      outcome: "scout",
      city: target,
      opponentUid: normalizedAttackerUid,
      opponentName: normalizedAttackerName,
      opponentFlag: attackerFlag,
      sentTroops: 1,
      troopCount: scoutReport?.troops,
      totalDefense: scoutReport?.totalDefense,
      defenseStats: scoutReport,
      summary: `You were scouted by ${normalizedAttackerName} from ${sourceCityName}. They saw ${Math.max(0, Math.floor(safeNumber(scoutReport?.troops, 0))).toLocaleString()} troops at ${targetName}.`,
      nowMs,
    });
  const activityReport = { ...report };
  delete activityReport.scoutReport;
  delete activityReport.expiresAtMs;
  return {
    ...activityReport,
    scoutPerspective: "defender",
    sourceCityId,
    sourceCityName,
    sourceRegionId,
    scoutDisclosure: createDefenderScoutDisclosure(scoutReport),
  };
}

function getCurrentScoutReportId(uid = "", cityId = "") {
  const key = `${safeString(uid, 128)}:${safeString(cityId, 96)}`;
  const digest = crypto.createHash("sha256").update(key, "utf8").digest("hex").slice(0, 32);
  return `scout_current_${digest}`;
}

function isSuccessfulScoutIntelReport(report = null) {
  return Boolean(report?.type === "scout" && report.scoutReport && typeof report.scoutReport === "object");
}

function getScoutIntelExpiresAtMs(report = null) {
  if (!isSuccessfulScoutIntelReport(report)) return 0;
  return Math.max(
    0,
    timestampToMs(report.expiresAtMs),
    timestampToMs(report.scoutReport?.expiresAtMs)
  );
}

function pruneExpiredScoutReportMap(reports = {}, nowMs = Date.now()) {
  const source = reports && typeof reports === "object" && !Array.isArray(reports) ? reports : {};
  let changed = source !== reports;
  const activeEntries = [];
  Object.entries(source).forEach(([cityId, report]) => {
    const expiresAtMs = timestampToMs(report?.expiresAtMs);
    if (!expiresAtMs || expiresAtMs <= nowMs) {
      changed = true;
      return;
    }
    activeEntries.push([cityId, report]);
  });
  activeEntries.sort((a, b) => (
    timestampToMs(b[1]?.createdAtMs || b[1]?.scoutedAtMs || b[1]?.updatedAtMs)
      - timestampToMs(a[1]?.createdAtMs || a[1]?.scoutedAtMs || a[1]?.updatedAtMs)
  ) || a[0].localeCompare(b[0]));
  if (activeEntries.length > LEGACY_PROFILE_SCOUT_REPORT_LIMIT) changed = true;
  const active = Object.fromEntries(activeEntries.slice(0, LEGACY_PROFILE_SCOUT_REPORT_LIMIT));
  return changed ? active : source;
}

function getBattleReportOccurredAtMs(report = null) {
  return Math.max(
    0,
    timestampToMs(report?.occurredAtMs),
    timestampToMs(report?.resolvedAtMs),
    timestampToMs(report?.createdAtMs),
    timestampToMs(report?.createdAt)
  );
}

function isBattleReportHistoryExpired(report = null, nowMs = Date.now()) {
  if (!report || typeof report !== "object") return true;
  if (isSuccessfulScoutIntelReport(report)) {
    const expiresAtMs = getScoutIntelExpiresAtMs(report);
    return !expiresAtMs || expiresAtMs <= nowMs;
  }
  const occurredAtMs = getBattleReportOccurredAtMs(report);
  return Boolean(occurredAtMs && occurredAtMs + BATTLE_REPORT_RETENTION_MS <= nowMs);
}

function deleteRemovedScoutReportEntries(transaction, profileRef, before = {}, after = {}) {
  if (!transaction || !profileRef || !before || typeof before !== "object") return;
  Object.keys(before).forEach(cityId => {
    if (!Object.prototype.hasOwnProperty.call(after, cityId)) {
      transaction.update(profileRef, new FieldPath("scoutReports", cityId), FieldValue.delete());
    }
  });
}

function pruneExpiredBattleScoutReports(reports = [], nowMs = Date.now()) {
  const source = Array.isArray(reports) ? reports : [];
  const active = [];
  const successfulScoutIndexByCity = new Map();
  let changed = source !== reports;
  source.forEach(report => {
    if (isBattleReportHistoryExpired(report, nowMs)) {
      changed = true;
      return;
    }
    if (!isSuccessfulScoutIntelReport(report)) {
      active.push(report);
      return;
    }
    const cityId = safeString(report.cityId, 96);
    const existingIndex = successfulScoutIndexByCity.get(cityId);
    if (existingIndex === undefined) {
      successfulScoutIndexByCity.set(cityId, active.length);
      active.push(report);
      return;
    }
    changed = true;
    const existing = active[existingIndex];
    if (timestampToMs(report.createdAtMs) > timestampToMs(existing?.createdAtMs)) {
      active[existingIndex] = report;
    }
  });
  return changed ? active : source;
}

function normalizeCampReportReward(value = null) {
  if (!value || typeof value !== "object") return null;
  const rewardType = ["gold", "troops", "city", "item"].includes(value.rewardType)
    ? value.rewardType
    : "";
  if (!rewardType) return null;
  const amount = Math.max(0, Math.floor(safeNumber(value.amount, 0)));
  if ((rewardType === "gold" || rewardType === "troops") && amount <= 0) return null;
  if (rewardType === "city") {
    const cityId = safeString(value.cityId, 96);
    const cityName = safeString(value.cityName, 80);
    if (!cityId || !cityName) return null;
    return {
      rewardType,
      amount: Math.max(1, amount),
      cityId,
      cityName,
      cityRegionId: safeString(normalizeRegionId(value.cityRegionId), 80),
      cityRegionName: safeString(value.cityRegionName, 80),
    };
  }
  if (rewardType === "item") {
    const itemId = safeString(value.itemId, 64);
    const itemName = safeString(value.itemName, 80);
    const itemQuantity = Math.max(0, Math.floor(safeNumber(value.itemQuantity, amount)));
    if (!itemId || !itemName || itemQuantity <= 0) return null;
    return {
      rewardType,
      amount: itemQuantity,
      itemId,
      itemName,
      itemQuantity,
    };
  }
  return { rewardType, amount };
}

function makeReport({
  id,
  uid,
  type,
  outcome,
  eventKind = "",
  rewardEventId = "",
  rewardSourceId = "",
  rewardSourceRegionId = "",
  city,
  opponentUid = "",
  opponentName = "",
  opponentFlag = null,
  summary = "",
  sentTroops = 0,
  troopCount = 0,
  result = {},
  totalDefense = 0,
  defenseStats = null,
  scoutReport = null,
  xpAwarded = 0,
  goldAwarded = 0,
  troopsAwarded = 0,
  characterAfter = null,
  levelUpReward = null,
  goldAfter = null,
  campReward = null,
  attackProtection = null,
  launchCombatForecast = null,
  defenderXpMultiplierApplied = 1,
  firstProtectedDefenseBonus = false,
  battleId = "",
  fieldMedicsRecovered = 0,
  bulkOrderKind = "",
  bulkRequestId = "",
  bulkArrivalCue = "",
  bulkArrivalIndex = 0,
  bulkOrderCount = 0,
  nowMs = Date.now(),
}) {
  const targetType = isRewardCamp(city) ? "camp" : "city";
  const normalizedTotalDefense = Math.max(
    0,
    Math.floor(safeNumber(totalDefense, 0)),
    Math.floor(safeNumber(result.defensePower, 0))
  );
  const defenseBreakdown = defenseStats || scoutReport;
  const normalizedRewardEventId = safeString(rewardEventId, 160);
  const normalizedRewardSourceId = safeString(rewardSourceId, 96);
  const normalizedRewardSourceRegionId = safeString(rewardSourceRegionId, 80);
  const normalizedBaseDefense = Math.min(
    normalizedTotalDefense,
    Math.max(0, Math.floor(safeNumber(defenseBreakdown?.baseTotalDefense, normalizedTotalDefense)))
  );
  const scoutIntelExpiresAtMs = timestampToMs(scoutReport?.expiresAtMs);
  return {
    id,
    uid,
    type,
    outcome,
    eventKind: safeString(eventKind, 48),
    ...(normalizedRewardEventId ? { rewardEventId: normalizedRewardEventId } : {}),
    ...(normalizedRewardSourceId ? { rewardSourceId: normalizedRewardSourceId } : {}),
    ...(normalizedRewardSourceRegionId ? { rewardSourceRegionId: normalizedRewardSourceRegionId } : {}),
    cityId: safeString(city?.id, 96),
    regionId: safeString(city?.regionId || city?.startPool || "", 80),
    cityName: safeString(city?.name || city?.id || "Unknown city", 40),
    targetType,
    cityLevel: targetType === "camp" ? 0 : clampCityLevel(city?.level || 1),
    troopCount: Math.max(0, Math.floor(safeNumber(troopCount, city?.troops || 0))),
    sentTroops: Math.max(0, Math.floor(safeNumber(sentTroops, 0))),
    survivors: Math.max(0, Math.floor(safeNumber(result.survivors, 0))),
    defendersLeft: Math.max(0, Math.floor(safeNumber(result.defendersLeft, 0))),
    attackerLosses: Math.max(0, Math.floor(safeNumber(result.attackerLosses, 0))),
    defenderLosses: Math.max(0, Math.floor(safeNumber(result.defenderLosses, 0))),
    totalDefense: normalizedTotalDefense,
    baseTotalDefense: normalizedBaseDefense,
    totalDefenseBonus: Math.max(0, normalizedTotalDefense - normalizedBaseDefense),
    opponentUid: safeString(opponentUid, 128),
    opponentName: normalizePlayerName(opponentName, "Unknown ruler"),
    opponentFlag: normalizeServerFlag(opponentFlag, opponentUid)
      || (opponentUid ? PLAYER_FLAG_CONFIG.createDeterministicFlag(opponentUid) : null),
    ownerName: normalizePlayerName(city?.ownerName, ""),
    summary: safeString(summary, 220),
    occurredAtMs: nowMs,
    createdAtMs: nowMs,
    resetGeneration: RESET_GENERATION,
    worldId: ONLINE_WORLD_ID,
    scoutReport,
    ...(scoutIntelExpiresAtMs ? { expiresAtMs: scoutIntelExpiresAtMs } : {}),
    xpAwarded: Math.max(0, Math.floor(safeNumber(xpAwarded, 0))),
    goldAwarded: Math.max(0, Math.floor(safeNumber(goldAwarded, 0))),
    troopsAwarded: Math.max(0, Math.floor(safeNumber(troopsAwarded, 0))),
    characterAfter,
    levelUpReward: levelUpReward && levelUpReward.toLevel > levelUpReward.fromLevel
      ? {
        fromLevel: Math.max(1, Math.floor(safeNumber(levelUpReward.fromLevel, 1))),
        toLevel: Math.max(1, Math.floor(safeNumber(levelUpReward.toLevel, 1))),
        levelsGained: Math.max(1, Math.floor(safeNumber(levelUpReward.levelsGained, 1))),
        skillPointsAwarded: Math.max(0, Math.floor(safeNumber(levelUpReward.skillPointsAwarded, 0))),
        goldAwarded: Math.max(0, Math.floor(safeNumber(levelUpReward.goldAwarded, 0))),
        troopsAwarded: Math.max(0, Math.floor(safeNumber(levelUpReward.troopsAwarded, 0))),
        cityId: safeString(levelUpReward.cityId, 96),
        cityName: safeString(levelUpReward.cityName, 80),
        regionId: levelUpReward.regionId ? normalizeRegionId(levelUpReward.regionId) : "",
      }
      : null,
    goldAfter,
    campReward: normalizeCampReportReward(campReward),
    attackProtection: normalizeAttackProtectionSnapshot(attackProtection),
    launchCombatForecast: normalizeCombatForecast(launchCombatForecast),
    siegeCombatVersion: result.fortification ? SIEGE_COMBAT_VERSION : 0,
    defenseCombatVersion: Math.max(0, Math.floor(safeNumber(
      result.fortification?.defenseCombatVersion,
      defenseBreakdown?.defenseCombatVersion
    ))),
    fortification: normalizeCombatFortificationSnapshot(result.fortification),
    defenderXpMultiplierApplied: Math.max(0, safeNumber(defenderXpMultiplierApplied, 1)),
    firstProtectedDefenseBonus: firstProtectedDefenseBonus === true,
    battleId: safeString(battleId, 160),
    battleSnapshotVersion: battleId ? BATTLE_SNAPSHOT_MODEL_VERSION : 0,
    fieldMedicsRecovered: Math.max(0, Math.floor(safeNumber(fieldMedicsRecovered, 0))),
    ...(bulkRequestId ? {
      bulkOrderKind: safeString(bulkOrderKind, 32),
      bulkRequestId: safeString(bulkRequestId, 96),
      bulkArrivalCue: safeString(bulkArrivalCue, 16),
      bulkArrivalIndex: Math.max(0, Math.floor(safeNumber(bulkArrivalIndex, 0))),
      bulkOrderCount: Math.max(1, Math.floor(safeNumber(bulkOrderCount, 1))),
    } : {}),
  };
}

exports.markReportsViewed = onCall(
  { region: "us-central1", maxInstances: 20, invoker: "public" },
  async request => {
    const uid = requireAuth(request);
    const nowMs = Date.now();
    const requestedViewedAtMs = Math.max(0, timestampToMs(request.data?.viewedThroughMs));
    return runTransactionWithInfrastructureRetry(async transaction => {
      const profileRef = db.doc(`players/${uid}`);
      const profileSnap = await transaction.get(profileRef);
      if (!profileSnap.exists) {
        throw new HttpsError("failed-precondition", "Your Crownlands profile is not ready yet.");
      }
      const profile = profileSnap.data() || {};
      const currentViewedAtMs = Math.max(0, timestampToMs(profile.reportsViewedAtMs));
      const viewedAtMs = Math.max(
        currentViewedAtMs,
        Math.min(nowMs, requestedViewedAtMs || nowMs)
      );
      transaction.set(profileRef, {
        reportsViewedAtMs: viewedAtMs,
        updatedAt: FieldValue.serverTimestamp(),
      }, { merge: true });
      return {
        ok: true,
        reportsViewedAtMs: viewedAtMs,
        serverTimeMs: nowMs,
      };
    }, "markReportsViewed");
  }
);

exports.markRealmAnnouncementSeen = onCall(
  { region: "us-central1", maxInstances: 20, invoker: "public" },
  async request => {
    const uid = requireAuth(request);
    const nowMs = Date.now();
    const eventId = safeString(request.data?.eventId, 180).replace(/[^a-zA-Z0-9_-]/g, "_");
    const requestedSeenThroughMs = Math.max(0, timestampToMs(request.data?.seenThroughMs));
    const eventRef = realmActivityEventRef(eventId);
    if (!eventRef) throw new HttpsError("invalid-argument", "Choose a valid Realm Activity event.");

    return runTransactionWithInfrastructureRetry(async transaction => {
      const profileRef = db.doc(`players/${uid}`);
      const [profileSnap, eventSnap] = await Promise.all([
        transaction.get(profileRef),
        transaction.get(eventRef),
      ]);
      if (!profileSnap.exists) {
        throw new HttpsError("failed-precondition", "Your Crownlands profile is not ready yet.");
      }
      if (!eventSnap.exists) {
        throw new HttpsError("not-found", "That Realm Activity event is no longer available.");
      }

      const event = eventSnap.data() || {};
      const eventOccurredAtMs = Math.max(0, timestampToMs(event.occurredAtMs || event.createdAtMs));
      if (
        safeString(event.worldId, 120) !== ONLINE_WORLD_ID
        || safeString(event.resetGeneration, 120) !== RESET_GENERATION
        || !["STRONGHOLD_CAPTURED", "CITADEL_CAPTURED"].includes(safeString(event.eventType, 32))
        || !eventOccurredAtMs
      ) {
        throw new HttpsError("failed-precondition", "That announcement belongs to a different Crownlands realm.");
      }
      if (requestedSeenThroughMs && requestedSeenThroughMs < eventOccurredAtMs) {
        throw new HttpsError("invalid-argument", "The Realm announcement cursor cannot precede its selected event.");
      }

      const profile = profileSnap.data() || {};
      const currentSeenThroughMs = Math.max(0, timestampToMs(profile.realmAnnouncementSeenThroughMs));
      const seenThroughMs = Math.max(
        currentSeenThroughMs,
        Math.min(nowMs, Math.max(eventOccurredAtMs, requestedSeenThroughMs || eventOccurredAtMs))
      );
      const claimed = currentSeenThroughMs < eventOccurredAtMs;
      if (seenThroughMs > currentSeenThroughMs) {
        transaction.set(profileRef, {
          realmAnnouncementSeenThroughMs: seenThroughMs,
          lastRealmAnnouncementEventId: eventId,
          updatedAt: FieldValue.serverTimestamp(),
        }, { merge: true });
      }
      return {
        ok: true,
        claimed,
        eventId,
        realmAnnouncementSeenThroughMs: seenThroughMs,
        lastRealmAnnouncementEventId: seenThroughMs > currentSeenThroughMs
          ? eventId
          : safeString(profile.lastRealmAnnouncementEventId, 180),
        serverTimeMs: nowMs,
      };
    }, "markRealmAnnouncementSeen");
  }
);

function createIslandReportProjection(report = {}) {
  if (report?.type !== "scout") return report;
  return {
    ...report,
    troopCount: 0,
    totalDefense: 0,
    baseTotalDefense: 0,
    totalDefenseBonus: 0,
    scoutReport: null,
    summary: `${safeString(report.cityName || "A holding", 40)} was scouted.`,
  };
}

function battleClanIdentity(profile = {}) {
  const clanId = safeString(profile.clanId, 128);
  return clanId ? {
    clanId,
    clanName: safeString(profile.clanName, 24),
    clanTag: safeString(profile.clanTag, 5),
  } : null;
}

function splitBattleObjectiveBonusPower(totalPower = 0, personalPercent = 0, sharedPercent = 0) {
  const total = Math.max(0, Math.floor(safeNumber(totalPower, 0)));
  const personal = Math.max(0, safeNumber(personalPercent, 0));
  const shared = Math.max(0, safeNumber(sharedPercent, 0));
  const combined = personal + shared;
  const personalPower = combined > 0 ? Math.floor(total * personal / combined) : total;
  return {
    personalObjectiveBonusPower: personalPower,
    sharedClanBonusPower: Math.max(0, total - personalPower),
  };
}

function createBattleAttackPowerBreakdown(
  basePower = 0,
  effectivePower = 0,
  swordmasteryPercent = 0,
  gearAttackStrengthPercent = 0
) {
  const baseAttackPower = Math.max(0, Math.floor(safeNumber(basePower, 0)));
  const totalAttackPower = Math.max(baseAttackPower, Math.floor(safeNumber(effectivePower, baseAttackPower)));
  const totalBonusPower = Math.max(0, totalAttackPower - baseAttackPower);
  const skillPercent = Math.max(0, safeNumber(swordmasteryPercent, 0));
  const gearPercent = Math.max(0, safeNumber(gearAttackStrengthPercent, 0));
  const combinedPercent = skillPercent + gearPercent;
  const gearAttackStrengthBonusPower = combinedPercent > 0
    ? Math.floor(totalBonusPower * gearPercent / combinedPercent)
    : 0;
  return {
    baseAttackPower,
    swordmasteryBonusPower: Math.max(0, totalBonusPower - gearAttackStrengthBonusPower),
    gearAttackStrengthBonusPower,
    totalAttackPower,
  };
}

function getBattleAttackerBasePower({
  troops = 0,
  effectivePower = 0,
  bonusPercent = 0,
  attackPowerPerTroop = 0,
} = {}) {
  const normalizedTroops = Math.max(0, Math.floor(safeNumber(troops, 0)));
  const multiplier = 1 + Math.max(0, safeNumber(bonusPercent, 0)) / 100;
  const snapshottedPowerPerTroop = Math.max(0, safeNumber(attackPowerPerTroop, 0));
  if (snapshottedPowerPerTroop > 0) {
    return Math.max(0, Math.floor(normalizedTroops * snapshottedPowerPerTroop / multiplier));
  }
  return Math.max(0, Math.floor(safeNumber(effectivePower, 0) / multiplier));
}

function createBattleDefensePowerBreakdown(row = {}, { siege = false } = {}) {
  const startingTroops = Math.max(0, Math.floor(safeNumber(row.startingTroops ?? row.troops, 0)));
  const basePower = Math.max(startingTroops, Math.floor(safeNumber(row.basePower, startingTroops)));
  const soldierDefenseEnabled = Math.floor(safeNumber(row.defenseCombatVersion, 0)) >= DEFENSE_COMBAT_VERSION;
  const fortificationPower = siege
    ? 0
    : Math.min(basePower - startingTroops, Math.max(0, Math.floor(safeNumber(
      row.fortifications?.totalDefense,
      row.fortifications?.cityWalls
    ))));
  const baseDefenseBonusPower = soldierDefenseEnabled
    ? Math.max(0, basePower - startingTroops)
    : 0;
  const cityLevelDefensePower = soldierDefenseEnabled
    ? 0
    : Math.max(0, basePower - startingTroops - fortificationPower);
  const effectivePower = Math.max(basePower, Math.floor(safeNumber(row.effectivePower, basePower)));
  const shieldwallPercent = soldierDefenseEnabled
    ? Math.max(0, safeNumber(row.shieldwallDisciplinePercent, 0))
    : 0;
  const personalPercent = Math.max(0, safeNumber(row.personalDefenseBonusPercent ?? row.personalBonusPercent, 0));
  const sharedPercent = Math.max(0, safeNumber(row.sharedDefenseBonusPercent ?? row.sharedBonusPercent, 0));
  const gearPercent = soldierDefenseEnabled
    ? Math.max(0, safeNumber(row.gearDefenderStrengthPercent, 0))
    : 0;
  const totalBonusPower = Math.max(0, effectivePower - basePower);
  const combinedPercent = shieldwallPercent + gearPercent + personalPercent + sharedPercent;
  const gearDefenderStrengthBonusPower = soldierDefenseEnabled
    ? Math.min(totalBonusPower, Math.max(0, Math.floor(safeNumber(
      row.gearDefenderStrengthBonusPower,
      combinedPercent > 0 ? totalBonusPower * gearPercent / combinedPercent : 0
    ))))
    : 0;
  const nonGearBonusPower = Math.max(0, totalBonusPower - gearDefenderStrengthBonusPower);
  const nonGearCombinedPercent = shieldwallPercent + personalPercent + sharedPercent;
  const resolvedShieldwallDisciplineBonusPower = soldierDefenseEnabled && nonGearCombinedPercent > 0
    ? Math.floor(nonGearBonusPower * shieldwallPercent / nonGearCombinedPercent)
    : 0;
  const objective = splitBattleObjectiveBonusPower(
    nonGearBonusPower - resolvedShieldwallDisciplineBonusPower,
    personalPercent,
    sharedPercent
  );
  return {
    baseTroopDefensePower: startingTroops,
    baseDefenseBonusPower,
    shieldwallDisciplineBonusPower: resolvedShieldwallDisciplineBonusPower,
    gearDefenderStrengthBonusPower,
    cityLevelDefensePower,
    legacyFortificationPower: fortificationPower,
    ...objective,
    totalDefensePower: effectivePower,
  };
}

function createBattleWallPowerBreakdown(siege = null, owner = {}, defenderBonuses = {}) {
  const startingWallPower = Math.max(0, Math.floor(safeNumber(siege?.startingWallPower, 0)));
  if (!siege || startingWallPower <= 0) {
    return {
      baseWallPower: 0,
      stoneworksWallBonusPower: 0,
      gearWallStrengthBonusPower: 0,
      personalObjectiveBonusPower: 0,
      sharedClanBonusPower: 0,
      totalWallPower: 0,
    };
  }
  const integrityBps = clampInt(siege.startingIntegrityBps, 0, 10_000);
  const baseWallPower = Math.min(
    startingWallPower,
    Math.floor(Math.max(0, safeNumber(owner.fortifications?.baseCityWalls, 0)) * integrityBps / 10_000)
  );
  const fullBaseWallPower = Math.max(0, safeNumber(owner.fortifications?.baseCityWalls, 0));
  const reinforcedWalls = Math.max(fullBaseWallPower, safeNumber(owner.fortifications?.cityWalls, 0));
  const ownerWallPower = Math.min(
    startingWallPower,
    Math.floor(reinforcedWalls * integrityBps / 10_000)
  );
  const ownerWallBonusPower = Math.max(0, ownerWallPower - baseWallPower);
  const stoneworksPercent = Math.max(0, safeNumber(owner.fortifications?.stoneworksPercent, 0));
  const gearWallStrengthPercent = Math.max(0, safeNumber(owner.fortifications?.gearWallStrengthPercent, 0));
  const combinedOwnerWallPercent = stoneworksPercent + gearWallStrengthPercent;
  const stoneworksWallBonusPower = combinedOwnerWallPercent > 0
    ? Math.floor(ownerWallBonusPower * stoneworksPercent / combinedOwnerWallPercent)
    : ownerWallBonusPower;
  const gearWallStrengthBonusPower = Math.max(0, ownerWallBonusPower - stoneworksWallBonusPower);
  const objective = splitBattleObjectiveBonusPower(
    startingWallPower - ownerWallPower,
    defenderBonuses.personalDefenseBonusPercent,
    defenderBonuses.sharedDefenseBonusPercent
  );
  return {
    baseWallPower,
    stoneworksWallBonusPower,
    gearWallStrengthBonusPower,
    ...objective,
    totalWallPower: startingWallPower,
  };
}

function createDetailedBattleSnapshot({
  battleId = "",
  armyId = "",
  target = {},
  targetType = "city",
  attackerUid = "",
  attackerProfile = {},
  defenderUid = "",
  defenderProfile = {},
  defenderBonuses = {},
  defensePackages = null,
  allocation = null,
  attackerPackages = [],
  attackerAllocation = [],
  result = {},
  outcome = "",
  attackProtection = null,
  attackCombatSnapshot = null,
  nowMs = Date.now(),
} = {}) {
  if (!battleId || !defensePackages) return null;
  const allocationByUid = new Map((allocation?.contributions || []).map(entry => [entry.ownerUid, entry]));
  const ownerLosses = Math.max(0, Math.floor(safeNumber(allocation?.ownerLosses, 0)));
  const ownerTroops = Math.max(0, Math.floor(safeNumber(defensePackages.owner?.troops, 0)));
  const siege = normalizeCombatFortificationSnapshot(result.fortification || defensePackages.fortification);
  const reinforcementRows = (defensePackages.reinforcements || []).map(row => {
    const settled = allocationByUid.get(row.ownerUid) || {};
    const snapshotRow = {
      ownerUid: row.ownerUid,
      ownerName: row.ownerName,
      ownerFlag: row.ownerFlag || null,
      reinforcementId: row.reinforcementId,
      startingTroops: row.troops,
      basePower: row.basePower,
      fortifications: {
        baseCityWalls: row.baseCityWalls,
        cityWallSharePercent: row.cityWallSharePercent,
        cityWallDefense: row.cityWallDefense,
        stoneworksPercent: row.stoneworksPercent,
        stoneworksBonus: row.stoneworksBonus,
        totalDefense: row.fortificationPower,
      },
      personalDefenseBonusPercent: row.personalBonusPercent,
      sharedDefenseBonusPercent: row.sharedBonusPercent,
      totalDefenseBonusPercent: row.bonusPercent,
      defenseCombatVersion: row.defenseCombatVersion,
      baseDefensePowerPerTroop: row.baseDefensePowerPerTroop,
      shieldwallDisciplineLevel: row.shieldwallDisciplineLevel,
      shieldwallDisciplinePercent: row.shieldwallDisciplinePercent,
      gearDefenderStrengthPercent: row.gearDefenderStrengthPercent,
      gearDefenderStrengthBonusPower: row.gearDefenderStrengthBonusPower,
      effectivePower: row.effectivePower,
      objectiveSource: safeString(row.objectiveSource, 48),
      losses: Math.max(0, Math.floor(safeNumber(settled.losses, 0))),
      survivors: Math.max(0, Math.floor(safeNumber(settled.remaining, row.troops))),
    };
    snapshotRow.powerBreakdown = createBattleDefensePowerBreakdown(snapshotRow, { siege: Boolean(siege) });
    return snapshotRow;
  });
  const rallyAttackers = (Array.isArray(attackerPackages) ? attackerPackages : []).map(row => {
    const settled = (Array.isArray(attackerAllocation) ? attackerAllocation : [])
      .find(entry => entry.uid === row.uid) || {};
    const startingTroops = Math.max(0, Math.floor(safeNumber(row.troops, 0)));
    const swordmasteryPercent = Math.max(0, safeNumber(row.attackBonusPercent, 0));
    const gearAttackStrengthPercent = Math.max(0, safeNumber(row.attackGearPercent, 0));
    const effectivePower = Math.max(0, Math.floor(safeNumber(row.effectivePower, 0)));
    const basePower = getBattleAttackerBasePower({
      troops: startingTroops,
      effectivePower,
      bonusPercent: swordmasteryPercent + gearAttackStrengthPercent,
      attackPowerPerTroop: row.attackPowerPerTroop,
    });
    return {
      ownerUid: safeString(row.uid, 128),
      ownerName: normalizePlayerName(row.ownerName, "Ruler"),
      ownerFlag: row.ownerFlag || null,
      role: row.role === "leader" ? "leader" : "ally",
      sourceId: safeString(row.sourceId, 96),
      sourceRegionId: normalizeRegionId(row.sourceRegionId),
      startingTroops,
      basePower,
      swordmasteryLevel: Math.max(0, Math.floor(safeNumber(row.attackSkillLevel, 0))),
      swordmasteryPercent,
      gearAttackStrengthPercent,
      effectivePower,
      powerBreakdown: createBattleAttackPowerBreakdown(
        basePower,
        effectivePower,
        swordmasteryPercent,
        gearAttackStrengthPercent
      ),
      losses: Math.max(0, Math.floor(safeNumber(settled.losses, 0))),
      survivors: Math.max(0, Math.floor(safeNumber(settled.survivors, row.troops))),
    };
  });
  const participants = [...new Set([
    safeString(attackerUid, 128),
    safeString(defenderUid, 128),
    ...rallyAttackers.map(row => row.ownerUid),
    ...reinforcementRows.map(row => row.ownerUid),
  ].filter(Boolean))];
  const defendersAtStart = ownerTroops + reinforcementRows.reduce((total, row) => total + row.startingTroops, 0);
  const defenderLosses = Math.max(0, Math.floor(safeNumber(result.defenderLosses, 0)));
  const combatSnapshot = normalizeAttackCombatSnapshot(attackCombatSnapshot);
  const attackerStartingTroops = Math.max(0, Math.floor(safeNumber(result.attackerLosses, 0)))
    + Math.max(0, Math.floor(safeNumber(result.survivors, 0)));
  const attackerSwordmasteryPercent = combatSnapshot?.swordmasteryPercent
    ?? getSkillPercent(attackerProfile, "swordmastery");
  const attackerGearStrengthPercent = combatSnapshot?.attackStrengthPercent
    ?? getCommonGearBonuses(attackerProfile).attackStrength;
  const attackerBasePower = getBattleAttackerBasePower({
    troops: attackerStartingTroops,
    effectivePower: result.attackPower,
    bonusPercent: attackerSwordmasteryPercent + attackerGearStrengthPercent,
    attackPowerPerTroop: combatSnapshot?.attackPowerPerTroop,
  });
  const normalizedProtection = normalizeAttackProtectionSnapshot(attackProtection);
  const defenderSnapshot = {
    ownerUid: safeString(defenderUid, 128),
    ownerName: defensePackages.owner.ownerName,
    ownerFlag: defensePackages.owner.ownerFlag || null,
    clan: battleClanIdentity(defenderProfile),
    startingTroops: ownerTroops,
    basePower: defensePackages.owner.basePower,
    defenseCombatVersion: defensePackages.owner.defenseCombatVersion,
    baseDefensePowerPerTroop: defensePackages.owner.baseDefensePowerPerTroop,
    shieldwallDisciplineLevel: defensePackages.owner.shieldwallDisciplineLevel,
    shieldwallDisciplinePercent: defensePackages.owner.shieldwallDisciplinePercent,
    gearDefenderStrengthPercent: defensePackages.owner.gearDefenderStrengthPercent,
    gearDefenderStrengthBonusPower: defensePackages.owner.gearDefenderStrengthBonusPower,
    personalDefenseBonusPercent: Math.max(
      0,
      safeNumber(defenderBonuses.personalDefenseBonusPercent, defenderBonuses.cityDefenseBonusPercent)
    ),
    sharedDefenseBonusPercent: Math.max(0, safeNumber(defenderBonuses.sharedDefenseBonusPercent, 0)),
    totalDefenseBonusPercent: defensePackages.owner.bonusPercent,
    objectiveSource: safeString(defenderBonuses.objectiveSource || defenderBonuses.source, 48),
    effectivePower: defensePackages.owner.effectivePower,
    losses: ownerLosses,
    survivors: Math.max(0, ownerTroops - ownerLosses),
    fortifications: {
      cityLevelDefensePercent: defensePackages.owner.cityLevelDefensePercent,
      baseCityWalls: defensePackages.owner.baseCityWalls,
      cityWalls: defensePackages.owner.cityWalls,
      stoneworksPercent: defensePackages.owner.stoneworksPercent,
      gearWallStrengthPercent: defensePackages.owner.gearWallStrengthPercent,
    },
  };
  defenderSnapshot.powerBreakdown = createBattleDefensePowerBreakdown(defenderSnapshot, { siege: Boolean(siege) });
  const wallPowerBreakdown = createBattleWallPowerBreakdown(siege, defenderSnapshot, defenderBonuses);
  const reinforcementDefensePower = reinforcementRows.reduce(
    (total, row) => total + row.effectivePower,
    0
  );
  const defensePowerBreakdown = {
    baseTroopDefensePower: defenderSnapshot.powerBreakdown.baseTroopDefensePower,
    baseDefenseBonusPower: defenderSnapshot.powerBreakdown.baseDefenseBonusPower,
    shieldwallDisciplineBonusPower: defenderSnapshot.powerBreakdown.shieldwallDisciplineBonusPower,
    gearDefenderStrengthBonusPower: defenderSnapshot.powerBreakdown.gearDefenderStrengthBonusPower,
    cityLevelDefensePower: defenderSnapshot.powerBreakdown.cityLevelDefensePower,
    baseWallPower: wallPowerBreakdown.baseWallPower,
    stoneworksWallBonusPower: wallPowerBreakdown.stoneworksWallBonusPower,
    gearWallStrengthBonusPower: wallPowerBreakdown.gearWallStrengthBonusPower,
    personalObjectiveBonusPower: defenderSnapshot.powerBreakdown.personalObjectiveBonusPower
      + wallPowerBreakdown.personalObjectiveBonusPower,
    sharedClanBonusPower: defenderSnapshot.powerBreakdown.sharedClanBonusPower
      + wallPowerBreakdown.sharedClanBonusPower,
    reinforcementDefensePower,
    legacyFortificationPower: defenderSnapshot.powerBreakdown.legacyFortificationPower,
    totalDefensePower: Math.max(0, Math.floor(safeNumber(result.defensePower, defensePackages.totalDefense))),
  };
  const attributedDefensePower = [
    defensePowerBreakdown.baseTroopDefensePower,
    defensePowerBreakdown.baseDefenseBonusPower,
    defensePowerBreakdown.shieldwallDisciplineBonusPower,
    defensePowerBreakdown.gearDefenderStrengthBonusPower,
    defensePowerBreakdown.cityLevelDefensePower,
    defensePowerBreakdown.baseWallPower,
    defensePowerBreakdown.stoneworksWallBonusPower,
    defensePowerBreakdown.gearWallStrengthBonusPower,
    defensePowerBreakdown.personalObjectiveBonusPower,
    defensePowerBreakdown.sharedClanBonusPower,
    defensePowerBreakdown.reinforcementDefensePower,
    defensePowerBreakdown.legacyFortificationPower,
  ].reduce((total, value) => total + Math.max(0, Math.floor(safeNumber(value, 0))), 0);
  defensePowerBreakdown.otherDefensePower = Math.max(
    0,
    defensePowerBreakdown.totalDefensePower - attributedDefensePower
  );
  const protectedRaid = normalizedProtection?.mode === "raid" && result.convertedReinforcementCapture !== true;
  const protectedBreach = normalizedProtection?.mode === "assault"
    && normalizedProtection.captureAllowed !== true
    && result.convertedReinforcementCapture !== true;
  const combatRule = protectedRaid
    ? {
      id: "protected_raid",
      captureAllowed: false,
      breachRequired: false,
      maxDefenderLossPercent: 10,
    }
    : protectedBreach
      ? {
        id: "protected_breach",
        captureAllowed: false,
        breachRequired: true,
        maxDefenderLossPercent: 100,
      }
      : {
        id: normalizedProtection?.mode === "assault" ? "protected_capture" : "normal_capture",
        captureAllowed: true,
        breachRequired: false,
        maxDefenderLossPercent: 100,
      };
  return {
    battleId,
    armyId: safeString(armyId, 96),
    modelVersion: BATTLE_SNAPSHOT_MODEL_VERSION,
    combatModel: targetType === "camp"
      ? "camp_troops_only"
      : siege
        ? "city_wall_then_garrison"
        : "reinforcement_quarter_walls_full_stoneworks",
    siegeCombatVersion: siege ? SIEGE_COMBAT_VERSION : 0,
    defenseCombatVersion: Math.max(0, Math.floor(safeNumber(defensePackages.defenseCombatVersion, 0))),
    worldId: ONLINE_WORLD_ID,
    resetGeneration: RESET_GENERATION,
    participantUids: participants,
    target: {
      id: safeString(target.id, 96),
      name: safeString(target.name || target.id, 80),
      regionId: normalizeRegionId(target.regionId),
      targetType: targetType === "camp" ? "camp" : "city",
      strongholdType: safeString(target.strongholdType, 32),
      level: targetType === "camp" ? 0 : clampCityLevel(target.level || 1),
      fortifications: {
        cityLevelDefensePercent: defensePackages.owner.cityLevelDefensePercent,
        baseDefensePowerPerTroop: defensePackages.owner.baseDefensePowerPerTroop,
        shieldwallDisciplinePercent: defensePackages.owner.shieldwallDisciplinePercent,
        baseCityWalls: defensePackages.owner.baseCityWalls,
        cityWalls: defensePackages.owner.cityWalls,
        stoneworksPercent: defensePackages.owner.stoneworksPercent,
        gearWallStrengthPercent: defensePackages.owner.gearWallStrengthPercent,
        fullWallPower: siege?.fullWallPower || 0,
        startingWallPower: siege?.startingWallPower || 0,
        startingIntegrityBps: siege?.startingIntegrityBps ?? 10_000,
        endingIntegrityBps: siege?.endingIntegrityBps ?? 10_000,
        repairAtMs: siege?.repairAtMs || 0,
        repairWindowMinutes: siege?.repairWindowMinutes || 0,
        repairReductionPercent: siege?.repairReductionPercent || 0,
        repairAddedMs: siege?.repairAddedMs || 0,
      },
    },
    attacker: {
      ownerUid: safeString(attackerUid, 128),
      ownerName: normalizePlayerName(attackerProfile.playerName || attackerProfile.displayName, "Rival ruler"),
      ownerFlag: attackerProfile.flag || null,
      clan: battleClanIdentity(attackerProfile),
      startingTroops: attackerStartingTroops,
      basePower: attackerBasePower,
      swordmasteryLevel: combatSnapshot?.swordmasteryLevel ?? getSkillLevel(attackerProfile, "swordmastery"),
      swordmasteryPercent: attackerSwordmasteryPercent,
      gearAttackStrengthPercent: attackerGearStrengthPercent,
      effectivePower: Math.max(0, Math.floor(safeNumber(result.attackPower, 0))),
      powerBreakdown: createBattleAttackPowerBreakdown(
        attackerBasePower,
        result.attackPower,
        attackerSwordmasteryPercent,
        attackerGearStrengthPercent
      ),
      losses: Math.max(0, Math.floor(safeNumber(result.attackerLosses, 0))),
      survivors: Math.max(0, Math.floor(safeNumber(result.survivors, 0))),
    },
    attackers: rallyAttackers,
    defender: defenderSnapshot,
    reinforcements: reinforcementRows,
    siege,
    totals: {
      attackers: attackerStartingTroops,
      defenders: defendersAtStart,
      attackPower: Math.max(0, Math.floor(safeNumber(result.attackPower, 0))),
      defensePower: Math.max(0, Math.floor(safeNumber(result.defensePower, defensePackages.totalDefense))),
      attackerLosses: Math.max(0, Math.floor(safeNumber(result.attackerLosses, 0))),
      defenderLosses,
      attackerSurvivors: Math.max(0, Math.floor(safeNumber(result.survivors, 0))),
      defenderSurvivors: Math.max(0, defendersAtStart - defenderLosses),
      attackPowerBreakdown: createBattleAttackPowerBreakdown(
        attackerBasePower,
        result.attackPower,
        attackerSwordmasteryPercent,
        attackerGearStrengthPercent
      ),
      defensePowerBreakdown,
    },
    formula: {
      powerRatio: Math.max(0, safeNumber(result.ratio, 0)),
      defenderCasualtyPercent: defendersAtStart > 0 ? defenderLosses * 100 / defendersAtStart : 0,
      captureRequiresAttackPowerAboveDefense: combatRule.captureAllowed,
      captureThresholdPower: Math.max(0, Math.floor(safeNumber(result.defensePower, defensePackages.totalDefense))) + 1,
    },
    combatRule,
    attackProtection: normalizedProtection,
    outcome: safeString(outcome, 24),
    occurredAtMs: nowMs,
    createdAtMs: nowMs,
    createdAt: FieldValue.serverTimestamp(),
  };
}

function writeDetailedBattleSnapshot(transaction, snapshot = null) {
  const ref = battleSnapshotRef(snapshot?.battleId);
  if (!transaction || !ref || !snapshot) return null;
  transaction.set(ref, snapshot, { merge: false });
  return ref;
}

function getBattleReportsArray(profile = {}, nowMs = Date.now()) {
  return pruneExpiredBattleScoutReports(profile.battleReports, nowMs).slice(-119);
}

function buildPlayerProgressPatch(profile = {}, { xp = 0, gold = 0 } = {}) {
  const baseGold = Math.max(0, Math.floor(safeNumber(profile.gold, 0)));
  const xpResult = applyXpToCharacter(profile.character, xp);
  const upgrades = normalizeSkillUpgrades(profile.upgrades);
  const character = reconcileSkillPoints(xpResult.character, upgrades);
  const nextGold = baseGold + Math.max(0, Math.floor(safeNumber(gold, 0))) + xpResult.goldReward;
  return {
    character,
    gold: nextGold,
    goldFloat: nextGold,
    xpAwarded: xpResult.xp,
    goldAwarded: Math.max(0, Math.floor(safeNumber(gold, 0))) + xpResult.goldReward,
    levelTroopReward: xpResult.troopReward,
    levelUpReward: xpResult.levelUpReward,
  };
}

function finalizeLevelUpReward(progress = null, troopCredit = null) {
  const reward = progress?.levelUpReward;
  if (!reward || reward.toLevel <= reward.fromLevel) return null;
  const fromLevel = Math.max(1, Math.floor(safeNumber(reward.fromLevel, 1)));
  const toLevel = Math.max(1, Math.floor(safeNumber(reward.toLevel, 1)));
  if (toLevel <= fromLevel) return null;
  const finalized = {
    fromLevel,
    toLevel,
    levelsGained: toLevel - fromLevel,
    skillPointsAwarded: Math.max(0, Math.floor(safeNumber(reward.skillPointsAwarded, 0))),
    goldAwarded: Math.max(0, Math.floor(safeNumber(reward.goldAwarded, 0))),
    troopsAwarded: Math.max(0, Math.floor(safeNumber(troopCredit?.credited, 0))),
    cityId: safeString(troopCredit?.cityId, 96),
    cityName: safeString(troopCredit?.cityName, 80),
    regionId: troopCredit?.regionId ? normalizeRegionId(troopCredit.regionId) : "",
  };
  progress.levelUpReward = finalized;
  return finalized;
}

function writeReport(transaction, uid, report, profileSnap = null, extraProfilePatch = {}) {
  if (!uid || !report?.id) return;
  const profileRef = db.doc(`players/${uid}`);
  const profile = profileSnap?.exists ? profileSnap.data() || {} : {};
  const successfulScout = isSuccessfulScoutIntelReport(report);
  const currentReports = getBattleReportsArray(
    profile,
    timestampToMs(report.occurredAtMs) || timestampToMs(report.createdAtMs) || Date.now()
  );
  const retainedReports = currentReports.filter(existing => (
    safeString(existing?.id, 160) !== safeString(report.id, 160)
    && (!successfulScout || !(
      isSuccessfulScoutIntelReport(existing)
      && safeString(existing.cityId, 96) === safeString(report.cityId, 96)
    ))
  ));
  const nextReports = [...retainedReports, report].slice(-120);
  const reportDocument = {
    ...report,
    createdAt: FieldValue.serverTimestamp(),
  };
  if (successfulScout) transaction.set(reportRef(uid, report.id), reportDocument, { merge: false });
  else transaction.set(reportRef(uid, report.id), reportDocument, { merge: true });
  transaction.set(profileRef, {
    battleReports: nextReports,
    updatedAt: FieldValue.serverTimestamp(),
    ...extraProfilePatch,
  }, { merge: true });
}

function writeScoutReport(transaction, uid, cityId, report, profileSnap = null, extraProfilePatch = {}) {
  const profileRef = db.doc(`players/${uid}`);
  const profile = profileSnap?.exists ? profileSnap.data() || {} : {};
  const scoutReports = {
    ...pruneExpiredScoutReportMap(profile.scoutReports, timestampToMs(report.scoutedAtMs) || Date.now()),
    [cityId]: report,
  };
  transaction.set(profileRef, {
    scoutReports,
    updatedAt: FieldValue.serverTimestamp(),
    ...extraProfilePatch,
  }, { merge: true });
  if (profileSnap?.exists) {
    deleteRemovedScoutReportEntries(transaction, profileRef, profile.scoutReports, scoutReports);
  }
}

async function cleanupExpiredReportDocuments(nowMs = Date.now()) {
  const battleCutoffMs = nowMs - BATTLE_REPORT_RETENTION_MS;
  const [scoutSnapshot, historySnapshot, battleSnapshot] = await Promise.all([
    db.collectionGroup("serverReports")
      .where("scoutReport.expiresAtMs", "<=", nowMs)
      .limit(400)
      .get(),
    db.collectionGroup("serverReports")
      .where("createdAtMs", "<=", battleCutoffMs)
      .limit(400)
      .get(),
    db.collection(`battleSnapshots/${RESET_GENERATION}/entries`)
      .where("occurredAtMs", "<=", battleCutoffMs)
      .limit(400)
      .get(),
  ]);
  const expiredReportsByPath = new Map();
  [...scoutSnapshot.docs, ...historySnapshot.docs].forEach(doc => {
    const report = doc.data() || {};
    if (
      safeString(report.worldId, 120) !== ONLINE_WORLD_ID
      || safeString(report.resetGeneration, 120) !== RESET_GENERATION
      || !isBattleReportHistoryExpired(report, nowMs)
    ) return;
    expiredReportsByPath.set(doc.ref.path, doc);
  });
  const expiredBattleSnapshots = battleSnapshot.docs.filter(doc => {
    const snapshot = doc.data() || {};
    return safeString(snapshot.worldId, 120) === ONLINE_WORLD_ID
      && safeString(snapshot.resetGeneration, 120) === RESET_GENERATION
      && timestampToMs(snapshot.occurredAtMs) <= battleCutoffMs;
  });
  const expiredReports = [...expiredReportsByPath.values()];
  if (!expiredReports.length && !expiredBattleSnapshots.length) {
    return {
      reportsDeleted: 0,
      battleSnapshotsDeleted: 0,
      reportsScanned: scoutSnapshot.size + historySnapshot.size,
      battleSnapshotsScanned: battleSnapshot.size,
    };
  }
  const writer = db.bulkWriter();
  const reportDeletions = expiredReports.map(doc => writer
    .delete(doc.ref, { lastUpdateTime: doc.updateTime })
    .then(() => true, () => false));
  const battleSnapshotDeletions = expiredBattleSnapshots.map(doc => writer
    .delete(doc.ref, { lastUpdateTime: doc.updateTime })
    .then(() => true, () => false));
  await writer.close();
  const [reportOutcomes, battleSnapshotOutcomes] = await Promise.all([
    Promise.all(reportDeletions),
    Promise.all(battleSnapshotDeletions),
  ]);
  return {
    reportsDeleted: reportOutcomes.filter(Boolean).length,
    battleSnapshotsDeleted: battleSnapshotOutcomes.filter(Boolean).length,
    reportsScanned: scoutSnapshot.size + historySnapshot.size,
    battleSnapshotsScanned: battleSnapshot.size,
  };
}

function dropCapturedCityLevel(city = {}) {
  if (isStronghold(city)) return clampCityLevel(city.level);
  return Math.max(1, clampCityLevel(city.level) - 1);
}

function cleanCityUpdate(city = {}, patch = {}) {
  const merged = { ...city, ...patch };
  const cityId = safeString(merged.id, 96);
  const regionId = normalizeRegionId(merged.regionId || merged.startPool);
  const shouldCanonicalizeName = cityId
    && !isStronghold(merged)
    && getServerWorldRegularCityIds(regionId).has(cityId);
  return {
    ...patch,
    ...(shouldCanonicalizeName
      ? { name: getServerCanonicalCityName(merged, regionId) }
      : {}),
    updatedAt: FieldValue.serverTimestamp(),
  };
}

async function getProfileSnapshots(transaction, uids) {
  const uniqueUids = [...new Set(uids.filter(Boolean))];
  const entries = [];
  for (const uid of uniqueUids) {
    const ref = db.doc(`players/${uid}`);
    const snap = await transaction.get(ref);
    entries.push([uid, { ref, snap, data: snap.exists ? snap.data() || {} : {} }]);
  }
  return new Map(entries);
}

async function getGlobalStatsSnapshots(transaction, uids) {
  const uniqueUids = [...new Set((Array.isArray(uids) ? uids : []).filter(Boolean))];
  const entries = [];
  for (const uid of uniqueUids) {
    const ref = playerGlobalStatsRef(uid);
    const snap = await transaction.get(ref);
    entries.push([uid, snap.exists ? snap.data() || {} : {}]);
  }
  return new Map(entries);
}

async function getAuthoritativeDefensePackages(transaction, {
  target = {},
  targetType = "city",
  targetRegionId = "",
  ownerProfile = {},
  ownerGlobalStats = {},
  siegeCombatVersion = SIEGE_COMBAT_VERSION,
  defenseCombatVersion = DEFENSE_COMBAT_VERSION,
  nowMs = Date.now(),
} = {}) {
  const targetOwnerUid = safeString(getOwnerUid(target), 128);
  const targetKey = getReinforcementTargetKey(targetType, targetRegionId || target.regionId, target.id);
  const reinforcementSnap = targetOwnerUid
    ? await transaction.get(stationedReinforcementsForTargetQuery(targetKey))
    : null;
  const contributions = reinforcementSnap
    ? reinforcementSnap.docs.map(normalizeReinforcementContribution).filter(Boolean)
    : [];
  const contributorUids = contributions.map(entry => entry.ownerUid);
  const [profileEntries, contributorStats] = await Promise.all([
    getProfileSnapshots(transaction, contributorUids),
    getGlobalStatsSnapshots(transaction, contributorUids),
  ]);
  const contributorProfiles = new Map(
    [...profileEntries.entries()].map(([uid, entry]) => [uid, entry.data || {}])
  );
  const ownerBonuses = {
    objectiveSource: safeString(ownerGlobalStats.strongholdBonusSource, 48),
    crownCitadelControlled: ownerGlobalStats.crownCitadelControlled === true,
    objectiveTroopDefenseBonusPercent: getObjectiveTroopDefenseBonusPercent(ownerGlobalStats),
    cityDefenseBonusPercent: getObjectiveTroopDefenseBonusPercent(ownerGlobalStats),
    personalDefenseBonusPercent: Math.max(0, safeNumber(
      ownerGlobalStats.personalObjectiveTroopDefenseBonusPercent,
      safeNumber(
        ownerGlobalStats.personalStrongholdDefenseBonusPercent,
        ownerGlobalStats.strongholdDefenseBonusPercent
      )
    )),
    sharedDefenseBonusPercent: Math.max(0, safeNumber(
      ownerGlobalStats.sharedClanObjectiveTroopDefenseBonusPercent,
      ownerGlobalStats.sharedClanDefenseBonusPercent
    )),
  };
  return {
    contributions,
    contributorProfiles,
    contributorStats,
    ownerBonuses,
    packages: calculateDefenderArmyPackages({
      target,
      targetType,
      ownerProfile,
      ownerBonuses,
      contributions,
      contributorProfiles,
      contributorStats,
      siegeCombatVersion,
      defenseCombatVersion,
      nowMs,
    }),
  };
}

function timestampToMs(value) {
  if (!value) return 0;
  if (typeof value.toMillis === "function") return value.toMillis();
  if (typeof value.seconds === "number") return value.seconds * 1000 + Math.floor((value.nanoseconds || 0) / 1000000);
  return Math.max(0, Math.floor(safeNumber(value, 0)));
}

function getProfileLastSeenMs(profile = {}) {
  return Math.max(
    timestampToMs(profile.economyUpdatedAtMs),
    timestampToMs(profile.lastSeenAtMs),
    timestampToMs(profile.lastRealTimeMs),
    timestampToMs(profile.updatedAt)
  );
}

function getRegionIdFromOnlineIslandId(islandId = "") {
  const raw = String(islandId || "");
  const prefix = `${ONLINE_WORLD_ID}-`;
  if (raw.startsWith(prefix)) return normalizeRegionId(raw.slice(prefix.length));
  const parts = raw.split("-");
  return normalizeRegionId(parts[parts.length - 1] || raw);
}

function getRegionIdFromCityDoc(doc = null, data = {}) {
  const rawStored = data.regionId || data.startPool || "";
  if (rawStored) return normalizeRegionId(rawStored);
  const islandId = doc?.ref?.parent?.parent?.id || "";
  return getRegionIdFromOnlineIslandId(islandId);
}

function createDefaultShopItems() {
  return Object.keys(SHOP_ITEMS).reduce((items, itemId) => {
    items[itemId] = 0;
    return items;
  }, {});
}

function normalizeShopItems(items = {}) {
  const normalized = createDefaultShopItems();
  if (!items || typeof items !== "object") return normalized;
  Object.keys(SHOP_ITEMS).forEach(itemId => {
    normalized[itemId] = Math.max(0, Math.floor(safeNumber(items[itemId], 0)));
  });
  mergeLegacyShopItemCount(items, normalized, WAR_DRUMS_ITEM_ID, "troop_boost_1h");
  mergeLegacyShopItemCount(items, normalized, VEIL_OF_SILENCE_ITEM_ID, "anti_scout_1h");
  return normalized;
}

function mergeLegacyShopItemCount(items, normalized, canonicalId, legacyId) {
  const hasCanonicalCount = Object.prototype.hasOwnProperty.call(items, canonicalId);
  const legacyCount = Math.max(0, Math.floor(safeNumber(items[legacyId], 0)));
  const hasLegacyCount = legacyCount > 0 && Object.prototype.hasOwnProperty.call(items, legacyId);
  if (!hasCanonicalCount && Number.isFinite(Number(items[legacyId]))) {
    normalized[canonicalId] = legacyCount;
  } else if (hasLegacyCount) {
    normalized[canonicalId] = Math.min(normalized[canonicalId], legacyCount);
  }
}

function addLegacyShopItemDeletes(patch = {}) {
  LEGACY_SHOP_ITEM_IDS.forEach(itemId => {
    patch[`shopItems.${itemId}`] = FieldValue.delete();
  });
  return patch;
}

function normalizeItemEffects(effects = {}) {
  return {
    shieldExpiresAtMs: timestampToMs(effects.shieldExpiresAtMs || effects.shieldExpiresAt),
    warDrumsStartedAtMs: timestampToMs(effects.warDrumsStartedAtMs || effects.warDrumsStartedAt),
    warDrumsExpiresAtMs: timestampToMs(effects.warDrumsExpiresAtMs || effects.warDrumsExpiresAt || effects.troopBoostExpiresAtMs || effects.troopBoostExpiresAt),
    royalTaxDecreeStartedAtMs: timestampToMs(effects.royalTaxDecreeStartedAtMs || effects.royalTaxDecreeStartedAt),
    royalTaxDecreeExpiresAtMs: timestampToMs(effects.royalTaxDecreeExpiresAtMs || effects.royalTaxDecreeExpiresAt),
    veilOfSilenceExpiresAtMs: timestampToMs(effects.veilOfSilenceExpiresAtMs || effects.veilOfSilenceExpiresAt || effects.antiScoutExpiresAtMs || effects.antiScoutExpiresAt),
  };
}

function isVeilOfSilenceActive(profile = {}, nowMs = Date.now()) {
  return timestampToMs(
    profile?.itemEffects?.veilOfSilenceExpiresAtMs ||
    profile?.itemEffects?.veilOfSilenceExpiresAt ||
    profile?.itemEffects?.antiScoutExpiresAtMs ||
    profile?.itemEffects?.antiScoutExpiresAt
  ) > nowMs;
}

function doesVeilOfSilenceBlock(kind = "", targetType = "city") {
  return kind === "scout" && targetType !== "camp";
}

function normalizeItemPurchaseTimestamps(value = {}) {
  const rawTimestamps = Array.isArray(value?.purchaseTimestampsMs)
    ? value.purchaseTimestampsMs
    : Array.isArray(value?.purchaseTimestamps)
      ? value.purchaseTimestamps
      : [];
  return rawTimestamps
    .map(timestampToMs)
    .filter(timestamp => timestamp > 0)
    .sort((a, b) => a - b)
    .slice(-MAX_ITEM_DAILY_PURCHASE_LIMIT);
}

function getNextUtcDayStartMs(nowMs = Date.now()) {
  const date = new Date(Math.max(0, safeNumber(nowMs, Date.now())));
  return Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), date.getUTCDate() + 1);
}

function dailyMissionStateRef(uid = "", cycleKey = "") {
  const safeUid = safeString(uid, 128);
  const safeCycleKey = safeString(cycleKey, 160).replace(/[^a-zA-Z0-9_-]/g, "_");
  return safeUid && safeCycleKey
    ? db.doc(`players/${safeUid}/dailyMissions/${safeCycleKey}`)
    : null;
}

function dailyMissionEventRef(uid = "", eventId = "") {
  const safeUid = safeString(uid, 128);
  const safeEventId = safeString(eventId, 220);
  if (!safeUid || !safeEventId) return null;
  const digest = crypto.createHash("sha256").update(`${safeUid}|${safeEventId}`).digest("hex").slice(0, 36);
  return db.doc(`dailyMissionEvents/${safeUid}_${digest}`);
}

function getDailyMissionTargetCategory(target = {}, targetType = "city") {
  if (targetType === "camp" || target?.campType) return "camp";
  if (isCrownCitadel(target)) return "citadel";
  if (isStronghold(target)) return "stronghold";
  if (getOwnerUid(target)) return target?.isMainCity ? "main_city" : "player_city";
  return "neutral_city";
}

function enqueueDailyMissionEvent(transaction, {
  uid = "",
  eventId = "",
  type = "",
  occurredAtMs = Date.now(),
  ...details
} = {}) {
  const eventRef = dailyMissionEventRef(uid, eventId);
  const normalizedType = safeString(type, 48).toUpperCase();
  if (!transaction || !eventRef || !normalizedType) return null;
  const nowMs = Math.max(0, Math.floor(safeNumber(occurredAtMs, Date.now())));
  const cycle = getDailyMissionCycle(nowMs, RESET_GENERATION);
  const event = {
    id: eventRef.id,
    eventId: safeString(eventId, 220),
    uid: safeString(uid, 128),
    type: normalizedType,
    worldId: ONLINE_WORLD_ID,
    resetGeneration: RESET_GENERATION,
    cycleKey: cycle.cycleKey,
    occurredAtMs: nowMs,
    targetCategory: safeString(details.targetCategory, 32).toLowerCase(),
    opponentUid: safeString(details.opponentUid, 128),
    cityId: safeString(details.cityId, 96),
    campType: safeString(details.campType, 24).toLowerCase(),
    committedTroops: Math.max(0, Math.floor(safeNumber(details.committedTroops, 0))),
    defenderLosses: Math.max(0, Math.floor(safeNumber(details.defenderLosses, 0))),
    levelsGained: Math.max(0, Math.floor(safeNumber(details.levelsGained, 0))),
    goldSpent: Math.max(0, Math.floor(safeNumber(details.goldSpent, 0))),
    goldProduced: Math.max(0, Math.floor(safeNumber(details.goldProduced, 0))),
    troopsProduced: Math.max(0, Math.floor(safeNumber(details.troopsProduced, 0))),
    productionFromMs: Math.max(0, Math.floor(safeNumber(details.productionFromMs, 0))),
    productionToMs: Math.max(0, Math.floor(safeNumber(details.productionToMs, 0))),
    success: Boolean(details.success),
    cityCaptured: Boolean(details.cityCaptured),
    campCaptured: Boolean(details.campCaptured),
    deedCompleted: Boolean(details.deedCompleted),
    clanGiftSent: Boolean(details.clanGiftSent),
    meaningful: details.meaningful !== false,
    processedAtMs: 0,
    expiresAtMs: cycle.resetsAtMs + DAILY_MISSION_EVENT_RETENTION_MS,
    expiresAt: Timestamp.fromMillis(cycle.resetsAtMs + DAILY_MISSION_EVENT_RETENTION_MS),
    createdAt: FieldValue.serverTimestamp(),
  };
  transaction.create(eventRef, event);
  return eventRef;
}

function seasonalAchievementStateRef(uid = "", seasonId = "") {
  const safeUid = safeString(uid, 128);
  const safeSeasonId = safeString(seasonId, 180).replace(/[^a-zA-Z0-9_-]/g, "_");
  return safeUid && safeSeasonId
    ? db.doc(`players/${safeUid}/seasonalAchievements/${safeSeasonId}`)
    : null;
}

function seasonalAchievementStateForClient(state = {}, nowMs = Date.now()) {
  const achievements = Array.isArray(state.achievements) ? state.achievements : [];
  return {
    ...state,
    achievementCount: SEASONAL_ACHIEVEMENT_COUNT,
    completedCount: achievements.filter(entry => entry?.completedAtMs || entry?.claimedAtMs).length,
    claimedCount: achievements.filter(entry => entry?.claimedAtMs).length,
    claimableCount: achievements.filter(entry => entry?.completedAtMs && !entry?.claimedAtMs).length,
    serverTimeMs: Math.max(0, Math.floor(safeNumber(nowMs, Date.now()))),
  };
}

function getSeasonalAchievementRewardCapacity(stats = {}) {
  return {
    goldPerHour: Math.max(1, Math.floor(safeNumber(stats.untimedGoldPerHour, stats.goldPerHour || 1))),
    troopPerHour: Math.max(1, Math.floor(safeNumber(stats.untimedTroopPerHour, stats.troopPerHour || 1))),
  };
}

async function ensureSeasonalAchievementStateForPlayer(uid = "", nowMs = Date.now()) {
  const cycle = getSeasonalAchievementCycle(nowMs, RESET_GENERATION);
  const stateRef = seasonalAchievementStateRef(uid, cycle.seasonId);
  if (!stateRef) throw new HttpsError("invalid-argument", "A player is required for Seasonal Achievements.");
  return runTransactionWithInfrastructureRetry(async transaction => {
    const profileRef = db.doc(`players/${uid}`);
    const [stateSnap, profileSnap] = await Promise.all([
      transaction.get(stateRef),
      transaction.get(profileRef),
    ]);
    if (!profileSnap.exists) {
      throw new HttpsError("failed-precondition", "Claim a starting city before opening Seasonal Achievements.");
    }
    assertCurrentPlayerProfile(profileSnap.data() || {});
    const state = stateSnap.exists
      ? reconcileSeasonalAchievementState(stateSnap.data() || {}, {
        uid,
        worldId: ONLINE_WORLD_ID,
        resetGeneration: RESET_GENERATION,
        nowMs,
      })
      : createSeasonalAchievementState({
        uid,
        worldId: ONLINE_WORLD_ID,
        resetGeneration: RESET_GENERATION,
        nowMs,
      });
    const needsWrite = !stateSnap.exists
      || Math.floor(safeNumber(stateSnap.data()?.schemaVersion, 0)) !== SEASONAL_ACHIEVEMENT_SCHEMA_VERSION
      || Math.floor(safeNumber(stateSnap.data()?.definitionVersion, 0)) !== SEASONAL_ACHIEVEMENT_DEFINITION_VERSION
      || !Array.isArray(stateSnap.data()?.achievements)
      || stateSnap.data().achievements.length !== SEASONAL_ACHIEVEMENT_COUNT;
    if (needsWrite) {
      transaction.set(stateRef, {
        ...state,
        ...(stateSnap.exists ? {} : { createdAt: FieldValue.serverTimestamp() }),
        updatedAt: FieldValue.serverTimestamp(),
      }, { merge: stateSnap.exists });
    }
    return seasonalAchievementStateForClient(state, nowMs);
  }, "ensureSeasonalAchievementState");
}

async function applyLongReignProgressForPlayer(uid = "", nowMs = Date.now()) {
  const cycle = getSeasonalAchievementCycle(nowMs, RESET_GENERATION);
  const stateRef = seasonalAchievementStateRef(uid, cycle.seasonId);
  const reignRef = crownCitadelReignRef(uid);
  if (!stateRef || !reignRef) return null;
  await ensureSeasonalAchievementStateForPlayer(uid, nowMs);
  return runTransactionWithInfrastructureRetry(async transaction => {
    const [stateSnap, reignSnap, statsSnap] = await Promise.all([
      transaction.get(stateRef),
      transaction.get(reignRef),
      transaction.get(playerGlobalStatsRef(uid)),
    ]);
    if (!stateSnap.exists || !reignSnap.exists) return null;
    const reign = reignSnap.data() || {};
    if (
      reign.isCurrentHolder !== true
      || safeString(reign.worldId, 120) !== ONLINE_WORLD_ID
      || safeString(reign.resetGeneration, 120) !== RESET_GENERATION
    ) return null;
    const heldSinceMs = Math.max(cycle.startsAtMs, Math.max(0, timestampToMs(reign.currentHeldSinceMs)));
    if (!heldSinceMs || heldSinceMs >= nowMs) return null;
    const result = applySeasonalAchievementEvent(
      stateSnap.data() || {},
      { type: "LONG_REIGN_PROGRESS", occurredAtMs: nowMs, heldMs: nowMs - heldSinceMs },
      getSeasonalAchievementRewardCapacity(statsSnap.data() || {}),
      nowMs
    );
    transaction.set(stateRef, {
      ...result.state,
      updatedAt: FieldValue.serverTimestamp(),
    }, { merge: true });
    return { seasonId: cycle.seasonId, newlyCompletedIds: result.newlyCompletedIds };
  }, "applyLongReignProgress");
}

async function processSeasonalAchievementActionEvent(event) {
  const snapshot = event?.data;
  const raw = snapshot?.exists ? snapshot.data() || {} : {};
  const uid = safeString(raw.uid, 128);
  if (!uid || raw.seasonalAchievementProcessedAtMs) return null;
  if (safeString(raw.worldId, 128) !== ONLINE_WORLD_ID || safeString(raw.resetGeneration, 128) !== RESET_GENERATION) return null;
  const occurredAtMs = Math.max(0, Math.floor(safeNumber(raw.occurredAtMs, Date.now())));
  const cycle = getSeasonalAchievementCycle(occurredAtMs, RESET_GENERATION);
  const stateRef = seasonalAchievementStateRef(uid, cycle.seasonId);
  const eventRef = snapshot.ref;
  await ensureSeasonalAchievementStateForPlayer(uid, occurredAtMs);
  return runTransactionWithInfrastructureRetry(async transaction => {
    const [freshEventSnap, stateSnap, statsSnap] = await Promise.all([
      transaction.get(eventRef),
      transaction.get(stateRef),
      transaction.get(playerGlobalStatsRef(uid)),
    ]);
    if (!freshEventSnap.exists || !stateSnap.exists) return null;
    const freshEvent = freshEventSnap.data() || {};
    if (freshEvent.seasonalAchievementProcessedAtMs) return { replayed: true };
    const nowMs = Date.now();
    const result = applySeasonalAchievementEvent(
      stateSnap.data() || {},
      freshEvent,
      getSeasonalAchievementRewardCapacity(statsSnap.data() || {}),
      nowMs
    );
    transaction.set(stateRef, {
      ...result.state,
      updatedAt: FieldValue.serverTimestamp(),
    }, { merge: true });
    transaction.set(eventRef, {
      seasonalAchievementProcessedAtMs: nowMs,
      appliedAchievementSeasonId: cycle.seasonId,
      completedAchievementIds: result.newlyCompletedIds,
      updatedAt: FieldValue.serverTimestamp(),
    }, { merge: true });
    return { replayed: false, seasonId: cycle.seasonId, newlyCompletedIds: result.newlyCompletedIds };
  }, "processSeasonalAchievementActionEvent");
}

async function processSeasonalAchievementRealmEvent(event) {
  const snapshot = event?.data;
  const raw = snapshot?.exists ? snapshot.data() || {} : {};
  if (!snapshot?.exists || raw.seasonalAchievementProcessedAtMs) return null;
  if (safeString(raw.worldId, 128) !== ONLINE_WORLD_ID || safeString(raw.resetGeneration, 128) !== RESET_GENERATION) return null;
  const type = safeString(raw.eventType, 48).toUpperCase();
  if (!["STRONGHOLD_CAPTURED", "CITADEL_CAPTURED"].includes(type)) return null;
  const attackerUid = safeString(raw.attackerPlayerId, 128);
  if (!attackerUid) return null;
  const previousKingUid = type === "CITADEL_CAPTURED" ? safeString(raw.previousKingPlayerId, 128) : "";
  const occurredAtMs = Math.max(0, timestampToMs(raw.occurredAtMs || raw.createdAtMs)) || Date.now();
  const cycle = getSeasonalAchievementCycle(occurredAtMs, RESET_GENERATION);
  const affectedUids = [...new Set([attackerUid, previousKingUid].filter(Boolean))];
  await Promise.all(affectedUids.map(uid => ensureSeasonalAchievementStateForPlayer(uid, occurredAtMs)));
  return runTransactionWithInfrastructureRetry(async transaction => {
    const eventRef = snapshot.ref;
    const stateRefs = new Map(affectedUids.map(uid => [uid, seasonalAchievementStateRef(uid, cycle.seasonId)]));
    const [eventSnap, ...reads] = await Promise.all([
      transaction.get(eventRef),
      ...affectedUids.flatMap(uid => [
        transaction.get(stateRefs.get(uid)),
        transaction.get(playerGlobalStatsRef(uid)),
      ]),
    ]);
    if (!eventSnap.exists) return null;
    const freshEvent = eventSnap.data() || {};
    if (freshEvent.seasonalAchievementProcessedAtMs) return { replayed: true };
    const stateSnapshots = new Map();
    const statsSnapshots = new Map();
    affectedUids.forEach((uid, index) => {
      stateSnapshots.set(uid, reads[index * 2]);
      statsSnapshots.set(uid, reads[index * 2 + 1]);
    });
    const nowMs = Date.now();
    const newlyCompletedIds = [];
    const attackerResult = applySeasonalAchievementEvent(
      stateSnapshots.get(attackerUid)?.data() || {},
      {
        type,
        occurredAtMs,
        strongholdType: safeString(freshEvent.strongholdType, 32),
        previousKingPlayerId: safeString(freshEvent.previousKingPlayerId, 128),
        attackerPlayerId: attackerUid,
      },
      getSeasonalAchievementRewardCapacity(statsSnapshots.get(attackerUid)?.data() || {}),
      nowMs
    );
    transaction.set(stateRefs.get(attackerUid), {
      ...attackerResult.state,
      updatedAt: FieldValue.serverTimestamp(),
    }, { merge: true });
    newlyCompletedIds.push(...attackerResult.newlyCompletedIds.map(id => `${attackerUid}:${id}`));

    const previousReignStartedAtMs = Math.max(0, timestampToMs(freshEvent.previousReignStartedAtMs));
    if (previousKingUid && previousKingUid !== attackerUid && previousReignStartedAtMs > 0) {
      const heldSinceMs = Math.max(cycle.startsAtMs, previousReignStartedAtMs);
      const heldMs = Math.max(0, occurredAtMs - heldSinceMs);
      const previousResult = applySeasonalAchievementEvent(
        stateSnapshots.get(previousKingUid)?.data() || {},
        { type: "LONG_REIGN_PROGRESS", occurredAtMs, heldMs },
        getSeasonalAchievementRewardCapacity(statsSnapshots.get(previousKingUid)?.data() || {}),
        nowMs
      );
      transaction.set(stateRefs.get(previousKingUid), {
        ...previousResult.state,
        updatedAt: FieldValue.serverTimestamp(),
      }, { merge: true });
      newlyCompletedIds.push(...previousResult.newlyCompletedIds.map(id => `${previousKingUid}:${id}`));
    }
    transaction.set(eventRef, {
      seasonalAchievementProcessedAtMs: nowMs,
      appliedAchievementSeasonId: cycle.seasonId,
      completedAchievementIds: newlyCompletedIds,
      updatedAt: FieldValue.serverTimestamp(),
    }, { merge: true });
    return { replayed: false, seasonId: cycle.seasonId, newlyCompletedIds };
  }, "processSeasonalAchievementRealmEvent");
}

function getConfiguredRewardCampSeeds() {
  return (Array.isArray(SERVER_WORLD_LAYOUT?.maps) ? SERVER_WORLD_LAYOUT.maps : []).flatMap(map => (
    (Array.isArray(map?.camps) ? map.camps : []).map(camp => ({
      ...camp,
      regionId: normalizeRegionId(map.id || map.region?.id),
      campType: safeString(camp.campType || camp.type, 24).toLowerCase(),
    }))
  )).filter(camp => camp.id && REWARD_CAMP_CONFIG[camp.campType]);
}

function getConfiguredStrongholdSeeds() {
  return (Array.isArray(SERVER_WORLD_LAYOUT?.maps) ? SERVER_WORLD_LAYOUT.maps : []).flatMap(map => (
    (Array.isArray(map?.cities) ? map.cities : []).map(city => ({
      ...city,
      regionId: normalizeRegionId(map.id || map.region?.id),
    }))
  )).filter(city => city.id && city.strongholdType && !isCrownCitadel(city));
}

const DAILY_MISSION_SAFE_ARMY_PERCENT = 15;
const DAILY_MISSION_SAFE_LOSS_PERCENT = 10;
const DAILY_MISSION_SAFE_PEER_LIMIT = 3;
const DAILY_MISSION_SAFE_CITY_LIMIT = 12;

function getDailyMissionSourceForTarget(regularEntries = [], target = {}, maximumTroops = 0, minimumTroops = 1) {
  const troopCeiling = Math.max(1, Math.floor(safeNumber(maximumTroops, 1)));
  const minimum = Math.max(1, Math.floor(safeNumber(minimumTroops, 1)));
  const sources = (Array.isArray(regularEntries) ? regularEntries : [])
    .filter(entry => entry?.city && getOwnerUid(entry.city))
    .map(entry => ({
      ...entry,
      availableTroops: Math.max(0, Math.floor(safeNumber(entry.city.troops, 0))),
    }))
    .filter(entry => Math.min(entry.availableTroops, troopCeiling) >= minimum)
    .sort((left, right) => right.availableTroops - left.availableTroops || left.city.id.localeCompare(right.city.id));
  for (const entry of sources) {
    try {
      buildServerGeneratedArmyRoute(entry.city, target);
      return {
        city: entry.city,
        troops: Math.min(entry.availableTroops, troopCeiling),
      };
    } catch (error) {
      if (error?.code !== "failed-precondition") throw error;
    }
  }
  return null;
}

function createDailyMissionSafeBattleTarget({
  uid = "",
  nowMs = Date.now(),
  attackerProfile = {},
  attackerKingPower = 0,
  launchableTroops = 0,
  qualifyingAttackTroops = 1,
  regularEntries = [],
  target = {},
  targetType = "city",
  defenderProfile = {},
  defenderBonuses = {},
  defenderKingPower = 1,
} = {}) {
  const totalTroops = Math.max(0, Math.floor(safeNumber(launchableTroops, 0)));
  const maximumCommitment = Math.max(1, Math.floor(totalTroops * DAILY_MISSION_SAFE_ARMY_PERCENT / 100));
  const source = getDailyMissionSourceForTarget(
    regularEntries,
    target,
    maximumCommitment,
    qualifyingAttackTroops
  );
  if (!source) return null;
  const reinforcedTarget = createReinforcedCombatTarget(target, targetType);
  const defensePackages = calculateDefenderArmyPackages({
    target: reinforcedTarget,
    targetType,
    ownerProfile: defenderProfile,
    ownerBonuses: defenderBonuses,
    contributions: [],
    siegeCombatVersion: targetType === "city" ? SIEGE_COMBAT_VERSION : 0,
    defenseCombatVersion: targetType === "city" ? DEFENSE_COMBAT_VERSION : 0,
    nowMs,
  });
  const attackProtection = targetType === "city"
    ? createServerAttackProtectionSnapshot({
      sourceTroops: Math.max(1, Math.floor(safeNumber(source.city.troops, source.troops))),
      target: reinforcedTarget,
      targetType,
      requestedTroops: source.troops,
      attackerKingPower,
      defenderKingPower,
      attackerUid: uid,
      attackerProfile,
      defenderProfile,
      defenderBonuses,
      defensePower: defensePackages.totalDefense,
      assaultStage: "breach",
    })
    : null;
  if (attackProtection) return null;
  const result = calculateCombatResult(source.troops, reinforcedTarget, attackerProfile, defenderProfile, {
    defenderBonuses,
    defensePower: defensePackages.totalDefense,
    siegeCombatVersion: targetType === "city" ? SIEGE_COMBAT_VERSION : 0,
    targetType,
    fortification: defensePackages.fortification,
    garrisonDefensePower: defensePackages.totalGarrisonDefense,
    nowMs,
  });
  const maximumLosses = Math.max(0, Math.floor(totalTroops * DAILY_MISSION_SAFE_LOSS_PERCENT / 100));
  if (!result.success || result.attackerLosses > maximumLosses) return null;
  return {
    cityId: safeString(target.id, 96),
    regionId: normalizeRegionId(target.regionId || target.startPool),
    cityName: safeString(target.name || target.id || "Enemy City", 80),
    sourceCityId: safeString(source.city.id, 96),
    sourceRegionId: normalizeRegionId(source.city.regionId || source.city.startPool),
    sourceCityName: safeString(source.city.name || source.city.id || "City", 80),
    recommendedTroops: source.troops,
    estimatedLosses: Math.max(0, Math.floor(safeNumber(result.attackerLosses, 0))),
    evaluatedAtMs: nowMs,
  };
}

function selectDailyMissionPeerCandidates(opponents = [], attackerKingPower = 0) {
  const attackerPower = Math.max(1, Math.floor(safeNumber(attackerKingPower, 1)));
  return (Array.isArray(opponents) ? opponents : [])
    .filter(entry => Math.max(1, Math.floor(safeNumber(entry.kingPower, 1))) * ATTACK_PROTECTION_ASSAULT_MIN_RATIO > attackerPower)
    .sort((left, right) => {
      const leftDifference = Math.abs(Math.log(attackerPower / Math.max(1, safeNumber(left.kingPower, 1))));
      const rightDifference = Math.abs(Math.log(attackerPower / Math.max(1, safeNumber(right.kingPower, 1))));
      return leftDifference - rightDifference || safeString(left.uid, 128).localeCompare(safeString(right.uid, 128));
    })
    .slice(0, DAILY_MISSION_SAFE_PEER_LIMIT);
}

async function findDailyMissionSafePvpTargets(transaction, {
  uid = "",
  nowMs = Date.now(),
  profile = {},
  economy = null,
  opponents = [],
  regularEntries = [],
  launchableTroops = 0,
  qualifyingAttackTroops = 1,
} = {}) {
  const attackerKingPower = Math.max(0, Math.floor(safeNumber(economy?.globalStats?.kingPower, profile.kingPower)));
  const peers = selectDailyMissionPeerCandidates(opponents, attackerKingPower);
  if (!peers.length) return [];
  const reads = peers.flatMap(peer => [
    transaction.get(
      db.collectionGroup("cities")
        .where("ownerUid", "==", peer.uid)
        .where("resetGeneration", "==", RESET_GENERATION)
        .where("worldId", "==", ONLINE_WORLD_ID)
        .limit(DAILY_MISSION_SAFE_CITY_LIMIT)
    ),
    transaction.get(db.doc(`players/${peer.uid}`)),
    transaction.get(playerGlobalStatsRef(peer.uid)),
  ]);
  const snapshots = await Promise.all(reads);
  const safeTargets = [];
  peers.forEach((peer, peerIndex) => {
    const citySnap = snapshots[peerIndex * 3];
    const defenderProfileSnap = snapshots[peerIndex * 3 + 1];
    const defenderStatsSnap = snapshots[peerIndex * 3 + 2];
    if (!defenderProfileSnap?.exists) return;
    const defenderProfile = defenderProfileSnap.data() || {};
    const defenderStats = defenderStatsSnap?.exists ? defenderStatsSnap.data() || {} : {};
    if (safeString(profile.clanId, 128)
      && safeString(defenderProfile.clanId, 128) === safeString(profile.clanId, 128)) return;
    citySnap.docs.forEach(cityDoc => {
      if (safeTargets.length >= DAILY_MISSION_SAFE_CITY_LIMIT) return;
      const rawCity = cityDoc.data() || {};
      const regionId = getRegionIdFromCityDoc(cityDoc, rawCity);
      const target = { id: cityDoc.id, ...rawCity, regionId };
      if (!getServerWorldTargetIds(regionId).has(cityDoc.id)
        || isStronghold(target)
        || target.isMainCity
        || isProtectedMainCity(target, uid, defenderProfile)
        || isCityShielded(target, uid, nowMs)
        || getAlliedReinforcementTroops(target) > 0) return;
      const safeTarget = createDailyMissionSafeBattleTarget({
        uid,
        nowMs,
        attackerProfile: profile,
        attackerKingPower,
        launchableTroops,
        qualifyingAttackTroops,
        regularEntries,
        target,
        targetType: "city",
        defenderProfile,
        defenderBonuses: defenderStats,
        defenderKingPower: Math.max(1, Math.floor(safeNumber(
          defenderStats.kingPower,
          safeNumber(peer.kingPower, target.ownerKingPower)
        ))),
      });
      if (safeTarget) safeTargets.push(safeTarget);
    });
  });
  return safeTargets.slice(0, DAILY_MISSION_SAFE_CITY_LIMIT);
}

function getDailyMissionUpgradeBonuses(economy = null) {
  return {
    ...(economy?.bonuses || {}),
    upgradeCostReductionPercent: Math.min(
      85,
      Math.max(0, safeNumber(economy?.bonuses?.upgradeCostReductionPercent, 0))
        + getSkillPercent(economy?.profileAfter || {}, "guildCharters")
    ),
  };
}

function simulateDailyMissionUpgradeTargets(economy = null, remainingHours = 24) {
  const regularCities = (economy?.cityEntries || [])
    .filter(entry => entry?.city && getOwnerUid(entry.city) === economy.uid && !isStronghold(entry.city))
    .map(entry => ({ ...entry.city }));
  const rate = Math.max(1, Math.floor(safeNumber(economy?.globalStats?.untimedGoldPerHour, 1)));
  const currentGold = Math.max(0, Math.floor(safeNumber(economy?.gold, 0)));
  const bonuses = getDailyMissionUpgradeBonuses(economy);
  const definitions = {
    easy: { effortHours: 1, totalCap: 1, singleCap: 1, uniqueCap: 1 },
    medium: { effortHours: 2, totalCap: 2, singleCap: 1, uniqueCap: 2 },
    hard: { effortHours: 4, totalCap: 3, singleCap: 2, uniqueCap: 3 },
  };

  return Object.fromEntries(Object.entries(definitions).map(([difficulty, definition]) => {
    const effortHours = Math.max(0.1, Math.min(definition.effortHours, Math.max(0.1, remainingHours * 0.5)));
    const availableGold = currentGold + rate * Math.max(0, remainingHours);
    const workingBudget = Math.min(availableGold, currentGold + rate * effortHours);
    const workingCities = regularCities.map(city => ({ ...city }));
    let totalLevels = 0;
    let totalSpent = 0;
    while (workingCities.length && totalLevels < definition.totalCap) {
      const choices = workingCities.map((city, index) => ({ index, cost: getCityUpgradeCost(city, bonuses) }))
        .filter(choice => Number.isFinite(choice.cost))
        .sort((left, right) => left.cost - right.cost);
      const choice = choices[0];
      if (!choice || totalSpent + choice.cost > workingBudget) break;
      totalSpent += choice.cost;
      totalLevels += 1;
      workingCities[choice.index].level = clampCityLevel(workingCities[choice.index].level + 1);
    }

    let singleCityLevels = 0;
    regularCities.forEach(source => {
      const city = { ...source };
      let spent = 0;
      let levels = 0;
      while (levels < definition.singleCap) {
        const cost = getCityUpgradeCost(city, bonuses);
        if (!Number.isFinite(cost) || spent + cost > workingBudget) break;
        spent += cost;
        levels += 1;
        city.level = clampCityLevel(city.level + 1);
      }
      singleCityLevels = Math.max(singleCityLevels, levels);
    });

    const nextCosts = regularCities.map(city => getCityUpgradeCost(city, bonuses))
      .filter(Number.isFinite)
      .sort((left, right) => left - right);
    let uniqueCities = 0;
    let uniqueSpent = 0;
    for (const cost of nextCosts) {
      if (uniqueCities >= Math.min(definition.uniqueCap, regularCities.length) || uniqueSpent + cost > workingBudget) break;
      uniqueSpent += cost;
      uniqueCities += 1;
    }
    const cheapestCost = nextCosts[0] || 0;
    const goldSpendTarget = cheapestCost > 0 && cheapestCost <= availableGold
      ? Math.max(1, Math.floor(Math.min(
        Math.max(cheapestCost, Math.min(totalSpent || cheapestCost, workingBudget)),
        rate * effortHours
      )))
      : 0;
    return [difficulty, { totalLevels, singleCityLevels, uniqueCities, goldSpendTarget }];
  }));
}

async function buildDailyMissionCapacity(transaction, uid = "", nowMs = Date.now(), economy = null) {
  const profile = economy?.profileAfter || {};
  const cycle = getDailyMissionCycle(nowMs, RESET_GENERATION);
  const regularEntries = (economy?.cityEntries || []).filter(entry => (
    entry?.city && getOwnerUid(entry.city) === uid && !isStronghold(entry.city)
  ));
  const ownedLaunchEntries = (economy?.cityEntries || []).filter(entry => entry?.city && getOwnerUid(entry.city) === uid);
  const launchableTroops = ownedLaunchEntries.reduce(
    (total, entry) => total + Math.max(0, Math.floor(safeNumber(entry.city.troops, 0))),
    0
  );
  const maxSourceTroops = ownedLaunchEntries.reduce(
    (maximum, entry) => Math.max(maximum, Math.max(0, Math.floor(safeNumber(entry.city.troops, 0)))),
    0
  );
  const qualifyingAttackTroops = Math.max(1, Math.ceil(launchableTroops * 0.05));
  const goldPerHour = Math.max(1, Math.floor(safeNumber(economy?.globalStats?.untimedGoldPerHour, 1)));
  const troopPerHour = Math.max(1, Math.floor(safeNumber(economy?.globalStats?.untimedTroopPerHour, 1)));
  const projectedCombatTroops = Math.max(
    launchableTroops,
    Math.floor(launchableTroops + troopPerHour * Math.min(12, cycle.remainingHours))
  );

  const leaderboardQuery = db.collection(`leaderboards/${RESET_GENERATION}/entries`).limit(GAME_SERVER_CAPACITY);
  const campSeeds = getConfiguredRewardCampSeeds();
  const strongholdSeeds = getConfiguredStrongholdSeeds();
  const clanId = safeString(profile.clanId, 128);
  const reads = [transaction.get(leaderboardQuery)];
  campSeeds.forEach(camp => reads.push(transaction.get(campRefForRegion(camp.regionId, camp.id))));
  strongholdSeeds.forEach(city => reads.push(transaction.get(cityRefForRegion(city.regionId, city.id))));
  if (clanId) {
    reads.push(transaction.get(db.doc(`clans/${clanId}`)));
    reads.push(transaction.get(clanMemberRewardsRef(clanId, uid)));
  }
  reads.push(transaction.get(db.doc(`players/${uid}/objectiveStats/deedCamp`)));
  const snapshots = await Promise.all(reads);
  let readIndex = 0;
  const leaderboardSnap = snapshots[readIndex++];
  const campSnaps = campSeeds.map(() => snapshots[readIndex++]);
  const strongholdSnaps = strongholdSeeds.map(() => snapshots[readIndex++]);
  const clanSnap = clanId ? snapshots[readIndex++] : null;
  const memberRewardsSnap = clanId ? snapshots[readIndex++] : null;
  const deedClaimSnap = snapshots[readIndex++];
  const campHolderUids = [...new Set(campSnaps
    .map(snapshot => safeString(snapshot?.data()?.holderUid || snapshot?.data()?.ownerUid, 128))
    .filter(Boolean))];
  const campDefenderSnaps = await Promise.all(campHolderUids.flatMap(holderUid => [
    transaction.get(db.doc(`players/${holderUid}`)),
    transaction.get(playerGlobalStatsRef(holderUid)),
  ]));
  const campDefenders = new Map(campHolderUids.map((holderUid, index) => [holderUid, {
    profile: campDefenderSnaps[index * 2]?.exists ? campDefenderSnaps[index * 2].data() || {} : {},
    stats: campDefenderSnaps[index * 2 + 1]?.exists ? campDefenderSnaps[index * 2 + 1].data() || {} : {},
  }]));

  const opponents = leaderboardSnap.docs.map(doc => ({ uid: doc.id, ...doc.data() }))
    .filter(entry => entry.uid !== uid)
    .filter(entry => safeString(entry.worldId, 128) === ONLINE_WORLD_ID)
    .filter(entry => safeString(entry.resetGeneration, 128) === RESET_GENERATION)
    .filter(entry => Math.max(0, Math.floor(safeNumber(entry.cityCount, 0))) > 1)
    .filter(entry => !clanId || safeString(entry.clanId, 128) !== clanId);
  const eligibleEnemyCityCount = opponents.reduce((total, entry) => (
    total + Math.max(0, Math.floor(safeNumber(entry.cityCount, 0)) - 1)
  ), 0);

  const feasibleCampTypes = [];
  campSeeds.forEach((seed, index) => {
    const data = campSnaps[index]?.exists ? campSnaps[index].data() || {} : {};
    const holderUid = safeString(data.holderUid || data.ownerUid, 128);
    const holderClanId = safeString(data.ownerClanId || data.holderClanId, 128);
    const defender = campDefenders.get(holderUid) || { profile: {}, stats: {} };
    const currentHolderClanId = safeString(defender.profile.clanId || holderClanId, 128);
    const target = getRewardCampCombatTarget({
      id: seed.id,
      ...seed,
      ...data,
      regionId: seed.regionId,
    });
    if (!target
      || holderUid === uid
      || clanId && currentHolderClanId === clanId
      || getAlliedReinforcementTroops(target) > 0) return;
    const safeTarget = createDailyMissionSafeBattleTarget({
      uid,
      nowMs,
      attackerProfile: profile,
      attackerKingPower: Math.max(0, Math.floor(safeNumber(economy?.globalStats?.kingPower, profile.kingPower))),
      launchableTroops,
      qualifyingAttackTroops,
      regularEntries: ownedLaunchEntries,
      target,
      targetType: "camp",
      defenderProfile: defender.profile,
      defenderBonuses: defender.stats,
      defenderKingPower: Math.max(1, Math.floor(safeNumber(defender.stats.kingPower, defender.profile.kingPower || 1))),
    });
    if (safeTarget) feasibleCampTypes.push(seed.campType);
  });

  const safePvpTargets = await findDailyMissionSafePvpTargets(transaction, {
    uid,
    nowMs,
    profile,
    economy,
    opponents,
    regularEntries: ownedLaunchEntries,
    launchableTroops,
    qualifyingAttackTroops,
  });

  const strongholdEligible = cycle.remainingHours >= 0.5 && strongholdSeeds.some((seed, index) => {
    const data = strongholdSnaps[index]?.exists ? strongholdSnaps[index].data() || {} : seed;
    const ownerUid = getOwnerUid(data);
    const ownerClanId = safeString(data.ownerClanId, 128);
    return ownerUid !== uid && (!clanId || ownerClanId !== clanId);
  });
  const giftData = memberRewardsSnap?.exists ? memberRewardsSnap.data() || {} : {};
  const lastGiftSentAtMs = Math.max(0, timestampToMs(giftData.lastGiftSentAtMs));
  const giftReadyAtMs = lastGiftSentAtMs + CLAN_GIFT_COOLDOWN_MS;
  const clanGiftEligible = Boolean(
    clanId
    && clanSnap?.exists
    && clanSnap.data()?.status === "active"
    && Math.max(0, Math.floor(safeNumber(clanSnap.data()?.memberCount, 0))) >= 2
    && giftReadyAtMs < cycle.resetsAtMs
  );
  const deedClaims = deedClaimSnap?.exists ? deedClaimSnap.data() || {} : {};
  const deedCampEligible = feasibleCampTypes.includes("deed")
    && cycle.remainingHours >= (DEED_CAMP_HOLD_DURATION_MS + 30 * 60 * 1000) / 3_600_000
    && !(safeString(deedClaims.date, 10) === cycle.utcDate && Math.max(0, Math.floor(safeNumber(deedClaims.count, 0))) >= 1)
    && regularEntries.length < NEUTRAL_CITY_COUNT_LIMIT;

  return {
    cityCount: regularEntries.length,
    totalCityLevels: regularEntries.reduce((total, entry) => total + clampCityLevel(entry.city.level), 0),
    averageCityLevel: regularEntries.length
      ? regularEntries.reduce((total, entry) => total + clampCityLevel(entry.city.level), 0) / regularEntries.length
      : 1,
    gold: Math.max(0, Math.floor(safeNumber(economy?.gold, 0))),
    goldPerHour,
    troopPerHour,
    launchableTroops,
    maxSourceTroops,
    qualifyingAttackTroops,
    projectedCombatTroops,
    kingPower: Math.max(0, Math.floor(safeNumber(economy?.globalStats?.kingPower, profile.kingPower))),
    eligibleOpponentCount: opponents.length,
    eligibleEnemyCityCount,
    safePvpTargets,
    maxCampCaptures: feasibleCampTypes.length,
    feasibleCampTypes,
    deedCampEligible,
    strongholdEligible,
    clanGiftEligible,
    remainingHours: cycle.remainingHours,
    upgradeTargets: simulateDailyMissionUpgradeTargets(economy, cycle.remainingHours),
    itemCosts: Object.fromEntries(Object.entries(SHOP_ITEMS).map(([itemId, item]) => [itemId, item.cost])),
  };
}

function dailyMissionStateForClient(state = {}, nowMs = Date.now()) {
  return {
    ...state,
    serverTimeMs: Math.max(0, Math.floor(safeNumber(nowMs, Date.now()))),
  };
}

async function ensureDailyMissionStateForPlayer(uid = "", nowMs = Date.now()) {
  const cycle = getDailyMissionCycle(nowMs, RESET_GENERATION);
  const stateRef = dailyMissionStateRef(uid, cycle.cycleKey);
  if (!stateRef) throw new HttpsError("invalid-argument", "A player is required for Daily Missions.");
  return runTransactionWithInfrastructureRetry(async transaction => {
    const profileRef = db.doc(`players/${uid}`);
    const [stateSnap, profileSnap] = await Promise.all([
      transaction.get(stateRef),
      transaction.get(profileRef),
    ]);
    if (!profileSnap.exists) {
      throw new HttpsError("failed-precondition", "Claim a starting city before opening Daily Missions.");
    }
    const profile = profileSnap.data() || {};
    assertCurrentPlayerProfile(profile);
    if (stateSnap.exists) {
      const existingState = stateSnap.data() || {};
      if (Math.max(0, Math.floor(safeNumber(existingState.schemaVersion, 0))) >= DAILY_MISSION_SCHEMA_VERSION) {
        return dailyMissionStateForClient(existingState, nowMs);
      }
      const economy = await prepareEconomyCollection(transaction, uid, nowMs, { profileRef, profileSnap });
      const capacity = await buildDailyMissionCapacity(transaction, uid, nowMs, economy);
      const migratedState = migrateDailyMissionState(existingState, capacity, nowMs);
      transaction.set(stateRef, {
        ...migratedState,
        updatedAt: FieldValue.serverTimestamp(),
      }, { merge: true });
      writePreparedEconomy(transaction, economy, {}, [], {
        nowMs,
        suppressDailyMissionProduction: true,
      });
      return dailyMissionStateForClient(migratedState, nowMs);
    }
    const economy = await prepareEconomyCollection(transaction, uid, nowMs, { profileRef, profileSnap });
    const capacity = await buildDailyMissionCapacity(transaction, uid, nowMs, economy);
    let state;
    try {
      state = createDailyMissionState({
        uid,
        worldId: ONLINE_WORLD_ID,
        resetGeneration: RESET_GENERATION,
        nowMs,
        capacity,
      });
    } catch (error) {
      console.error("Daily mission generation failed", { uid, cycleKey: cycle.cycleKey, error: error?.message });
      throw new HttpsError("unavailable", "Daily Missions are being prepared. Try again in a moment.");
    }
    transaction.create(stateRef, {
      ...state,
      createdAt: FieldValue.serverTimestamp(),
      updatedAt: FieldValue.serverTimestamp(),
      expiresAt: Timestamp.fromMillis(state.expiresAtMs),
    });
    writePreparedEconomy(transaction, economy, {}, [], {
      nowMs,
      suppressDailyMissionProduction: true,
    });
    return dailyMissionStateForClient(state, nowMs);
  });
}

async function processDailyMissionEvent(event) {
  const snapshot = event?.data;
  const raw = snapshot?.exists ? snapshot.data() || {} : {};
  if (!raw?.uid || raw.processedAtMs) return null;
  if (safeString(raw.worldId, 128) !== ONLINE_WORLD_ID || safeString(raw.resetGeneration, 128) !== RESET_GENERATION) return null;
  const occurredAtMs = Math.max(0, Math.floor(safeNumber(raw.occurredAtMs, Date.now())));
  await Promise.all([
    ensureDailyMissionStateForPlayer(raw.uid, occurredAtMs),
    ensureSeasonalAchievementStateForPlayer(raw.uid, occurredAtMs),
  ]);
  const cycle = getDailyMissionCycle(occurredAtMs, RESET_GENERATION);
  const stateRef = dailyMissionStateRef(raw.uid, cycle.cycleKey);
  const achievementCycle = getSeasonalAchievementCycle(occurredAtMs, RESET_GENERATION);
  const achievementStateRef = seasonalAchievementStateRef(raw.uid, achievementCycle.seasonId);
  const eventRef = snapshot?.ref || dailyMissionEventRef(raw.uid, raw.eventId || raw.id);
  return runTransactionWithInfrastructureRetry(async transaction => {
    const playerRef = db.doc(`players/${raw.uid}`);
    const [freshEventSnap, stateSnap, achievementStateSnap, statsSnap, playerSnap] = await Promise.all([
      transaction.get(eventRef),
      transaction.get(stateRef),
      transaction.get(achievementStateRef),
      transaction.get(playerGlobalStatsRef(raw.uid)),
      transaction.get(playerRef),
    ]);
    if (!freshEventSnap.exists || !stateSnap.exists || !achievementStateSnap.exists) return null;
    const freshEvent = freshEventSnap.data() || {};
    if (freshEvent.processedAtMs) return { replayed: true };
    const nowMs = Date.now();
    const currentState = stateSnap.data() || {};
    let eventForProgress = freshEvent;
    if (safeString(freshEvent.type, 48).toUpperCase() === "ECONOMY_PRODUCED") {
      const productionToMs = Math.max(0, Math.floor(safeNumber(
        freshEvent.productionToMs,
        freshEvent.occurredAtMs
      )));
      const productionFromMs = Math.min(
        productionToMs,
        Math.max(0, Math.floor(safeNumber(freshEvent.productionFromMs, productionToMs)))
      );
      const eligibleFromMs = Math.max(
        productionFromMs,
        Math.floor(safeNumber(currentState.cycleStartsAtMs, cycle.startsAtMs)),
        Math.floor(safeNumber(currentState.generatedAtMs, cycle.startsAtMs))
      );
      const fullDurationMs = Math.max(0, productionToMs - productionFromMs);
      const eligibleDurationMs = Math.max(0, productionToMs - eligibleFromMs);
      const eligibleShare = fullDurationMs > 0
        ? clamp(eligibleDurationMs / fullDurationMs, 0, 1)
        : 0;
      eventForProgress = {
        ...freshEvent,
        goldProduced: Math.floor(Math.max(0, safeNumber(freshEvent.goldProduced, 0)) * eligibleShare),
        troopsProduced: Math.floor(Math.max(0, safeNumber(freshEvent.troopsProduced, 0)) * eligibleShare),
      };
    }
    const nextState = applyDailyMissionEvent(currentState, eventForProgress, nowMs);
    const priorCompletedIds = new Set((Array.isArray(currentState.missions) ? currentState.missions : [])
      .filter(mission => mission?.completedAtMs || mission?.claimedAtMs)
      .map(mission => safeString(mission.id, 96)));
    const newlyCompletedMissions = (Array.isArray(nextState.missions) ? nextState.missions : [])
      .filter(mission => (mission?.completedAtMs || mission?.claimedAtMs) && !priorCompletedIds.has(safeString(mission.id, 96)));
    let achievementState = achievementStateSnap.data() || {};
    const newlyCompletedAchievementIds = [];
    if (newlyCompletedMissions.length) {
      const completionResult = applySeasonalAchievementEvent(
        achievementState,
        {
          type: "DAILY_MISSIONS_COMPLETED",
          occurredAtMs,
          count: newlyCompletedMissions.length,
        },
        getSeasonalAchievementRewardCapacity(statsSnap.data() || {}),
        nowMs
      );
      achievementState = completionResult.state;
      newlyCompletedAchievementIds.push(...completionResult.newlyCompletedIds);
      if (Math.max(0, Math.floor(safeNumber(currentState.completedCount, 0))) < 3 && nextState.completedCount >= 3) {
        const allCompletedResult = applySeasonalAchievementEvent(
          achievementState,
          {
            type: "DAILY_ALL_COMPLETED",
            occurredAtMs,
            dateKey: cycle.utcDate,
          },
          getSeasonalAchievementRewardCapacity(statsSnap.data() || {}),
          nowMs
        );
        achievementState = allCompletedResult.state;
        newlyCompletedAchievementIds.push(...allCompletedResult.newlyCompletedIds);
        const gear = normalizeCommonGear(playerSnap.exists ? playerSnap.data() || {} : {});
        gear.commonGearBoxes += 1;
        gear.updatedAtMs = nowMs;
        transaction.set(playerRef, { gear }, { merge: true });
        nextState.allCompletedGearBoxAwardedAtMs = nowMs;
      }
      transaction.set(achievementStateRef, {
        ...achievementState,
        updatedAt: FieldValue.serverTimestamp(),
      }, { merge: true });
    }
    transaction.set(stateRef, {
      ...nextState,
      updatedAt: FieldValue.serverTimestamp(),
    }, { merge: true });
    transaction.set(eventRef, {
      processedAtMs: nowMs,
      appliedCycleKey: cycle.cycleKey,
      dailyAchievementCompletedMissionIds: newlyCompletedMissions.map(mission => safeString(mission.id, 96)),
      completedDailyAchievementIds: newlyCompletedAchievementIds,
      updatedAt: FieldValue.serverTimestamp(),
    }, { merge: true });
    return { replayed: false, cycleKey: cycle.cycleKey };
  });
}

function getCityRelinquishPolicy(lastCityRelinquishedAtMs = 0, nowMs = Date.now()) {
  const currentTime = Math.max(0, Math.floor(safeNumber(nowMs, Date.now())));
  const lastRelinquishedAtMs = timestampToMs(lastCityRelinquishedAtMs);
  const utcDate = getUtcDateKey(currentTime);
  const used = lastRelinquishedAtMs > 0 && getUtcDateKey(lastRelinquishedAtMs) === utcDate;
  return {
    limit: CITY_RELINQUISH_DAILY_LIMIT,
    utcDate,
    used,
    lastCityRelinquishedAtMs: lastRelinquishedAtMs,
    availableAtMs: used ? getNextUtcDayStartMs(currentTime) : 0,
  };
}

function getDailyLoginRewardMonthInfo(nowMs = Date.now()) {
  const month = getUtcMonthCycle(nowMs);
  const date = new Date(month.startsAtMs);
  const year = date.getUTCFullYear();
  const monthIndex = date.getUTCMonth();
  const monthLengthDays = new Date(Date.UTC(year, monthIndex + 1, 0)).getUTCDate();
  return {
    monthKey: month.monthKey,
    monthLengthDays,
    monthStartsAtMs: month.startsAtMs,
    monthEndsAtMs: month.endsAtMs,
    daysRemaining: month.daysRemaining,
    track: DAILY_LOGIN_REWARD_TRACKS[String(monthLengthDays)],
  };
}

function normalizeDailyLoginRewardReceipt(raw = {}) {
  if (!raw || typeof raw !== "object") return null;
  const monthLengthDays = clampInt(
    Object.prototype.hasOwnProperty.call(raw, "monthLengthDays")
      ? raw.monthLengthDays
      : LEGACY_DAILY_LOGIN_REWARD_CYCLE_DAYS,
    28,
    31
  );
  const day = clampInt(raw.day, 1, monthLengthDays);
  const cycle = Math.max(1, Math.floor(safeNumber(raw.cycle, 1)));
  const dayKey = safeString(raw.dayKey, 10);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(dayKey)) return null;
  const monthKey = /^\d{4}-\d{2}$/.test(safeString(raw.monthKey, 7))
    ? safeString(raw.monthKey, 7)
    : dayKey.slice(0, 7);
  const items = Object.fromEntries(
    Object.entries(raw.items || {})
      .filter(([itemId, quantity]) => SHOP_ITEMS[itemId] && Number(quantity) > 0)
      .map(([itemId, quantity]) => [itemId, Math.max(1, Math.floor(safeNumber(quantity, 1)))])
  );
  return {
    cycle,
    day,
    ordinal: Math.max(1, Math.floor(safeNumber(raw.ordinal, day))),
    monthKey,
    monthLengthDays,
    claimId: safeString(raw.claimId, 96),
    dayKey,
    claimedAtMs: Math.max(0, timestampToMs(raw.claimedAtMs || raw.claimedAt)),
    goldHours: Math.max(0, safeNumber(raw.goldHours, 0)),
    troopHours: Math.max(0, safeNumber(raw.troopHours, 0)),
    gold: Math.max(0, Math.floor(safeNumber(raw.gold, 0))),
    troops: Math.max(0, Math.floor(safeNumber(raw.troops, 0))),
    commonGearBoxes: Math.max(0, Math.floor(safeNumber(raw.commonGearBoxes, 0))),
    items,
    targetCityId: safeString(raw.targetCityId, 96),
  };
}

function getLegacyDailyLoginRewardOrdinal(cycle = 1, day = 1) {
  const safeCycle = Math.max(1, Math.floor(safeNumber(cycle, 1)));
  const safeDay = clampInt(day, 1, LEGACY_DAILY_LOGIN_REWARD_CYCLE_DAYS);
  return ((safeCycle - 1) * LEGACY_DAILY_LOGIN_REWARD_CYCLE_DAYS) + safeDay;
}

function getLegacyDailyLoginRewardPosition(ordinal = 1) {
  const safeOrdinal = Math.max(1, Math.floor(safeNumber(ordinal, 1)));
  return {
    ordinal: safeOrdinal,
    cycle: Math.floor((safeOrdinal - 1) / LEGACY_DAILY_LOGIN_REWARD_CYCLE_DAYS) + 1,
    day: ((safeOrdinal - 1) % LEGACY_DAILY_LOGIN_REWARD_CYCLE_DAYS) + 1,
  };
}

function getDailyLoginRewardPendingCount(rawState = {}, nowMs = Date.now()) {
  const state = normalizeDailyLoginRewardState(rawState, nowMs);
  return state.nextDay <= state.monthLengthDays
    ? Math.max(0, state.earnedThroughDay - state.nextDay + 1)
    : 0;
}

function normalizeDailyLoginRewardState(raw = {}, nowMs = Date.now()) {
  const month = getDailyLoginRewardMonthInfo(nowMs);
  const sourceVersion = Math.max(0, Math.floor(safeNumber(raw?.schemaVersion, 0)));
  const sourceMonthKey = safeString(raw?.monthKey, 7);
  const totalClaims = Math.max(0, Math.floor(safeNumber(raw?.totalClaims, 0)));
  let nextClaimOrdinal;
  let nextDay;
  let earnedThroughDay;

  if (sourceVersion >= DAILY_LOGIN_REWARD_SCHEMA_VERSION && sourceMonthKey === month.monthKey) {
    nextClaimOrdinal = Math.max(1, Math.floor(safeNumber(raw?.nextClaimOrdinal, totalClaims + 1)));
    nextDay = clampInt(raw?.nextDay, 1, month.monthLengthDays + 1);
    earnedThroughDay = nextDay <= month.monthLengthDays
      ? clampInt(raw?.earnedThroughDay, nextDay - 1, Math.min(
          month.monthLengthDays,
          nextDay + DAILY_LOGIN_REWARD_MAX_PENDING - 1
        ))
      : month.monthLengthDays;
  } else if (sourceVersion >= DAILY_LOGIN_REWARD_SCHEMA_VERSION) {
    nextClaimOrdinal = Math.max(
      totalClaims + 1,
      Math.floor(safeNumber(raw?.nextClaimOrdinal, 1)),
      Math.floor(safeNumber(raw?.earnedThroughOrdinal, 0)) + 1
    ) + 1;
    nextDay = 1;
    earnedThroughDay = 0;
  } else {
    const legacyCycle = Math.max(1, Math.floor(safeNumber(raw?.cycle, 1)));
    const rawLegacyOrdinal = Math.max(
      1,
      Math.floor(safeNumber(raw?.nextClaimOrdinal, getLegacyDailyLoginRewardOrdinal(legacyCycle, raw?.nextDay)))
    );
    const legacyPosition = getLegacyDailyLoginRewardPosition(rawLegacyOrdinal);
    const legacyNextDay = Number(raw?.nextDay) > 0
      ? clampInt(raw.nextDay, 1, LEGACY_DAILY_LOGIN_REWARD_CYCLE_DAYS)
      : legacyPosition.day;
    const legacyEarnedThroughOrdinal = Math.max(
      rawLegacyOrdinal - 1,
      Math.floor(safeNumber(raw?.earnedThroughOrdinal, rawLegacyOrdinal - 1))
    );
    const legacyPendingCount = Math.min(
      DAILY_LOGIN_REWARD_MAX_PENDING,
      Math.max(0, legacyEarnedThroughOrdinal - rawLegacyOrdinal + 1)
    );
    nextClaimOrdinal = rawLegacyOrdinal;
    nextDay = Math.min(month.monthLengthDays + 1, legacyNextDay);
    earnedThroughDay = nextDay <= month.monthLengthDays
      ? Math.min(month.monthLengthDays, nextDay + legacyPendingCount - 1)
      : month.monthLengthDays;
  }

  const pendingCount = nextDay <= month.monthLengthDays
    ? Math.max(0, earnedThroughDay - nextDay + 1)
    : 0;
  const earnedThroughOrdinal = pendingCount > 0
    ? nextClaimOrdinal + pendingCount - 1
    : nextClaimOrdinal - 1;
  const lastClaimDayKey = safeString(raw?.lastClaimDayKey, 10);
  const lastAttendanceDayKey = safeString(
    raw?.lastAttendanceDayKey || (Number(raw?.schemaVersion) < DAILY_LOGIN_REWARD_SCHEMA_VERSION ? lastClaimDayKey : ""),
    10
  );
  const sameMonth = sourceVersion < DAILY_LOGIN_REWARD_SCHEMA_VERSION || sourceMonthKey === month.monthKey;
  const deferredAttendanceDayKey = sameMonth ? safeString(raw?.deferredAttendanceDayKey, 10) : "";
  return {
    schemaVersion: DAILY_LOGIN_REWARD_SCHEMA_VERSION,
    monthKey: month.monthKey,
    monthLengthDays: month.monthLengthDays,
    cycle: 1,
    nextDay,
    earnedThroughDay,
    nextClaimOrdinal,
    earnedThroughOrdinal,
    totalClaims,
    lastAttendanceDayKey: sameMonth && /^\d{4}-\d{2}-\d{2}$/.test(lastAttendanceDayKey)
      ? lastAttendanceDayKey
      : "",
    deferredAttendanceDayKey: /^\d{4}-\d{2}-\d{2}$/.test(deferredAttendanceDayKey)
      ? deferredAttendanceDayKey
      : "",
    lastClaimDayKey: /^\d{4}-\d{2}-\d{2}$/.test(lastClaimDayKey) ? lastClaimDayKey : "",
    lastClaimedAtMs: Math.max(0, timestampToMs(raw?.lastClaimedAtMs || raw?.lastClaimedAt)),
    lastClaimRequestId: safeString(raw?.lastClaimRequestId, 96),
    lastReceipt: normalizeDailyLoginRewardReceipt(raw?.lastReceipt),
  };
}

function createDefaultDailyLoginRewardState(nowMs = Date.now()) {
  return normalizeDailyLoginRewardState({}, nowMs);
}

function syncDailyLoginRewardAttendance(rawState = {}, nowMs = Date.now()) {
  const sourceVersion = Math.max(0, Math.floor(safeNumber(rawState?.schemaVersion, 0)));
  const serverTimeMs = Math.max(0, Math.floor(safeNumber(nowMs, Date.now())));
  const dayKey = getCurrentDateKey(new Date(serverTimeMs));
  const state = normalizeDailyLoginRewardState(rawState, serverTimeMs);
  let changed = sourceVersion !== DAILY_LOGIN_REWARD_SCHEMA_VERSION
    || safeString(rawState?.monthKey, 7) !== state.monthKey
    || Math.floor(safeNumber(rawState?.monthLengthDays, 0)) !== state.monthLengthDays;

  if (state.deferredAttendanceDayKey && state.deferredAttendanceDayKey !== dayKey) {
    state.deferredAttendanceDayKey = "";
    changed = true;
  }

  let pendingCount = getDailyLoginRewardPendingCount(state, serverTimeMs);
  if (state.lastAttendanceDayKey !== dayKey) {
    state.lastAttendanceDayKey = dayKey;
    changed = true;
    if (pendingCount < DAILY_LOGIN_REWARD_MAX_PENDING && state.earnedThroughDay < state.monthLengthDays) {
      state.earnedThroughDay += 1;
      pendingCount += 1;
    } else if (state.earnedThroughDay < state.monthLengthDays) {
      state.deferredAttendanceDayKey = dayKey;
    }
  }

  if (
    state.deferredAttendanceDayKey === dayKey
    && pendingCount < DAILY_LOGIN_REWARD_MAX_PENDING
    && state.earnedThroughDay < state.monthLengthDays
  ) {
    state.earnedThroughDay += 1;
    state.deferredAttendanceDayKey = "";
    changed = true;
  }

  return {
    state: normalizeDailyLoginRewardState(state, serverTimeMs),
    changed,
    dayKey,
    serverTimeMs,
  };
}

function createDailyLoginRewardStatus(rawState = {}, nowMs = Date.now()) {
  const serverTimeMs = Math.max(0, Math.floor(safeNumber(nowMs, Date.now())));
  const state = normalizeDailyLoginRewardState(rawState, serverTimeMs);
  const month = getDailyLoginRewardMonthInfo(serverTimeMs);
  const dayKey = getCurrentDateKey(new Date(serverTimeMs));
  const pendingCount = getDailyLoginRewardPendingCount(state, serverTimeMs);
  const attendedToday = state.lastAttendanceDayKey === dayKey;
  const claimedToday = state.lastClaimDayKey === dayKey;
  return {
    ...state,
    eligible: pendingCount > 0,
    pendingCount,
    queuedCount: Math.max(0, pendingCount - 1),
    maxPendingRewards: DAILY_LOGIN_REWARD_MAX_PENDING,
    attendedToday,
    attendanceDeferred: state.deferredAttendanceDayKey === dayKey,
    claimedToday,
    earnedThroughCycle: 1,
    earnedThroughDay: state.earnedThroughDay,
    dayKey,
    serverTimeMs,
    nextUtcUnlockAtMs: attendedToday ? getNextUtcDayStartMs(serverTimeMs) : 0,
    cycleLengthDays: state.monthLengthDays,
    monthStartsAtMs: month.monthStartsAtMs,
    monthEndsAtMs: month.monthEndsAtMs,
    daysRemaining: month.daysRemaining,
  };
}

function assertCurrentPlayerProfile(profile = {}) {
  if (
    safeString(profile.resetGeneration, 120) !== RESET_GENERATION
    || safeString(profile.worldId, 120) !== ONLINE_WORLD_ID
  ) {
    throw new HttpsError("failed-precondition", "Enter the current Crownlands world before claiming a daily reward.");
  }
}

function normalizeDailyItemPurchaseCounter(value = {}, limit = 0) {
  const safeLimit = Math.max(0, Math.floor(safeNumber(limit, 0)));
  const explicitDate = safeString(value?.utcDate || value?.date, 10);
  if (/^\d{4}-\d{2}-\d{2}$/.test(explicitDate)) {
    return {
      utcDate: explicitDate,
      purchaseCount: Math.min(safeLimit, Math.max(0, Math.floor(safeNumber(value?.purchaseCount ?? value?.count, 0)))),
    };
  }

  const legacyTimestamps = normalizeItemPurchaseTimestamps(value);
  const lastPurchasedAtMs = timestampToMs(value?.lastPurchasedAtMs || value?.lastPurchasedAt);
  if (lastPurchasedAtMs > 0) legacyTimestamps.push(lastPurchasedAtMs);
  if (!legacyTimestamps.length) return { utcDate: "", purchaseCount: 0 };

  const latestPurchaseAtMs = Math.max(...legacyTimestamps);
  const utcDate = getUtcDateKey(latestPurchaseAtMs);
  const purchaseCount = legacyTimestamps.filter(timestamp => getUtcDateKey(timestamp) === utcDate).length;
  return {
    utcDate,
    purchaseCount: Math.min(safeLimit, purchaseCount),
  };
}

function getItemDailyPurchaseLimit(itemId) {
  return Math.max(0, Math.floor(safeNumber(ITEM_DAILY_PURCHASE_LIMITS[itemId], 0)));
}

function normalizeItemPurchaseCooldowns(cooldowns = {}) {
  const normalized = Object.fromEntries(
    Object.keys(ITEM_DAILY_PURCHASE_LIMITS)
      .map(itemId => [itemId, { utcDate: "", purchaseCount: 0 }])
  );
  Object.keys(ITEM_DAILY_PURCHASE_LIMITS).forEach(itemId => {
    normalized[itemId] = normalizeDailyItemPurchaseCounter(
      cooldowns?.[itemId],
      getItemDailyPurchaseLimit(itemId)
    );
  });
  return normalized;
}

function getItemPurchaseStatus(itemId, cooldowns = {}, nowMs = Date.now()) {
  const limit = getItemDailyPurchaseLimit(itemId);
  const currentTime = Math.max(0, safeNumber(nowMs, Date.now()));
  const utcDate = getUtcDateKey(currentTime);
  if (limit <= 0) return { count: 0, limit: 0, remainingMs: 0, utcDate };
  const counter = normalizeDailyItemPurchaseCounter(cooldowns?.[itemId], limit);
  const count = counter.utcDate === utcDate ? Math.min(limit, counter.purchaseCount) : 0;
  return {
    count,
    limit,
    remainingMs: count >= limit ? Math.max(0, getNextUtcDayStartMs(currentTime) - currentTime) : 0,
    utcDate,
  };
}

function formatCooldownMs(ms) {
  const totalSeconds = Math.max(0, Math.ceil(safeNumber(ms, 0) / 1000));
  if (totalSeconds >= 3600) {
    const hours = Math.floor(totalSeconds / 3600);
    const minutes = Math.floor((totalSeconds % 3600) / 60);
    return `${hours}h${minutes > 0 ? ` ${minutes}m` : ""}`;
  }
  if (totalSeconds >= 60) {
    const minutes = Math.floor(totalSeconds / 60);
    const seconds = totalSeconds % 60;
    return `${minutes}m ${seconds}s`;
  }
  return `${totalSeconds}s`;
}

function emptyObjectiveBonuses() {
  return {
    goldBonusPercent: 0,
    troopBonusPercent: 0,
    marchSpeedBonusPercent: 0,
    cityDefenseBonusPercent: 0,
    upgradeCostReductionPercent: 0,
  };
}

function calculateReinforcementFortificationDefense(baseCityWalls = 0, profile = {}) {
  const normalizedBaseCityWalls = Math.max(0, Math.floor(safeNumber(baseCityWalls, 0)));
  const cityWallSharePercent = REINFORCEMENT_CITY_WALL_SHARE * 100;
  const cityWallDefense = Math.floor(normalizedBaseCityWalls * REINFORCEMENT_CITY_WALL_SHARE);
  const stoneworksPercent = Math.max(0, getSkillPercent(profile, "stoneworks"));
  const stoneworksBonus = Math.floor(normalizedBaseCityWalls * stoneworksPercent / 100);
  return {
    baseCityWalls: normalizedBaseCityWalls,
    cityWallSharePercent,
    cityWallDefense,
    stoneworksPercent,
    stoneworksBonus,
    totalDefense: cityWallDefense + stoneworksBonus,
  };
}

function calculateDefenderArmyPackages({
  target = {},
  targetType = "city",
  ownerProfile = {},
  ownerBonuses = {},
  contributions = [],
  contributorProfiles = new Map(),
  contributorStats = new Map(),
  siegeCombatVersion = 0,
  defenseCombatVersion = DEFENSE_COMBAT_VERSION,
  nowMs = Date.now(),
} = {}) {
  const rewardCamp = targetType === "camp";
  const siegeEnabled = usesSiegeCombat(siegeCombatVersion, targetType);
  const soldierDefenseEnabled = siegeEnabled
    && usesSoldierDefenseModel(defenseCombatVersion, target);
  const ownerTroops = getTargetOwnerTroops(target, targetType);
  const ownerTarget = {
    ...target,
    troops: ownerTroops,
    troopFloat: ownerTroops,
    alliedReinforcementTroops: 0,
  };
  const ownerStats = getCityStats(ownerTarget, ownerProfile, ownerBonuses, {
    defenseCombatVersion: soldierDefenseEnabled ? DEFENSE_COMBAT_VERSION : 0,
  });
  const fortification = siegeEnabled ? getFortificationSnapshot(target, ownerStats, nowMs) : null;
  const ownerBasePower = siegeEnabled
    ? Math.max(0, Math.floor(safeNumber(
      soldierDefenseEnabled ? ownerStats.baseTroopDefense : ownerStats.troopDefense,
      0
    )))
    : Math.max(0, ownerStats.totalDefense - ownerStats.strongholdDefenseBonus);
  const ownerEffectivePower = siegeEnabled
    ? soldierDefenseEnabled
      ? Math.max(0, Math.floor(safeNumber(ownerStats.troopDefenseBeforeGear, ownerStats.troopDefense)))
      : Math.max(0, Math.floor(ownerBasePower * (1 + ownerStats.strongholdDefenseBonusPercent / 100)))
    : Math.max(0, Math.floor(safeNumber(ownerStats.totalDefense, 0)));
  const ownerPackage = {
    ownerUid: safeString(getOwnerUid(target), 128),
    ownerName: normalizePlayerName(getOwnerName(target) || ownerProfile.playerName, "Neutral defenders"),
    ownerFlag: ownerProfile.flag || target.ownerFlag || null,
    troops: ownerTroops,
    basePower: ownerBasePower,
    bonusPercent: getObjectiveTroopDefenseBonusPercent(ownerStats),
    effectivePower: ownerEffectivePower,
    defenseCombatVersion: soldierDefenseEnabled ? DEFENSE_COMBAT_VERSION : 0,
    baseDefensePowerPerTroop: soldierDefenseEnabled ? BASE_TROOP_DEFENSE_POWER : 1,
    shieldwallDisciplineLevel: Math.max(0, Math.floor(safeNumber(ownerStats.shieldwallDisciplineLevel, 0))),
    shieldwallDisciplinePercent: Math.max(0, safeNumber(ownerStats.shieldwallDisciplinePercent, 0)),
    gearDefenderStrengthPercent: Math.max(0, safeNumber(ownerStats.gearDefenderStrengthPercent, 0)),
    gearDefenderStrengthBonusPower: 0,
    personalBonusPercent: rewardCamp ? 0 : Math.max(0, safeNumber(
      ownerBonuses.personalDefenseBonusPercent,
      getObjectiveTroopDefenseBonusPercent(ownerStats)
    )),
    sharedBonusPercent: rewardCamp ? 0 : Math.max(0, safeNumber(ownerBonuses.sharedDefenseBonusPercent, 0)),
    objectiveSource: rewardCamp ? "" : safeString(ownerBonuses.objectiveSource || ownerBonuses.source, 48),
    cityLevelDefensePercent: Math.max(0, safeNumber(ownerStats.defensePercent, 0)),
    baseCityWalls: Math.max(0, Math.floor(safeNumber(ownerStats.baseCityWalls, 0))),
    cityWalls: Math.max(0, Math.floor(safeNumber(ownerStats.cityWalls, 0))),
    stoneworksPercent: Math.max(0, safeNumber(ownerStats.stoneworksPercent, 0)),
    gearWallStrengthPercent: Math.max(0, safeNumber(ownerStats.gearWallStrengthPercent, 0)),
  };
  const destinationGearDefenderStrengthPercent = rewardCamp
    ? 0
    : Math.max(0, safeNumber(ownerStats.gearDefenderStrengthPercent, 0));
  const reinforcementPackages = (Array.isArray(contributions) ? contributions : []).map(contribution => {
    const profile = contributorProfiles.get(contribution.ownerUid) || {};
    const stats = contributorStats.get(contribution.ownerUid) || {};
    const troops = Math.max(0, Math.floor(safeNumber(contribution.troops, 0)));
    const bonusPercent = rewardCamp ? 0 : getObjectiveTroopDefenseBonusPercent(stats);
    const shieldwallDisciplineLevel = soldierDefenseEnabled
      ? getSkillLevel(profile, "shieldwallDiscipline")
      : 0;
    const shieldwallDisciplinePercent = soldierDefenseEnabled
      ? getSkillPercent(profile, "shieldwallDiscipline")
      : 0;
    const fortifications = rewardCamp || siegeEnabled
      ? {
        baseCityWalls: Math.max(0, Math.floor(safeNumber(ownerStats.baseCityWalls, 0))),
        cityWallSharePercent: 0,
        cityWallDefense: 0,
        stoneworksPercent: 0,
        stoneworksBonus: 0,
        totalDefense: 0,
      }
      : calculateReinforcementFortificationDefense(ownerStats.baseCityWalls, profile);
    const basePower = rewardCamp
      ? Math.floor(troops * REWARD_CAMP_TROOP_POWER)
      : soldierDefenseEnabled
        ? Math.floor(troops * BASE_TROOP_DEFENSE_POWER)
        : troops + fortifications.totalDefense;
    const effectivePower = rewardCamp
      ? basePower
      : soldierDefenseEnabled
        ? Math.floor(troops * BASE_TROOP_DEFENSE_POWER * (
          1 + (shieldwallDisciplinePercent + bonusPercent) / 100
        ))
        : Math.floor(basePower * (1 + bonusPercent / 100));
    return {
      reinforcementId: contribution.id,
      ownerUid: safeString(contribution.ownerUid, 128),
      ownerName: normalizePlayerName(profile.playerName || contribution.ownerName, "Ruler"),
      ownerFlag: profile.flag || contribution.ownerFlag || null,
      troops,
      basePower,
      bonusPercent,
      defenseCombatVersion: soldierDefenseEnabled ? DEFENSE_COMBAT_VERSION : 0,
      baseDefensePowerPerTroop: soldierDefenseEnabled ? BASE_TROOP_DEFENSE_POWER : 1,
      shieldwallDisciplineLevel,
      shieldwallDisciplinePercent,
      gearDefenderStrengthPercent: destinationGearDefenderStrengthPercent,
      gearDefenderStrengthBonusPower: 0,
      personalBonusPercent: rewardCamp ? 0 : Math.max(0, safeNumber(
        stats.personalObjectiveTroopDefenseBonusPercent,
        safeNumber(stats.personalStrongholdDefenseBonusPercent, bonusPercent)
      )),
      sharedBonusPercent: rewardCamp ? 0 : Math.max(0, safeNumber(
        stats.sharedClanObjectiveTroopDefenseBonusPercent,
        stats.sharedClanDefenseBonusPercent
      )),
      objectiveSource: rewardCamp ? "" : safeString(stats.strongholdBonusSource, 48),
      baseCityWalls: fortifications.baseCityWalls,
      cityWallSharePercent: fortifications.cityWallSharePercent,
      cityWallDefense: fortifications.cityWallDefense,
      stoneworksPercent: fortifications.stoneworksPercent,
      stoneworksBonus: fortifications.stoneworksBonus,
      fortificationPower: fortifications.totalDefense,
      effectivePower: Math.max(0, effectivePower),
    };
  }).filter(row => row.ownerUid && row.troops > 0);
  const defenderRows = [ownerPackage, ...reinforcementPackages].filter(row => row.troops > 0);
  const totalDefenderTroops = defenderRows.reduce((total, row) => total + row.troops, 0);
  const totalGearDefenderStrengthBonusPower = soldierDefenseEnabled && totalDefenderTroops > 0
    ? Math.floor(
      totalDefenderTroops * BASE_TROOP_DEFENSE_POWER * destinationGearDefenderStrengthPercent / 100
    )
    : 0;
  let remainingGearDefenderStrengthBonusPower = totalGearDefenderStrengthBonusPower;
  defenderRows.forEach((row, index) => {
    const bonusPower = index === defenderRows.length - 1
      ? remainingGearDefenderStrengthBonusPower
      : Math.floor(totalGearDefenderStrengthBonusPower * row.troops / totalDefenderTroops);
    row.gearDefenderStrengthBonusPower = Math.max(0, bonusPower);
    row.effectivePower += row.gearDefenderStrengthBonusPower;
    remainingGearDefenderStrengthBonusPower -= row.gearDefenderStrengthBonusPower;
  });
  const totalGarrisonDefense = Math.max(
    0,
    ownerPackage.effectivePower
      + reinforcementPackages.reduce((total, row) => total + row.effectivePower, 0)
  );
  const resolvedFortification = fortification ? {
    ...fortification,
    defenseCombatVersion: soldierDefenseEnabled ? DEFENSE_COMBAT_VERSION : 0,
    baseDefensePowerPerTroop: soldierDefenseEnabled ? BASE_TROOP_DEFENSE_POWER : 1,
    shieldwallDisciplinePercent: ownerPackage.shieldwallDisciplinePercent,
    troopObjectiveDefenseBonusPercent: ownerPackage.bonusPercent,
    garrisonDefensePower: totalGarrisonDefense,
    ownerGarrisonDefensePower: ownerPackage.effectivePower,
    reinforcementGarrisonDefensePower: reinforcementPackages.reduce(
      (total, row) => total + row.effectivePower,
      0
    ),
  } : null;
  return {
    siegeCombatVersion: siegeEnabled ? SIEGE_COMBAT_VERSION : 0,
    defenseCombatVersion: soldierDefenseEnabled ? DEFENSE_COMBAT_VERSION : 0,
    owner: ownerPackage,
    reinforcements: reinforcementPackages,
    fortification: resolvedFortification,
    totalGarrisonDefense,
    totalDefense: Math.max(
      0,
      totalGarrisonDefense + (resolvedFortification?.currentWallPower || 0)
    ),
  };
}

function normalizeObjectiveBonuses(value = {}) {
  return {
    goldBonusPercent: Math.max(0, safeNumber(value.goldBonusPercent, 0)),
    troopBonusPercent: Math.max(0, safeNumber(value.troopBonusPercent, 0)),
    marchSpeedBonusPercent: Math.max(0, safeNumber(value.marchSpeedBonusPercent, 0)),
    cityDefenseBonusPercent: Math.max(0, safeNumber(value.cityDefenseBonusPercent, 0)),
    upgradeCostReductionPercent: Math.max(0, safeNumber(value.upgradeCostReductionPercent, 0)),
  };
}

function addObjectiveBonuses(left = {}, right = {}) {
  const first = normalizeObjectiveBonuses(left);
  const second = normalizeObjectiveBonuses(right);
  return {
    goldBonusPercent: first.goldBonusPercent + second.goldBonusPercent,
    troopBonusPercent: first.troopBonusPercent + second.troopBonusPercent,
    marchSpeedBonusPercent: first.marchSpeedBonusPercent + second.marchSpeedBonusPercent,
    cityDefenseBonusPercent: first.cityDefenseBonusPercent + second.cityDefenseBonusPercent,
    upgradeCostReductionPercent: first.upgradeCostReductionPercent + second.upgradeCostReductionPercent,
  };
}

function subtractObjectiveBonuses(left = {}, right = {}) {
  const first = normalizeObjectiveBonuses(left);
  const second = normalizeObjectiveBonuses(right);
  return {
    goldBonusPercent: Math.max(0, first.goldBonusPercent - second.goldBonusPercent),
    troopBonusPercent: Math.max(0, first.troopBonusPercent - second.troopBonusPercent),
    marchSpeedBonusPercent: Math.max(0, first.marchSpeedBonusPercent - second.marchSpeedBonusPercent),
    cityDefenseBonusPercent: Math.max(0, first.cityDefenseBonusPercent - second.cityDefenseBonusPercent),
    upgradeCostReductionPercent: Math.max(0, first.upgradeCostReductionPercent - second.upgradeCostReductionPercent),
  };
}

function scaleObjectiveBonuses(value = {}, multiplier = 1) {
  const bonuses = normalizeObjectiveBonuses(value);
  const scale = Math.max(0, safeNumber(multiplier, 0));
  return {
    goldBonusPercent: bonuses.goldBonusPercent * scale,
    troopBonusPercent: bonuses.troopBonusPercent * scale,
    marchSpeedBonusPercent: bonuses.marchSpeedBonusPercent * scale,
    cityDefenseBonusPercent: bonuses.cityDefenseBonusPercent * scale,
    upgradeCostReductionPercent: bonuses.upgradeCostReductionPercent * scale,
  };
}

function objectiveBonusForCity(city = {}, multiplier = 1) {
  const scale = Math.max(0, safeNumber(multiplier, 0));
  if (isCrownCitadel(city)) {
    return {
      goldBonusPercent: CROWN_CITADEL_GOLD_BONUS_PERCENT * scale,
      troopBonusPercent: CROWN_CITADEL_TROOP_BONUS_PERCENT * scale,
      marchSpeedBonusPercent: CROWN_CITADEL_MARCH_SPEED_BONUS_PERCENT * scale,
      cityDefenseBonusPercent: CROWN_CITADEL_DEFENSE_BONUS_PERCENT * scale,
      upgradeCostReductionPercent: CROWN_CITADEL_UPGRADE_COST_REDUCTION_PERCENT * scale,
    };
  }
  const bonuses = emptyObjectiveBonuses();
  if (isGoldStronghold(city)) bonuses.goldBonusPercent += getStrongholdBonusPercent(city) * scale;
  if (isTrainingStronghold(city)) bonuses.troopBonusPercent += getStrongholdBonusPercent(city) * scale;
  if (isSpeedStronghold(city)) bonuses.marchSpeedBonusPercent += getStrongholdBonusPercent(city) * scale;
  if (isDefenseStronghold(city)) bonuses.cityDefenseBonusPercent += getStrongholdBonusPercent(city) * scale;
  return bonuses;
}

function getOwnedStrongholdBonuses(cities = []) {
  const ownedCities = (Array.isArray(cities) ? cities : []).map(entry => entry?.city || entry).filter(Boolean);
  const ownsCrownCitadel = ownedCities.some(isCrownCitadel);
  if (ownsCrownCitadel) {
    return {
      source: "crown_citadel",
      crownCitadelControlled: true,
      goldBonusPercent: CROWN_CITADEL_GOLD_BONUS_PERCENT,
      troopBonusPercent: CROWN_CITADEL_TROOP_BONUS_PERCENT,
      marchSpeedBonusPercent: CROWN_CITADEL_MARCH_SPEED_BONUS_PERCENT,
      cityDefenseBonusPercent: CROWN_CITADEL_DEFENSE_BONUS_PERCENT,
      upgradeCostReductionPercent: CROWN_CITADEL_UPGRADE_COST_REDUCTION_PERCENT,
      personalGoldBonusPercent: CROWN_CITADEL_GOLD_BONUS_PERCENT,
      personalTroopBonusPercent: CROWN_CITADEL_TROOP_BONUS_PERCENT,
      personalMarchSpeedBonusPercent: CROWN_CITADEL_MARCH_SPEED_BONUS_PERCENT,
      personalDefenseBonusPercent: CROWN_CITADEL_DEFENSE_BONUS_PERCENT,
      personalUpgradeCostReductionPercent: CROWN_CITADEL_UPGRADE_COST_REDUCTION_PERCENT,
      sharedGoldBonusPercent: 0,
      sharedTroopBonusPercent: 0,
      sharedMarchSpeedBonusPercent: 0,
      sharedDefenseBonusPercent: 0,
      sharedUpgradeCostReductionPercent: 0,
      clanCitadelBonusPercent: 0,
      clanObjectiveBenefitRevision: 0,
    };
  }
  return cities.reduce((bonuses, entry) => {
    const city = entry?.city || entry;
    if (!city) return bonuses;
    if (isGoldStronghold(city)) bonuses.goldBonusPercent += getStrongholdBonusPercent(city);
    if (isTrainingStronghold(city)) bonuses.troopBonusPercent += getStrongholdBonusPercent(city);
    if (isSpeedStronghold(city)) bonuses.marchSpeedBonusPercent += getStrongholdBonusPercent(city);
    if (isDefenseStronghold(city)) bonuses.cityDefenseBonusPercent += getStrongholdBonusPercent(city);
    bonuses.personalGoldBonusPercent = bonuses.goldBonusPercent;
    bonuses.personalTroopBonusPercent = bonuses.troopBonusPercent;
    bonuses.personalMarchSpeedBonusPercent = bonuses.marchSpeedBonusPercent;
    bonuses.personalDefenseBonusPercent = bonuses.cityDefenseBonusPercent;
    return bonuses;
  }, {
    source: "individual",
    crownCitadelControlled: false,
    goldBonusPercent: 0,
    troopBonusPercent: 0,
    marchSpeedBonusPercent: 0,
    cityDefenseBonusPercent: 0,
    upgradeCostReductionPercent: 0,
    personalGoldBonusPercent: 0,
    personalTroopBonusPercent: 0,
    personalMarchSpeedBonusPercent: 0,
    personalDefenseBonusPercent: 0,
    personalUpgradeCostReductionPercent: 0,
    sharedGoldBonusPercent: 0,
    sharedTroopBonusPercent: 0,
    sharedMarchSpeedBonusPercent: 0,
    sharedDefenseBonusPercent: 0,
    sharedUpgradeCostReductionPercent: 0,
    clanCitadelBonusPercent: 0,
    clanObjectiveBenefitRevision: 0,
  });
}

function getLiveClanBenefitIntegrals(benefits = {}, nowMs = Date.now()) {
  const lastIntegratedAtMs = Math.max(0, timestampToMs(benefits.lastIntegratedAtMs));
  const elapsedMs = Math.max(0, nowMs - lastIntegratedAtMs);
  const shared = normalizeObjectiveBonuses(benefits.sharedBonuses);
  return {
    goldPercentMs: Math.max(0, safeNumber(benefits.cumulativeGoldPercentMs, 0))
      + shared.goldBonusPercent * elapsedMs,
    troopPercentMs: Math.max(0, safeNumber(benefits.cumulativeTroopPercentMs, 0))
      + shared.troopBonusPercent * elapsedMs,
    atMs: nowMs,
  };
}

function clanBenefitAccrualBaseline(benefits = {}, clanId = "", nowMs = Date.now()) {
  const integrals = getLiveClanBenefitIntegrals(benefits, nowMs);
  return {
    modelVersion: CLAN_OBJECTIVE_BENEFIT_MODEL_VERSION,
    resetGeneration: RESET_GENERATION,
    clanId: safeString(clanId, 128),
    goldPercentMs: integrals.goldPercentMs,
    troopPercentMs: integrals.troopPercentMs,
    checkpointAtMs: nowMs,
  };
}

function buildClanBenefitExitPatch(profile = {}, benefits = {}, clanId = "", nowMs = Date.now()) {
  const live = getLiveClanBenefitIntegrals(benefits, nowMs);
  const accrual = profile.clanObjectiveAccrual && typeof profile.clanObjectiveAccrual === "object"
    ? profile.clanObjectiveAccrual
    : {};
  const matching = safeString(accrual.clanId, 128) === safeString(clanId, 128)
    && safeString(accrual.resetGeneration, 120) === RESET_GENERATION;
  const pending = profile.pendingClanObjectiveAccrual && typeof profile.pendingClanObjectiveAccrual === "object"
    ? profile.pendingClanObjectiveAccrual
    : {};
  return {
    clanObjectiveAccrual: FieldValue.delete(),
    pendingClanObjectiveAccrual: {
      resetGeneration: RESET_GENERATION,
      goldPercentMs: Math.max(0, safeNumber(pending.goldPercentMs, 0))
        + (matching ? Math.max(0, live.goldPercentMs - safeNumber(accrual.goldPercentMs, live.goldPercentMs)) : 0),
      troopPercentMs: Math.max(0, safeNumber(pending.troopPercentMs, 0))
        + (matching ? Math.max(0, live.troopPercentMs - safeNumber(accrual.troopPercentMs, live.troopPercentMs)) : 0),
      citadelControllerUid: safeString(benefits.citadelControllerUid, 128),
      endedAtMs: nowMs,
    },
  };
}

function combinePlayerObjectiveBonuses(uid = "", ownedEntries = [], benefits = null) {
  const playerUid = safeString(uid, 128);
  const ownedCities = (Array.isArray(ownedEntries) ? ownedEntries : [])
    .map(entry => entry?.city || entry)
    .filter(city => city && isStronghold(city));
  if (!benefits || safeString(benefits.resetGeneration, 120) !== RESET_GENERATION) {
    return getOwnedStrongholdBonuses(ownedEntries);
  }

  const clanCitadelControllerUid = safeString(benefits.citadelControllerUid, 128);
  const ownsClanCitadel = Boolean(clanCitadelControllerUid && clanCitadelControllerUid === playerUid);
  const nonCitadelOwned = ownedCities.filter(city => !isCrownCitadel(city));
  const fullPersonalStrongholds = nonCitadelOwned.reduce(
    (bonuses, city) => addObjectiveBonuses(bonuses, objectiveBonusForCity(city)),
    emptyObjectiveBonuses()
  );
  const halfPersonalStrongholds = scaleObjectiveBonuses(fullPersonalStrongholds, CLAN_SHARED_OBJECTIVE_MULTIPLIER);
  const citadelPersonal = ownsClanCitadel
    ? objectiveBonusForCity(ownedCities.find(isCrownCitadel) || { id: CROWN_CITADEL_ID, kind: "stronghold", strongholdType: "crown_citadel" })
    : emptyObjectiveBonuses();
  const personal = ownsClanCitadel
    ? addObjectiveBonuses(citadelPersonal, halfPersonalStrongholds)
    : fullPersonalStrongholds;
  const rawShared = normalizeObjectiveBonuses(benefits.sharedBonuses);
  const shared = ownsClanCitadel
    ? emptyObjectiveBonuses()
    : clanCitadelControllerUid
      ? rawShared
      : subtractObjectiveBonuses(rawShared, halfPersonalStrongholds);
  const total = addObjectiveBonuses(personal, shared);
  return {
    source: clanCitadelControllerUid ? "clan_crown_citadel" : "clan_objectives",
    crownCitadelControlled: ownsClanCitadel,
    ...total,
    personalGoldBonusPercent: personal.goldBonusPercent,
    personalTroopBonusPercent: personal.troopBonusPercent,
    personalMarchSpeedBonusPercent: personal.marchSpeedBonusPercent,
    personalDefenseBonusPercent: personal.cityDefenseBonusPercent,
    personalUpgradeCostReductionPercent: personal.upgradeCostReductionPercent,
    sharedGoldBonusPercent: shared.goldBonusPercent,
    sharedTroopBonusPercent: shared.troopBonusPercent,
    sharedMarchSpeedBonusPercent: shared.marchSpeedBonusPercent,
    sharedDefenseBonusPercent: shared.cityDefenseBonusPercent,
    sharedUpgradeCostReductionPercent: shared.upgradeCostReductionPercent,
    clanCitadelBonusPercent: clanCitadelControllerUid
      ? ownsClanCitadel ? CROWN_CITADEL_GOLD_BONUS_PERCENT : CROWN_CITADEL_GOLD_BONUS_PERCENT * CLAN_SHARED_OBJECTIVE_MULTIPLIER
      : 0,
    clanObjectiveBenefitRevision: Math.max(0, Math.floor(safeNumber(benefits.revision, 0))),
  };
}

async function resolvePlayerObjectiveBenefits(
  transaction,
  uid = "",
  profile = {},
  ownedEntries = [],
  nowMs = Date.now(),
  elapsedMs = 0
) {
  const clanId = safeString(profile.clanId, 128);
  const pending = safeString(profile.pendingClanObjectiveAccrual?.resetGeneration, 120) === RESET_GENERATION
    ? profile.pendingClanObjectiveAccrual
    : {};
  const pendingGoldPercentMs = Math.max(0, safeNumber(pending.goldPercentMs, 0));
  const pendingTroopPercentMs = Math.max(0, safeNumber(pending.troopPercentMs, 0));
  const benefitsRef = clanWorldBenefitsRef(clanId);
  const benefitsSnap = benefitsRef ? await transaction.get(benefitsRef) : null;
  const benefits = benefitsSnap?.exists ? benefitsSnap.data() || {} : null;
  const currentBonuses = combinePlayerObjectiveBonuses(uid, ownedEntries, benefits);
  let accruedGoldPercentMs = pendingGoldPercentMs;
  let accruedTroopPercentMs = pendingTroopPercentMs;
  let nextAccrual = FieldValue.delete();

  if (clanId && benefits && benefits.status !== "inactive") {
    const live = getLiveClanBenefitIntegrals(benefits, nowMs);
    const accrual = profile.clanObjectiveAccrual && typeof profile.clanObjectiveAccrual === "object"
      ? profile.clanObjectiveAccrual
      : {};
    const matching = safeString(accrual.clanId, 128) === clanId
      && safeString(accrual.resetGeneration, 120) === RESET_GENERATION;
    const baselineGold = matching ? safeNumber(accrual.goldPercentMs, live.goldPercentMs) : live.goldPercentMs;
    const baselineTroops = matching ? safeNumber(accrual.troopPercentMs, live.troopPercentMs) : live.troopPercentMs;
    accruedGoldPercentMs += Math.max(0, live.goldPercentMs - baselineGold);
    accruedTroopPercentMs += Math.max(0, live.troopPercentMs - baselineTroops);
    nextAccrual = clanBenefitAccrualBaseline(benefits, clanId, nowMs);
  }

  const boundedElapsedMs = Math.max(1, safeNumber(elapsedMs, 0));
  const rawAverageSharedGold = accruedGoldPercentMs / boundedElapsedMs;
  const rawAverageSharedTroops = accruedTroopPercentMs / boundedElapsedMs;
  const citadelControllerUid = safeString(
    benefits?.citadelControllerUid || pending.citadelControllerUid,
    128
  );
  const ownsClanCitadel = Boolean(citadelControllerUid && citadelControllerUid === safeString(uid, 128));
  const averageSharedGold = ownsClanCitadel
    ? 0
    : citadelControllerUid
      ? rawAverageSharedGold
      : Math.max(
        0,
        rawAverageSharedGold
          - safeNumber(currentBonuses.personalGoldBonusPercent, 0) * CLAN_SHARED_OBJECTIVE_MULTIPLIER
      );
  const averageSharedTroops = ownsClanCitadel
    ? 0
    : citadelControllerUid
      ? rawAverageSharedTroops
      : Math.max(
        0,
        rawAverageSharedTroops
          - safeNumber(currentBonuses.personalTroopBonusPercent, 0) * CLAN_SHARED_OBJECTIVE_MULTIPLIER
      );
  const productionBonuses = {
    ...currentBonuses,
    goldBonusPercent: Math.max(0, safeNumber(currentBonuses.personalGoldBonusPercent, currentBonuses.goldBonusPercent))
      + averageSharedGold,
    troopBonusPercent: Math.max(0, safeNumber(currentBonuses.personalTroopBonusPercent, currentBonuses.troopBonusPercent))
      + averageSharedTroops,
  };

  return {
    currentBonuses,
    productionBonuses,
    profilePatch: {
      clanObjectiveAccrual: nextAccrual,
      pendingClanObjectiveAccrual: FieldValue.delete(),
    },
  };
}

function buildClanSharedObjectiveBonuses(objectives = []) {
  const citadel = objectives.find(objective => isCrownCitadel(objective));
  if (citadel) {
    return {
      sharedBonuses: objectiveBonusForCity(citadel, CLAN_SHARED_OBJECTIVE_MULTIPLIER),
      citadelControllerUid: safeString(citadel.ownerUid, 128),
    };
  }
  return {
    sharedBonuses: objectives.reduce(
      (bonuses, objective) => addObjectiveBonuses(
        bonuses,
        objectiveBonusForCity(objective, CLAN_SHARED_OBJECTIVE_MULTIPLIER)
      ),
      emptyObjectiveBonuses()
    ),
    citadelControllerUid: "",
  };
}

async function rebuildClanWorldBenefits(clanId = "", effectiveAtMs = Date.now()) {
  const safeClanId = safeString(clanId, 128);
  const benefitsRef = clanWorldBenefitsRef(safeClanId);
  if (!safeClanId || !benefitsRef) return null;
  const clanSnap = await db.doc(`clans/${safeClanId}`).get();
  const clan = clanSnap.exists ? clanSnap.data() || {} : {};
  const objectiveRefs = SERVER_WORLD_OBJECTIVE_TARGETS.map(objective => cityRefForRegion(objective.regionId, objective.id));
  const objectiveSnaps = objectiveRefs.length ? await db.getAll(...objectiveRefs) : [];
  const ownerUids = [...new Set(objectiveSnaps
    .filter(snapshot => snapshot.exists)
    .map(snapshot => safeString(snapshot.data()?.ownerUid, 128))
    .filter(Boolean))];
  const ownerProfileRefs = ownerUids.map(uid => db.doc(`players/${uid}`));
  const ownerProfileSnaps = ownerProfileRefs.length ? await db.getAll(...ownerProfileRefs) : [];
  const ownerClanByUid = new Map(ownerProfileSnaps.map(snapshot => [
    snapshot.id,
    safeString(snapshot.data()?.clanId, 128),
  ]));
  const controlledObjectives = objectiveSnaps.map(snapshot => {
    if (!snapshot.exists) return null;
    const city = { id: snapshot.id, ...snapshot.data() };
    const ownerUid = safeString(city.ownerUid, 128);
    if (!ownerUid || ownerClanByUid.get(ownerUid) !== safeClanId || !isStronghold(city)) return null;
    return {
      id: city.id,
      regionId: normalizeRegionId(city.regionId || getRegionIdFromOnlineIslandId(snapshot.ref.parent?.parent?.id)),
      strongholdType: safeString(city.strongholdType, 32),
      ownerUid,
      ownerName: normalizePlayerName(city.ownerName || ownerUid, "Ruler"),
      bonusPercent: getStrongholdBonusPercent(city),
      ...city,
    };
  }).filter(Boolean);
  const next = buildClanSharedObjectiveBonuses(controlledObjectives);
  const normalizedEffectiveAtMs = Math.max(0, Math.floor(safeNumber(effectiveAtMs, Date.now())));

  return runTransactionWithInfrastructureRetry(async transaction => {
    const priorSnap = await transaction.get(benefitsRef);
    const prior = priorSnap.exists ? priorSnap.data() || {} : {};
    const priorLastAtMs = Math.max(0, timestampToMs(prior.lastIntegratedAtMs));
    const integrationAtMs = Math.max(priorLastAtMs, normalizedEffectiveAtMs);
    const priorShared = normalizeObjectiveBonuses(prior.sharedBonuses);
    const integrationElapsedMs = Math.max(0, integrationAtMs - priorLastAtMs);
    const status = clanSnap.exists && clan.status === "active" ? "active" : "inactive";
    const data = {
      clanId: safeClanId,
      worldId: ONLINE_WORLD_ID,
      resetGeneration: RESET_GENERATION,
      modelVersion: CLAN_OBJECTIVE_BENEFIT_MODEL_VERSION,
      status,
      objectives: status === "active" ? controlledObjectives.map(objective => ({
        id: objective.id,
        regionId: objective.regionId,
        strongholdType: objective.strongholdType,
        ownerUid: objective.ownerUid,
        ownerName: objective.ownerName,
        bonusPercent: objective.bonusPercent,
      })) : [],
      sharedBonuses: status === "active" ? next.sharedBonuses : emptyObjectiveBonuses(),
      citadelControllerUid: status === "active" ? next.citadelControllerUid : "",
      cumulativeGoldPercentMs: Math.max(0, safeNumber(prior.cumulativeGoldPercentMs, 0))
        + priorShared.goldBonusPercent * integrationElapsedMs,
      cumulativeTroopPercentMs: Math.max(0, safeNumber(prior.cumulativeTroopPercentMs, 0))
        + priorShared.troopBonusPercent * integrationElapsedMs,
      lastIntegratedAtMs: integrationAtMs,
      effectiveAtMs: normalizedEffectiveAtMs,
      revision: Math.max(0, Math.floor(safeNumber(prior.revision, 0))) + 1,
      updatedAtMs: Date.now(),
      updatedAt: FieldValue.serverTimestamp(),
      ...(priorSnap.exists ? {} : {
        createdAtMs: normalizedEffectiveAtMs,
        createdAt: FieldValue.serverTimestamp(),
      }),
    };
    transaction.set(benefitsRef, data, { merge: true });
    return data;
  });
}

async function rebuildClanBenefitsAndMemberStats(clanId = "", effectiveAtMs = Date.now()) {
  const safeClanId = safeString(clanId, 128);
  if (!safeClanId) return { clanId: "", membersUpdated: 0 };
  const benefits = await rebuildClanWorldBenefits(safeClanId, effectiveAtMs);
  const membersSnap = await db.collection(`clans/${safeClanId}/members`).get();
  let membersUpdated = 0;
  await processWithConcurrency(membersSnap.docs, 4, async memberDoc => {
    await rebuildGlobalStatsForPlayer(memberDoc.id);
    membersUpdated += 1;
  });
  return { clanId: safeClanId, benefits, membersUpdated };
}

function getCityUpgradeTargetHours(currentLevel) {
  const level = clampCityLevel(currentLevel);
  if (level <= CITY_UPGRADE_EARLY_END_LEVEL) {
    const progress = (level - 1) / Math.max(1, CITY_UPGRADE_EARLY_END_LEVEL - 1);
    return CITY_UPGRADE_EARLY_START_HOURS
      + (CITY_UPGRADE_EARLY_END_HOURS - CITY_UPGRADE_EARLY_START_HOURS)
        * Math.pow(progress, 1.35);
  }
  if (level <= CITY_UPGRADE_MID_END_LEVEL) {
    const progress = (level - CITY_UPGRADE_EARLY_END_LEVEL)
      / (CITY_UPGRADE_MID_END_LEVEL - CITY_UPGRADE_EARLY_END_LEVEL);
    return CITY_UPGRADE_EARLY_END_HOURS
      + (CITY_UPGRADE_MID_END_HOURS - CITY_UPGRADE_EARLY_END_HOURS)
        * Math.pow(progress, 1.4);
  }
  const endgameProgress = (level - CITY_UPGRADE_MID_END_LEVEL)
    / Math.max(1, 150 - CITY_UPGRADE_MID_END_LEVEL);
  return Math.min(
    CITY_UPGRADE_MAX_TARGET_HOURS,
    CITY_UPGRADE_MID_END_HOURS
      + (CITY_UPGRADE_END_LEVEL_150_HOURS - CITY_UPGRADE_MID_END_HOURS)
        * Math.pow(endgameProgress, 1.5)
  );
}

function getCityUpgradeCost(city = {}, bonuses = {}) {
  if (isStronghold(city)) return Infinity;
  const startLevel = clampCityLevel(city.level);
  const targetLevel = startLevel + 1;
  if (!Number.isSafeInteger(targetLevel)) return Infinity;
  const totalCost = getMillionLordsPassiveGoldPerHour(startLevel)
    * getCityUpgradeTargetHours(startLevel);
  if (!Number.isFinite(totalCost)) return Infinity;
  const reduction = Math.max(0, safeNumber(bonuses.upgradeCostReductionPercent, 0));
  return Math.max(10, Math.floor(totalCost * (1 - Math.min(85, reduction) / 100) + 0.000001));
}

function getEconomyCityByRef(economy = null, ref = null) {
  if (!economy || !ref) return null;
  return economy.cityEntries.find(entry => entry.ref.path === ref.path) || null;
}

function appendEconomyCityPatch(economy = null, ref = null, city = {}, patch = {}) {
  if (!economy || !ref || !patch || typeof patch !== "object") return false;
  economy.cityPatches.push({ ref, city, patch });
  const entry = getEconomyCityByRef(economy, ref);
  if (entry?.city) entry.city = { ...entry.city, ...patch };
  return true;
}

function creditLevelUpTroopsToMainCity(economy = null, profile = {}, troopReward = 0, nowMs = Date.now()) {
  const credited = Math.max(0, Math.floor(safeNumber(troopReward, 0)));
  if (!economy?.uid || credited <= 0) return null;
  const mainEntry = getCanonicalMainCityEntry(profile, economy.cityEntries);
  const city = mainEntry?.city;
  if (!mainEntry?.ref || !city || getOwnerUid(city) !== economy.uid || isStronghold(city)) return null;

  const troopFloat = Math.max(0, safeNumber(city.troopFloat, city.troops || 0)) + credited;
  const patch = {
    troops: Math.max(0, Math.floor(troopFloat)),
    troopFloat,
    productionUpdatedAtMs: nowMs,
  };
  appendEconomyCityPatch(economy, mainEntry.ref, city, patch);

  const cityUpdate = {
    id: city.id,
    regionId: normalizeRegionId(city.regionId || getRegionIdFromOnlineIslandId(getCityEntryIslandId(mainEntry))),
    ...patch,
  };
  const existingUpdate = economy.cityUpdates.find(update => (
    update?.id === cityUpdate.id && normalizeRegionId(update.regionId) === cityUpdate.regionId
  ));
  if (existingUpdate) Object.assign(existingUpdate, cityUpdate);
  else economy.cityUpdates.push(cityUpdate);

  return {
    credited,
    cityId: city.id,
    cityName: safeString(city.name || city.id || "main city", 40),
    regionId: cityUpdate.regionId,
    patch,
  };
}

function findNearestOwnedCityDestination(economy = null, source = null, excludedPaths = []) {
  if (!economy || !source) return null;
  const excluded = new Set((Array.isArray(excludedPaths) ? excludedPaths : []).map(path => safeString(path, 240)));
  const sourceRegionId = normalizeRegionId(source.regionId || "");
  const sourceX = safeNumber(source.x, 0);
  const sourceY = safeNumber(source.y, 0);
  return economy.cityEntries
    .filter(entry => !excluded.has(safeString(entry?.ref?.path, 240)))
    .filter(entry => getOwnerUid(entry.city) === economy.uid)
    .filter(entry => !isStronghold(entry.city))
    .map(entry => {
      const city = entry.city || {};
      const sameRegion = normalizeRegionId(city.regionId || "") === sourceRegionId;
      const distance = Math.hypot(safeNumber(city.x, 0) - sourceX, safeNumber(city.y, 0) - sourceY);
      return { ...entry, sameRegion, distance };
    })
    .sort((a, b) => {
      if (a.sameRegion !== b.sameRegion) return a.sameRegion ? -1 : 1;
      if (a.distance !== b.distance) return a.distance - b.distance;
      return safeString(a.city?.name || a.city?.id, 80).localeCompare(safeString(b.city?.name || b.city?.id, 80));
    })[0] || null;
}

function findNearestRelinquishDestination(economy = null, sourceEntry = null) {
  if (!sourceEntry?.city) return null;
  return findNearestOwnedCityDestination(economy, sourceEntry.city, [sourceEntry.ref?.path]);
}

function getOwnedMainCityDestination(economy = null, profile = {}) {
  if (!economy) return null;
  const ownedEntries = economy.cityEntries.filter(entry => (
    entry?.city
    && getOwnerUid(entry.city) === economy.uid
    && !isStronghold(entry.city)
  ));
  return getCanonicalMainCityEntry(profile, ownedEntries);
}

function getReinforcementReturnDestination(economy = null, profile = {}, contribution = {}) {
  if (!economy?.uid) return null;
  const sourceRegionId = normalizeRegionId(
    contribution.reinforcementSourceRegionId || contribution.sourceRegionId
  );
  const sourceId = safeString(
    contribution.reinforcementSourceId || contribution.sourceId,
    96
  );
  const sourceRef = sourceRegionId && sourceId ? cityRefForRegion(sourceRegionId, sourceId) : null;
  const originalEntry = sourceRef ? getEconomyCityByRef(economy, sourceRef) : null;
  if (originalEntry?.city && getOwnerUid(originalEntry.city) === economy.uid) return originalEntry;
  return getOwnedMainCityDestination(economy, profile)
    || economy.cityEntries.find(entry => entry?.city && getOwnerUid(entry.city) === economy.uid)
    || null;
}

function getRallyReturnDestination(economy = null, profile = {}, participant = {}) {
  if (!economy?.uid) return null;
  const sourceRegionId = normalizeRegionId(participant.sourceRegionId);
  const sourceId = safeString(participant.sourceId, 96);
  const sourceRef = sourceRegionId && sourceId ? cityRefForRegion(sourceRegionId, sourceId) : null;
  const originalEntry = sourceRef ? getEconomyCityByRef(economy, sourceRef) : null;
  if (originalEntry?.city && getOwnerUid(originalEntry.city) === economy.uid) return originalEntry;
  return getOwnedMainCityDestination(economy, profile)
    || economy.cityEntries.find(entry => entry?.city && getOwnerUid(entry.city) === economy.uid)
    || null;
}

function createRallyReturnMovement({
  rally = {},
  participant = {},
  source = {},
  destinationEntry = null,
  economy = null,
  profile = {},
  nowMs = Date.now(),
  reason = "rally_return",
  movementId = "",
} = {}) {
  if (!destinationEntry?.city || !economy?.uid) {
    throw new HttpsError("failed-precondition", "The rally participant has no owned return destination.");
  }
  const destination = destinationEntry.city;
  const route = buildServerGeneratedArmyRoute(source, destination);
  const rawId = normalizeRallyId(movementId || `${rally.id}_${participant.uid}_return_${nowMs.toString(36)}`);
  const troops = Math.max(0, Math.floor(safeNumber(participant.survivors, participant.troops)));
  const sourceRegionId = normalizeRegionId(source.regionId || rally.targetRegionId || rally.assemblyRegionId);
  const destinationRegionId = normalizeRegionId(
    destination.regionId || getRegionIdFromOnlineIslandId(getCityEntryIslandId(destinationEntry))
  );
  const stats = createPreparedEconomyStatsSnapshot(economy, profile, { nowMs });
  const duration = calculateTravelTime({
    pathLength: route.pathLength,
    troopCount: troops,
    kind: "transfer",
    speedMultiplier: addCommonGearMarchSpeed(profile, "transfer", skillMultiplier(profile, "marchOrders")
      * (1 + Math.max(0, safeNumber(economy.bonuses?.marchSpeedBonusPercent, 0)) / 100)),
  });
  return {
    id: rawId,
    worldId: ONLINE_WORLD_ID,
    resetGeneration: RESET_GENERATION,
    ownerKind: "player",
    ownerUid: economy.uid,
    ownerName: normalizePlayerName(profile.playerName || participant.ownerName, "Ruler"),
    ownerFlag: profile.flag || participant.ownerFlag || null,
    ownerKingPower: Math.max(0, Math.floor(safeNumber(stats?.kingPower, participant.ownerKingPower))),
    kingPowerVersion: GLOBAL_PLAYER_STATS_VERSION,
    kind: "transfer",
    launchKind: "rally_join",
    rallyReturn: true,
    rallyId: normalizeRallyId(rally.id),
    rallyClanId: safeString(rally.clanId, 128),
    returnReason: safeString(reason, 40),
    targetType: "city",
    fromId: safeString(source.id || rally.targetId || rally.assemblyCityId, 96),
    toId: safeString(destination.id, 96),
    fromName: safeString(source.name || rally.targetName || rally.assemblyCityName || "Rally", 40),
    toName: safeString(destination.name || "Return city", 40),
    sourceRegionId,
    targetRegionId: destinationRegionId,
    troops,
    requestedTroops: troops,
    total: duration,
    path: route.path,
    pathSegments: route.pathSegments,
    routeRegionIds: route.routeRegionIds,
    viewRegionIds: route.routeRegionIds,
    pathLength: route.pathLength,
    targetKey: `${destinationRegionId}:${destination.id}`,
    targetOwnerAtLaunch: "player",
    originalTargetOwnerUid: economy.uid,
    targetOwnerUid: economy.uid,
    attackerKingPower: Math.max(0, Math.floor(safeNumber(stats?.kingPower, participant.ownerKingPower))),
    defenderKingPower: Math.max(0, Math.floor(safeNumber(stats?.kingPower, participant.ownerKingPower))),
    launchedAtMs: nowMs,
    arrivesAtMs: nowMs + Math.ceil(duration * 1000),
    status: "active",
    createdByServer: true,
    rallyModelVersion: RALLY_MODEL_VERSION,
    serverAuthorityVersion: 3,
  };
}

function getRallyShieldDeactivation(economy = null, nowMs = Date.now()) {
  if (!economy) return { deactivated: false, profileOverrides: {}, cityPatches: [], cityUpdates: [] };
  const itemEffects = { ...(economy.itemEffects || {}) };
  const shieldIsActive = safeNumber(itemEffects.shieldExpiresAtMs, 0) > nowMs
    || economy.cityEntries.some(entry => (
      entry?.city
      && !isStronghold(entry.city)
      && getShieldExpiresAtMs(entry.city) > nowMs
    ));
  if (!shieldIsActive) {
    return { deactivated: false, profileOverrides: {}, cityPatches: [], cityUpdates: [] };
  }
  itemEffects.shieldExpiresAtMs = 0;
  const cityPatches = [];
  const cityUpdates = [];
  economy.cityEntries.forEach(entry => {
    if (!entry?.ref || !entry.city || isStronghold(entry.city)) return;
    const patch = { ownerShieldExpiresAtMs: 0 };
    cityPatches.push({ ref: entry.ref, city: entry.city, patch });
    cityUpdates.push({
      id: entry.city.id,
      regionId: normalizeRegionId(entry.city.regionId || getRegionIdFromOnlineIslandId(getCityEntryIslandId(entry))),
      ...patch,
    });
  });
  return {
    deactivated: true,
    profileOverrides: { itemEffects },
    cityPatches,
    cityUpdates,
  };
}

function createRelinquishContinuationMovement({
  army = {},
  source = {},
  destinationEntry = null,
  economy = null,
  profile = {},
  nowMs = Date.now(),
  reason = "released_destination",
} = {}) {
  if (!destinationEntry?.city || !economy?.uid) {
    throw new HttpsError("failed-precondition", "No owned city is available for the relinquished troops.");
  }
  const destination = destinationEntry.city;
  const route = buildServerGeneratedArmyRoute(source, destination);
  const continuationCount = clampInt(army.relinquishContinuationCount, 0, 999) + 1;
  const rawOriginId = safeString(army.relinquishOriginArmyId || army.id, 72)
    .replace(/[^a-zA-Z0-9_-]/g, "_") || "relinquish";
  const suffix = `_rb${continuationCount}_${Math.max(0, Math.floor(nowMs)).toString(36)}`;
  const continuationId = `${rawOriginId.slice(0, Math.max(1, 96 - suffix.length))}${suffix}`;
  const sourceRegionId = normalizeRegionId(source.regionId || source.startPool);
  const destinationRegionId = normalizeRegionId(destination.regionId || destination.startPool);
  const currentStats = createPreparedEconomyStatsSnapshot(economy, profile, { nowMs });
  const ownerKingPower = Math.max(0, Math.floor(safeNumber(
    currentStats?.kingPower,
    safeNumber(economy.lastGlobalStats?.kingPower, safeNumber(economy.globalStats?.kingPower, army.ownerKingPower))
  )));
  const troops = Math.max(0, Math.floor(safeNumber(army.troops, 0)));
  const duration = calculateTravelTime({
    pathLength: route.pathLength,
    troopCount: troops,
    kind: "transfer",
    speedMultiplier: addCommonGearMarchSpeed(profile, "transfer", skillMultiplier(profile, "marchOrders")
      * (1 + Math.max(0, safeNumber(economy.bonuses?.marchSpeedBonusPercent, 0)) / 100)),
  });
  return {
    id: continuationId,
    worldId: ONLINE_WORLD_ID,
    resetGeneration: RESET_GENERATION,
    ownerKind: "player",
    ownerUid: economy.uid,
    ownerName: normalizePlayerName(profile.playerName || army.ownerName, "Ruler"),
    ownerFlag: profile.flag || army.ownerFlag || null,
    ownerKingPower,
    kingPowerVersion: GLOBAL_PLAYER_STATS_VERSION,
    kind: "transfer",
    targetType: "city",
    relinquishTransfer: true,
    relinquishOriginArmyId: rawOriginId,
    relinquishContinuationCount: continuationCount,
    relinquishRedirectReason: safeString(reason, 40),
    fromId: safeString(source.id, 96),
    toId: safeString(destination.id, 96),
    fromName: safeString(source.name || army.toName || "Released city", 40),
    toName: safeString(destination.name || "Owned city", 40),
    sourceRegionId,
    targetRegionId: destinationRegionId,
    troops,
    requestedTroops: troops,
    total: duration,
    path: route.path,
    pathSegments: route.pathSegments,
    routeRegionIds: route.routeRegionIds,
    viewRegionIds: route.routeRegionIds,
    pathLength: route.pathLength,
    targetKey: `${destinationRegionId}:${destination.id}`,
    targetOwnerAtLaunch: "player",
    targetOwnerUid: economy.uid,
    attackerKingPower: ownerKingPower,
    defenderKingPower: ownerKingPower,
    demoAttack: null,
    launchedAtMs: nowMs,
    arrivesAtMs: nowMs + Math.ceil(duration * 1000),
    status: "active",
    createdByServer: true,
    serverAuthorityVersion: 2,
  };
}

function getReinforcementTargetRef(contribution = {}) {
  const targetType = contribution.targetType === "camp" ? "camp" : "city";
  const regionId = normalizeRegionId(contribution.targetRegionId);
  const targetId = safeString(contribution.targetId, 96);
  if (!regionId || !targetId) return null;
  return targetType === "camp"
    ? campRefForRegion(regionId, targetId)
    : cityRefForRegion(regionId, targetId);
}

function createReinforcementReturnMovement({
  contribution = {},
  source = {},
  destinationEntry = null,
  economy = null,
  profile = {},
  nowMs = Date.now(),
  reason = "recalled",
} = {}) {
  if (!destinationEntry?.city || !economy?.uid) {
    throw new HttpsError("failed-precondition", "The troop owner has no available return holding.");
  }
  const destination = destinationEntry.city;
  const route = buildServerGeneratedArmyRoute(source, destination);
  const revision = clampInt(contribution.returnRevision, 0, 999999) + 1;
  const rawId = safeString(contribution.id || "reinforcement", 64).replace(/[^a-zA-Z0-9_-]/g, "_");
  const suffix = `_return_${revision}`;
  const movementId = `${rawId.slice(0, Math.max(1, 96 - suffix.length))}${suffix}`;
  const sourceRegionId = normalizeRegionId(source.regionId || contribution.targetRegionId);
  const destinationRegionId = normalizeRegionId(destination.regionId || getRegionIdFromOnlineIslandId(getCityEntryIslandId(destinationEntry)));
  const troops = Math.max(0, Math.floor(safeNumber(contribution.troops, 0)));
  const stats = createPreparedEconomyStatsSnapshot(economy, profile, { nowMs });
  const duration = calculateTravelTime({
    pathLength: route.pathLength,
    troopCount: troops,
    kind: "transfer",
    speedMultiplier: addCommonGearMarchSpeed(profile, "transfer", skillMultiplier(profile, "marchOrders")
      * (1 + Math.max(0, safeNumber(economy.bonuses?.marchSpeedBonusPercent, 0)) / 100)),
  });
  return {
    id: movementId,
    worldId: ONLINE_WORLD_ID,
    resetGeneration: RESET_GENERATION,
    ownerKind: "player",
    ownerUid: economy.uid,
    ownerName: normalizePlayerName(profile.playerName || contribution.ownerName, "Ruler"),
    ownerFlag: profile.flag || contribution.ownerFlag || null,
    ownerKingPower: Math.max(0, Math.floor(safeNumber(stats?.kingPower, contribution.ownerKingPower))),
    kingPowerVersion: GLOBAL_PLAYER_STATS_VERSION,
    kind: "transfer",
    launchKind: "reinforce",
    reinforcementReturn: true,
    reinforcementId: safeString(contribution.id, 96),
    reinforcementRecipientUid: safeString(
      contribution.reinforcementRecipientUid || contribution.originalTargetOwnerUid || contribution.targetOwnerUid,
      128
    ),
    reinforcementSourceId: safeString(
      contribution.reinforcementSourceId || contribution.sourceId,
      96
    ),
    reinforcementSourceRegionId: normalizeRegionId(
      contribution.reinforcementSourceRegionId || contribution.sourceRegionId
    ),
    reinforcementSourceCityName: safeString(
      contribution.reinforcementSourceCityName || contribution.sourceName,
      40
    ),
    returnReason: safeString(reason, 40),
    targetType: "city",
    fromId: safeString(source.id || contribution.targetId, 96),
    toId: safeString(destination.id, 96),
    fromName: safeString(source.name || contribution.targetName || "Allied holding", 40),
    toName: safeString(destination.name || "Return holding", 40),
    sourceRegionId,
    targetRegionId: destinationRegionId,
    troops,
    requestedTroops: troops,
    total: duration,
    path: route.path,
    pathSegments: route.pathSegments,
    routeRegionIds: route.routeRegionIds,
    viewRegionIds: route.routeRegionIds,
    pathLength: route.pathLength,
    targetKey: `${destinationRegionId}:${destination.id}`,
    reinforcementTargetKey: safeString(contribution.targetKey, 220),
    targetOwnerAtLaunch: "player",
    originalTargetOwnerUid: economy.uid,
    targetOwnerUid: economy.uid,
    attackerKingPower: Math.max(0, Math.floor(safeNumber(stats?.kingPower, contribution.ownerKingPower))),
    defenderKingPower: Math.max(0, Math.floor(safeNumber(stats?.kingPower, contribution.ownerKingPower))),
    launchedAtMs: nowMs,
    arrivesAtMs: nowMs + Math.ceil(duration * 1000),
    status: "active",
    createdByServer: true,
    reinforcementModelVersion: REINFORCEMENT_MODEL_VERSION,
    serverAuthorityVersion: 3,
  };
}

async function beginReinforcementReturn({
  reinforcementId = "",
  callerUid = "",
  reason = "recalled",
  nowMs = Date.now(),
} = {}) {
  const id = safeString(reinforcementId, 96).replace(/[^a-zA-Z0-9_-]/g, "_");
  if (!id) throw new HttpsError("invalid-argument", "Choose reinforcements to return.");
  const contributionRef = db.doc(`reinforcements/${id}`);
  return runTransactionWithInfrastructureRetry(async transaction => {
    const contributionSnap = await transaction.get(contributionRef);
    if (!contributionSnap.exists) throw new HttpsError("not-found", "Those reinforcements were not found.");
    let contribution = { id: contributionSnap.id, ...contributionSnap.data() };
    if (
      safeString(contribution.resetGeneration, 120) !== RESET_GENERATION
      || safeString(contribution.worldId, 120) !== ONLINE_WORLD_ID
    ) {
      throw new HttpsError("failed-precondition", "Those reinforcements belong to an archived world.");
    }
    if (contribution.status !== REINFORCEMENT_STATUS_STATIONED || safeNumber(contribution.troops, 0) <= 0) {
      return { ok: true, duplicate: true, status: contribution.status || REINFORCEMENT_STATUS_DEPLETED };
    }

    if (
      (!contribution.reinforcementSourceId || !contribution.reinforcementSourceRegionId)
      && contribution.lastArrivalArmyId
    ) {
      const arrivalArmySnap = await transaction.get(canonicalArmyRef(
        safeString(contribution.lastArrivalArmyId, 96)
      ));
      if (arrivalArmySnap.exists) {
        const arrivalArmy = arrivalArmySnap.data() || {};
        contribution = {
          ...contribution,
          reinforcementSourceId: safeString(arrivalArmy.reinforcementSourceId || arrivalArmy.fromId, 96),
          reinforcementSourceRegionId: normalizeRegionId(
            arrivalArmy.reinforcementSourceRegionId || arrivalArmy.sourceRegionId
          ),
          reinforcementSourceCityName: safeString(
            arrivalArmy.reinforcementSourceCityName || arrivalArmy.fromName,
            40
          ),
          reinforcementRecipientUid: safeString(
            arrivalArmy.reinforcementRecipientUid
              || arrivalArmy.originalTargetOwnerUid
              || contribution.targetOwnerUid,
            128
          ),
        };
      }
    }

    const ownerUid = safeString(contribution.ownerUid, 128);
    const targetRef = getReinforcementTargetRef(contribution);
    if (!ownerUid || !targetRef) throw new HttpsError("failed-precondition", "Reinforcement ownership data is incomplete.");
    const targetSnap = await transaction.get(targetRef);
    const target = targetSnap.exists
      ? contribution.targetType === "camp"
        ? getRewardCampCombatTarget({ id: targetSnap.id, ...targetSnap.data() })
        : { id: targetSnap.id, ...targetSnap.data() }
      : {
        id: safeString(contribution.targetId, 96),
        name: safeString(contribution.targetName, 40),
        regionId: normalizeRegionId(contribution.targetRegionId),
        x: safeNumber(contribution.targetX, 0),
        y: safeNumber(contribution.targetY, 0),
      };
    const capacitySnap = isOrdinaryReinforcementCity(target, contribution.targetType)
      ? await transaction.get(reinforcementCapacityRef(contribution.targetKey))
      : null;
    const currentHolderUid = targetSnap.exists ? getOwnerUid(target) : safeString(contribution.targetOwnerUid, 128);
    if (callerUid && callerUid !== ownerUid && callerUid !== currentHolderUid) {
      throw new HttpsError("permission-denied", "Only the troop owner or holding owner can return these reinforcements.");
    }
    const returnInitiatorRole = callerUid === ownerUid
      ? "contributor"
      : callerUid === currentHolderUid
        ? "holder"
        : "server";
    const effectiveReturnReason = returnInitiatorRole === "contributor"
      ? "contributor_recall"
      : returnInitiatorRole === "holder"
        ? "holder_send_home"
        : safeString(reason, 40) || "server_return";

    const economy = await prepareEconomyCollection(transaction, ownerUid, nowMs);
    const profile = economy.profileAfter || {};
    const destinationEntry = getReinforcementReturnDestination(economy, profile, contribution);
    if (!destinationEntry?.city) {
      throw new HttpsError("failed-precondition", "The troop owner has no available return holding.");
    }
    const movement = createReinforcementReturnMovement({
      contribution,
      source: target,
      destinationEntry,
      economy,
      profile,
      nowMs,
      reason: effectiveReturnReason,
    });
    const currentStationed = getProfileStationedReinforcementTroops(profile);
    const returningTroops = Math.max(0, Math.floor(safeNumber(contribution.troops, 0)));
    const profileOverrides = {
      stationedReinforcementTroops: Math.max(0, currentStationed - returningTroops),
      reinforcementResetGeneration: RESET_GENERATION,
    };
    writePreparedEconomy(transaction, economy, profileOverrides, [], {
      addActiveArmies: [movement],
      nowMs,
    });
    writeArmyMovementCopies(transaction, movement, { includeCreatedAt: true });

    releaseOrdinaryCityReinforcementSlot(transaction, {
      capacitySnap,
      targetRef,
      target: { ...target, regionId: contribution.targetRegionId },
      targetKey: contribution.targetKey,
      ownerUid,
      nowMs,
    });
    releaseClanReinforcementAssignment(
      transaction,
      ownerUid,
      contribution.reinforcementRecipientUid
        || contribution.originalTargetOwnerUid
        || contribution.targetOwnerUid,
      contribution.targetKey
    );

    let targetUpdate = null;
    if (targetSnap.exists && target) {
      const alliedTroops = getAlliedReinforcementTroops(target);
      const patch = {
        alliedReinforcementTroops: Math.max(0, alliedTroops - returningTroops),
      };
      transaction.set(targetRef, patch, { merge: true });
      targetUpdate = contribution.targetType === "camp"
        ? { campUpdate: campUpdateForClient(target.id, contribution.targetRegionId, patch) }
        : { cityUpdates: [{ id: target.id, regionId: contribution.targetRegionId, ...patch }] };
    }
    transaction.set(contributionRef, {
      troops: 0,
      status: REINFORCEMENT_STATUS_RETURNING,
      returnRevision: clampInt(contribution.returnRevision, 0, 999999) + 1,
      returnArmyId: movement.id,
      returnReason: effectiveReturnReason,
      returnDestinationId: movement.toId,
      returnDestinationRegionId: movement.targetRegionId,
      returnDestinationName: movement.toName,
      usedMainCityFallback: movement.toId !== safeString(
        contribution.reinforcementSourceId || contribution.sourceId,
        96
      ),
      returnedAtMs: nowMs,
      updatedAt: FieldValue.serverTimestamp(),
    }, { merge: true });

    return {
      ok: true,
      status: REINFORCEMENT_STATUS_RETURNING,
      reinforcementId: id,
      returnInitiatorRole,
      troops: returningTroops,
      movement,
      returnDestination: {
        id: movement.toId,
        regionId: movement.targetRegionId,
        name: movement.toName,
        usedMainCityFallback: movement.toId !== safeString(
          contribution.reinforcementSourceId || contribution.sourceId,
          96
        ),
      },
      ...targetUpdate,
      ...(returnInitiatorRole === "contributor"
        ? {
          currentUser: createEconomyResponse(economy, {
            currentUser: {
              ...createEconomyResponse(economy).currentUser,
              globalStats: globalStatsForClient(economy.lastGlobalStats || economy.globalStats),
            },
          }).currentUser,
        }
        : {}),
    };
  });
}

async function beginOutboundReinforcementReturn({
  armyId = "",
  reason = "reinforcement_capacity_overflow",
  nowMs = Date.now(),
} = {}) {
  const id = safeString(armyId, 96).replace(/[^a-zA-Z0-9_-]/g, "_");
  if (!id) return { ok: true, status: "missing" };
  const armyRef = canonicalArmyRef(id);
  return runTransactionWithInfrastructureRetry(async transaction => {
    const armySnap = await transaction.get(armyRef);
    if (!armySnap.exists) return { ok: true, status: "missing" };
    const army = { id: armySnap.id, ...armySnap.data() };
    const launchedAsReinforcement = !army.reinforcementReturn && (
      army.kind === "reinforce"
      || army.launchKind === "reinforce"
      || army.retargetedFromKind === "reinforce"
    );
    if (army.status !== "active" || army.returning || !launchedAsReinforcement) {
      return { ok: true, status: army.returning ? "returning" : army.status || "resolved" };
    }
    const sourceRegionId = normalizeRegionId(army.sourceRegionId);
    const targetRegionId = normalizeRegionId(army.targetRegionId);
    const targetRef = army.targetType === "camp"
      ? null
      : cityRefForRegion(targetRegionId, army.toId);
    const targetSnap = targetRef ? await transaction.get(targetRef) : null;
    const target = targetSnap?.exists
      ? { id: targetSnap.id, ...targetSnap.data(), regionId: targetRegionId }
      : null;
    const targetKey = safeString(
      army.reinforcementTargetKey
        || getReinforcementTargetKey(army.targetType, targetRegionId, army.toId),
      220
    );
    const capacitySnap = target && isOrdinaryReinforcementCity(target, army.targetType)
      ? await transaction.get(reinforcementCapacityRef(targetKey))
      : null;
    const launchedAtMs = Math.max(0, Math.floor(safeNumber(
      army.launchedAtMs,
      nowMs - Math.max(100, safeNumber(army.total, 0.1) * 1000)
    )));
    const originalArrivesAtMs = Math.max(
      nowMs,
      Math.floor(safeNumber(army.swiftMarchOriginalArrivesAtMs, army.arrivesAtMs))
    );
    const originalTotalMs = Math.max(100, originalArrivesAtMs - launchedAtMs);
    const returnStartProgress = clamp(getArmyRouteProgressAtMs(army, nowMs), 0.000001, 0.999999);
    const returnDurationMs = Math.max(
      RECALL_HORN_MINIMUM_RETURN_MS,
      Math.ceil(originalTotalMs * returnStartProgress)
    );
    const movementPatch = {
      returning: true,
      returnReason: safeString(reason, 40),
      recalledAtMs: nowMs,
      returnStartProgress,
      returnDestinationId: army.fromId,
      returnDestinationRegionId: sourceRegionId,
      arrivesAtMs: nowMs + returnDurationMs,
      total: Math.max(0.1, returnDurationMs / 1000),
      targetOwnerUid: "",
      updatedAt: FieldValue.serverTimestamp(),
    };
    writeArmyMovementCopies(transaction, { ...army, ...movementPatch, id }, {
      previousTargetOwnerUid: army.targetOwnerUid,
    });
    releaseOrdinaryCityReinforcementSlot(transaction, {
      capacitySnap,
      targetRef,
      target,
      targetKey,
      ownerUid: army.ownerUid,
      nowMs,
    });
    return {
      ok: true,
      status: "returning",
      armyId: id,
      returnReason: movementPatch.returnReason,
    };
  });
}

function getCityEntryIslandId(entry = {}) {
  return safeString(entry?.ref?.parent?.parent?.id || getOnlineIslandId(entry?.city?.regionId), 160);
}

function getCityEntryPath(entry = {}) {
  return safeString(entry?.ref?.path, 240);
}

function getCityEntryClaimedAtMs(entry = {}) {
  const city = entry.city || {};
  const timestamps = [
    timestampToMs(city.claimedAt),
    timestampToMs(city.createdAt),
    timestampToMs(city.productionUpdatedAtMs),
    timestampToMs(city.updatedAt)
  ].filter(value => value > 0);
  return timestamps.length ? Math.min(...timestamps) : Number.MAX_SAFE_INTEGER;
}

function compareMainCityCandidates(a = {}, b = {}) {
  const aTime = getCityEntryClaimedAtMs(a);
  const bTime = getCityEntryClaimedAtMs(b);
  if (aTime !== bTime) return aTime - bTime;
  return getCityEntryPath(a).localeCompare(getCityEntryPath(b));
}

function getCanonicalMainCityEntry(profile = {}, cityEntries = []) {
  const regularEntries = cityEntries.filter(entry => entry?.city && !isStronghold(entry.city));
  if (!regularEntries.length) return null;
  const profileMainCityId = safeString(profile.mainCityId, 96).replace(/[^a-zA-Z0-9_-]/g, "_");
  const profileIslandId = safeString(profile.mainIslandId, 160);
  if (profileMainCityId) {
    const profileMatch = regularEntries.find(entry => {
      if (entry.city.id !== profileMainCityId) return false;
      return !profileIslandId || getCityEntryIslandId(entry) === profileIslandId;
    });
    if (profileMatch) return profileMatch;
  }
  const flaggedMainEntries = regularEntries
    .filter(entry => Boolean(entry.city.isMainCity))
    .sort(compareMainCityCandidates);
  if (flaggedMainEntries.length) return flaggedMainEntries[0];
  return regularEntries.slice().sort(compareMainCityCandidates)[0];
}

function createOwnedCityEntriesFromSnapshot(uid, ownedSnap) {
  return ownedSnap.docs
    .map(doc => {
      const data = doc.data() || {};
      const islandId = safeString(doc.ref.parent?.parent?.id, 160);
      if (!isCurrentWorldIslandId(islandId)) return null;
      if ((data.ownerKind || "player") !== "player" || getOwnerUid(data) !== uid) return null;
      const regionId = getRegionIdFromCityDoc(doc, data);
      if (!getServerWorldTargetIds(regionId).has(doc.id)) return null;
      return {
        ref: doc.ref,
        city: {
          id: doc.id,
          ...data,
          islandId,
          regionId,
          ownerKind: "player",
          ownerUid: uid,
        },
      };
    })
    .filter(Boolean);
}

function createMainCityAssignmentRepair(uid, rawProfile = {}, cityEntries = []) {
  const cityPatches = [];
  const cityUpdates = [];
  const mainCityEntry = getCanonicalMainCityEntry(rawProfile, cityEntries);
  const mainCityEntryPath = getCityEntryPath(mainCityEntry);
  const canonicalMainCityId = mainCityEntry?.city?.id || "";
  const canonicalMainIslandId = mainCityEntry ? getCityEntryIslandId(mainCityEntry) : safeString(rawProfile.mainIslandId, 160);
  const canonicalMainRegionId = mainCityEntry
    ? normalizeRegionId(mainCityEntry.city.regionId || getRegionIdFromOnlineIslandId(canonicalMainIslandId))
    : normalizeRegionId(rawProfile.mainRegionId || getRegionIdFromOnlineIslandId(canonicalMainIslandId));

  cityEntries.forEach(entry => {
    if (!entry?.city) return;
    const shouldBeMain = Boolean(mainCityEntryPath && getCityEntryPath(entry) === mainCityEntryPath && !isStronghold(entry.city));
    if (Boolean(entry.city.isMainCity) === shouldBeMain) return;
    const patch = { isMainCity: shouldBeMain };
    cityPatches.push({ ref: entry.ref, city: entry.city, patch });
    cityUpdates.push({
      id: entry.city.id,
      regionId: entry.city.regionId,
      ...patch,
    });
    entry.city = { ...entry.city, ...patch };
  });

  const profileFields = {
    mainCityAssignmentVersion: MAIN_CITY_ASSIGNMENT_VERSION,
    ...(canonicalMainCityId ? {
        mainCityId: canonicalMainCityId,
        mainIslandId: canonicalMainIslandId,
        mainRegionId: canonicalMainRegionId,
      } : {}),
  };

  return {
    mainCityEntry,
    mainCityEntryPath,
    canonicalMainCityId,
    canonicalMainIslandId,
    canonicalMainRegionId,
    profileFields,
    cityPatches,
    cityUpdates,
  };
}

function createSingleMainCityPatches(cityEntries = [], mainRef = null) {
  const mainPath = safeString(mainRef?.path, 240);
  const cityPatches = [];
  const cityUpdates = [];
  cityEntries.forEach(entry => {
    if (!entry?.ref || !entry.city || isStronghold(entry.city)) return;
    const shouldBeMain = Boolean(mainPath && getCityEntryPath(entry) === mainPath);
    if (Boolean(entry.city.isMainCity) === shouldBeMain) return;
    const patch = { isMainCity: shouldBeMain };
    cityPatches.push({ ref: entry.ref, city: entry.city, patch });
    cityUpdates.push({
      id: entry.city.id,
      regionId: entry.city.regionId,
      ...patch,
    });
    entry.city = { ...entry.city, ...patch };
  });
  return { cityPatches, cityUpdates };
}

function createEmptyPendingAwayProduction(observedAtMs = 0) {
  return {
    version: WELCOME_BACK_SUMMARY_VERSION,
    goldGained: 0,
    troopsByCity: {},
    startedAtMs: 0,
    updatedAtMs: 0,
    observedAtMs: Math.max(0, Math.floor(safeNumber(observedAtMs, 0))),
  };
}

function getIntegerProductionGain(currentFloat = 0, gainFloat = 0) {
  const before = Math.max(0, safeNumber(currentFloat, 0));
  const gain = Math.max(0, safeNumber(gainFloat, 0));
  return Math.max(0, Math.floor(before + gain) - Math.floor(before));
}

function normalizePendingAwayProduction(raw = null) {
  const source = raw && typeof raw === "object" ? raw : {};
  const troopsByCity = {};
  Object.entries(source.troopsByCity && typeof source.troopsByCity === "object" ? source.troopsByCity : {})
    .slice(0, PENDING_AWAY_PRODUCTION_CITY_LIMIT)
    .forEach(([rawKey, rawTroops]) => {
      const key = safeString(rawKey, 220);
      const troops = Math.max(0, Math.floor(safeNumber(rawTroops, 0)));
      if (key.startsWith("city:") && troops > 0) troopsByCity[key] = troops;
    });
  return {
    version: WELCOME_BACK_SUMMARY_VERSION,
    goldGained: Math.max(0, Math.floor(safeNumber(source.goldGained, 0))),
    troopsByCity,
    startedAtMs: Math.max(0, Math.floor(safeNumber(source.startedAtMs, 0))),
    updatedAtMs: Math.max(0, Math.floor(safeNumber(source.updatedAtMs, 0))),
    observedAtMs: Math.max(0, Math.floor(safeNumber(source.observedAtMs, 0))),
  };
}

function addPendingAwayProduction(rawPending = null, production = {}, nowMs = Date.now()) {
  const pending = normalizePendingAwayProduction(rawPending);
  const goldGained = Math.max(0, Math.floor(safeNumber(production.goldGained, 0)));
  const entries = Object.entries(
    production.troopsByCity && typeof production.troopsByCity === "object"
      ? production.troopsByCity
      : {}
  );
  pending.goldGained += goldGained;
  entries.forEach(([rawKey, rawTroops]) => {
    const key = safeString(rawKey, 220);
    const troops = Math.max(0, Math.floor(safeNumber(rawTroops, 0)));
    if (!key.startsWith("city:") || troops <= 0) return;
    if (!Object.prototype.hasOwnProperty.call(pending.troopsByCity, key)
      && Object.keys(pending.troopsByCity).length >= PENDING_AWAY_PRODUCTION_CITY_LIMIT) return;
    pending.troopsByCity[key] = Math.max(0, Math.floor(safeNumber(pending.troopsByCity[key], 0))) + troops;
  });
  if ((goldGained > 0 || entries.length > 0) && !pending.startedAtMs) {
    pending.startedAtMs = Math.max(0, Math.floor(safeNumber(production.startedAtMs, nowMs)));
  }
  if (goldGained > 0 || entries.length > 0) pending.updatedAtMs = nowMs;
  return pending;
}

function consumePendingAwayCityTroops(economy = null, city = null, losses = 0, { captured = false } = {}) {
  if (!economy || !city?.id) return;
  const pending = normalizePendingAwayProduction(economy.profilePatch?.pendingAwayProduction);
  const key = getReinforcementTargetKey("city", city.regionId || getRegionIdFromCityDoc(null, city), city.id);
  if (captured) {
    delete pending.troopsByCity[key];
  } else {
    const remaining = Math.max(0, Math.floor(safeNumber(pending.troopsByCity[key], 0)) - Math.max(0, Math.floor(safeNumber(losses, 0))));
    if (remaining > 0) pending.troopsByCity[key] = remaining;
    else delete pending.troopsByCity[key];
  }
  economy.profilePatch.pendingAwayProduction = pending;
  economy.profileAfter.pendingAwayProduction = pending;
}

async function prepareEconomyCollection(transaction, uid, nowMs = Date.now(), options = {}) {
  if (!options.allowInactivityMaintenance) {
    const maintenanceRef = inactivityMaintenanceRef(uid);
    const maintenanceSnap = maintenanceRef ? await transaction.get(maintenanceRef) : null;
    const maintenance = maintenanceSnap?.exists ? maintenanceSnap.data() || {} : {};
    if (isInactivityLifecycleBlockingPlayer(maintenance)) {
      throw new HttpsError(
        "unavailable",
        "Your kingdom is completing scheduled realm maintenance. Try again in a moment."
      );
    }
  }
  const profileRef = options.profileRef || db.doc(`players/${uid}`);
  const profileSnap = options.profileSnap || await transaction.get(profileRef);
  const rawProfile = profileSnap.exists ? profileSnap.data() || {} : {};
  const upgrades = normalizeSkillUpgrades(rawProfile.upgrades);
  const character = reconcileSkillPoints(rawProfile.character, upgrades);
  const freeSkillResetState = normalizeFreeSkillResetState(rawProfile);
  const itemEffects = normalizeItemEffects(rawProfile.itemEffects);
  const shopItems = normalizeShopItems(rawProfile.shopItems);
  const itemPurchaseCooldowns = normalizeItemPurchaseCooldowns(rawProfile.itemPurchaseCooldowns);
  const baseGold = Math.max(0, safeNumber(rawProfile.goldFloat, safeNumber(rawProfile.gold, TEST_STARTING_GOLD)));
  const pendingAwayProductionBefore = normalizePendingAwayProduction(rawProfile.pendingAwayProduction);
  const productionObservedAtMs = Math.min(
    nowMs,
    Math.max(0, pendingAwayProductionBefore.observedAtMs)
  );
  const fallbackProductionAtMs = Math.min(nowMs, getProfileLastSeenMs(rawProfile) || nowMs);
  const economyRevisionMs = Math.max(nowMs, timestampToMs(rawProfile.economyUpdatedAtMs) + 1);

  const [ownedSnap, activeArmiesSnap, heldCampsSnap] = await Promise.all([
    transaction.get(db.collectionGroup("cities")
      .where("ownerUid", "==", uid)
      .where("resetGeneration", "==", RESET_GENERATION)
      .where("worldId", "==", ONLINE_WORLD_ID)),
    transaction.get(activeArmiesQueryForPlayer(uid)),
    transaction.get(heldRewardCampsQueryForPlayer(uid)),
  ]);
  const cityEntries = createOwnedCityEntriesFromSnapshot(uid, ownedSnap);
  const activeArmies = createActiveArmiesFromSnapshot(uid, activeArmiesSnap);
  const heldCamps = createHeldCampEntriesFromSnapshot(uid, heldCampsSnap);
  const mainCityRepair = createMainCityAssignmentRepair(uid, rawProfile, cityEntries);
  const cityPatches = [...mainCityRepair.cityPatches];
  const cityUpdates = [...mainCityRepair.cityUpdates];
  const productionCityPatches = [];

  const lastEconomyAtMs = Math.min(
    nowMs,
    timestampToMs(rawProfile.economyUpdatedAtMs) || fallbackProductionAtMs
  );
  itemEffects.warDrumsStartedAtMs = resolveTimedProductionBoostStartedAtMs(
    itemEffects.warDrumsStartedAtMs,
    itemEffects.warDrumsExpiresAtMs,
    lastEconomyAtMs,
    nowMs
  );
  itemEffects.royalTaxDecreeStartedAtMs = resolveTimedProductionBoostStartedAtMs(
    itemEffects.royalTaxDecreeStartedAtMs,
    itemEffects.royalTaxDecreeExpiresAtMs,
    lastEconomyAtMs,
    nowMs
  );
  const goldElapsedSeconds = clamp((nowMs - lastEconomyAtMs) / 1000, 0, MAX_SERVER_PRODUCTION_SECONDS);
  const pendingGoldStartedAtMs = Math.max(lastEconomyAtMs, productionObservedAtMs);
  const pendingGoldElapsedSeconds = clamp(
    (nowMs - pendingGoldStartedAtMs) / 1000,
    0,
    MAX_SERVER_PRODUCTION_SECONDS
  );
  const objectiveBenefits = await resolvePlayerObjectiveBenefits(
    transaction,
    uid,
    rawProfile,
    cityEntries,
    nowMs,
    goldElapsedSeconds * 1000
  );
  const bonuses = objectiveBenefits.currentBonuses;
  const productionBonuses = objectiveBenefits.productionBonuses;
  let goldGainFloat = 0;
  let pendingGoldGainFloat = 0;
  let troopsGained = 0;
  const troopsByCity = {};
  let maxElapsedSeconds = goldElapsedSeconds;

  cityEntries.forEach(entry => {
    const city = entry.city;
    if (isStronghold(city)) return;
    const lastProductionAtMs = Math.min(
      nowMs,
      timestampToMs(city.productionUpdatedAtMs || city.economyUpdatedAtMs) || fallbackProductionAtMs
    );
    const elapsedSeconds = clamp((nowMs - lastProductionAtMs) / 1000, 0, MAX_SERVER_PRODUCTION_SECONDS);
    const collectionStartedAtMs = Math.max(lastProductionAtMs, lastEconomyAtMs);
    const collectionElapsedSeconds = clamp((nowMs - collectionStartedAtMs) / 1000, 0, MAX_SERVER_PRODUCTION_SECONDS);
    const pendingCollectionStartedAtMs = Math.max(collectionStartedAtMs, productionObservedAtMs);
    const pendingCollectionElapsedSeconds = clamp(
      (nowMs - pendingCollectionStartedAtMs) / 1000,
      0,
      MAX_SERVER_PRODUCTION_SECONDS
    );
    maxElapsedSeconds = Math.max(maxElapsedSeconds, collectionElapsedSeconds);
    const stats = getCityProductionStats(city, { ...rawProfile, character, upgrades, itemEffects }, productionBonuses, {
      nowMs,
      includeWarDrums: false,
      includeRoyalTaxDecree: false,
    });
    const troopIntervalStartMs = nowMs - elapsedSeconds * 1000;
    const warDrumsOverlapSeconds = getTimedProductionBoostOverlapSeconds(
      troopIntervalStartMs,
      nowMs,
      itemEffects.warDrumsStartedAtMs,
      itemEffects.warDrumsExpiresAtMs
    );
    const taxDecreeOverlapSeconds = getTimedProductionBoostOverlapSeconds(
      nowMs - goldElapsedSeconds * 1000,
      nowMs,
      itemEffects.royalTaxDecreeStartedAtMs,
      itemEffects.royalTaxDecreeExpiresAtMs
    );
    const currentTroopFloat = Math.max(0, safeNumber(city.troopFloat, safeNumber(city.troops, 0)));
    const troopGainFloat = stats.troopProductionPerSecond * elapsedSeconds
      + stats.baseTroopProductionPerHour / 3600
        * warDrumsOverlapSeconds
        * WAR_DRUMS_TROOP_PRODUCTION_BONUS_PERCENT / 100;
    const nextTroopFloat = currentTroopFloat + troopGainFloat;
    const nextTroops = Math.max(0, Math.floor(nextTroopFloat));
    const collectionWarDrumsOverlapSeconds = getTimedProductionBoostOverlapSeconds(
      collectionStartedAtMs,
      nowMs,
      itemEffects.warDrumsStartedAtMs,
      itemEffects.warDrumsExpiresAtMs
    );
    const collectionTroopGainFloat = stats.troopProductionPerSecond * collectionElapsedSeconds
      + stats.baseTroopProductionPerHour / 3600
        * collectionWarDrumsOverlapSeconds
        * WAR_DRUMS_TROOP_PRODUCTION_BONUS_PERCENT / 100;
    const cityTroopsGained = getIntegerProductionGain(
      nextTroopFloat - collectionTroopGainFloat,
      collectionTroopGainFloat
    );
    const pendingWarDrumsOverlapSeconds = getTimedProductionBoostOverlapSeconds(
      pendingCollectionStartedAtMs,
      nowMs,
      itemEffects.warDrumsStartedAtMs,
      itemEffects.warDrumsExpiresAtMs
    );
    const pendingTroopGainFloat = stats.troopProductionPerSecond * pendingCollectionElapsedSeconds
      + stats.baseTroopProductionPerHour / 3600
        * pendingWarDrumsOverlapSeconds
        * WAR_DRUMS_TROOP_PRODUCTION_BONUS_PERCENT / 100;
    const pendingCityTroopsGained = getIntegerProductionGain(
      nextTroopFloat - pendingTroopGainFloat,
      pendingTroopGainFloat
    );
    goldGainFloat += stats.goldProductionPerSecond * goldElapsedSeconds
      + stats.baseGoldProductionPerHour / 3600
        * taxDecreeOverlapSeconds
        * ROYAL_TAX_DECREE_GOLD_PRODUCTION_BONUS_PERCENT / 100;
    const pendingTaxDecreeOverlapSeconds = getTimedProductionBoostOverlapSeconds(
      pendingGoldStartedAtMs,
      nowMs,
      itemEffects.royalTaxDecreeStartedAtMs,
      itemEffects.royalTaxDecreeExpiresAtMs
    );
    pendingGoldGainFloat += stats.goldProductionPerSecond * pendingGoldElapsedSeconds
      + stats.baseGoldProductionPerHour / 3600
        * pendingTaxDecreeOverlapSeconds
        * ROYAL_TAX_DECREE_GOLD_PRODUCTION_BONUS_PERCENT / 100;
    troopsGained += cityTroopsGained;
    if (pendingCityTroopsGained > 0) {
      const cityKey = getReinforcementTargetKey("city", city.regionId, city.id);
      troopsByCity[cityKey] = pendingCityTroopsGained;
    }
    const patch = {
      troops: nextTroops,
      troopFloat: nextTroopFloat,
      productionUpdatedAtMs: nowMs,
    };
    if (elapsedSeconds > 0 || !timestampToMs(city.productionUpdatedAtMs)) {
      cityUpdates.push({
        id: city.id,
        regionId: city.regionId,
        ...patch,
      });
      entry.city = {
        ...city,
        ...patch,
      };
    }
    const shouldCheckpointCity = !timestampToMs(city.productionUpdatedAtMs)
      || nowMs - lastProductionAtMs >= ECONOMY_CITY_CHECKPOINT_MS;
    if (shouldCheckpointCity) {
      productionCityPatches.push({ ref: entry.ref, city, patch });
    }
  });
  const sharedCheckpointWriteBudget = options.sharedCheckpointWriteBudget;
  const perCollectionCheckpointWriteBudget = clampInt(
    options.checkpointWriteBudget ?? ECONOMY_MAX_CITY_CHECKPOINT_WRITES,
    0,
    ECONOMY_MAX_CITY_CHECKPOINT_WRITES
  );
  const checkpointWriteBudget = clampInt(
    sharedCheckpointWriteBudget && typeof sharedCheckpointWriteBudget === "object"
      ? Math.min(sharedCheckpointWriteBudget.remaining, perCollectionCheckpointWriteBudget)
      : perCollectionCheckpointWriteBudget,
    0,
    ECONOMY_MAX_CITY_CHECKPOINT_WRITES
  );
  const priorityCheckpointPaths = new Set((Array.isArray(options.checkpointPriorityRefs)
    ? options.checkpointPriorityRefs
    : [])
    .map(ref => safeString(ref?.path || ref, 240))
    .filter(Boolean));
  const mandatoryCheckpointByPath = new Map();
  cityPatches.forEach(entry => {
    if (!entry?.ref || !entry.patch) return;
    const path = safeString(entry.ref.path, 240);
    if (!path) return;
    const previous = mandatoryCheckpointByPath.get(path);
    mandatoryCheckpointByPath.set(path, previous
      ? {
        ref: entry.ref,
        city: { ...(previous.city || {}), ...(entry.city || {}) },
        patch: { ...(previous.patch || {}), ...entry.patch },
      }
      : entry);
  });
  const optionalCheckpointByPath = new Map();
  productionCityPatches.forEach(entry => {
    if (!entry?.ref || !entry.patch) return;
    const path = safeString(entry.ref.path, 240);
    if (!path) return;
    const mandatory = mandatoryCheckpointByPath.get(path);
    if (mandatory) {
      mandatoryCheckpointByPath.set(path, {
        ref: entry.ref,
        city: { ...(mandatory.city || {}), ...(entry.city || {}) },
        patch: { ...(mandatory.patch || {}), ...entry.patch },
      });
      return;
    }
    const previous = optionalCheckpointByPath.get(path);
    optionalCheckpointByPath.set(path, previous
      ? {
        ref: entry.ref,
        city: { ...(previous.city || {}), ...(entry.city || {}) },
        patch: { ...(previous.patch || {}), ...entry.patch },
      }
      : entry);
  });
  const mandatoryCheckpoints = [...mandatoryCheckpointByPath.values()];
  const optionalCheckpoints = [...optionalCheckpointByPath.entries()]
    .sort(([leftPath], [rightPath]) => (
      Number(priorityCheckpointPaths.has(rightPath)) - Number(priorityCheckpointPaths.has(leftPath))
    ))
    .map(([, entry]) => entry);
  const optionalCheckpointWriteBudget = Math.max(
    0,
    checkpointWriteBudget - mandatoryCheckpoints.length
  );
  cityPatches.length = 0;
  cityPatches.push(
    ...mandatoryCheckpoints,
    ...optionalCheckpoints.slice(0, optionalCheckpointWriteBudget)
  );
  if (sharedCheckpointWriteBudget && typeof sharedCheckpointWriteBudget === "object") {
    sharedCheckpointWriteBudget.remaining = Math.max(
      0,
      clampInt(sharedCheckpointWriteBudget.remaining, 0, ECONOMY_MAX_CITY_CHECKPOINT_WRITES)
        - cityPatches.length
    );
  }

  const goldFloat = baseGold + goldGainFloat;
  const gold = Math.max(0, Math.floor(goldFloat));
  const goldGained = getIntegerProductionGain(baseGold, goldGainFloat);
  const pendingGoldGained = getIntegerProductionGain(
    goldFloat - pendingGoldGainFloat,
    pendingGoldGainFloat
  );
  const pendingAwayProduction = addPendingAwayProduction(pendingAwayProductionBefore, {
    goldGained: pendingGoldGained,
    troopsByCity,
    startedAtMs: Math.max(lastEconomyAtMs, productionObservedAtMs),
  }, nowMs);
  const scoutReports = pruneExpiredScoutReportMap(rawProfile.scoutReports, nowMs);
  const battleReports = pruneExpiredBattleScoutReports(rawProfile.battleReports, nowMs);
  const gear = normalizeCommonGear(rawProfile);
  const profileAfter = {
    ...rawProfile,
    character,
    upgrades,
    freeSkillResetGrantVersion: freeSkillResetState.version,
    freeSkillResetCredits: freeSkillResetState.credits,
    gold,
    goldFloat,
    shopItems,
    itemEffects,
    itemPurchaseCooldowns,
    pendingAwayProduction,
    scoutReports,
    battleReports,
    gear,
    ...mainCityRepair.profileFields,
    economyUpdatedAtMs: economyRevisionMs,
  };
  const globalStatsRef = playerGlobalStatsRef(uid);
  const globalStats = createGlobalStatsSnapshot({
    uid,
    profile: profileAfter,
    cityEntries,
    heldCamps,
    activeArmies,
    bonuses,
    nowMs,
  });
  const profilePatch = {
    uid,
    resetGeneration: rawProfile.resetGeneration || RESET_GENERATION,
    worldId: rawProfile.worldId || ONLINE_WORLD_ID,
    gold,
    goldFloat,
    character,
    upgrades,
    freeSkillResetGrantVersion: freeSkillResetState.version,
    freeSkillResetCredits: freeSkillResetState.credits,
    shopItems,
    itemEffects,
    itemPurchaseCooldowns,
    pendingAwayProduction,
    gear,
    ...(scoutReports !== rawProfile.scoutReports ? { scoutReports } : {}),
    ...(battleReports !== rawProfile.battleReports ? { battleReports } : {}),
    ...mainCityRepair.profileFields,
    ...objectiveBenefits.profilePatch,
    economyUpdatedAtMs: economyRevisionMs,
  };

  return {
    uid,
    profileRef,
    profileSnap,
    profileBefore: rawProfile,
    profileAfter,
    profilePatch,
    globalStatsRef,
    globalStats,
    activeArmies,
    heldCamps,
    cityEntries,
    cityPatches,
    cityUpdates,
    bonuses,
    gold,
    goldFloat,
    shopItems,
    itemEffects,
    itemPurchaseCooldowns,
    production: {
      goldGained,
      troopsGained,
      elapsedSeconds: Math.floor(maxElapsedSeconds),
      cityCount: cityEntries.filter(entry => !isStronghold(entry.city)).length,
    },
    productionByCity: troopsByCity,
    pendingAwayProduction,
  };
}

function createPatchedCityEntriesForStats(economy = null, extraCityPatches = []) {
  const byPath = new Map();
  (economy?.cityEntries || []).forEach(entry => {
    if (!entry?.ref || !entry.city) return;
    byPath.set(getCityEntryPath(entry), {
      ref: entry.ref,
      city: { ...entry.city },
    });
  });
  [...(economy?.cityPatches || []), ...(Array.isArray(extraCityPatches) ? extraCityPatches : [])].forEach(entry => {
    if (!entry?.ref || !entry.patch) return;
    const path = safeString(entry.ref.path, 240);
    const existing = byPath.get(path) || { ref: entry.ref, city: { ...(entry.city || {}), id: entry.city?.id || entry.ref.id } };
    byPath.set(path, {
      ref: entry.ref,
      city: {
        ...existing.city,
        ...(entry.city || {}),
        ...entry.patch,
        id: existing.city.id || entry.city?.id || entry.ref.id,
        islandId: existing.city.islandId || safeString(entry.ref.parent?.parent?.id, 160),
        regionId: normalizeRegionId(existing.city.regionId || entry.city?.regionId || getRegionIdFromOnlineIslandId(entry.ref.parent?.parent?.id)),
      },
    });
  });
  return [...byPath.values()];
}

function createPatchedActiveArmiesForStats(economy = null, options = {}) {
  const byId = new Map();
  (economy?.activeArmies || []).forEach(army => {
    const key = getArmyStatsKey(army);
    if (key) byId.set(key, { ...army });
  });
  (Array.isArray(options.addActiveArmies) ? options.addActiveArmies : []).forEach(army => {
    const key = getArmyStatsKey(army);
    if (key) byId.set(key, { ...army, status: army.status || "active" });
  });
  (Array.isArray(options.armyPatches) ? options.armyPatches : []).forEach(patch => {
    const key = getArmyStatsKey(patch);
    if (!key) return;
    const next = { ...(byId.get(key) || {}), ...patch, id: key };
    if (next.status !== "active") byId.delete(key);
    else byId.set(key, next);
  });
  (Array.isArray(options.excludeArmyIds) ? options.excludeArmyIds : []).forEach(id => {
    byId.delete(safeString(id, 96));
  });
  return [...byId.values()].filter(army => army.status === "active");
}

function createPreparedEconomyStatsSnapshot(economy = null, profileOverrides = {}, options = {}) {
  if (!economy?.uid) return null;
  const profile = {
    ...(economy.profileAfter || {}),
    ...(profileOverrides || {}),
  };
  return createGlobalStatsSnapshot({
    uid: economy.uid,
    profile,
    cityEntries: createPatchedCityEntriesForStats(economy, options.extraCityPatches),
    heldCamps: economy.heldCamps,
    activeArmies: createPatchedActiveArmiesForStats(economy, options),
    bonuses: economy.bonuses || null,
    nowMs: options.nowMs || Date.now(),
  });
}

function writeGlobalStatsFromEconomy(transaction, economy = null, profileOverrides = {}, extraCityPatches = [], options = {}) {
  if (!economy?.uid || !economy.globalStatsRef) return null;
  const profile = {
    ...(economy.profileAfter || {}),
    ...(profileOverrides || {}),
  };
  const stats = createPreparedEconomyStatsSnapshot(economy, profileOverrides, {
    ...options,
    extraCityPatches,
  });
  transaction.set(economy.globalStatsRef, stats, { merge: true });
  transaction.set(leaderboardEntryRef(economy.uid), {
    uid: economy.uid,
    worldId: ONLINE_WORLD_ID,
    resetGeneration: RESET_GENERATION,
    displayName: normalizePlayerName(profile.playerName || profile.displayName),
    playerName: normalizePlayerName(profile.playerName || profile.displayName),
    flag: normalizeServerFlag(profile.flag, economy.uid) || PLAYER_FLAG_CONFIG.createDeterministicFlag(economy.uid),
    kingPower: stats.kingPower,
    kingPowerVersion: GLOBAL_PLAYER_STATS_VERSION,
    kingPowerUpdatedAtMs: stats.updatedAtMs,
    cityCount: stats.totalCities,
    totalTroops: stats.totalTroops,
    totalCampTroops: stats.totalCampTroops,
    totalMarchingTroops: stats.totalMarchingTroops,
    totalReinforcementTroops: stats.totalReinforcementTroops,
    armyPower: stats.armyPower,
    reinforcementTroopPower: stats.reinforcementTroopPower,
    replacementPower: stats.replacementPower,
    defensivePower: stats.defensivePower,
    goldPerHour: stats.goldPerHour,
    troopPerHour: stats.troopPerHour,
    sustainableTroopPerHour: stats.sustainableTroopPerHour,
    strongholdTroopBonusPercent: stats.strongholdTroopBonusPercent,
    strongholdDefenseBonusPercent: stats.strongholdDefenseBonusPercent,
    strongholdCount: stats.strongholdCount,
    mainCityId: stats.mainCityId,
    mainRegionId: stats.mainRegionId,
    mainIslandId: stats.mainIslandId,
    updatedAtMs: stats.updatedAtMs,
    updatedAt: FieldValue.serverTimestamp(),
  }, { merge: true });
  economy.lastGlobalStats = stats;
  return stats;
}

function writePreparedEconomy(transaction, economy, profileOverrides = {}, extraCityPatches = [], options = {}) {
  if (!economy) return null;
  economy.cityPatches.forEach(entry => {
    transaction.set(entry.ref, cleanCityUpdate(entry.city, entry.patch), { merge: true });
  });
  extraCityPatches.forEach(entry => {
    if (!entry?.ref || !entry.patch) return;
    transaction.set(entry.ref, cleanCityUpdate(entry.city || {}, entry.patch), { merge: true });
  });
  const statsCityPatches = Array.isArray(options.statsCityPatches) ? options.statsCityPatches : [];
  const stats = writeGlobalStatsFromEconomy(transaction, economy, profileOverrides, [
    ...extraCityPatches,
    ...statsCityPatches,
  ], options);
  transaction.set(economy.profileRef, {
    ...economy.profilePatch,
    ...profileOverrides,
    ...(stats ? {
      kingPower: stats.kingPower,
      kingPowerVersion: GLOBAL_PLAYER_STATS_VERSION,
      kingPowerUpdatedAtMs: stats.updatedAtMs,
    } : {}),
    updatedAt: FieldValue.serverTimestamp(),
  }, { merge: true });
  if (economy.profileSnap?.exists) {
    if (economy.profilePatch.scoutReports !== undefined) {
      deleteRemovedScoutReportEntries(
        transaction,
        economy.profileRef,
        economy.profileBefore?.scoutReports,
        economy.profilePatch.scoutReports
      );
    }
    transaction.update(economy.profileRef, addLegacyShopItemDeletes());
  }
  if (
    !options.suppressDailyMissionProduction
    && (Math.max(0, Math.floor(safeNumber(economy.production?.goldGained, 0))) > 0
      || Math.max(0, Math.floor(safeNumber(economy.production?.troopsGained, 0))) > 0)
  ) {
    enqueueDailyMissionEvent(transaction, {
      uid: economy.uid,
      eventId: `economy_${economy.uid}_${Math.max(0, Math.floor(safeNumber(economy.profilePatch?.economyUpdatedAtMs, options.nowMs || Date.now())))}`,
      type: "ECONOMY_PRODUCED",
      occurredAtMs: options.nowMs || economy.profilePatch?.economyUpdatedAtMs || Date.now(),
      goldProduced: economy.production?.goldGained,
      troopsProduced: economy.production?.troopsGained,
      productionFromMs: (options.nowMs || economy.profilePatch?.economyUpdatedAtMs || Date.now())
        - Math.max(0, Math.floor(safeNumber(economy.production?.elapsedSeconds, 0))) * 1000,
      productionToMs: options.nowMs || economy.profilePatch?.economyUpdatedAtMs || Date.now(),
    });
  }
  return stats;
}

async function rebuildGlobalStatsForPlayer(uid = "") {
  const playerUid = safeString(uid, 128);
  if (!playerUid) throw new HttpsError("invalid-argument", "A player uid is required.");
  const nowMs = Date.now();
  const profileRef = db.doc(`players/${playerUid}`);
  const [profileSnap, ownedSnap, activeArmiesSnap, heldCampsSnap] = await Promise.all([
    profileRef.get(),
    db.collectionGroup("cities")
      .where("ownerUid", "==", playerUid)
      .where("resetGeneration", "==", RESET_GENERATION)
      .where("worldId", "==", ONLINE_WORLD_ID)
      .get(),
    activeArmiesQueryForPlayer(playerUid).get(),
    heldRewardCampsQueryForPlayer(playerUid).get(),
  ]);
  const profile = profileSnap.exists ? profileSnap.data() || {} : {};
  const identity = getCanonicalPlayerIdentity(playerUid, profile, {}, {});
  const cityEntries = createOwnedCityEntriesFromSnapshot(playerUid, ownedSnap);
  const clanBenefitsSnap = identity.clanId
    ? await clanWorldBenefitsRef(identity.clanId).get()
    : null;
  const objectiveBonuses = combinePlayerObjectiveBonuses(
    playerUid,
    cityEntries,
    clanBenefitsSnap?.exists ? clanBenefitsSnap.data() || {} : null
  );
  const mainRepair = createMainCityAssignmentRepair(playerUid, profile, cityEntries);
  const activeArmyDocs = activeArmiesSnap.docs.filter(armyDoc => {
    const army = {
      id: safeString(armyDoc.data()?.id || armyDoc.id, 96),
      islandId: safeString(armyDoc.ref.parent?.parent?.id, 160),
      ...armyDoc.data(),
    };
    return isCurrentWorldArmy(army);
  });
  const activeArmies = createActiveArmiesFromSnapshot(playerUid, activeArmiesSnap);
  const heldCamps = createHeldCampEntriesFromSnapshot(playerUid, heldCampsSnap);
  const profileForStats = {
    ...profile,
    playerName: identity.ownerName,
    displayName: identity.ownerName,
    flag: identity.ownerFlag,
    ...mainRepair.profileFields,
  };
  const stats = createGlobalStatsSnapshot({
    uid: playerUid,
    profile: profileForStats,
    cityEntries,
    heldCamps,
    activeArmies,
    bonuses: objectiveBonuses,
    nowMs,
  });
  const mainRegionId = mainRepair.canonicalMainRegionId
    || normalizeRegionId(profile.mainRegionId || getRegionIdFromOnlineIslandId(profile.mainIslandId));
  const mainIslandId = mainRepair.canonicalMainIslandId || profile.mainIslandId || getOnlineIslandId(mainRegionId);
  const mainCityId = mainRepair.canonicalMainCityId || safeString(profile.mainCityId, 96);
  const writes = [
    {
      ref: profileRef,
      data: {
        uid: playerUid,
        worldId: ONLINE_WORLD_ID,
        resetGeneration: RESET_GENERATION,
        playerName: identity.ownerName,
        displayName: identity.ownerName,
        flag: identity.ownerFlag,
        clanId: identity.clanId,
        clanName: identity.clanName,
        clanTag: identity.clanTag,
        kingPower: stats.kingPower,
        kingPowerVersion: GLOBAL_PLAYER_STATS_VERSION,
        kingPowerUpdatedAtMs: nowMs,
        ...mainRepair.profileFields,
        updatedAt: FieldValue.serverTimestamp(),
      },
    },
    {
      ref: playerGlobalStatsRef(playerUid),
      data: stats,
    },
    {
      ref: leaderboardEntryRef(playerUid),
      data: {
        uid: playerUid,
        worldId: ONLINE_WORLD_ID,
        resetGeneration: RESET_GENERATION,
        displayName: identity.ownerName,
        playerName: identity.ownerName,
        flag: identity.ownerFlag,
        clanId: identity.clanId,
        clanName: identity.clanName,
        clanTag: identity.clanTag,
        kingPower: stats.kingPower,
        kingPowerVersion: GLOBAL_PLAYER_STATS_VERSION,
        kingPowerUpdatedAtMs: nowMs,
        cityCount: stats.totalCities,
        totalTroops: stats.totalTroops,
        totalCampTroops: stats.totalCampTroops,
        totalMarchingTroops: stats.totalMarchingTroops,
        totalReinforcementTroops: stats.totalReinforcementTroops,
        armyPower: stats.armyPower,
        reinforcementTroopPower: stats.reinforcementTroopPower,
        replacementPower: stats.replacementPower,
        defensivePower: stats.defensivePower,
        goldPerHour: stats.goldPerHour,
        troopPerHour: stats.troopPerHour,
        sustainableTroopPerHour: stats.sustainableTroopPerHour,
        strongholdTroopBonusPercent: stats.strongholdTroopBonusPercent,
        strongholdDefenseBonusPercent: stats.strongholdDefenseBonusPercent,
        strongholdCount: stats.strongholdCount,
        mainCityId,
        mainRegionId,
        mainIslandId,
        updatedAtMs: nowMs,
        updatedAt: FieldValue.serverTimestamp(),
      },
    },
  ];

  cityEntries.forEach(entry => {
    writes.push({
      ref: entry.ref,
      data: {
        ownerKind: "player",
        ownerUid: playerUid,
        ownerName: identity.ownerName,
        ownerFlag: identity.ownerFlag,
        ownerKingPower: stats.kingPower,
        kingPowerVersion: GLOBAL_PLAYER_STATS_VERSION,
        updatedAt: FieldValue.serverTimestamp(),
      },
    });
  });
  activeArmyDocs.forEach(armyDoc => {
    writes.push({
      ref: armyDoc.ref,
      data: {
        ownerName: identity.ownerName,
        ownerFlag: identity.ownerFlag,
        ownerKingPower: stats.kingPower,
        attackerKingPower: stats.kingPower,
        kingPowerVersion: GLOBAL_PLAYER_STATS_VERSION,
        updatedAt: FieldValue.serverTimestamp(),
      },
    });
  });
  mainRepair.cityPatches.forEach(entry => {
    writes.push({
      ref: entry.ref,
      data: cleanCityUpdate(entry.city, entry.patch),
    });
  });

  for (let index = 0; index < writes.length; index += 450) {
    const batch = db.batch();
    writes.slice(index, index + 450).forEach(write => {
      batch.set(write.ref, write.data, { merge: true });
    });
    await batch.commit();
  }

  return {
    uid: playerUid,
    stats: globalStatsForClient(stats),
    cityUpdates: cityEntries.length,
    armyUpdates: activeArmyDocs.length,
    mainCityRepairs: mainRepair.cityPatches.length,
  };
}

function createEconomyResponse(economy = null, overrides = {}) {
  if (!economy) return { ok: true };
  const globalStats = globalStatsForClient(overrides.globalStats || economy.lastGlobalStats || economy.globalStats);
  const {
    gold,
    goldFloat,
    shopItems,
    itemEffects,
    itemPurchaseCooldowns,
    character,
    upgrades,
    skillPresets,
    gear,
    daily,
    dailyLoginReward,
    harvestBonuses,
    harvestSpawnTimer,
    harvestNextSpawnAtMs,
    harvestNextBonusType,
    cityUpdates,
    globalStats: _globalStats,
    ...meta
  } = overrides;
  const resolvedHarvestBonuses = harvestBonuses !== undefined
    ? harvestBonuses
    : economy.profileAfter.harvestBonuses;
  const resolvedHarvestNextSpawnAtMs = timestampToMs(
    harvestNextSpawnAtMs !== undefined ? harvestNextSpawnAtMs : economy.profileAfter.harvestNextSpawnAtMs
  );
  const currentUser = {
    gold: Math.max(0, Math.floor(safeNumber(gold, economy.gold))),
    goldFloat: Math.max(0, safeNumber(goldFloat, gold ?? economy.goldFloat)),
    economyUpdatedAtMs: Math.max(0, timestampToMs(economy.profilePatch?.economyUpdatedAtMs)),
    shopItems: shopItems || economy.shopItems,
    itemEffects: itemEffects || economy.itemEffects,
    itemPurchaseCooldowns: itemPurchaseCooldowns || economy.itemPurchaseCooldowns,
    gear: normalizeCommonGear(gear !== undefined ? gear : economy.profileAfter),
    character: character || economy.profileAfter.character || null,
    upgrades: upgrades || normalizeSkillUpgrades(economy.profileAfter.upgrades),
    skillPresets: normalizeSkillPresets(
      skillPresets !== undefined ? skillPresets : economy.profileAfter.skillPresets
    ),
    freeSkillResetGrantVersion: Math.max(0, Math.floor(safeNumber(
      overrides.freeSkillResetGrantVersion,
      economy.profileAfter.freeSkillResetGrantVersion
    ))),
    freeSkillResetCredits: Math.max(0, Math.floor(safeNumber(
      overrides.freeSkillResetCredits,
      economy.profileAfter.freeSkillResetCredits
    ))),
    mainCityId: safeString(economy.profileAfter.mainCityId, 96),
    mainIslandId: safeString(economy.profileAfter.mainIslandId, 160),
    mainRegionId: normalizeRegionId(economy.profileAfter.mainRegionId || getRegionIdFromOnlineIslandId(economy.profileAfter.mainIslandId)),
    mainCityChangedAtMs: timestampToMs(economy.profileAfter.mainCityChangedAtMs),
    lastCityRelinquishedAtMs: timestampToMs(economy.profileAfter.lastCityRelinquishedAtMs),
  };
  if (globalStats) currentUser.globalStats = globalStats;
  if (daily !== undefined) currentUser.daily = normalizeDaily(daily);
  if (dailyLoginReward !== undefined) {
    currentUser.dailyLoginReward = normalizeDailyLoginRewardState(dailyLoginReward);
  }
  if (resolvedHarvestBonuses !== undefined) currentUser.harvestBonuses = enforceHarvestBonusActiveLimit(resolvedHarvestBonuses);
  if (harvestSpawnTimer !== undefined) {
    currentUser.harvestSpawnTimer = clampInt(harvestSpawnTimer, 0, HARVEST_BONUS_SPAWN_INTERVAL_SECONDS);
  }
  if (resolvedHarvestNextSpawnAtMs) {
    currentUser.harvestNextSpawnAtMs = resolvedHarvestNextSpawnAtMs;
    if (harvestSpawnTimer === undefined) {
      currentUser.harvestSpawnTimer = getHarvestSpawnTimerFromNextAt(resolvedHarvestNextSpawnAtMs);
    }
  }
  if (harvestNextBonusType !== undefined) {
    currentUser.harvestNextBonusType = normalizeHarvestBonusType(harvestNextBonusType);
  } else if (economy.profileAfter.harvestNextBonusType !== undefined) {
    currentUser.harvestNextBonusType = normalizeHarvestBonusType(economy.profileAfter.harvestNextBonusType);
  }
  return {
    ok: true,
    currentUser,
    ...(globalStats ? { globalStats } : {}),
    cityUpdates: cityUpdates || economy.cityUpdates,
    production: economy.production,
    ...meta,
  };
}

function normalizeWelcomeBackSummary(raw = null) {
  if (!raw || typeof raw !== "object") return null;
  const lostCities = (Array.isArray(raw.lostCities) ? raw.lostCities : [])
    .slice(0, 50)
    .map(city => ({
      id: safeString(city?.id, 96),
      name: safeString(city?.name, 80),
      regionId: normalizeRegionId(city?.regionId),
      kind: safeString(city?.kind, 40),
      lostAtMs: Math.max(0, Math.floor(safeNumber(city?.lostAtMs, 0))),
    }))
    .filter(city => city.id && city.regionId);
  return {
    version: WELCOME_BACK_SUMMARY_VERSION,
    elapsedSeconds: Math.max(0, Math.floor(safeNumber(raw.elapsedSeconds, 0))),
    goldGained: Math.max(0, Math.floor(safeNumber(raw.goldGained, 0))),
    troopsGained: Math.max(0, Math.floor(safeNumber(raw.troopsGained, 0))),
    lostCityCount: Math.max(lostCities.length, Math.floor(safeNumber(raw.lostCityCount, lostCities.length))),
    lostCities,
  };
}

function getServerWorldCityNode(regionId = "", cityId = "") {
  const map = getServerWorldMap(regionId);
  const targets = [
    ...(Array.isArray(map?.cities) ? map.cities : []),
    ...(Array.isArray(map?.objectives) ? map.objectives : []),
  ];
  return targets.find(target => safeString(target?.id, 96) === safeString(cityId, 96)) || null;
}

function createWelcomeBackLostCityList(lossSnapshot = null, economy = null) {
  const currentlyOwnedKeys = new Set((economy?.cityEntries || []).map(entry => (
    getReinforcementTargetKey("city", entry?.city?.regionId, entry?.city?.id)
  )));
  const lostByTargetKey = new Map();
  (lossSnapshot?.docs || []).forEach(doc => {
    const event = doc.data() || {};
    if (safeString(event.reason, 64) !== "city_captured" || event.targetType !== "city") return;
    const id = safeString(event.targetId, 96);
    const regionId = normalizeRegionId(event.regionId);
    const targetKey = getReinforcementTargetKey("city", regionId, id);
    if (!id || currentlyOwnedKeys.has(targetKey)) return;
    const configured = getServerWorldCityNode(regionId, id) || { id, regionId };
    const kind = safeString(
      configured.kind || configured.strongholdType || configured.type || (isStronghold(configured) ? "stronghold" : "city"),
      40
    );
    lostByTargetKey.set(targetKey, {
      id,
      name: getServerCanonicalCityName({ ...configured, id }, regionId),
      regionId,
      kind,
      lostAtMs: Math.max(0, timestampToMs(event.createdAtMs || event.createdAt)),
    });
  });
  return [...lostByTargetKey.values()].sort((left, right) => (
    left.lostAtMs - right.lostAtMs || left.id.localeCompare(right.id)
  ));
}

function createWelcomeBackSummary(economy = null, welcomeBack = null, lossSnapshot = null) {
  const session = normalizeWelcomeBackSession(welcomeBack);
  if (!economy || !session.sessionStartedAtMs || !session.awayStartedAtMs) return null;
  const pending = normalizePendingAwayProduction(economy.pendingAwayProduction);
  const ownedCitiesByKey = new Map((economy.cityEntries || []).map(entry => [
    getReinforcementTargetKey("city", entry?.city?.regionId, entry?.city?.id),
    entry?.city || {},
  ]));
  const troopsGained = Object.entries(pending.troopsByCity).reduce((total, [key, rawTroops]) => {
    const city = ownedCitiesByKey.get(key);
    if (!city) return total;
    return total + Math.min(
      Math.max(0, Math.floor(safeNumber(rawTroops, 0))),
      Math.max(0, Math.floor(safeNumber(city.troops, 0)))
    );
  }, 0);
  const lostCities = createWelcomeBackLostCityList(lossSnapshot, economy);
  return normalizeWelcomeBackSummary({
    elapsedSeconds: Math.floor(Math.max(0, session.sessionStartedAtMs - session.awayStartedAtMs) / 1000),
    goldGained: pending.goldGained,
    troopsGained,
    lostCityCount: lostCities.length,
    lostCities,
  });
}

function getRewardedAdBaseRates(economy = null) {
  if (!economy) return { goldPerHour: 0, troopsPerHour: 0 };
  return economy.cityEntries.reduce((totals, entry) => {
    const city = entry?.city || {};
    if (isStronghold(city) || getOwnerUid(city) !== economy.uid) return totals;
    const stats = getCityProductionStats(city, economy.profileAfter, {}, {
      includeStrongholdBoosts: false,
      includeWarDrums: false,
      includeRoyalTaxDecree: false,
    });
    totals.goldPerHour += Math.max(0, safeNumber(stats.baseGoldProductionPerHour, 0));
    totals.troopsPerHour += Math.max(0, safeNumber(stats.baseTroopProductionPerHour, 0));
    return totals;
  }, { goldPerHour: 0, troopsPerHour: 0 });
}

function getRewardedAdRewardAmount(baseRatePerHour = 0) {
  return Math.max(
    0,
    Math.floor(Math.max(0, safeNumber(baseRatePerHour, 0)) * REWARDED_AD_REWARD_MINUTES / 60)
  );
}

function getRewardedAdPreviewRewardsFromStats(stats = {}) {
  return {
    gold: getRewardedAdRewardAmount(stats?.baseGoldPerHour),
    troops: getRewardedAdRewardAmount(stats?.baseTroopPerHour),
  };
}

function getHarvestBonusReward(economy = null, type = "gold") {
  const rates = getRewardedAdBaseRates(economy);
  if (type === "troops") {
    const passiveTroops = Math.floor(rates.troopsPerHour * HARVEST_BONUS_TROOP_SECONDS / 3600);
    return clampInt(
      Math.max(HARVEST_BONUS_MIN_TROOPS, passiveTroops),
      HARVEST_BONUS_MIN_TROOPS,
      HARVEST_BONUS_MAX_TROOPS
    );
  }
  const passiveGold = Math.floor(rates.goldPerHour * HARVEST_BONUS_GOLD_SECONDS / 3600);
  return Math.max(HARVEST_BONUS_MIN_GOLD, passiveGold);
}

function removeHarvestBonusFromProfile(profile = {}, bonusId = "") {
  const id = safeString(bonusId, 96);
  if (!id || !Array.isArray(profile.harvestBonuses)) return Array.isArray(profile.harvestBonuses) ? profile.harvestBonuses : [];
  return profile.harvestBonuses.filter(bonus => safeString(bonus?.id, 96) !== id);
}

function createIncomingArmyNotification({ defenderUid = "", attackerUid = "", movement = {}, source = {}, target = {} } = {}) {
  const kind = movement.kind === "scout"
    ? "scout"
    : movement.kind === "attack"
      ? "attack"
      : movement.kind === "reinforce"
        ? "reinforce"
        : "";
  if (!defenderUid || !attackerUid || defenderUid === attackerUid || !kind) return null;
  const attackerName = normalizePlayerName(movement.ownerName || source.ownerName, "A rival ruler");
  const sourceName = safeString(movement.fromName || source.name || movement.fromId || "Unknown city", 40);
  const targetName = safeString(movement.toName || target.name || movement.toId || "your city", 40);
  const title = kind === "scout" ? "Scout incoming" : kind === "reinforce" ? "Clan reinforcement incoming" : "Attack incoming";
  const troopEstimate = ["attack", "reinforce"].includes(kind)
    ? getIncomingTroopEstimate(movement.troops)
    : null;
  const body = kind === "scout"
    ? `${attackerName} is scouting ${targetName} from ${sourceName}.`
    : kind === "reinforce"
      ? `${attackerName} is reinforcing ${targetName} with an estimated ${troopEstimate.label} troops.`
      : `${attackerName} is attacking ${targetName} with an estimated ${troopEstimate.label} troops.`;
  const notification = {
    defenderUid,
    attackerUid,
    title,
    body,
    kind,
    armyId: safeString(movement.id, 96),
    cityId: safeString(movement.toId, 96),
    sourceCityId: safeString(movement.fromId, 96),
    targetRegionId: normalizeRegionId(movement.targetRegionId || target.regionId || target.startPool),
    sourceRegionId: normalizeRegionId(movement.sourceRegionId || source.regionId || source.startPool),
    targetName,
    sourceName,
    attackerName,
    troopVisibility: ["attack", "reinforce"].includes(kind) ? "estimate" : "exact",
    troopEstimateMin: troopEstimate ? String(troopEstimate.min) : "",
    troopEstimateMax: troopEstimate ? String(troopEstimate.max) : "",
    troopEstimateLabel: troopEstimate?.label || "",
    arrivesAtMs: String(Math.max(0, Math.floor(safeNumber(movement.arrivesAtMs, 0)))),
    url: "/",
  };
  return notification;
}

function isInvalidMessagingTokenError(error = {}) {
  const code = String(error.code || error.errorInfo?.code || "");
  return code === "messaging/registration-token-not-registered"
    || code === "messaging/invalid-registration-token"
    || code === "messaging/invalid-argument";
}

async function removeNotificationTokenDocs(uid, tokenDocIds = []) {
  const uniqueIds = [...new Set(tokenDocIds.filter(Boolean))];
  if (!uid || !uniqueIds.length) return;
  const batch = db.batch();
  uniqueIds.forEach(tokenId => {
    batch.delete(db.doc(`players/${uid}/notificationTokens/${tokenId}`));
  });
  await batch.commit();
}

async function sendIncomingArmyNotification(notification = {}) {
  const defenderUid = safeString(notification.defenderUid, 128);
  if (!defenderUid) return false;
  const tokenSnap = await db.collection(`players/${defenderUid}/notificationTokens`)
    .where("enabled", "==", true)
    .limit(100)
    .get();
  if (tokenSnap.empty) return false;

  const tokenDocs = tokenSnap.docs
    .map(doc => ({ id: doc.id, token: safeString(doc.data()?.token, 512) }))
    .filter(entry => entry.token);
  if (!tokenDocs.length) return false;

  const data = {
    type: "incoming_army",
    title: safeString(notification.title, 80),
    body: safeString(notification.body, 180),
    kind: safeString(notification.kind, 16),
    armyId: safeString(notification.armyId, 96),
    cityId: safeString(notification.cityId, 96),
    sourceCityId: safeString(notification.sourceCityId, 96),
    targetRegionId: safeString(notification.targetRegionId, 80),
    sourceRegionId: safeString(notification.sourceRegionId, 80),
    targetName: safeString(notification.targetName, 60),
    sourceName: safeString(notification.sourceName, 60),
    attackerName: safeString(notification.attackerName, 60),
    troopVisibility: safeString(notification.troopVisibility, 16),
    troopEstimateMin: safeString(notification.troopEstimateMin, 32),
    troopEstimateMax: safeString(notification.troopEstimateMax, 32),
    troopEstimateLabel: safeString(notification.troopEstimateLabel, 40),
    arrivesAtMs: safeString(notification.arrivesAtMs, 32),
    url: safeString(notification.url || "/", 160),
  };
  if (notification.troops !== undefined) {
    data.troops = safeString(notification.troops, 32);
  }

  const messages = tokenDocs.map(entry => ({
    token: entry.token,
    data,
    webpush: {
      headers: {
        TTL: "1800",
        Urgency: data.kind === "attack" ? "high" : "normal",
      },
      fcmOptions: {
        link: data.url,
      },
    },
  }));

  const result = await messaging.sendEach(messages);
  const invalidTokenDocIds = [];
  result.responses.forEach((response, index) => {
    if (!response.success && isInvalidMessagingTokenError(response.error)) {
      invalidTokenDocIds.push(tokenDocs[index]?.id);
    }
  });
  if (invalidTokenDocIds.length) {
    await removeNotificationTokenDocs(defenderUid, invalidTokenDocIds).catch(error => {
      console.warn("Could not remove invalid notification tokens", error);
    });
  }
  return result.successCount > 0;
}

function queueIncomingArmyNotification(transaction, armyId = "", notification = null, nowMs = Date.now()) {
  const notificationId = safeString(`incoming_${armyId}`, 180).replace(/[^a-zA-Z0-9_-]/g, "_");
  if (!transaction || !notificationId || !notification?.defenderUid) return false;
  transaction.set(db.doc(`serverNotificationOutbox/${notificationId}`), {
    type: "incoming_army",
    armyId: safeString(armyId, 96),
    notification,
    status: "pending",
    attempts: 0,
    createdAtMs: nowMs,
    expiresAtMs: nowMs + 7 * 24 * 60 * 60 * 1000,
    expiresAt: Timestamp.fromMillis(nowMs + 7 * 24 * 60 * 60 * 1000),
    createdAt: FieldValue.serverTimestamp(),
    updatedAt: FieldValue.serverTimestamp(),
  }, { merge: false });
  return true;
}

async function cleanupExpiredNotificationOutbox(nowMs = Date.now(), limit = 250) {
  const snapshot = await db.collection("serverNotificationOutbox")
    .where("expiresAtMs", "<=", nowMs)
    .limit(Math.max(1, Math.min(500, Math.floor(limit))))
    .get();
  if (snapshot.empty) return { removed: 0 };
  const batch = db.batch();
  snapshot.docs.forEach(doc => batch.delete(doc.ref));
  await batch.commit();
  return { removed: snapshot.size };
}

exports.deliverIncomingArmyNotification = onDocumentCreated({
  document: "serverNotificationOutbox/{notificationId}",
  region: "us-central1",
  retry: true,
}, async event => {
  const snapshot = event.data;
  if (!snapshot?.exists) return;
  const record = snapshot.data() || {};
  if (record.status === "delivered" || record.status === "skipped") return;
  const attempts = Math.max(0, Math.floor(safeNumber(record.attempts, 0))) + 1;
  try {
    const delivered = await sendIncomingArmyNotification(record.notification || {});
    await snapshot.ref.set({
      status: delivered ? "delivered" : "skipped",
      attempts,
      deliveredAtMs: Date.now(),
      lastError: FieldValue.delete(),
      updatedAt: FieldValue.serverTimestamp(),
    }, { merge: true });
  } catch (error) {
    await snapshot.ref.set({
      status: "pending",
      attempts,
      lastError: safeString(error?.message || error, 240),
      updatedAt: FieldValue.serverTimestamp(),
    }, { merge: true });
    throw error;
  }
});

function requireCommonGearInstance(gear, instanceId) {
  const id = safeString(instanceId, 128).replace(/[^a-zA-Z0-9_-]/g, "_");
  const instance = gear.instances[id];
  if (!instance) throw new HttpsError("not-found", "That gear piece is no longer available.");
  return instance;
}

function createCommonGearClientStatus(profile = {}, nowMs = Date.now()) {
  const gear = normalizeCommonGear(profile);
  const today = getUtcDateKey(nowMs);
  const purchasedToday = gear.shopPurchase.utcDate === today ? gear.shopPurchase.purchaseCount : 0;
  return {
    gear,
    bonuses: getCommonGearBonuses(gear),
    shop: {
      utcDate: today,
      purchaseCount: purchasedToday,
      dailyLimit: COMMON_GEAR.SHOP_DAILY_LIMIT,
      available: purchasedToday < COMMON_GEAR.SHOP_DAILY_LIMIT,
      price: COMMON_GEAR.SHOP_PRICE_GOLD,
      resetsAtMs: getNextUtcDayStartMs(nowMs),
    },
  };
}

exports.getCommonGearStatus = onCall({ region: "us-central1", maxInstances: 30, invoker: "public" }, async request => {
  const uid = requireAuth(request);
  const nowMs = Date.now();
  return runTransactionWithInfrastructureRetry(async transaction => {
    const economy = await prepareEconomyCollection(transaction, uid, nowMs);
    writePreparedEconomy(transaction, economy);
    return { ok: true, ...createCommonGearClientStatus(economy.profileAfter, nowMs), ...createEconomyResponse(economy) };
  });
});

exports.purchaseCommonGearBox = onCall({ region: "us-central1", maxInstances: 30, invoker: "public" }, async request => {
  const uid = requireAuth(request);
  const nowMs = Date.now();
  return runTransactionWithInfrastructureRetry(async transaction => {
    const economy = await prepareEconomyCollection(transaction, uid, nowMs);
    const status = createCommonGearClientStatus(economy.profileAfter, nowMs);
    if (!status.shop.available) throw new HttpsError("resource-exhausted", "You already bought today's Common Gear Box.");
    if (economy.goldFloat < status.shop.price) throw new HttpsError("failed-precondition", "Not enough gold for today's Common Gear Box.");
    const gear = status.gear;
    gear.commonGearBoxes += 1;
    gear.shopPurchase = { utcDate: status.shop.utcDate, purchaseCount: 1 };
    gear.updatedAtMs = nowMs;
    const goldFloat = economy.goldFloat - status.shop.price;
    const gold = Math.floor(goldFloat);
    writePreparedEconomy(transaction, economy, { gear, gold, goldFloat });
    return createEconomyResponse(economy, {
      gear, gold, goldFloat, purchased: true, spentGold: status.shop.price,
      commonGearStatus: createCommonGearClientStatus({ gear }, nowMs),
    });
  });
});

exports.openCommonGearBox = onCall({ region: "us-central1", maxInstances: 30, invoker: "public" }, async request => {
  const uid = requireAuth(request);
  const requestId = safeString(request.data?.requestId, 96).replace(/[^a-zA-Z0-9_-]/g, "_");
  if (!requestId) throw new HttpsError("invalid-argument", "A gear box request id is required.");
  const nowMs = Date.now();
  return runTransactionWithInfrastructureRetry(async transaction => {
    const profileRef = db.doc(`players/${uid}`);
    const profileSnap = await transaction.get(profileRef);
    if (!profileSnap.exists) throw new HttpsError("failed-precondition", "Claim a kingdom before opening gear.");
    const gear = normalizeCommonGear(profileSnap.data() || {});
    if (gear.lastOpenRequestId === requestId && gear.lastOpenReceipt) {
      return { ok: true, replayed: true, gear, receipt: gear.lastOpenReceipt };
    }
    if (gear.commonGearBoxes < 1) throw new HttpsError("failed-precondition", "You do not have a Common Gear Box.");
    gear.commonGearBoxes -= 1;
    const instanceIds = [];
    for (let index = 0; index < COMMON_GEAR.BOX_REVEAL_COUNT; index += 1) {
      const definition = COMMON_GEAR.DEFINITIONS[crypto.randomInt(0, COMMON_GEAR.DEFINITIONS.length)];
      const instanceId = `cg_${nowMs.toString(36)}_${crypto.randomBytes(8).toString("hex")}`;
      gear.instances[instanceId] = COMMON_GEAR.normalizeInstance({
        instanceId, gearKey: definition.gearKey, level: 1, isNew: true, acquiredAtMs: nowMs,
      });
      gear.newMarkers[definition.buildingId] = true;
      instanceIds.push(instanceId);
    }
    gear.lastOpenRequestId = requestId;
    gear.lastOpenReceipt = { requestId, openedAtMs: nowMs, instanceIds };
    gear.updatedAtMs = nowMs;
    transaction.set(profileRef, { gear, updatedAt: FieldValue.serverTimestamp() }, { merge: true });
    return { ok: true, replayed: false, gear, receipt: gear.lastOpenReceipt };
  });
});

exports.viewCommonGearBuilding = onCall({ region: "us-central1", maxInstances: 30, invoker: "public" }, async request => {
  const uid = requireAuth(request);
  const buildingId = safeString(request.data?.buildingId, 32);
  if (!COMMON_GEAR.BUILDINGS[buildingId]) throw new HttpsError("invalid-argument", "Unknown Inner Castle building.");
  return runTransactionWithInfrastructureRetry(async transaction => {
    const ref = db.doc(`players/${uid}`);
    const snap = await transaction.get(ref);
    if (!snap.exists) throw new HttpsError("failed-precondition", "Claim a kingdom before managing gear.");
    const gear = normalizeCommonGear(snap.data() || {});
    gear.newMarkers[buildingId] = false;
    Object.values(gear.instances).forEach(instance => {
      if (instance.buildingId === buildingId) instance.isNew = false;
    });
    gear.updatedAtMs = Date.now();
    transaction.set(ref, { gear }, { merge: true });
    return { ok: true, gear };
  });
});

async function mutateCommonGearLoadout(uid, request, mode) {
  const nowMs = Date.now();
  return runTransactionWithInfrastructureRetry(async transaction => {
    const economy = await prepareEconomyCollection(transaction, uid, nowMs);
    const gear = normalizeCommonGear(economy.profileAfter);
    const instance = requireCommonGearInstance(gear, request.data?.instanceId);
    if (mode === "equip") {
      const currentId = gear.equipped[instance.buildingId][instance.slot];
      if (currentId && gear.instances[currentId]) gear.instances[currentId].isEquipped = false;
      gear.equipped[instance.buildingId][instance.slot] = instance.instanceId;
      instance.isEquipped = true;
      instance.isNew = false;
    } else {
      if (!instance.isEquipped) throw new HttpsError("failed-precondition", "That gear piece is not equipped.");
      gear.equipped[instance.buildingId][instance.slot] = "";
      instance.isEquipped = false;
    }
    gear.updatedAtMs = nowMs;
    writePreparedEconomy(transaction, economy, { gear });
    return createEconomyResponse(economy, { gear, bonuses: getCommonGearBonuses(gear) });
  });
}

exports.equipCommonGear = onCall({ region: "us-central1", maxInstances: 30, invoker: "public" }, request => {
  const uid = requireAuth(request);
  return mutateCommonGearLoadout(uid, request, "equip");
});

exports.unequipCommonGear = onCall({ region: "us-central1", maxInstances: 30, invoker: "public" }, request => {
  const uid = requireAuth(request);
  return mutateCommonGearLoadout(uid, request, "unequip");
});

exports.upgradeCommonGear = onCall({ region: "us-central1", maxInstances: 30, invoker: "public" }, async request => {
  const uid = requireAuth(request);
  const nowMs = Date.now();
  return runTransactionWithInfrastructureRetry(async transaction => {
    const economy = await prepareEconomyCollection(transaction, uid, nowMs);
    const gear = normalizeCommonGear(economy.profileAfter);
    const instance = requireCommonGearInstance(gear, request.data?.instanceId);
    const requirement = COMMON_GEAR.getUpgradeRequirement(instance.level);
    if (!requirement) throw new HttpsError("failed-precondition", "Max Level Reached.");
    const materials = Object.values(gear.instances)
      .filter(candidate => candidate.instanceId !== instance.instanceId
        && candidate.gearKey === instance.gearKey
        && candidate.level === instance.level
        && !candidate.isEquipped)
      .sort((a, b) => a.acquiredAtMs - b.acquiredAtMs || a.instanceId.localeCompare(b.instanceId));
    if (materials.length < requirement.duplicates) {
      throw new HttpsError(
        "failed-precondition",
        `You need ${requirement.duplicates} unequipped matching Level ${instance.level} cop${requirement.duplicates === 1 ? "y" : "ies"}.`
      );
    }
    const rates = getRewardedAdBaseRates(economy);
    const cost = Math.max(0, Math.floor(rates.goldPerHour * requirement.baseGoldHours));
    if (economy.goldFloat < cost) throw new HttpsError("failed-precondition", "Not enough gold for this gear upgrade.");
    materials.slice(0, requirement.duplicates).forEach(material => { delete gear.instances[material.instanceId]; });
    instance.level += 1;
    instance.upgradedAtMs = nowMs;
    const goldFloat = economy.goldFloat - cost;
    const gold = Math.floor(goldFloat);
    gear.updatedAtMs = nowMs;
    writePreparedEconomy(transaction, economy, { gear, gold, goldFloat });
    return createEconomyResponse(economy, {
      gear, gold, goldFloat, upgradedInstanceId: instance.instanceId, spentGold: cost,
      bonuses: getCommonGearBonuses(gear),
    });
  });
});

